local Text_AwakerStory = readonly({
  AwakerStory_100415_Content = {
    Text = "A. F. 3@2 ปี 2 เดือน 12 วัน\nในระหว่างการเยี่ยมชมที่สตูดิโอประติมากรรม ได้ทาสีผลงานประติมากรรมที่เสร็จสมบูรณ์แล้ว การออกแบบสีถือว่าแปลกใหม่ แต่กลับขัดแย้งกับระบบการออกแบบของกลุ่มประติมากรรมดั้งเดิม \nหลังจากนั้นได้ตกลงที่จะรับผิดชอบการทาสีผลงานประติมากรรมทั้งหมดฟรี อาจจะมีโอกาสในการร่วมสร้างสรรค์ในอนาคต \nผู้รับรอง: ซังก้า \n...\n\nA. F. 3@2 ปี 4 เดือน 9 วัน\nพยายามขุดศพในกุญแจหลุมศพเพื่อใช้เป็นแบบ แต่ไม่สำเร็จ ถูกจับได้ในที่เกิดเหตุและเชิญเจ้าหน้าที่ตรวจสอบมาทำเป็นศพ \nผู้รับรอง: โอเกียร์ \n...\n\nA. F. 3@2 ปี 4 เดือน 11 วัน\nขโมยวัตถุดิบในครัวมาใช้เป็นแบบในการวาดภาพ แม้ว่าวัตถุดิบจะถูกช่วยชีวิตได้สำเร็จ แต่เวลาที่ใช้หมักเครื่องเทศและรสชาติของวัตถุดิบกลับถูกทำลายจนหมดสิ้น ทำให้สูญเสียคุณค่า \nส่วนเกี่ยวกับคุณสมบัติและแหล่งที่มาของวัตถุดิบ... คงไม่สะดวกที่จะเปิดเผยในขณะนี้ \nผู้รับรอง: ดูเรซิน \n...\n\nA. F. 3@2 ปี 6 เดือน 29 วัน\nแอบเข้าไปในหอเก็บสะสมของโรงเรียน นำผลงานจิตรกรรมขนาดใหญ่ที่ตนสร้างสรรค์ไปแขวนไว้ที่กลางผนัง ในเวลาหลายทุ่ม เนื่องจากได้รับผลกระทบจากความหนาแน่นของพลังงานเงินใจของโรงเรียน สัตว์ประหลาดแปลกประหลาดจึงวิ่งออกมาจากภาพ ทำให้ทรัพย์สินที่ไม่ได้รับการป้องกันบางส่วนเสียหาย \nหลังจากนั้นได้สมัครใจขอทำการซ่อมแซม ในระหว่างกระบวนการทรัพย์สินที่เสียหายกลับมากกว่าที่สัตว์ประหลาดทำลายเสียอีก โรงเรียนจึงได้ระงับการซ่อมแซมของเขาอย่างเร่งด่วน \nผู้รับรอง: ชอร์ท \n...\n\nA. F. 3@2 ปี 7 เดือน 23 วัน\nแอบเข้าไปในสระดำ พยายามใช้สระน้ำเป็นสี ทาวิลไม่ได้รบกวนเขา แต่พลังของสระดำทำให้เขาได้รับบาดเจ็บไม่น้อย \nฉันยังคงคาดหวังว่า เขาจะสร้างสรรค์ภาพอะไรจากสระดำได้บ้าง? \nผู้รับรอง: อลิสเตอร์ \n...\n\n——«เอกสารของพิคแมน·บันทึกการละเมิด»"
  },
  AwakerStory_100415_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_100415_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
