  AwakerStory_100417_Content = {
    Text = "จิตรกรที่เป็นมนุษย์ครึ่งหนึ่งและซอมบี้ครึ่งหนึ่ง มีพรสวรรค์ที่คนอื่นยากจะเข้าถึง ผลงานศิลปะซอมบี้ที่เขาสร้างขึ้นสามารถทำให้เส้นแบ่งระหว่างโลกในภาพวาดและโลกจริงเบลอจนทำให้ผู้ชมรู้สึกเหมือนอยู่ในเหตุการณ์จริงๆ \n แต่พิกแมนไม่เคยยอมรับคำเรียกนี้ว่าเป็นจิตรกรแนวเหนือจริงที่บ้าคลั่ง ในคำประกาศของเขา เขาเป็นเพียงนักเขียนภาพที่วาดเฉพาะโลกที่แท้จริงเท่านั้น。"
  },
  AwakerStory_100417_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_100417_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_100418_Content = {
    Text = "พวกที่แปลกประหลาด มนุษย์ที่ผิดแปลก ไหลเวียนไปด้วยเลือดของมอนสเตอร์ พวกบ้าคลั่งที่ดูหมิ่นศิลปะ...\nผืนผ้าใบกางออกต่อหน้าพิคแมน เสียงสบประมาทและเสียงอื่นๆ พากันทาสีให้เป็นสีสันสดใสบนผืนผ้าใบ \nเขากระโดดเข้าสู่โลกที่สดใสนี้ ล่องลอยอยู่ในสีสันที่บ้าคลั่ง เขาหวังอย่างกระตือรือร้นที่จะนำคนอื่นเข้าสู่ผลงานของเขา พาเขาไปเป็นพยานในความจริงของโลก \nหนามแหลมของความจริงเจาะหัวใจของเขาหลายครั้ง ความเข้าใจระหว่างมนุษย์ยากยิ่งกว่าการเปิดขอบเขตของสองโลก \nจากมนุษย์สู่ซอมบี้ จากเมืองมนุษย์สู่เนครอโพลิส เส้นทางนี้เต็มไปด้วยความคดเคี้ยวและยาวไกล เขาถูกทำร้ายซ้ำแล้วซ้ำเล่า แต่ก็ลุกขึ้นอีกครั้ง เขาเข้าใจดีว่าไม่มีความจริงและไม่มีเท็จ ความเจ็บปวดและความบ้าคลั่งคือความจริงของโลก และหน้าที่ของเขาคือการวาดภาพทุกสิ่งอย่างซื่อสัตย์ \nความหมายของการวาดภาพอยู่ที่การวาดภาพเพียงอย่างเดียว \nเขามอบชีวิตและความหลงใหลทั้งหมดให้กับการวาดภาพ ความหวังของเขามีน้อยที่จะได้รับการตอบสนอง การไล่ล่าของเขาไม่เคยหยุดนิ่ง。"
  },
