  AwakerStory_11160_Content = {
    Text = "หลังจากที่ได้กลับมาพบกับเฟนท์ ทิงค์เทตก็เริ่มตั้งหลักที่มหาวิทยาลัยมิซากะอีกครั้ง ในเหตุการณ์ที่โรงอุปรากรหมายเลข P-063@2ที่เธอได้รับบาดเจ็บอีกครั้งทำให้ทิงค์เทตกลัวคนแปลกหน้ามากขึ้น จึงทำให้เธอใช้ชีวิตอย่างโดดเดี่ยว แตกต่างจากเสียงร้องที่สูงและไพเราะ เสียงที่เธอใช้พูดคุยในชีวิตประจำวันกลับหวานและใส แต่กลับมีผู้ที่ได้ยินเสียงของเธอเพียงไม่กี่คน\nมีผู้มีน้ำใจพยายามสร้างกระแสให้ทิงค์เทตขึ้นเวทีในวิทยาเขต และยังหาภาพโปสเตอร์การแสดงของทิงค์เทตในโรงอุปรากรเมื่อปีก่อนๆ จากที่ไหนไม่รู้ มาติดตามมุมประชาสัมพันธ์ต่างๆ ทั่ววิทยาเขต\nทิงค์เทตไม่อยากตอบสนองต่อความปรารถนาเหล่านี้ ความร้อนรนเหล่านั้นกลับทำให้ความทรงจำในอดีตที่เธอพยายามลืมกลับมาแปรปรวน\n「จบโศกนาฏกรรมที่ไร้สาระนี้เถอะ อยู่เคียงข้างคุณ ฉันไม่มีสิ่งใดที่ต้องการอีกแล้ว หากเป็นไปได้ ขอให้ฉันถูกลืมจากโลกใบนี้ก็ไม่เป็นไร」\n「ไม่ ทิงค์เทต วันข้างหน้าที่เราจะอยู่ด้วยกันยังอีกยาวไกล ที่นี่ไม่ใช่ดาวร้างอีกต่อไป และฉันก็ไม่ใช่ภาระของคุณอีกแล้ว คุณควรหาสิ่งที่คุณอยากทำ และมีชีวิตเพื่อความสุขของตัวเอง」"
  },
  AwakerStory_11160_Title = {
    Text = "เรื่องราว·2"
