  },
  AwakerStory_11162_Content = {
    Text = "A. F. 315 ปี@1เดือน@2วัน\nหมอซิลเวียแนะนำฉันให้จดบันทึกความคิดของตัวเองลงในสมุดโน้ต เพื่อเป็นการฝึกความจำ ทุกคนบอกว่าหมอมีความรู้และสามารถช่วยฉันได้แน่นอน ดังนั้น ฝากด้วยนะ ตัวฉันในวันพรุ่งนี้ ขออย่าลืมว่าบันทึกเล่มนี้มีประโยชน์แค่ไหน!\nวันนี้ฉันได้เสร็จสิ้นการสร้างและประกอบท่อไอเสียแล้ว ตอนนี้มันสามารถปล่อยไอเสียได้โดยไม่รบกวนการเคลื่อนไหวของสายยางเสริม นี่ควรจะเป็นขั้นตอนสุดท้ายแล้วใช่ไหม? อย่างน้อยตอนนี้ฉันก็ยังไม่ได้พบปัญหา แต่ก็ไม่แน่ว่าฉันอาจจะลืมสกรูบางตัว... ก็ใช่ ฉันต้องลืมอะไรบางอย่างไปแน่ๆ ไม่ว่าจะเป็นสกรู ท่อ หรือการหล่อลื่นแบริ่ง? น้ำมันเครื่อง? พูดตรงๆ ก็เถอะ ฉันมีความรู้สึกลางๆ มาเสมอว่าแฟนธอมมีบางอย่างที่ไม่ปกติอยู่ มันยังขาดอะไรบางอย่าง... บางอย่างที่สำคัญมากกว่าตัวเครื่องยนต์เองอีก ถ้าไม่มีมัน ฉันก็ไม่สามารถเริ่มต้นการเดินทางไปยังดินแดนปริศนาได้ เพราะนั่นคือของเรา...@2\nทำไมฉันถึงพูดว่า ของเรา? ฉันกับใคร? ฉันเคย... จำได้ว่า รู้สึกเหมือน... @2@4@3\nอา หัวเจ็บมาก\nแต่บันทึกนี้ดูเหมือนจะมีประโยชน์พอสมควร แบบนี้พรุ่งนี้ฉันก็แค่มาอ่านต่อจากตรงนี้ บางทีอาจจะนึกอะไรขึ้นมาได้จริงๆ ก็ได้นะ?\n——หน้าบันทึกเดียวในสมุดบันทึกของโนร์ทิรา."
  },
  AwakerStory_11162_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11162_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11163_Content = {
    Text = "ผู้ที่ไม่ได้รับการเรียกนั้นน่าเวทนา เพราะเขาไม่สามารถเข้าใจความหมายที่เป็นอมตะได้ ความขัดแย้งในโลกนี้เป็นสิ่งที่ไร้ค่า เพราะมันเป็นเพียงการเบี่ยงเบนที่ตื้นเขินในกระบวนการเท่านั้น \nฉันเคยมองตรงไป ฉันเคยลิ้มรส ฉันได้เข้าใจภารกิจของร่างกายนี้แล้ว \nแต่ แต่ทว่า... ชะตากรรมช่างโหดร้าย! ทำไมท่าน... ถึงไม่เลือกนักบวชที่ภักดีที่สุดของท่านอีกครั้ง? \n—— แน่นอนว่าท่านกำลังมอบการทดสอบให้ฉัน ท่านกำลังทดสอบความเชื่อของฉัน ฉันอยู่ในที่ที่ห่างไกลจากบ้านเกิดที่สุด ในเวลาที่ไม่มีพระคุณของท่าน ความเชื่อของฉันผ่านไปหมื่นปี ไม่เคยเปลี่ยนแปลง \nฉันไม่สามารถเป็นผู้ที่ต้อนรับการฟื้นคืนชีพของท่าน แต่ฉันได้เตรียมทุกอย่างสำหรับการฟื้นคืนชีพของท่าน ฉันจะหาที่ดินนิรันดร์ให้กับท่าน... ความไม่พอใจและเกียรติยศอยู่ในตัวฉัน ฉันจึงต้องรับผิดชอบเรื่องนี้เพียงลำพัง... \nโปรดให้อภัยความอิจฉาที่น่าเกลียดของฉัน ขอเพียงได้เห็นพระอำนาจของท่านอีกครั้ง ขอเพียงได้สร้างอาณาจักรของท่านขึ้นมาอีกครั้ง ฉันยินดีที่จะทำทุกอย่าง。"
  },
  AwakerStory_11163_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11163_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11164_Content = {
    Text = "เต็มไปด้วยเครื่องประดับหยกและไข่มุก ผ้าบางเบาโอบล้อม ทำให้จิตใจซ่อนอยู่ใต้ความงดงามอันน่าหลงใหล\nเสมอมีคนคิดว่าไทอีสเป็นคนที่รักความหรูหราและไม่จริงจัง แต่บางทีนี่อาจจะเป็นเพียงหน้ากากหนึ่งที่เธอสวมใส่\n「อ๊ะ พี่ชายกำลังเขียนอะไรอยู่? ให้ฉันช่วยหน่อยนะ——」"
  },
  AwakerStory_11164_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11164_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11165_Content = {
    Text = "ขวดที่ใช้แล้วต้องทำความสะอาดให้เหมือนใหม่ โต๊ะที่ถูกไฟไหม้จากการทดลองต้องถูกขัดจนเงา และตาชั่งต้องสอบเทียบใหม่ทุกสามวัน ด้วยความหลงใหลและเคารพต่อวิทยาศาสตร์และความลึกลับของโลก เธอจึงมีมาตรฐานสูงต่อคนและสิ่งรอบตัว\nแน่นอนว่ามาตรฐานนี้ก็ใช้กับตัวเธอเองด้วย——ในเมื่อไม่ใช่ทุกคนที่จะสามารถเผชิญหน้ากับความตายอย่างสงบและขอเป็นผู้ปลุกตื่นได้."
  },
  AwakerStory_11165_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11165_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11166_Content = {
    Text = "A. F. 315 ปี@1เดือน@2วัน,     08:13 น..\nคณะกรรมการตรวจสอบได้ตอบสนองต่อการมาถึงของสมาชิกกลุ่มที่ 3 และการควบคุมและจัดการวัตถุหลอมกร่อน(ต่อไปนี้เรียกว่า DISM) กลุ่ม β7 ที่พื้นที่หลอมกร่อน L-E-933(หมายถึง ถนนเซาท์วาร์ค@2,     พิพิธภัณฑ์หุ่นขี้ผึ้งโรเจอร์สเดิม) โดยรับช่วงงานจากกลุ่มที่ 1 และกลุ่ม DISM α2 เพื่อดำเนินการทำให้พื้นที่ปลอดภัย.\n09:24 น..\nสมาชิก DISM เจมส์เกิดอาการปวดหัว คลื่นไส้ เวียนศีรษะ ขณะทำความสะอาดพื้นที่ใต้พิพิธภัณฑ์.\n10:47 น..\nสมาชิกกลุ่มที่ 3 โรแลนด์ และสมาชิก DISM ซัครีย์ และโบลตัน หนีออกจากพื้นที่ใต้ดิน ทั้งสามคนรายงานว่า ความมืดในพื้นที่ใต้ดินได้กลืนพวกเขาเข้าไปในท้องฟ้าที่เต็มไปด้วยดาว สีสันที่มีรูปร่างพันกันอยู่ในอวกาศ สวยงามแต่ทำให้รู้สึกหนาวเย็นไปทั้งตัว จากนั้นสีเหล่านี้รวมตัวกันเป็นหนูจำนวนมาก และพุ่งเข้าหาพวกเขาอย่างรวดเร็ว.\nโบลตันปฏิเสธที่จะดำเนินการต่อและกลับไปที่สำนักงานลอนดีเนี่ยนของคณะกรรมการตรวจสอบ สมาชิกกลุ่มที่ 3 โรแลนด์ และ DISM ซัครีย์ จึงได้ร่วมกับกัปตันกลุ่มที่ 3 ฟิชเชอร์ กลับเข้าสู่พื้นที่ใต้ดินเพื่อตรวจสอบที่เกี่ยวข้อง.\n13:03 น..\nจากการตรวจสอบค้นหา กัปตันกลุ่มที่ 3 ฟิชเชอร์ พบและเก็บเกี่ยวเงินใจ L3202 ที่หลงเหลืออยู่ในขี้ผึ้งหลอมกร่อนในพื้นที่ใต้ดิน ซึ่งได้ส่งต่อให้มหาวิทยาลัยมิซากะเพื่อดำเนินการต่อไป.\n——«รายงานการจัดการทำให้ปลอดภัยพื้นที่หลอมกร่อน L-E-933»"
  },
  AwakerStory_11166_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11166_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11167_Content = {
    Text = "24ย้ายมาไม่ถึงหนึ่งเดือนก็พบว่าบ้านโดนขโมย\nเริ่มจากชีส ตามด้วยขนมปัง นม มะเขือเทศ...อาหารในบ้านมักจะหายไปอย่างเงียบๆ\nเธอใช้ความอดทนเฝ้ารออยู่หลายวัน ในที่สุดก็พบว่าเป็นผู้ร้ายตัวจริง—หนูตัวหนึ่ง มันแกว่งไปแกว่งมาหลีกเลี่ยงกับดักที่24ตั้งไว้ แล้วคว้าผ mushrooms สองดอกแล้วหายไปที่ประตูห้องใต้ดิน\n24เปิดประตูห้องใต้ดิน ลงไปตามบันไดที่เปียกและมีเชื้อรา พบว่าที่นี่เชื่อมต่อกับช่องน้ำใต้ดิน\nหนูยก mushrooms วิ่งเข้าสู่เงามืด 24ตามไป ในความมืดเห็นดวงตาแวววาวคู่หนึ่ง เหมือนลูกหมาป่า เธอสวมผ้าขาดๆ ปิดทับด้วยหนังสือพิมพ์เก่าในอุณหภูมิใกล้ศูนย์ อาการสั่นจากความหนาวเย็น\nหัวใจของ24ถูกทิ่มแทงเบาๆ\n「ไม่ควรกิน mushrooms ดิบ จะป่วยได้」\nเด็กน้อยยังคงเงียบ\n24จึงไปต้มซุป mushrooms ใส่ชามเล็กวางไว้บนโต๊ะ แล้วก็ไปนอน เธอต้องตื่นขึ้นทำงานตอนหกโมงเช้าทุกวัน แทบไม่มีเวลาพักผ่อน\nพอตื่นขึ้นมาในวันถัดไป ชามยังอยู่ที่เดิม แต่ซุปถูกดื่มจนหมด\nหลังจากนั้น 24 ก็ทำอาหารมากขึ้นเพื่อเลี้ยงดูเพื่อนบ้านข้างล่าง บางครั้งฝ่ายนั้นก็จะตอบแทนเธอด้วยของขวัญเล็กๆ น้อยๆ โดยปกติจะเป็นเครื่องประดับหรือของเล่นที่ไม่รู้ไปเก็บได้จากที่ไหน\n\nความเข้าใจใหม่จึงถูกสร้างขึ้น。"
  },
  AwakerStory_11167_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11167_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11167_UnlockDesc_1 = {
    Text = "ผ่านด่านเนื้อเรื่องหลักบทที่ 2 「ในนามของหุ่นขี้ผึ้ง」"
  },
  AwakerStory_11168_Content = {
    Text = "เพื่อนที่ดีของเรา ฮันนา พีสลี ผู้มีความสามารถอันกว้างขวาง ไม่รู้ได้ไปขุดค้นข้อมูลการวิจัยของเซเลสเทมาจากที่ใด ด้วยความช่วยเหลือของนักข่าวที่กล้าหาญคนนี้ ข้อมูลที่ควรเป็นความลับและการสัมภาษณ์สั้นๆ ระหว่างพวกเขาก็กลายเป็นที่รู้กันทั่วเมืองแล้ว。\n\nหลังจากที่ฮันนาอ่านข้อมูลลับเสร็จ เธอได้ถามเซเลสเทซึ่งปกติแล้วขาดอารมณ์ว่า 「ร่างกายที่ตื่นขึ้นส่วนใหญ่มีความปรารถนาที่ยังไม่สมหวัง ซึ่งเป็นพื้นฐานหนึ่งในการร่วมมือกับโรงเรียน แต่ในเอกสารนี้ ช่องความปรารถนาของคุณว่างเปล่า คุณไม่มีสิ่งที่อยากทำเหรอ? หรือความหมายในการเป็นร่างกายที่ตื่นขึ้นของคุณอยู่ที่ไหน?」\n\n「มี ฉันมี」\n\nสีหน้าของสาวน้อยไม่ได้แสดงออกถึงจุดอ่อน เหมือนกับปกติที่ดูว่างเปล่าและสูงส่ง หากไม่ใช่คำตอบสั้นๆ และเร่งรีบนี้ นักข่าวสาวแทบจะคิดว่าฝ่ายตรงข้ามไม่ได้ยินคำถามของเธอ。\n\n「ฉันจะหาความปรารถนาให้พบ… ทุกคนต่างหวังอย่างนั้น ดังนั้น ฉันจะหามันให้เจอ」\n\n\nเสียงที่อ่อนโยน เหมือนกับความฝันที่อาจแตกสลายได้ในทันที。"
  },
  AwakerStory_11168_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11168_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11169_Content = {
    Text = "หนึ่งคำพูดหนึ่งการกระทำปฏิบัติตามความซื่อสัตย์ หนึ่งการเคลื่อนไหวหนึ่งการจัดการตามคุณธรรม\nแม้ว่า 「รู้จักมารยาทและปฏิบัติตามหลักการอย่างเคร่งครัด」 จะฝังลึกในจิตวิญญาณแล้ว แต่นักอัศวินผู้ทรงคุณธรรมผู้นี้ก็ยังคงมีรูปลักษณ์ของเด็ก\nแต่อย่าได้เป็นกังวล แม้ว่าต้องแลกกับการล่มสลายชั่วนิรันดร์ โอจิเอย์ก็จะทุ่มเททุกสิ่งทุกอย่างเพื่อปฏิบัติตามคำสั่งของเจ้านาย\nขอให้วันนั้นอย่าได้มาถึงเลย."
  },
  AwakerStory_11169_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11169_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11170_Content = {
    Text = "พระราชาที่ยังเยาว์วัยหลับใหลอยู่บนบัลลังก์ ขณะที่ตื่นขึ้นมาได้ทรงออกพระราชโองการที่มีอำนาจไปทั่วแผ่นดิน \n พระอาทิตย์ยังไม่ตกดิน พระองค์รู้สึกเหนื่อยล้าแล้ว พระองค์เบื่อหน่ายกับอำนาจของตนเอง และเบื่อหน่ายกับปัญญาที่เหนือมนุษย์ เบื่อหน่ายกับการเครื่องบูชาที่คลั่งไคล้และการถวายของผู้ศรัทธา และเบื่อหน่ายกับห้วงฝันอันยาวนานที่เกินกว่าหมื่นปี \n ไม่มีใครรู้ว่าพระองค์ฝันถึงอะไรในความหลับอันยาวนาน แต่พวกเขาควรจะรู้สึกโชคดีที่ได้มีความสุขจากความไม่รู้เช่นนี้。"
  },
  AwakerStory_11170_Title = {
