  AwakerStory_11171_Content = {
    Text = "「พระบิดาผู้ทรงเมตตาเคยเตือนว่า: พวกเจ้าจงรักและดูแลทุกสิ่งที่อยู่บนฟ้า บนดิน ในน้ำ และในดิน เพราะทุกสิ่งล้วนเป็นบุตรของข้า」\n「ดังนั้น ข้าจึงอยากจะกล่าวว่า: จงนำความทุกข์ทั้งหมดมาสู่ข้าเถิด เพื่อให้ผู้ที่ทุกข์ทรมานจากชีวิตและโรคระบาดได้หลุดพ้น ให้ความเจ็บปวดและความบ้าคลั่งทั้งหมดละลายไปเหมือนน้ำแข็งและหิมะ ขอให้พวกท่าน พี่น้องของข้า ได้รับความสุขอันยั่งยืน\n」จงเผาข้าให้ไหม้ บดกระดูกของข้า ทำลายเนื้อของข้า เพียงแต่พวกท่านจะได้รับการปลอบประโลม ข้าก็ไม่มีคำบ่น「\n——B. F. 1@1,      30 พฤษภาคม,      ซัลวา@1โด·มาร์ติน@2·อิ@1อัส ที่@3ศาลพิพากษา"
  },
  AwakerStory_11171_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11171_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11172_Content = {
    Text = "ฟีนต์เป็นเมล็ดที่สีจางและแตกออกได้ยาก。\nผู้คนเห็นใจเธอเพราะความไม่สมบูรณ์ของเธอ，รักเธอเพราะความอ่อนแอของเธอ。\nรู้ว่าเธอเป็นผู้ที่เลือกจะอยู่ในเปลือก，กลายเป็นผงละเอียด，กลายเป็นฝุ่นดาว。"
  },
  AwakerStory_11172_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11172_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11173_Content = {
    Text = "หลังเหตุการณ์@3@1 ไรเกอร์กลายเป็นที่ปรึกษาพิเศษของมหาวิทยาลัยมิซากะ\nไรเกอร์เป็นที่ปรึกษาที่มีความสามารถ ไม่ว่าจะเป็นการหายตัวไปอย่างลึกลับของศาสตราจารย์หรืออุปกรณ์เสียหายโดยไม่ทราบสาเหตุ รวมถึงเรื่องเล็กๆ เช่น การตามหาลูกแมวหรือสุนัข ไรเกอร์สามารถส่งมอบผลลัพธ์ที่น่าพอใจได้อย่างอดทนและรวดเร็ว\nไม่นาน ไรเกอร์ก็กลายเป็นไอดอลที่ได้รับความนิยมในหมู่วัยรุ่นชายหญิงนับพันในมิซากะ ด้วยรูปลักษณ์ที่โดดเด่น ท่าทางที่สง่างาม และนิสัยชอบช่วยเหลือผู้อื่น\nศาสตราจารย์เดกสเตอร์เคยกล่าวว่า 「ความสนใจทั้งหมดถูกแย่งชิงไปโดยคนหนุ่มสาว」\nแต่เมื่อเขาค่อยๆ ปรับตัวเข้ากับชีวิตในมหาวิทยาลัย ผู้คนเริ่มสังเกตว่าเวลาที่ไรเกอร์ปรากฏตัวต่อหน้าผู้อื่นลดน้อยลงเรื่อยๆ\nในขณะเดียวกัน เสียงของการเขย่าลูกเต๋าก็เริ่มดังขึ้นบ่อยครั้งในห้องใต้ดินที่ถูกทิ้งร้างของมิซากะ。"
  },
  AwakerStory_11173_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11173_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11174_Content = {
    Text = "ผู้ที่พบเธอเป็นครั้งแรกจะไม่เกิดความคิดที่จะเข้าใกล้หรือสื่อสารใดๆ สัญชาตญาณในการเอาชีวิตรอดจะส่งเสียงเตือนให้ถอยห่างออกไปอย่างสุดกำลัง \n เธอคือคนที่บ้าคลั่งอย่างสิ้นเชิง หรือพูดอีกอย่างหนึ่งคือสัตว์ร้ายที่แท้จริง \n หากสามารถเลือกใหม่ได้ เธออาจจะยินดีเป็นสัตว์ร้ายมากกว่าที่จะต้องเผชิญกับทุกสิ่งที่เป็นมนุษย์ \n เธอไม่เคยเชื่อใจใคร เมื่อดวงตาสีชาดของเธอมองมาที่คุณ สิ่งที่สะท้อนในดวงตานั้นไม่ใช่ความสงสัย แต่คือความเย็นชาและเจตนาฆ่า \n เธอไม่เคยมีความสนใจในการสงสัย ทุกคนในสายตาของเธอล้วนแต่ต่ำต้อยเหมือนกัน \n หากต้องการคำแนะนำในการอยู่ร่วมกับเธอ ควรหลีกเลี่ยงการพยายามเชื่องสัตว์ร้ายที่แท้จริง นั่นไม่ใช่สิ่งที่อ่อนโยนเลย เพียงมีโอกาสเพียงนิดเดียว เล็บงอและเขี้ยวของเธอจะทะลวงคอของคุณ \n หนีให้เร็วที่สุดก่อนที่เธอจะมองมาที่คุณ และอธิษฐานว่าเหยื่อคนถัดไปของเธอจะไม่ใช่คุณ。"
  },
  AwakerStory_11174_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11174_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11175_Content = {
    Text = "มาเต้นรำกันเถอะ! เต้นรำที่สนุกสนาน เต้นรำที่บ้าคลั่ง! มาหัวเราะร่วมกับเธอเถอะ ทำให้บรรยากาศร้อนแรงถึงขีดสุด.\nถึงเวลานั้น ตัวเอกก็จะได้ขึ้นเวที.\nที่จุดบรรจบของไฟสปอตไลท์ นักมายากลบ้าคลั่งได้ยื่นมือเข้าไปในหมวกใบใหญ่ของเธอแล้ว ส่วนสิ่งที่เธอหยิบออกมาจากความว่างเปล่าอันไม่มีที่สิ้นสุดนั้น คือริบบิ้นหลากสีสัน นกพิราบขาวที่บินได้ หรือเล็บงอของมอนสเตอร์น่าสยดสยอง... คงมีเพียงเธอเท่านั้นที่รู้.。"
  },
  AwakerStory_11175_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11175_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11176_Content = {
    Text = "นั้นคือของที่ระลึกที่ศาสตราจารย์เดกสเตอร์นำกลับมาจากการเดินทางที่ชายฝั่งเฟฟเฟอร์\nสภาพอากาศที่อบอุ่นและน่าอยู่ของมหาสมุทรเฟฟเฟอร์ทำให้ที่พักฟื้นเซวาดาที่มีประวัติศาสตร์ยาวนานนับร้อยปีตั้งอยู่ริมทะเล เป็นสถานที่ที่มีนักท่องเที่ยวจำนวนมากเลือกไปพักผ่อนในทุกปี\nในขวดแก้วที่ถูกน้ำและสาหร่ายพันรอบนี้ มีผงโปร่งใสอยู่เล็กน้อย มันไม่ใช่ขวดลอยน้ำที่ถูกทิ้งจากผู้ประสบภัยทางทะเล และไม่ใช่ของที่ทำจากทรายที่ผลิตในท้องถิ่น ศาสตราจารย์เดกสเตอร์ชัดเจนว่ารู้ว่าขวดนั้นบรรจุผงแกนเงิน กล่าวอีกนัยหนึ่งคือมีเจตจำนงที่อาศัยอยู่ในนั้น\nเขาบอกว่าซื้อจากชาวประมงในท้องถิ่น ชาวประมงเล่าเรื่องแปลกๆ ที่พบเจอล่าสุดอย่างคลุมเครือ เมื่อไม่กี่วันก่อนในตอนเช้า ชาวประมงออกไปหาปลาและได้พบกับฝูงปลาที่แปลกประหลาด ตอนนี้ไม่ใช่ฤดูวางไข่หรือฤดูหนาว แต่ฝูงปลากลับรวมตัวกันอยู่ที่นั่นเป็นเวลานาน เมื่อดึงอวนที่หนักอึ้งขึ้นมา พบว่ามีขวดแปลกๆ อยู่ในอวน ชาวประมงรู้สึกแปลกใจและรู้สึกไม่สบายใจอย่างลึกๆ ราวกับว่าขวดแปลกๆ นี้จะมีคำสาป ทำให้เขาได้รับโชคร้าย หลังจากนั้นไม่กี่วัน ในพื้นที่ทะเลนี้ก็ไม่สามารถจับปลาได้อีกเลย"
  },
  AwakerStory_11176_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11176_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11177_Content = {
    Text = "คณิตศาสตร์: ศูนย์คะแนน ออริตาถึงได้ 2 คะแนน\nภาษาอังกฤษ: ไม่ผ่าน ใช้เวลานานกว่าจะเข้าใจความแตกต่างระหว่าง \"เปลี่ยนเวร\"กับ \"ขี้หมา\"\n...\nประวัติศาสตร์: ไม่ผ่าน อ้างว่า คาลิกูล่าเป็นจักรพรรดิที่ยอดเยี่ยมที่สุดของโรม เพราะเขาสร้างสนามกีฬาเยอะมาก\n\nระดับอันตราย: C. แสดงพฤติกรรมก้าวร้าวในระดับหนึ่งขณะอยู่กับผู้ปลุกตื่นอื่นๆ มีภัยคุกคามไม่มาก ไม่จำเป็นต้องให้ความสนใจเป็นพิเศษ\nหมายเหตุ: นักเรียนคนนี้มีความสามารถในการดูแลตัวเองแทบเป็นศูนย์(อีกคนที่ถูกระบบทาสทำลาย) ต้องเฝ้าระวังตลอดเวลา ไม่สามารถให้เธอใช้ครีมทาผิวแทนยาสีฟันได้อีกแล้ว\n——คัดลอกจาก A. F. ปี 313,      \"บันทึกประจำปีของนักเรียนมิซากะ\""
  },
  AwakerStory_11177_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11177_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11178_Content = {
    Text = "@2ปี เมืองอากาคุ\nความหิวโหยที่ผ่านมาหมื่นปีในที่สุดก็ปะทุออกมา การฆ่าฟัน ดื่มเลือด การฆ่าฟัน ดื่มเลือด——ในที่สุด สิ่งที่เหลืออยู่ต่อหน้าเขาคือทะเลทรายที่ไร้ที่สิ้นสุดและศพที่แห้งเหี่ยวมากมาย แม้แต่ นกอีแร้งยังกลัวที่จะเข้าใกล้เขา\nเขาคุกเข่าลงบนทรายเหลือง หัวเราะฮ่าฮ่า: สบายจริง ๆ! สบายจริง ๆ @1!\nต่อไปนี้ ให้เขาเป็นผู้วาดจุดสิ้นสุดอันสมบูรณ์แบบให้กับงานเฉลิมฉลองการฆ่าฟันนี้\nนักรบกัดข้อมือของเขา เขาดูดเลือดสดของตัวเองจนหมด และล้มลงในสระเลือดสีชาดนี้。"
  },
  AwakerStory_11178_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11178_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11179_Content = {
    Text = "「ฮอร์ลา ตั้งแต่วันนี้เป็นต้นไป บทกวีทั้งหมดของเธอ ฉันจะช่วยเก็บรักษาไว้อย่างดีนะ ต่อไปนี้ ฉันจะใช้ดอกไม้ของฉันแลกกับบทกวีของเธอ!」\n「โคเลตต์ เธอต้องกลับมาช่วยฉันนะ... ใช่ไหม?」"
  },
  AwakerStory_11179_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11179_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11180_Content = {
    Text = "เมื่อวานนี้เวลา 18.00 น. ห้อง CB-101 ซึ่งตั้งอยู่ใต้อาคารเจ้าชายของมหาวิทยาลัยมิซากะ ถูกทำลายโดยบุคคลที่ไม่รู้จัก ประตูห้องที่เสริมความแข็งแกร่งถูกทำลายอย่างรุนแรง และมีรอยไหม้เป็นรูปสายฟ้าสีดำกระจายอยู่บนผนังภายในและภายนอก สถานที่เกิดเหตุเต็มไปด้วยความยุ่งเหยิง \n「กระแสไฟฟ้าแรงสูงในช่วงเวลาสั้น ๆ สามารถทำให้เกิดรอยแบบนี้ได้」 ดร.อดัมส์ ผู้เชี่ยวชาญด้านวิศวกรรมไฟฟ้า กล่าวถึงรอยไหม้บนผนัง 「สิ่งนี้ต้องการแรงดันไฟฟ้าที่สูงมาก ถ้าเป็นอุปกรณ์ปกติ มันจะต้องมีขนาดใหญ่และยากที่จะซ่อน แต่ถ้าเป็นเงินใจ... ทุกอย่างเป็นไปได้」 \n ในกรณีที่เงินใจถูกควบคุมอย่างเข้มงวดโดยระบบการตื่นรู้ มันยากที่จะจินตนาการว่ามีใครสามารถใช้เงินใจโดยไม่ถูกตรวจจับ ดังนั้น ความสนใจจึงหันไปที่ผู้ปลุกตื่นที่มีพลังงานเงินใจอยู่ในร่างกาย \n「ถ้าถามฉันนะ เรื่องนี้แน่นอนว่าเป็นเธอ」 นักเรียนของระบบการตื่นรู้ที่ไม่ประสงค์ออกนามกล่าวกับนักข่าว เมื่อถูกถามว่าใครคือคนที่พูดถึง เขาดูเหมือนจะตื่นเต้นเล็กน้อย 「ก็『เธอ』ไง คนที่ถูกเรียกว่า『คนติ๊กต๊อก』! คุณไม่เคยได้ยินเสียงกระแสไฟฟ้าที่ไหลอยู่ในร่างกายของเธอเหรอ? เมื่อพูดถึงกระแสไฟฟ้าฉันนึกถึงเธอเลย แน่นอนว่าเป็นเธอ」 \n นักเรียนหลายคนได้แสดงความคิดเห็นที่คล้ายกัน แต่ผู้ปลุกตื่นที่เคลื่อนไหวเหมือนหุ่นกระบอกและมีรอยยิ้มแปลก ๆ ไม่ได้อยู่เพียงลำพัง มีนักสืบหลายคนออกมาสนับสนุนเอริกา และเรียกร้องให้ทุกคนยึดมั่นในข้อเท็จจริง ใช้หลักฐานเป็นเกณฑ์ และอย่าทำร้ายผู้อื่นเพราะอคติส่วนบุคคล \n สำหรับเรื่องนี้ ดร.โซโคโลวา ผู้รับผิดชอบแทนของระบบการตื่นรู้ ปฏิเสธที่จะให้ความเห็น เหตุการณ์ยังอยู่ในระหว่างการสอบสวนต่อไป \n——คัดจาก「มิซากะเดลี่」,      「การสำรวจเหตุระเบิดในห้อง CB-101」"
  },
  AwakerStory_11180_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11180_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11181_Content = {
    Text = "เธอมักจะหยิ่งยะโสเรียกตัวเองว่า「มารดาแห่งเทพเจ้า」 เย็นชาและเต็มไปด้วยความเป็นปฏิปักษ์ ปิดกั้นทุกคนออกจากขอบเขตความปลอดภัยของตัวเอง คนที่พบเธอครั้งแรกแทบจะไม่สามารถเชื่อมโยงเธอกับเจ้าหญิงน้อยที่เอาแต่ใจคนนั้นได้เลย\n「แต่ในแก่นแท้แล้ว พวกเธอยังคงเป็นคนเดียวกัน」 ผู้ปกปิดความลับยังคงยืนกรานบอกกับทุกคนอยู่เสมอ 「แค่เคยเห็นเธอตะกละตะกลามกินเค้กชิ้นเล็กๆ คนเดียวก็รู้แล้ว」"
  },
  AwakerStory_11181_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11181_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11182_Content = {
    Text = "ความฉลาดและความบ้าคลั่งมีเส้นแบ่งเพียงนิดเดียว ในฐานะที่เคยเป็นอัจฉริยะที่สว่างไสวที่สุดของมิซากะ การล่มสลายของเธอก็เหมือนกับตึกที่พังทลาย จากซากปรักหักพังที่มีเหตุผลนั้น มีเพียงปีศาจที่บ้าคลั่งที่สุดเท่านั้นที่ปีนขึ้นมาได้ \n เธอใส่เสื้อคลุมทางวิทยาศาสตร์อย่างปกติ นำชีวิต มนุษยธรรม ความรัก และการล่มสลายเทลงในหม้อหลอม สร้างสรรค์เป็นพิษที่ทำลายโลก。"
  },
  AwakerStory_11182_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11182_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11183_Content = {
    Text = "อย่าคาดหวังกับความรู้สึกของแมงกะพรุนมากนัก ออรีตาไม่สามารถเข้าใจสิ่งที่เธอประสบมาได้ สิ่งเดียวที่เธอมั่นใจคือ เธอเคยอาศัยอยู่ในหมู่บ้านที่ไม่มีใครเลย ทุกครั้งที่พูดคุยเกี่ยวกับเรื่องราวในอดีต เธอมักจะเปลี่ยนหัวข้อด้วยการแสร้งทำเป็นเข้าใจ ดังนั้น ออรีตาจึงแทบจะไม่สามารถช่วยในการศึกษาวิชาต่างๆ เช่น ปรากฏการณ์หลอมละลาย หรือภัยพิบัติได้ \n แต่ในฐานะผู้ปลุกตื่นที่มีนิสัยไม่เป็นอันตราย ออรีตาจึงได้รับความนิยมจากอาจารย์และนักเรียนในระบบการปลุกตื่น เธอได้รับความเอาใจใส่จากชอร์ท ซึ่งเป็นผู้ควบคุมการศึกษาชีววิทยาหลอมละลาย \n โดยบังเอิญ เธอได้รับความสามารถในการแยกส่วนและเพิ่มจำนวนจากการรวมตัวกับจิตสำนึกของกลุ่มแมงกะพรุน แม้ว่าแมงกะพรุนที่เพิ่มขึ้นจะเป็นเพียงแมงกะพรุนธรรมดา ออรีตาก็จะตื่นเต้นยก 「เพื่อน」 ขึ้นมาเพื่ออวดบ้านแต่ละหลัง—แม้ว่าเธอจะไม่สามารถแยกแยะแต่ละตัวได้ แต่ก็ไม่รู้ว่า ทุกครั้งที่เธอแสดงให้ดูคือแมงกะพรุนตัวเดียวกัน。"
  },
  AwakerStory_11183_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11183_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11184_Content = {
    Text = "■หมายเลขแฟ้ม: AF315-C01\n■รหัสผู้ปลุกตื่น: @2นักเดินทาง\nผู้ปลุกตื่นนี้ถูกสังเกตครั้งแรกในปี A.F.315 เดือน @1\nในระหว่างการทดลอง 「โดเมนเทียม」 ครั้งแรก อิทธิพลจากการสะท้อนจิตวิญญาณของสิ่งที่มีต้นกำเนิดเดียวกัน ทำให้ 「โดเมนเทียม」 ที่อิงจากพื้นที่จิตวิญญาณของนักเรียนระดับ @2 ราโมน่า เดกสเตอร์ เกิดการทะลุขอบเขตมิติอย่างไม่คาดคิด\nผู้พิทักษ์ในขณะนั้นได้ยืนยันการมีอยู่ของโลกนอกมิติใน 「โดเมนเทียม」 นี้เป็นครั้งแรก พร้อมทั้งยืนยันว่าพละกำลังของ @2 จะมีผลกระทบต่อราโมน่า เดกสเตอร์ อย่างไร\nหลังจากนั้น สถาบันวิจัยการตื่นรู้ได้เริ่มการศึกษาเกี่ยวกับ 「ผู้ปลุกตื่นต้นกำเนิด」 อย่างเป็นทางการ\nในขณะเดียวกัน การวางแผนบทเรียนการควบคุมพละกำลังของราโมน่า เดกสเตอร์ ก็อยู่ในระหว่างการดำเนินการ。"
  },
  AwakerStory_11184_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11184_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11185_Content = {
    Text = "เธอสวมผ้าคลุมดำ ร่างกายที่ซ่อนอยู่ใต้เสื้อคลุมเป็นของมิลียาห์มที่ผอมแห้งและซูบซีด \n เธอเงียบสงบ แสดงออกถึงใบหน้าที่ผสมผสานระหว่างความเชื่อมั่นและความทุกข์ เหมือนกับรูปพระแม่มารีในภาพจิตรกรรมฝาผนัง ที่มีความหมายลึกลับไม่สิ้นสุด \n เธอทุ่มเททั้งร่างกายและจิตใจ รอคอยช่วงเวลาพิเศษ \n มันใกล้เข้ามาแล้ว วันที่ได้ตกลงกันนั้นกำลังจะมาถึง……"
  },
  AwakerStory_11185_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11185_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11186_Content = {
    Text = "ฮิลีย์สเตอร์เข้าร่วมโรงเรียนในนาทีแรก ก็ถูกดอลล์พาไปและได้รับการประเมินอย่างครบถ้วน\nในฐานะผู้ปลุกตื่นที่ไม่ได้ผ่านกระบวนการมหาวิทยาลัย สถานะจิตใจของฮิลีย์สเตอร์จึงมีความเสถียรอย่างน่าประหลาด แต่ในทางกลับกัน ไม่ว่าจะเป็นความเข้มแข็งของจิตวิญญาณ หรือดัชนีนอร์สซึ่งเป็นเกณฑ์ในการประเมินความเข้มแข็งของเงินใจ ฮิลีย์สเตอร์ยังไม่ถึงมาตรฐานของผู้ปลุกตื่น\nอย่างไรก็ตาม เธอได้ปรากฏตัวในโลกนี้เหมือนกับดอกไม้ที่ไร้รูปร่างบานในความว่างเปล่า\nแม้ว่าในกิจกรรมประจำวันและภารกิจภาคสนามจะไม่แสดงให้เห็นถึงความผิดปกติ แต่จากการตรวจสอบข้อมูลเราได้ทราบว่า สถานการณ์ของฮิลีย์สเตอร์ไม่น่ามองในแง่ดี: ความตั้งใจที่อ่อนแอของเธอกำลังค่อยๆ หายไป\nในขณะนี้ ระบบการตื่นรู้กำลังเตรียมจัดตั้งกลุ่มเล็กๆ หวังว่าจะแบ่งปันความเชื่อเพื่อรักษาการมีอยู่ของฮิลีย์สเตอร์ ผู้ที่สนใจเข้าร่วมและมีความเชี่ยวชาญด้านน้ำกรุณาติดต่อคุณนายซิลเวีย."
  },
  AwakerStory_11186_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11186_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11187_Content = {
    Text = "รอยแผลเป็นพาดผ่านลำคอของเขา ชนเผ่าของเขาได้รับความตายจากรอยแผลเป็น ในขณะที่เขาได้รับพละกำลังจากรอยแผลเป็นนั้น \nสุนัขที่ถูกขับไล่ออกจากดินแดนเลียรสขมของความล้มเหลวและความสิ้นหวัง ขณะถูกขังอยู่ในมหาสมุทรอันไร้ขอบเขต เขาได้อธิษฐานต่อพระเจ้าเพื่อขอพละกำลังแห่งการก้าวข้ามขีดจำกัด \nอัครทูตของพระเจ้าได้ตอบรับการสวดมนต์ โดยตัดคอของเขา \nอัครทูตของพระเจ้าได้ตอบรับการสวดมนต์ โดยปลูกเศษเสี้ยวแห่งความเป็นอมตะบนคอที่ถูกตัด \nอัครทูตของพระเจ้าได้ตอบรับการสวดมนต์ และนำเขาเข้าสู่ห้องโถงแห่งชีวิตนิรันดร์。"
  },
  AwakerStory_11187_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11187_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11188_Content = {
    Text = "เธอมีการเกิดที่น่าห envy : เป็นเด็กกำพร้าที่ถูกเลี้ยงดูเป็นทายาทเพียงคนเดียว ถือว่าโชคดีมาก \nเธอมีสติปัญญาที่น่าประหลาดใจ : สามารถพูดได้เมื่ออายุหนึ่งปี สามารถโต้แย้งได้เมื่ออายุสองปี และเริ่มต้นการเรียนรู้เกี่ยวกับโลกเมื่อสามขวบ \nเธอมีความสามารถที่น่าชื่นชม : จำได้ทุกอย่าง และสามารถใช้ดาบได้อย่างเชี่ยวชาญ ด้วยอายุที่ไม่น่าเชื่อ เธอสอบผ่านหลักสูตรเตรียมความพร้อมที่เข้มงวดของมหาวิทยาลัยมิซากะได้เต็มคะแนน \nเธอมีเพื่อนที่สามารถพึ่งพาได้และเดินทางร่วมกันสู่ความมืดและสิ่งที่ไม่รู้จัก \n<Italic:เธอมี...>"
  },
  AwakerStory_11188_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11188_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11189_Content = {
    Text = "การเข้าร่วมของดอร์ เป็นช่วงเวลาที่สว่างที่สุดเพียงช่วงเดียวของมหาวิทยาลัยมิซากะในสายตาของโลกภายนอก。\nนักวิชาการมากมายต่างพากันคร่ำครวญ ว่าความสามารถอันยอดเยี่ยมที่ตกลงมาจากฟ้า ก็ไม่อาจหลีกหนีจากพันธนาการของโลกมนุษย์ได้—เธอกลับต้องเข้าร่วมกับมหาวิทยาลัยที่ไม่มีชื่อเสียงใดๆ เพื่อเงินทอง และติดเชื้อกลิ่นอายของเงินทอง。\nในขณะที่โลกภายนอกประณามเธอที่ยอมตกต่ำ ดอร์ได้มอบสิ่งที่มีค่ากว่าทองคำในมหาวิทยาลัยมิซากะ。\nเธอสามารถข้ามพรมแดนของวิทยาศาสตร์วัตถุ และสัมผัสกับผ้าคลุมของโลกแห่งความเป็นจริง ใต้ผ้าคลุมนั้นซ่อนเร้นสิ่งที่เธอพร้อมจะสละชีวิตเพื่อแสวงหา。\nการศึกษาความอันตรายของเทคโนโลยีซิลเวอร์คอร์ ไม่ต่างจากการเต้นรำอยู่บนปลายมีด และดอร์กลายเป็นนักเต้นที่จริงจัง ขยันขันแข็ง และยอดเยี่ยมที่สุด。\nเมื่อรอยละลายปรากฏขึ้น นักเต้นทางวิทยาศาสตร์ก็ยังไม่หยุดหมุน แต่กลับใช้เวลาที่มีจำกัดหมุนวน หรือสะสม หรือผลึกออกมาเป็นท่าทางเฉพาะของเธอ。\nจนกระทั่งปรากฏการณ์การหลอมกร่อนทำร้ายร่างกาย จนแพร่กระจายไปยังจิตใจ และกัดกร่อนเหตุผล。\nถึงอย่างนั้น เธอก็ยังห่างไกลจากศูนย์กลางของความจริงมากเกินไป。\nดังนั้น เปลวไฟแห่งชีวิตนั้นได้มอดลงแล้ว แสงสว่างแห่งการแสวงหาความรู้ยังคงเป็นดาวที่เจิดจ้า และทิ้งคำพูดสุดท้ายว่า: \"ก่อนที่โลกจะลืมฉัน โปรดปลุกฉันขึ้นมา.\""
  },
  AwakerStory_11189_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11189_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11190_Content = {
    Text = "ท่านบิชอปผู้สูงศักดิ์ทุกครั้งที่ไปเยือนโรงเรียน จะได้รับการต้อนรับอย่างอบอุ่นจากครูและนักเรียน\nผู้ปลุกตื่นที่ยังมีจิตใจอ่อนเยาว์จะจับมือท่านและขอให้ท่านเล่าเรื่องราวก่อนยุคมหาอุทกภัยอีกสักเรื่อง นักเรียนจะเข้าใกล้และสอบถามว่าท่านบิชอปยินดีที่จะฟังปัญหาและความกังวลของพวกเขาหรือไม่ แม้แต่ผู้ปลุกตื่นที่ดูแข็งแกร่งและเย็นชาที่สุด รวมถึงอาจารย์ที่มีประสบการณ์มากมาย ก็ยังจะเข้ามาพูดคุยกับท่านบิชอปเมื่อท่านมีเวลาว่าง: บางคนก็เล่าถึงฝันร้ายของตน บางคนก็พูดคุยเกี่ยวกับความจริงของจิตวิญญาณ\nท่านมักจะใจเย็นเสมอ ไม่เคยรู้สึกเบื่อหน่าย ไม่ว่าใครก็สามารถได้รับการยอมรับและความอบอุ่นจากท่าน\n「แน่นอน ลูกของฉัน มีอะไรที่ฉันสามารถช่วยได้บ้าง?」"
  },
  AwakerStory_11190_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11190_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11192_Content = {
    Text = "เธอปฏิบัติต่อทุกคนและผู้ปลุกตื่นทุกตนอย่างเป็นมิตร ไม่เคยแสดงออกถึงแนวโน้มการโจมตีเลย\nส่วนใหญ่แล้ว เธอจะอยู่เงียบๆ ในห้อง มองออกไปนอกหน้าต่าง เราได้ค้นพบที่หัวเตียงของเธอ มีนวนิยายคลาสสิกที่ถูกอ่านซ้ำแล้วซ้ำเล่าอยู่ไม่กี่เล่ม และยังมีบทกวีที่เขียนบนกระดาษโน้ตด้วยลายมือที่สวยงาม\n「เมื่อเปรียบเทียบกับสาวคนนั้น ฉันชัดเจนว่ามีโชคดี」 เธอกระซิบถึงบ่อน้ำในวิทยาเขตที่มีแสงสะท้อนในขณะที่เธอหันหน้าไปทางพระอาทิตย์ตก\nเธอไม่ค่อยเข้าร่วมกิจกรรมกลางแจ้ง หากจะพูดว่าไม่อยากเข้าร่วมก็คงไม่ถูกนัก แต่ไม่รู้ว่าจะเข้าร่วมอย่างไร...ผู้ปลุกตื่นที่มีรูปลักษณ์เหมือนสาวคนนั้น ดูเหมือนจะขาดความรู้เรื่องชีวิตอยู่มาก\nเราได้เห็นเธอคุยกับปลาในน้ำพุหลายครั้ง โดยใช้เสียงแปลกๆ ที่เหมือนเสียงพ่นฟองหรือเสียงแหบแห้งของผู้ที่จมน้ำ แต่ใบหน้าของเธอกลับสงบและมีความสุข ราวกับว่าเธอกำลังปลอบใจและพูดคุยกับเพื่อนที่สนิท ในขณะนั้น เราทุกคนเชื่อว่าเธอได้ค้นพบความสงบที่แท้จริงแล้ว"
  },
  AwakerStory_11192_Title = {
    Text = "เรื่องราว·2"
