  AwakerStory_11192_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11193_Content = {
    Text = "ตอนนี้ การพูดคุยเกี่ยวกับ 「ชีวิตของตัวเอง」 กับฉัน อาจจะยากเกินไปแล้ว \n ฉันเคยชินกับการหายไปในที่สูง ปกปิดตัวเองในทะเลดาว \n สิ่งที่ผู้คนมองไม่ใช่ฉัน ไม่ใช่ฉันที่ถูกใช้เป็นของเล่นของกล่องเสียงเพลง ไม่ใช่ฉันที่ลอยอยู่ในท้องฟ้าที่แห้งแล้งนั้น มันเป็นเครื่องมือที่ขายเสียงเพื่อความอยู่รอด เป็นซากศพที่เร่ร่อนเพื่อค้นหาเฟนท์ เท่านั้นที่เชื่อว่าคุณค่าของผู้อื่นสูงกว่าตนเอง จึงจะเชื่อว่าการเสียสละทั้งหมดนั้นมีค่า \n ดังนั้น ตอนนี้ กรุณาอย่าให้ฉันสังเกตเห็นตัวเองอีก \n\n 「แต่ น้องสาว อย่าจมอยู่กับอดีตที่ผ่านไปแล้วอีกเลย \n เปิดตาดูสิ เสียงร้องที่เป็นเอกลักษณ์ของเธอ ได้ดังไปทั่วจักรวาลแล้วนะ」"
  },
  AwakerStory_11193_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11193_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11195_Content = {
    Text = "อัลวาพอใจกับอวัยวะเทียมของเธอมาก \n「หลังจากการต่อสู้นั้น ฉันไม่เคยคิดว่าตัวเองจะสามารถยืนขึ้นได้อีก การมีโอกาสต่อสู้เพื่อความยุติธรรมอีกครั้งถือเป็นเกียรติของฉัน」\nส่วนเสียงคร่ำครวญเบาๆ ที่ดังมาจากหอพักในช่วงเที่ยงคืน หลังจากที่ดวงอาทิตย์ใหม่โผล่พ้นขอบฟ้า ก็ขอให้ถือว่าไม่เคยมีอยู่เลยก็แล้วกัน。"
  },
  AwakerStory_11195_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11195_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11196_Content = {
    Text = "มิลียาห์มใช้ชีวิตอย่างเรียบง่ายในโรงเรียน สันโดษ คิดทบทวน สวดมนต์ ทำความสะอาด ทำงาน วนเวียนไปเช่นนี้ วันแล้ววันเล่า.\nความเคารพและระวังภัยจากผู้อื่น คำพูดและความอยากรู้อยากเห็น เธอไม่ใส่ใจเลย ในวิทยาเขตที่ห่างไกลจากบ้านเกิด เธอเหมือนจะพบวิธีการฝึกจิตวิญญาณแบบใหม่.\nในความเป็นจริง เธอไม่สนใจที่จะพูดคุยกับคนอื่น ตราบใดที่คุณยินดีแบ่งเวลาสักนิดเพื่อฟังเธอเล่าเรื่องความยิ่งใหญ่ของเทพเจ้าอมตะ เล่าเรื่องอารยธรรมโบราณที่มีอยู่ในยุคก่อนประวัติศาสตร์และอาณาจักรนิรันดร์ที่ปกครองโดยกษัตริย์หนุ่มผู้ฉลาด ทุกครั้งที่พูดถึงเรื่องนี้ ดวงตาของเธอจะส่องประกายด้วยความสงสารที่ผู้ฟังไม่เคยเห็น.\nสิ่งที่น่าสังเกตคือ มิลียาห์มมีความหลงใหลและเคารพต่อธูลูอย่างผิดปกติ แม้ว่าธูลูจะไม่ได้แสดงท่าทีพิเศษใดๆ ต่อเธอ.\nหากมีความจำเป็นต้องติดต่อกับมิลียาห์ม การขอให้ธูลูช่วยอาจทำให้สถานการณ์เปลี่ยนแปลงไปในทางที่ดีขึ้น."
  },
  AwakerStory_11196_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11196_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11197_Content = {
    Text = "หลังจากถูกปลุกตื่นเป็นเวลา 3 เดือน นักสืบและผู้พิทักษ์ได้จัดงานเลี้ยงให้กับนอติลา ไม่ใช่เพื่อเฉลิมฉลองที่เธอมาอยู่ที่นี่ แต่เพื่อเฉลิมฉลองที่เธอจำชื่อมหาวิทยาลัยมิซากะได้ในที่สุด\nแม้ว่าเธอจะลืมไปในวันถัดมา แต่ก็ยังสามารถจัดงานเลี้ยงได้อีกครั้ง ใครจะรู้ บางทีในอีก 3 เดือนข้างหน้าเธออาจจะจำได้จริงๆ\nยากที่จะบอกว่าสมองของนอติลาเหมือนปลาทองนั้นเป็นผลจากการย่อยสลายหรือผลจากการขาดเงินใจ แต่ความจำระยะสั้นก็ไม่ได้หมายความว่าเป็นเรื่องไม่ดีเสมอไป สำหรับช่างซ่อมที่ทำงานอย่างจริงจัง การลืมว่าสกรูตัวไหนต้องหมุนหมายถึงการต้องหมุนทุกตัวใหม่อีกครั้ง สองครั้ง สามครั้ง... ดังนั้น เครื่องมือที่ผ่านการซ่อมแซมโดยมือของนอติลา มักมีโครงสร้างที่แข็งแรงกว่าค่าเฉลี่ยและมีอายุการใช้งานที่ยาวนานกว่า\nดอลล์จึงชอบเธอมาก เพราะไม่ใช่ทุกคนที่จะมีฝีมือในการซ่อมที่เทียบเท่ากับการทำงานสิบปี。"
  },
  AwakerStory_11197_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11197_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11198_Content = {
    Text = "ดอลล์เคยทำการศึกษาเธออย่างละเอียดมาก แต่ไม่ว่าจะเป็นลำตัวหรือแขนขา ไม่ว่าจะเป็นกะโหลกหรืออุ้งเชิงกราน ก็ไม่พบส่วนประกอบใดๆ ที่สนับสนุนให้เธอพูดได้ เธอพูดได้อย่างไร—นี่กลายเป็นหนึ่งในปริศนาที่ไม่มีคำตอบมากมายของมิซากะ \n ในกรณีส่วนใหญ่ เธอสามารถสื่อสารกับคนได้ตามปกติ แต่บางครั้ง ส่วนประกอบเสียงลึกลับนั้นก็เหมือนมีจิตสำนึกของตัวเอง จะพูดสิ่งที่ทำให้รู้สึกขนลุกและเย็นยะเยือก。"
  },
  AwakerStory_11198_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11198_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11199_Content = {
    Text = "ฮันนา: คุณยังจำได้ไหมว่าเกิดอะไรขึ้นก่อนที่คุณจะถูกทำลาย?\nเอริกา: พฤติกรรมของตุ๊กตาจักรกลเริ่มควบคุมไม่ได้ จิตสำนึกเกิดการขาดช่วง และในช่วงขาดช่วงนั้นจะทำลายทุกสิ่งทุกอย่าง ทุกสิ่งจะถูกทำลายภายใต้กระแสไฟฟ้าและเปลวไฟ\nฮันนา: เอริกา?\nเอริกา: ……\nฮันนา: ฉันคงโชคดีไม่พอที่จะเจอ「ผลกระทบจากคนติ๊กต๊อก」ใช่ไหม... เอริกา?\nเอริกา: ส่วนประกอบในหัวกลับมาทำงานแล้ว ขอโทษสำหรับความไม่สะดวกเมื่อกี้\nตามที่ฉันได้กล่าวไปแล้ว ตุ๊กตาจักรกลสังเกตเห็นว่าความเป็นอันตรายต่อมนุษย์ของตนค่อยๆ เพิ่มขึ้น และเนื่องจากตุ๊กตาจักรกลยังคงมองว่าตนเป็นมนุษย์อยู่ จึงรู้สึกเจ็บปวดมาก\nฮันนา: การปกป้องที่คุณพูดถึงหมายถึงการปกป้องมนุษย์ใช่ไหม?\nเอริกา: ตุ๊กตาจักรกลหวังที่จะปกป้อง ใช่แล้ว\nฮันนา: แล้วทำไมคุณไม่บอกฉันเมื่อกี้ล่ะ?\nเอริกา: ……\nฮันนา: คุณต้องการให้ฉันถามคำถามใหม่ไหม?\nเอริกา: ไม่ ตอนนี้ฉันไม่ถูกอารมณ์รบกวน สามารถตอบได้\nเมื่อรู้สึกถึงความเป็นอันตราย ตุ๊กตาจักรกลพยายามทำให้ร่างกายเกิดความลัดวงจรในช่วงที่จิตสำนึกขาดช่วง เพื่อลดความเป็นไปได้ในการทำลายร่างกายของตน\nการปกป้องสุดท้ายกลับล้มเหลว เพื่อนมนุษย์เสียชีวิต\nตุ๊กตาจักรกลรู้สึกเศร้า เสียใจ สิ้นหวัง\nตุ๊กตาจักรกลระเบิดทำลายตนเอง เพื่อให้แน่ใจว่าจะไม่ทำลายเพิ่มเติม แล้วเงินใจถูกมหาวิทยาลัยมิซากะนำไปกู้คืน ทำให้เกิดฉัน เอริกา รหัสร่าง EA307881\n——คัดลอกจากการบันทึกเสียงของฮันนา พีสลี ที่มีชื่อว่า《0711 สัมภาษณ์คนติ๊กต๊อก》"
  },
  AwakerStory_11199_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11199_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11200_Content = {
    Text = "หมู่บ้านประมงที่น้ำทะเลใสแจ๋ว ในคืนกลางฤดูร้อนถูกตกแต่งเป็นชายหาดที่มีทางช้างเผือก ประดับด้วยเสียงหัวเราะที่เบาๆ ของรถบ้าน—ความทรงจำที่ไม่มีอยู่จริงเหล่านั้นจะปรากฏขึ้นเป็นครั้งคราว แล้วก็ถูกลืมไปในทันที \nเพียงแค่มีเพื่อนอยู่ข้างๆ ที่อุบัติขึ้นอย่างต่อเนื่อง ก็สามารถสร้างความทรงจำใหม่ได้เสมอ ยิ่งไปกว่านั้น แมงกะพรุนก็อยู่ที่นี่ด้วย—ออริตาก็คิดเช่นนั้น \nท้ายที่สุดแล้ว การสืบพันธุ์และการเพิ่มจำนวนในกระแสน้ำ เพื่อต่อต้านศัตรูที่แข็งแกร่งด้วยการสะสมจำนวน เป็นธรรมชาติและโชคชะตาของแมงกะพรุน。"
  },
  AwakerStory_11200_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11200_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11201_Content = {
    Text = "「ระวังแพนเดียให้ดี อันตรายของเธอไม่เหมือนกับภาพลักษณ์ภายนอกเลยแม้แต่น้อย เธอคือปีศาจ」\nคำพูดนี้เป็นผลสรุปจากประสบการณ์เต็มไปด้วยน้ำตาเลือดของเหล่านักสืบหลายคนที่ผ่านเรื่องนี้มา\nแพนเดียมักสร้างกับดักหวานๆ เพื่อหลอกล่อให้นักวิจัยคนอื่นๆ หรือผู้ที่ตื่นขึ้นมาบรรลุข้อตกลงในการเป็นนายบ่าวกับเธอ หลังจากนั้นก็รังแกและเล่นสนุกกับความรู้สึกและจิตวิญญาณของพวกเขา\nการพูดคุยกับแพนเดียมักจบลงโดยไร้ผล เธออ้างว่าเธอเพียงสร้าง แบ่งปัน และหว่านเมล็ดพันธุ์แห่งความสุขกับคนรักใหม่ของเธอ และทุกสัญญาที่ทำขึ้นนั้นก็เป็นการสมัครใจทั้งสิ้น ท้ายที่สุดแล้ว เธอก็ได้ให้บรรดาทาสลองลิ้มรสความหวานหวานของผลไม้นั้นเช่นกัน\nอย่างไรก็ตาม ในมหาวิทยาลัยก็มีตัวตนที่เป็นศัตรูของแพนเดียอยู่ เมื่อโซเรลเดินผ่านหน้าประตูห้องพักของแพนเดีย ไม่ว่าแพนเดียจะกำลังพูดคุยหัวข้อใดอยู่ เธอก็จะเงียบลงในทันที มีข่าวลือว่าแพนเดียเคยพ่ายแพ้อย่างย่อยยับเมื่อลองใช้เล่ห์กลกับโซเรล แต่ข้อเท็จจริงยังคงเป็นปริศนามาจนถึงทุกวันนี้。"
  },
  AwakerStory_11201_Title = {
    Text = "เรื่องราว·2"
