  AwakerStory_11201_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11202_Content = {
    Text = "ปี A.F. 297 วันที่ @1 เดือน @1 เวลา 03:47 น. เกิดการระเบิดที่ไม่ทราบต้นเหตุทางทิศตะวันออกเฉียงใต้ของเมือง @1@2@1 ในสาธารณรัฐอาร์เจนโต คลื่นกระแทกทำให้เกิดแผ่นดินไหวระดับ 3.8 ในพื้นที่ ซึ่งรู้สึกได้ชัดเจน และส่งผลกระทบไปยังหมู่บ้านที่อยู่ห่างจากเมือง @1@2@1 ประมาณ 5 กิโลเมตร \n หลังเกิดเหตุ เมือง @1@2@1 และพื้นที่อื่นๆ สูญเสียการติดต่อกัน และประชาชนรอบข้างไม่สามารถนึกถึงที่ตั้งของเมืองนี้ได้ ด้วยเหตุนี้ คณะกรรมการตรวจสอบจึงส่งสมาชิกไปทำการสอบสวน และตรวจพบสารหลอมละลายที่ขอบเมือง @1@2@1 \n หลังจากปิดล้อมเมืองนี้ นักสืบจากมหาวิทยาลัยมิซากะได้ทำการกำจัดร่างหลอมละลาย และได้เก็บกู้เงินใจ E-1929 จากพื้นที่ที่มีการหลอมละลายอย่างรุนแรงซึ่งสงสัยว่าเป็นศูนย์กลางการระเบิด \n E-1929 มีลักษณะเฉพาะ คือ ดัชนีนอร์สอยู่ในสถานะการผันผวนที่ไม่ปกติเป็นเวลานาน และจะผลิตเสียงคล้ายการหมุนของเกียร์ออกมาเอง โดยสามารถรักษาความเสถียรชั่วคราวได้ก็ต่อเมื่อเชื่อมต่อกับเศษชิ้นส่วนเครื่องจักรที่เก็บมาจากพื้นที่หลอมละลายอย่างรุนแรง ด้วยเหตุนี้ มหาวิทยาลัยมิซากะจึงใช้ระบบปลุกตื่นห่อหุ้ม E-1929 ด้วยเศษชิ้นส่วนเครื่องจักร และทำการปลุกตื่นอย่างรวดเร็วเมื่อดัชนีนอร์สเริ่มมีแนวโน้มเสถียร \n——《สรุปรายงานการเก็บกู้และปลุกตื่นเงินใจ E-1929》"
  },
  AwakerStory_11202_Title = {
