  AwakerStory_11203_Content = {
    Text = "ก่อนที่ไฟแห่งประวัติศาสตร์จะเผาทุกสิ่ง อกริปปาก็เป็นไข่มุกที่ส่องแสงที่สุดของคาปัว \n เธอทำตามใจชอบ แส้หนังมักจะฟาดไปที่กลาดิเอเตอร์ที่เงียบงันอย่างรุนแรง; เธอไม่ชอบให้คนมองตรงๆ เพราะมันจะเปิดเผยความอ่อนแอในใจของเธอ แต่ถ้าพูดถึงการฝึกสอนทาส อกริปปาก็เป็นมืออาชีพเลยทีเดียว อาจจะทำให้คุณสนใจไปเยี่ยมชมแส้หนังยี่สิบเส้นที่มีรูปแบบแตกต่างกันในห้องนอนของเธอ—ที่เตรียมไว้เพื่อคุณโดยเฉพาะ。"
  },
  AwakerStory_11203_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11203_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11204_Content = {
    Text = "ผมดำอ่อนนุ่ม แก้มที่อวบอิ่ม ดวงตาสว่างสดใสราวกับอัญมณี และริมฝีปากสีแดง——ตั้งแต่เด็ก คาเรนได้รับการปฏิบัติอย่างดีเพราะความงามที่เกิดมาของเธอ เมื่อโตขึ้น ชายหนุ่มต่างส่งของขวัญและดอกไม้มาให้ทุกวัน จนสามารถกองเป็นภูเขาอยู่หน้าประตูบ้านเธอได้ ดังนั้นเมื่อผู้ดูแลในพระราชวังประกาศว่าจะพาเธอเข้าไปในพระราชวัง เพื่อฝึกเป็นสาวรับใช้ที่มีเกียรติของพระราชา เธอจึงไม่รู้สึกแปลกใจ นี่ไม่ใช่สิ่งที่ควรจะเป็นหรือ? เธอเกิดมาเพื่อให้ผู้คนอิจฉา เธอเกิดมาเพื่อให้แตกต่าง และเธอเกิดมาเพื่อเป็นจุดสนใจของทุกคน\nแต่ในพระราชวังกลับมีความงามมากมาย แม้ว่าดอกไม้จากเมืองเล็กจะน่าทึ่งเพียงใด ที่นี่กลับดูธรรมดาและเรียบง่าย ความงามไม่สามารถมอบสิทธิพิเศษให้เธอได้อีกต่อไป แม้แต่โอกาสที่เธอเฝ้าฝันว่าจะได้เข้าไปในห้องโถงเพื่อรับใช้ในงานเลี้ยงร้อยปี ก็ถูกแย่งไปโดยสาวอีกคน\nทำไมล่ะ? สิ่งที่สาวคนนั้นมี คาเรนก็มี ทำไมมันจึงไม่ใช่เธอ?\nแล้วเธอก็เห็นเครื่องประดับหูเงินที่ห้อยอยู่ที่หูของอีกฝ่าย จึงเข้าใจในทันที\nในวันงานเลี้ยง เธอจึงจมน้ำสาวคนนั้นในทะเลสาบ และสวมใส่เครื่องประดับหูเงินขาวนั้น เธอได้เป็นสาวรับใช้ที่โดดเด่นที่สุด และยังได้รับอนุญาตให้เข้าไปรับใช้อยู่ข้างๆ พระราชา การมองที่เต็มไปด้วยความอิจฉาและความริษยา ทำให้เธอรู้สึกมีความสุขอย่างยิ่ง——ใช่แล้ว ใช่แล้ว ทุกอย่างควรเป็นแบบนี้ นี่คือวันแห่งความสุขที่สุดในชีวิตของเธอ\nจากนั้น เธอก็พบจุดจบของชีวิตท่ามกลางหมอกสีเขียวที่กลืนกินทั้งเมืองหลวง"
  },
  AwakerStory_11204_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11204_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11205_Content = {
    Text = "ความฝันคือการโปรเจ็กชันของความทรงจำ เป็นภาพสะท้อนของชีวิตประจำวัน เป็นการรวบรวมของมนุษย์เอง\nตั้งแต่เด็ก ราโมน่ามักจะฝันซ้ำๆ เหมือนเดิม\nในน้ำอุ่นและขุ่น เธอมีความสัมพันธ์อย่างใกล้ชิดกับสิ่งที่ไม่รู้จัก เสียงกลองที่ว่างเปล่าและมีจังหวะซ้ำๆ สร้างคลื่นในน้ำ\nเมื่อความฝันสิ้นสุดลง มักจะรู้สึกว่ามีบางสิ่งว่างเปล่าในใจ เหมือนมีบางอย่างถูกพรากไปจากชีวิตของเธอ\nแต่เพื่อไม่ให้พ่อแสดงสีหน้ากังวล และเพื่อไม่เพิ่มความยุ่งยากให้กับครูที่ยุ่งอยู่แล้ว ราโมน่าจึงกลืนคำถามที่เกือบจะหลุดออกจากลำคอ กลับไปสู่ชีวิตประจำวัน。"
  },
  AwakerStory_11205_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11205_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11206_Content = {
    Text = "สิ่งที่เธอประสบในโลกนี้ดูเหมือนจะมีไว้เพื่อทำให้เธอทุกข์ทรมาน ความดี ความอดทน ความเห็นอกเห็นใจ ความไว้วางใจ... ทุกสิ่งที่เป็นส่วนอ่อนนุ่มของมนุษย์ถูกตัดออกจากหัวใจของเธอ ทิ้งไว้เพียงเนื้อและเลือดที่เปรอะเปื้อนไปหมดแล้ว \n ในพจนานุกรมของเธอไม่เคยมีคำว่าให้อภัย สิ่งที่สามารถยุติเลือดและความเกลียดชังได้มีเพียงเลือดและความเกลียดชังของผู้อื่นเท่านั้น \n เลือดตอบแทนเลือด นี่คือกฎที่ยุติธรรมที่สุด ซึ่งทั้งนักรบและทาสต่างก็เชื่อถือ \n ภูเขาไฟที่กลั้นใจมานานนับพันปีปะทุขึ้นในชั่วข้ามคืน มือข้างหนึ่งยื่นออกมาจากแดนมรณะ ขึ้นมาเหยียบดินแดนมนุษย์ \n นั่นคือปีศาจแห่งการแก้แค้น ที่จะทำให้แม่น้ำสีแดงไหลเวียนไปทั่วโลกมนุษย์。"
  },
  AwakerStory_11206_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11206_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11207_Content = {
    Text = "「แม่ แม่ ลิลลี่ไม่ได้ร้องไห้ตอนฉีดยา!」\n「ลิลลี่เก่งมาก!」\n「อืม ลิลลี่ไม่เจ็บ ลิลลี่คิดถึงแม่ที่จะกลับมาอยู่กับลิลลี่ ก็เลยรู้สึกไม่เจ็บแล้ว!」\n……\n「เจ้านาย ให้ฉันทำคำสั่ง」\n「ไปนอนบนโต๊ะผ่าตัดให้เรียบร้อย ผ่านไปสิบห้านาทีจะเริ่มการผ่าตัด กินยาเป็นเวลาหรือยัง?」\n「กินแล้ว เจ้านาย」\n「กรีดตรงนี้ ไม่เจ็บใช่ไหม?」\n「……ไม่เจ็บ เจ้านาย」"
  },
  AwakerStory_11207_Title = {
    Text = "เรื่องราว·3"
