  AwakerStory_11207_UnlockDesc_1 = {
    Text = "ผ่านด่านเนื้อเรื่องหลักธรรมดาบทที่ 4 「ท่ามกลางความเงียบงัน」"
  },
  AwakerStory_11208_Content = {
    Text = "ฮอร์ล่ารู้สึกเหมือนมีพลังมหัศจรรย์ที่แปลกประหลาด นักเรียนที่มีความใฝ่ฝันในบทกวีและความงามมักจะถูกดึงดูดเข้าหาเธอและรวมตัวอยู่ข้างๆ เธอเสมอ \nฮอร์ล่าไม่ชอบที่จะเผยแพร่บทกวีของตนเอง แต่เหล่านักเรียนมิซากะยังคงพยายามหาวิธีเพื่อดูคำพูดบางส่วนของเธอ บทกลอนที่ไหลออกมาจากปลายปากกาของเธอมักจะโด่งดังไปทั่ววิทยาเขตในเวลาอันสั้น \nเมื่อยามเช้าตรู่มีน้ำค้างเกิดขึ้น มีคนอยู่ใต้หอนาฬิกาที่อ่านคำของเธอเบาๆ; ในยามพลบค่ำ นิมเฟียนั่งอยู่บนม้านั่งในจัตุรัสมิซากะ พลิกดูหนังสือรวมบทกวีของเธอ; หลังจากที่ค่ำคืนมาถึง นักเรียนจะมารวมตัวกันในห้องโถงเพื่อซ้อมการแสดงบทที่เธอเขียนขึ้น \nแต่ถึงแม้จะได้รับคำเชิญอย่างอบอุ่น ฮอร์ล่าก็ไม่ค่อยจะมองไปที่กิจกรรมเหล่านี้เลย ยิ่งไม่ต้องพูดถึงการเข้าร่วมด้วยซ้ำ เสียงที่แสดงอารมณ์โศกเศร้าและสถานการณ์ที่ทำให้ต้องน้ำตาไหลมักทำให้เธอรู้สึกไม่รู้จะทำอย่างไร \n「ฉันแพร่กระจายความโศกเศร้าใหม่อีกแล้วหรือ?」"
  },
  AwakerStory_11208_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11208_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11209_Content = {
    Text = "รามอน่า ปรากฏตัวครั้งแรกในมหาวิทยาลัย ทำให้เกิดกระแสฮือฮา\nที่มหาวิทยาลัยมิซากะ ซึ่งเต็มไปด้วยผู้ปลุกตื่นและคนแปลกหน้า การมีผมสีเงินและดวงตาสองสีไม่ใช่ลักษณะที่น่าจับตามอง สิ่งที่ทำให้รามอน่าเป็นที่สนทนาคือสถานะ「ลูกสาวของศาสตราจารย์」\nทุกคนยืนอยู่หน้าสำนักงานภาควิชาคณิตศาสตร์ หวังที่จะได้เห็นความงามของคุณท่านเดกสเตอร์ คนมันเยอะเกินไป ศาสตราจารย์จึงต้องขอความช่วยเหลือจากคุณโลทัน เพื่อให้ทุกคนแยกย้ายกันไปอย่างเสียใจ\nเมื่อรามอน่าโตขึ้นอีกนิด ศาสตราจารย์ก็เริ่มวางใจปล่อยให้เธอวิ่งเล่นในมหาวิทยาลัยได้ จนกระทั่งนักเรียนที่ถูกโลทันไล่ไป สามารถกลับมาหาโอกาสพูดคุยกับเธอได้\n「คุณลอร์ดคือใคร? ขอโทษนะ ตัวละครนี้ยังไม่มีอยู่จริง ฉันเป็นเด็กกำพร้า พ่อของฉันใจดีรับเลี้ยงฉัน」\nเพื่อหลีกเลี่ยงการรบกวน เด็กหญิงตัวเล็กพูดความจริงอย่างใจเย็น ขณะที่ทุกคนรู้สึกผิด เธอก็เดินจากไปอย่างสง่างาม."
  },
  AwakerStory_11209_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11209_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11210_Content = {
    Text = "นั่นคือ... แสงสว่างและคลื่นความร้อนที่ทำให้ตาลาย ความสุดเหวี่ยงของความสนุกสนานที่เต็มไปด้วยสีสัน \n เสียงเชียร์ดังก้องเหมือนคลื่นทะเลอยู่ใกล้หู นักรบอาบเลือดและเกียรติยศอยู่ในสนาม \n สาวน้อยกลับบ้านอย่างเซ็งๆ เธอยังคงฟาดแส้ใส่นักกลาดิเอเตอร์ที่อยู่ตรงหน้าอย่างไร้ความปรานี \n\n ที่นี่คือสนามรบของเธอ \n\n ไม่มีการต่อสู้ที่ดุเดือด ไม่มีดอกไม้และเสียงปรบมือ นักรบผู้สูงใหญ่เป็นกวางที่เชื่องที่สุด คำด่าทอและความโกรธของเธอเหมือนถูกดูดซับเข้าไปในความมืดมิด ไม่มีลมแม้แต่เส้นเดียวเหลืออยู่เลย。"
  },
  AwakerStory_11210_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11210_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11211_Content = {
    Text = "แตกต่างจากพี่สาวที่มีรูปร่างเล็กน่ารักที่มองเห็นได้ชัดเจน ทิงค์เทตมีความผิดปกติในด้านอื่นๆ \nไม่ว่าจะเป็นมิสเซิลโทหรือปูที่อาศัยอยู่ ทิงค์เทตดูเหมือนจะเป็นสิ่งมีชีวิตทางจิตวิญญาณที่ไม่สามารถมีชีวิตอยู่ได้หากไม่มีบุคคลอื่น \nในดาวที่แห้งแล้ง เธอทำทุกอย่างเพื่อรักษาโรคของเฟนท์ เธอเต็มใจที่จะลองทุกวิถีทางที่จะรักษาชีวิตพี่สาว แม้ต้องจ่ายในราคาที่ต้องจ่ายที่คนธรรมดาไม่สามารถทนได้ \nเธอไม่สนใจการเยาะเย้ยและดูถูกจากชนชั้นสูง แต่กลับทำธุรกรรมที่ไม่เท่าเทียมกับพวกเขาด้วยความสงบและอ่อนโยนตลอดไป และแม้กระทั่งขอความเห็นใจจากพวกเขา——ความเห็นใจนั้นทำให้เธอมีที่นั่งหลบหนีจากดาวที่แห้งแล้ง และเมื่อเธอได้มาในช่วงเวลานั้น เธอก็ไม่ลังเลที่จะมอบให้เฟนท์ \nเฟนท์กลับผลักทิงค์เทตขึ้นไปบนกระแสดาวเพื่อหลบหนีจากดาวที่แห้งแล้งในช่วงสุดท้าย——หวังว่าน้องสาวจะสามารถหลุดพ้นจากตัวเองและเริ่มต้นชีวิตใหม่บนดาวดวงใหม่ \nแต่เมื่อดาวที่แห้งแล้งถูกทำลาย ทิงค์เทตก็เริ่มต้นการเดินทางที่ไร้ตัวตนเพื่อตามหาเฟนท์ โดยไม่สนใจที่จะถูกคนอื่นควบคุมและจัดการ ทิงค์เทตแบบนี้ถูก@2คริสตจักรค้นพบ และถูกส่งต่อไปยัง@3 \nทิงค์เทตไม่เคยต่อต้าน อาจจะพูดได้ว่า ทิงค์เทตหวังว่าจะมีใครสักคนมาบอกเธอว่าควรทำอย่างไรดีที่สุด——แม้ว่ามันจะเป็นการโกหก การหลอกลวง หรือความฝันที่อยู่ได้เพียงชั่วขณะ ก็ยังดีกว่าการยืนอยู่ที่นั่นอย่างไม่รู้จะทำอย่างไร \nอย่างน้อย นั่นหมายความว่าอนาคตของเฟนท์ยังมีความหวัง."
  },
