  AwakerStory_11219_Content = {
    Text = "ในขณะที่รามอน่าถูกครอบงำ รามอน่ายังไม่เคยเดินอยู่ในมหาวิทยาลัยเลย \nโลทันที่มีความกล้าหาญ โอเกียร์ที่มีความซื่อสัตย์และขี้อาย วิลเลียมที่มีความสงบและมีสติ ดอลล์ที่มีความเข้มงวดและจริงจัง... ไม่มีใครที่จดจำช่วงเวลาเหล่านี้ได้ดีไปกว่าหญิงสาวคนนี้ \nแต่เธอยังคงระลึกอยู่เสมอว่า สิ่งดีๆ เหล่านี้ไม่ใช่ของเธออีกต่อไป \nตอนนี้เธอต้องมุ่งมั่นในการปกป้องบุคคลที่ถูกกำหนดอีกคนหนึ่ง... นี่คือการปกป้องโลกที่กำลังตกอยู่ในอันตรายอีกใบหนึ่ง เพื่อปกป้องตัวเองที่ไร้เดียงสาอีกคนหนึ่ง。"
  },
  AwakerStory_11219_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11219_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11220_Content = {
    Text = "มือที่คล่องแคล่วเกินไปของแจนจิน ทำให้คนกังวลว่าเธออาจจะกลายเป็นแขกประจำคนใหม่ของหนังสือพิมพ์มหาวิทยาลัยเมสซากา—ไม่ใช่ในฐานะที่เธอถูกสัมภาษณ์ แต่ในฐานะตัวการของเหตุการณ์ขโมยหลายๆ ครั้ง \nแม้ว่าในท้ายที่สุดเธอจะกลายเป็นแขกประจำหนังสือพิมพ์มหาวิทยาลัยเมสซากาจริงๆ แต่ก็ไม่ใช่เพราะเธอยังติดนิสัยเดียวเดิม—แค่เพียงมีเค้กขนาดเล็กพอ เธอก็พร้อมที่จะละทิ้งวิถีเก่า ใช้ชีวิตเกษียณแบบสุขสบายไปพร้อมกับหนูผู้ร่วมทางของเธอ \nเหตุผลเดียวที่เธอปรากฏตัวในข่าวบ่อยครั้งก็เพราะกองบรรณาธิการข่าวให้อะไรมากจนปฏิเสธไม่ลง \nเงียบไว้ก่อน—เบาเสียงหน่อย คุณไม่มีทางรู้เลยว่าเธออาจซ่อนตัวในมุมไหน และเตรียมใช้ข้อมูลที่ได้ยินไปแลกขนมหวานและเค้กจากฮันน่าเพิ่มเติม。"
  },
  AwakerStory_11220_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11220_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11221_Content = {
    Text = "ดาวรุ่งแห่งวิทยาศาสตร์และความรู้ได้ผุดขึ้นในครอบครัวคนงานธรรมดา \nส่วนใหญ่ของวัยเด็กของดอร์เต็มไปด้วยเสียงการกระตุ้นของกระบอกสูบและการทำงานของเกียร์ \nแต่ความรักในเครื่องจักรไม่เพียงพอที่จะสนับสนุนสาวน้อยในการปีนขึ้นภูเขาวิทยาศาสตร์ที่ขรุขระและยากลำบาก \nสิ่งที่นำเธอเข้าสู่เส้นทางการแสวงหาความรู้คือการระบาด \nความบ้าคลั่งที่ไม่รู้จักแพร่กระจายในเมือง โรงพยาบาลเต็มไปด้วยผู้คน ห้องเก็บศพเกินความสามารถ ทุกคนต่างหวาดกลัว \n「สุสานทั้งเมืองไม่เพียงพอ ต้องขุดคุณยายออกมาและเผาคุณแม่ คุณต้องเลือกอย่างใดอย่างหนึ่ง」 \nดังนั้น ดอร์จึงส่งแม่ของเธอหายไปในเปลวไฟ \nแตกต่างจากผู้ที่ถูกเผาอื่นๆ ชิ้นส่วนกระดูกและเถ้าถ่านที่เธอเคยเรียกว่า「แม่」มีประกายเงินไหลเวียนอยู่ \n「ฉันอยากรู้ว่าฉันจะได้พบเธออีกหรือไม่」 \n「ฉันอยากรู้ว่ามีวิญญาณที่ดีของเธออยู่ในนั้นหรือไม่」 \n「ฉันอยากรู้ว่าสารเงินนั้นเป็นต้นกำเนิดของชีวิตหรือไม่ เป็นสาระสำคัญของวิญญาณหรือไม่」 \n「ฉันอยากรู้ว่าสรรพสิ่งทั้งหมดมีจุดเริ่มต้นร่วมกันหรือไม่」 \nก่อนที่จะได้รับคำตอบ ดอร์จะไม่ยอมแพ้ต่อปรากฏการณ์การหลอมละลาย"
  },
  AwakerStory_11221_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11221_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11222_Content = {
    Text = "เงาร่างอันแผ่วเบาของเธอทำให้ผู้คนคิดถึงนกนางแอ่นที่กระพือปีกต้องการบิน เมื่อกระโปรงขาวปลิวไปตามลมทะเล ผู้ชมมักจะสามารถจินตนาการถึงภาพนกที่บินไปยังยูโทเปียได้เสมอ \n ไม่รู้ว่าสาวน้อยที่นั่งอยู่บนขวางเสาของเรือ เคยจินตนาการถึงการล่องลอยของตัวเองหรือไม่?"
  },
  AwakerStory_11222_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11222_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11223_Content = {
    Text = "ต่างหูทับทิม สร้อยคอแซฟไฟร์ เครื่องประดับผมสวยงามที่ถักทอจากหินทับทิมและมาลาไคต์... มันช่างเปล่งประกาย ช่างงดงาม และมีเสน่ห์เหลือเกิน เมื่อมันไปถึงที่ไหน ผู้คนต่างก็แห่แหนไปที่นั่น \n เครื่องประดับเหล่านี้ไม่ใช่ 「ของตกแต่ง」 แต่มันคือพระเอกของโลกนี้ สาวชนชั้นสูงที่สวมสร้อยคอเทอร์ควอยส์ถูกบรรจุลงในบทเพลงของกวีเพื่อให้ผู้คนขับร้อง; สตรีสูงวัยที่ห้อยหินอเมทิสต์ที่หูของพวกเธอก็ถูกมองว่าเป็นสัญลักษณ์แห่งความสูงส่ง แม้กระทั่งเด็กหญิงที่มีฐานะต่ำต้อยเหมือนเธอ ก็สามารถได้รับฉายาว่า 「สาวไข่มุก」 ด้วยสร้อยข้อมือราคาถูกที่อยู่บนข้อมือดึงดูดสายตาของผู้คนมากมาย \n แม้แต่กิ่งไม้แห้งหรือซากศพเน่าเปื่อย หากแขวนด้วยเครื่องประดับที่สวยงาม ก็จะกลายเป็นวัตถุที่ทุกคนแสวงหา \n หากเธอสามารถสวมสร้อยคอ ต่างหู หรือสร้อยข้อมือเหล่านั้นได้ เธอก็จะต้องกลายเป็นจุดสนใจของทุกคนแน่นอน。"
  },
  AwakerStory_11223_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11223_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11224_Content = {
    Text = "เหมือนกับเสียงที่ไพเราะจากกลีบตูมที่ส่งกลิ่นหอมหวานของน้ำผึ้ง ขุนนางคือผึ้งและผีเสื้อที่รายล้อมรอบเกสรดอกไม้ที่สั่นไหว \n ความปรารถนาที่รดน้ำไปยังพุ่มหนาม ได้พันรัดหน้าต่างดอกไม้แน่นหนาโดยไม่รู้ตัว \n แม้ว่าบุคลิกจะถูกผู้คนตำหนิ มือสองข้างจะถูกมงกุฎทำให้เลือดไหลโชก เธอก็จะไม่ปล่อยมือจากอำนาจที่ถูกกอดไว้ในอ้อมแขน \n เพราะท้ายที่สุด นี่คือสารอาหารที่แท้จริงที่ดอกกุหลาบต้องการในการเบ่งบาน。"
  },
  AwakerStory_11224_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11224_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11225_Content = {
    Text = "เธอเติบโตขึ้นภายใต้ความรักและคำสอนของสุภาพสตรีผู้นั้น กลายเป็นคนอ่อนโยนและใจดี เหมือนกับสุภาพสตรีผู้สูงศักดิ์อย่างแท้จริง แต่เพียงเพราะการช่วยเหลือทาสที่เธอไม่ได้ตั้งใจ เธอก็ถูก「พ่อแม่」ทอดทิ้งอย่างไร้หัวใจ\nชาวสปาร์ตาไม่เคยยอมรับเธอ และคนในชาติเดียวกันล้วนเกลียดชังเธอจนแทบอยากสังหาร\nชั่วพริบตาเดียว เธอกลายเป็นผู้ทรยศในสายตาของทุกคน เธอสูญเสียที่ทางในโลกนี้\nในเรือนจำ ทุกคนเปล่งกลิ่นร้ายออกมาอย่างหนาแน่น เหมือนโรคร้ายที่แพร่กระจายได้ ทั้งที่พวกเขาไม่เคยรู้จักกันมาก่อน\nความทุกข์ทรมานที่มืดมิดไร้ซึ่งแสงสว่างดูเหมือนจะเป็นนิรันดร์ เธอหวาดกลัวคนอื่นอย่างเสียสติจนไม่อาจหลับลงได้ เธอหลับได้ครั้งเดียวในยามหมดสติ แต่เมื่อตื่นขึ้นมาอีกครั้ง เธอก็ต้องกลับไปสู่ฝันร้ายที่ไม่มีจบสิ้น\nเธอทำผิดอะไร? ทุกสิ่งมาไกลถึงขั้นนี้ได้ยังไง?\nความแค้นของเธอเต็มไปด้วยความสับสน ไม่อาจหาเหตุผลของชะตากรรมได้\nเป็นเพราะเธอมีความผิดงั้นหรือ?\nแต่ถ้าเธอมีความผิด คนทั้งหมดก็ต้องรับความผิดนั้นด้วยสิบเท่า\nความเกลียดชังที่สะสมมากลายเป็นความโกรธแค้น ไฟแห่งความโกรธเผาไหม้ในเลือดของเธอตลอดวันและคืน และในที่สุดวันหนึ่งก็เผาผลาญคุกที่กักขังเธอเอาไว้\nโซ่ตรวนที่พันธนาการเธอมานานหลายปี บัดนี้พันคอของผู้คนที่กรีดร้องอย่างน่าเวทนา โซ่ตรวนที่หลอมรวมกับร่างกายของเธอมาเนิ่นนานเหมาะมือเธอยิ่งหนัก เธอถือโซ่ที่เปรอะเปื้อนกลิ่นเลือดเพื่อไล่ล่าวิญญาณที่แปดเปื้อนทีละดวง\nสีแดง สีแดง สีแดงอุ่นๆ สีแดงคาวเลือด\nดูสิ เธอรู้ดีว่าไม่มีวิญญาณของใครที่ขาวสะอาดเลย."
  },
  AwakerStory_11225_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11225_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11226_Content = {
    Text = "เธอรู้ทุกอย่าง\nเธอรู้ว่าหอนาฬิกาจะดังในช่วงเวลาฉุกเฉิน รู้ว่าฝนดาวตกโบเจียงจะมาถึงในอีกสิบปีข้างหน้า รู้ว่ามีพละกำลังที่แตกต่างไหลเวียนอยู่ในร่างกายของเธอ\nเธอไม่รู้ทุกอย่าง\nเธอไม่รู้สูตรเครื่องเทศลับในแกงของโรงอาหาร ไม่รู้วิธีคำนวณรัศมีหลังจากการทำลายล้างของดาวเคราะห์ ไม่รู้อนาคตของเธอจะถูกดึงไปทางไหน\nเธอยากจะตัดใจจากสิ่งรอบตัว แต่ก็ยากที่จะต้านทานเส้นทางที่สัญชาตญาณชี้นำเธอไป\nในการเดินทางสู่ความจริงและความถูกต้อง รามอน่าต้องเดินทางไปกับผู้ที่มุ่งมั่น เพื่อรักษาหนทางที่กลับสู่ชีวิตประจำวันของเธอ."
  },
  AwakerStory_11226_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11226_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11227_Content = {
    Text = "ถ้าเธอไม่ตื่นขึ้นก็ดีแล้ว คนที่จมอยู่ในความลึกไม่ควรลืมตาขึ้นมามองพระอาทิตย์ที่สว่างจ้า。\nเธอควรจะเป็นวัสดุทดลองที่ไร้ความรู้สึก เป็นคนที่ถูกโลกนี้ฝังกลบ ไม่ควรมีความรู้สึกเจ็บปวดหรือความปรารถนาในการได้รับความรัก。\nความผูกพันของแม่สร้างโศกนาฏกรรมในชีวิตของเธอ ขณะที่ลิลลี่ยังคงติดอยู่ในความสับสนว่า 「เธอควรเชื่อฟังการจัดการของโลกหรือไม่」。\nอาจจะมีวันหนึ่ง เธอจะได้คำตอบจากคนที่ต่อต้านชะตากรรม。"
  },
  AwakerStory_11227_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11227_UnlockDesc = {
