  AwakerStory_11227_UnlockDesc_1 = {
    Text = "ผ่านด่านเนื้อเรื่องหลักธรรมดาบทที่ 4 「ท่ามกลางความเงียบงัน」"
  },
  AwakerStory_11228_Content = {
    Text = "ฉันเหมือนจะตกอยู่ในเหตุการณ์เหนือธรรมชาติบางอย่าง ขอบันทึกสิ่งที่ค้นพบทั้งหมดไว้ที่นี่...\nเดิมทีเรากำลังดำเนินงานโบราณคดีขั้นสุดท้ายที่เอฟโรรตัส แต่เมื่อตื่นขึ้นมา สมาชิกทีมที่เหลือกลับหายไปหมด และเมืองนี้ก็เหมือนย้อนกลับไปเมื่อพันปีก่อนในชั่วข้ามคืน\nสิ่งปลูกสร้างโบราณที่พังลงมานานแล้วกลับตั้งตระหง่านขึ้นอีกครั้ง เผยให้เห็นสภาพเมืองที่แท้จริง รวมถึงซากกระดูกของประชากรจำนวนมากที่เคยอาศัยอยู่ในเมืองนี้ \nความตื่นเต้น, ตกใจ และหวาดกลัวต่างจับตัวฉันไว้ แม้ว่าเคยเห็นซากศพมามากมาย แต่สิ่งที่เห็นตรงหน้าก็ยังทำให้ฉันตัวสั่นไม่หยุด หากใครก็ตามได้เผชิญกับประสบการณ์เหมือนฉันในขณะนี้ เขาคงจะต้องหวาดผวามากกว่าฉันหลายเท่า \nดูเหมือนว่าทุกคนในเมืองนี้จะถูกสังหารอย่างโหดร้ายโดยบุคคลคนเดียว ซากกระดูกจำนวนมากเกลื่อนอยู่ตามถนนและในบ้าน ประตูเมืองถูกปิดแน่นไม่ทราบสาเหตุ ส่วนใกล้ประตูเต็มไปด้วยซากศพของผู้พยายามจะหนีแต่ก็ถูกฆาตกรรมอย่างโหดเหี้ยม เปรียบเสมือนเนินเขาที่สร้างขึ้นจากกองกระดูกขาว\nฉันไม่พบศพที่เป็นข้อยกเว้น ผู้ชาย ผู้หญิง คนชรา เด็กจำนวนมากถูกทุบด้วยอาวุธทื่อหรือสมองแตกเป็นเสี่ยงๆ เมื่อมองดูซากกระดูกเหล่านั้น อารมณ์สับสนยังทำให้ฉันเห็นภาพเมืองที่เต็มไปด้วยเลือดไหลล้นออกมาเหมือนภาพหลอน\nที่นี่มันเกิดอะไรขึ้นกันแน่?\n......\nฉันเดินสำรวจไปมาอย่างสับสน แต่ไม่มีเบาะแสใดๆ จนกระทั่งฉันเข้าสู่เรือนจำของเมืองนี้ \nสภาพภายในนี้ยิ่งน่ากลัวยิ่งกว่า ฆาตกรผู้ทำเช่นนี้ดูเหมือนเต็มไปด้วยความโกรธแค้น และได้ทำลายล้างทั้งเรือน จำ ผนังเต็มไปด้วยรอยตัวอักษรซึ่งบิดเบี้ยวและเป็นสีน้ำตาลแห้งคล้ายเขียนด้วยเลือด ราวกับมีใครสักคนเขียนสิ่งที่อยากกล่าวออกมาก่อนตาย ฉันพินิจดูดีๆ ดูเหมือนตัวอักษรที่เขียนไว้จะเป็นคำว่า วิญญาณอาฆาต\nวิญญาณอาฆาต? นี่หมายถึงฆาตกรที่ทำการสังหารนี้ หรือว่าเมืองนี้ประสบกับเหตุการณ์เหนือธรรมชาติจริงๆ?\nแน่นอนว่า การฆ่าล้างชีวิตทั้งเมืองด้วยคนเพียงคนเดียวมันเหลือเชื่อจนเกินไป คงมีแต่ผีปีศาจผู้ชั่วร้ายเท่านั้นที่จะสามารถเก็บเก็บชีวิตจำนวนมากเช่นนี้ไปอย่างโหดเหี้ยม\nหลังจากเดินออกมาจากเรือนจำ เมืองนี้ดูเหมือนจะเกิดการเปลี่ยนแปลงบางอย่างที่ละเอียดอ่อน ฉันเริ่มได้กลิ่นเลือดจางๆ ที่เหมือนกับปรากฏแล้วหายไป\nในขณะที่ฉันพยายามหาทางออก เสียงโซ่ที่คาดไม่ถึงกลับดังขึ้นมาโดยปริยาย ทั่วเมืองเหมือนมีใครบางคนกำลังลากของหนักอันใหญ่โตเดินไปมา\nวิญญาณอาฆาต! เป็นมัน...มันหาเจอฉันแล้ว! ฉันพยายามวิ่งหนีสุดชีวิต แต่ไม่ว่าฉันจะวิ่งไปที่ไหน เสียงลากโซ่ที่น่าหวาดกลัวนั้นกลับตามติดฉันไปตลอด\nฉันหมดแรงที่จะวิ่ง ต้องเข้าไปหลบอยู่ใต้โต๊ะในบ้านหลังหนึ่ง ฉันล็อคประตูอย่างแน่นหนา แต่เสียงลากโซ่นั่นก็ยังมาหาฉัน ฉันได้ยินเสียงมัน เดินมาใกล้เรื่อย ๆ ...\nฉันหวังเหลือเกินว่าความทั้งหมดนี้เป็นเพียงแค่ฝัน เมื่อฉันตื่น ความน่ากลัวทั้งหมดนี้จะหายไป เดี๋ยวนะ...เสียงนั้นเหมือนจะหายไปแล้ว บางทีวิญญาณอาฆาตอาจจะจากไปแล้วก็ได้?\n......\nบันทึกของเจ้าหน้าที่วิจัย: ลายมือที่เขียนปกติสิ้นสุดตรงนี้ เหลือลายมือสามคำสุดท้ายที่บิดเบี้ยวและอ่านยาก หลังจากมีการวิเคราะห์ คำสามคำนี้น่าจะเป็น:\nประตูเปิดแล้ว\n——ตัดตอนจากไดอารี่ของสมาชิกทีมโบราณคดีเอฟโรรตัสผู้ล่วงลับ"
  },
