  AwakerStory_11237_Content = {
    Text = "รายงานเหตุการณ์ผิดปกติของเขตโบสถ์ลอนดีเนี่ยน (ลับ)\n\nA.F. 315 @2เดือน@3วัน ในเหตุการณ์ผิดปกติของเขตโบสถ์ลอนดีเนี่ยน บิชอปซัลวาดอร์ได้ใช้พลังของ「พระพร」เพื่อรักษาผู้พิทักษ์มิซากะและชาวเมืองลอนดีเนี่ยนที่อยู่ในที่เกิดเหตุ ทำให้เปิดเผยตัวตนของเขาในฐานะผู้ปลุกตื่น\nในระหว่างกระบวนการ เนื่องจากผู้เชื่อมโยงมีพลังจิตไม่เพียงพอ เพื่อหลีกเลี่ยงการส่งผลกระทบต่อผู้เชื่อมโยง บิชอปซัลวาดอร์จึงเลือกที่จะใช้พลังของตนเองเพื่อสนับสนุน「พระพร」จนกว่าผู้พิทักษ์และผู้ปลุกตื่นโอเกียร์จะทำลายแกนกลางของปรากฏการณ์ผิดปกติ——กระจกพิธี หลังจากนั้น ผู้พิทักษ์ได้เข้ารับการเชื่อมโยงของบิชอปซัลวาดอร์ และ「พระพร」ได้รักษาฝูงชนทั้งหมดที่อยู่ในที่เกิดเหตุ ป้องกันไม่ให้เกิดการสูญเสียชีวิต\nจากการตรวจสอบพบว่า ผู้เชื่อมโยงเดิมของบิชอปซัลวาดอร์คือบิชอปเขตโบสถ์คนก่อน ปัจจุบันคืออัครมุขนายกลอนดีเนี่ยน@4\nA.F. 300 อัครมุขนายกได้ปลุกซัลวาดอร์ขึ้นมาโดยบังเอิญหลังจากสัมผัสกับเถ้าศักดิ์สิทธิ์ หลังจากนั้นในช่วง 5 ปี ซัลวาดอร์ได้ทำงานในเขตโบสถ์ในฐานะพระผู้ช่วย และเมื่อ■■■■■ได้เลื่อนตำแหน่ง เขาจึงเข้ามาแทนที่และกลายเป็นบิชอปของเขตโบสถ์\nหลังจากเหตุการณ์นี้ ผู้พิทักษ์ได้ตกลงที่จะรักษาความลับเกี่ยวกับตัวตนของบิชอปซัลวาดอร์ในฐานะผู้ปลุกตื่น ดังนั้นข้อมูลนี้จึงไม่ได้ถูกส่งต่อไปยังคณะกรรมการตรวจสอบข้อตกลงมิสเดีย นอกจากบุคลากรหลักของมหาวิทยาลัยมิซากะ ขณะนี้ไม่มีใครทราบเกี่ยวกับตัวตนของเขาในฐานะผู้ปลุกตื่น"
  },
  AwakerStory_11237_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11237_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
