  AwakerStory_11238_UnlockDesc_1 = {
    Text = "ผ่านด่านเนื้อเรื่องหลักบทที่ 2 「ในนามของหุ่นขี้ผึ้ง」"
  },
  AwakerStory_11239_Content = {
    Text = "「โอ้ผู้ที่กระทำความผิด นี่คือเหวแห่งความโลภ สุดปลายห้วงนรก สุนัขดำคำรามอยู่ที่นี่ กลิ่นเหม็นแพร่กระจายในที่นี้ และเสียงระฆังความตายดังก้อง ทุกคนที่รวมกัน ณ ที่แห่งนี้เพราะความโลภและความโหดเหี้ยม สิ่งที่รอคอยพวกเจ้ามีเพียงความทุกข์และความตายเท่านั้น」\nแปนเดีย เคยทำงานในเรือนจำประตูใหม่ ที่ซึ่งเป็นมุมที่หดหู่ที่สุด มืดมนที่สุด และน่าขนหัวลุกที่สุดในลอนดีเนี่ยน สถานที่ที่เต็มไปด้วยความโสโครกและไร้แสงแห่งวัน ผู้ที่เคยกระทำความผิดอย่างร้ายแรงทั้งหลาย สวมตรวนและโซ่เหล็ก ถูกริบความเคารพในตนเอง ในพื้นที่เรือนจำเขาวงกต พวกเขาคุกเข่าขอความเมตตาจากเธอ จุมพิตรองเท้าหนังของเธอ และถ่อมตัวอ้างตัวว่าเป็นทาสของเธอ\nครั้งเมื่อมีการประหารชีวิตผ่านการแขวนคอ เธอจะเรียกนักโทษประหารใหม่เข้ามา ให้พวกเขาชมเส้นทางสุดท้ายของตัวเอง เมื่อผู้ถูกประหารต้องบิดเบี้ยวและตายในเชือก เธอชอบที่จะนั่งบนที่สูงเพื่อเฝ้าดูผู้ร้ายที่โหดเหี้ยมสั่นกลัวจากความทุกข์ทรมานของความกลัวและสิ้นหวัง\nแต่มี「แมวแห่งนรก」ที่เคยสังเกตว่า แปนเดียเคยมายังประตูเหล็กของเรือนจำประตูใหม่ ครั้งแล้วครั้งเล่า เธอยืนเขย่งเท้าส่องมองออกไปนอกเมืองลอนดีเนี่ยน ราวกับกำลังรอคอยผู้เยี่ยมเยือนจากแดนไกล\n「แท้จริงแล้ว ฉันก็เป็นเพียงแค่นักโทษคนหนึ่งในบรรดานักโทษทั้งหลาย ที่ไม่มีวันออกจากคุกใต้ดินอันมืดมนและชื้นแฉะแห่งนี้ได้เลย」"
  },
  AwakerStory_11239_Title = {
