  },
  AwakerStory_11241_Content = {
    Text = "ชีวิตบนถนนไม่ได้เป็นเรื่องยากสำหรับเธอ\nหากหิวก็ไปหางานทำ ถ้าไม่มีงานก็ใช้มือของตัวเองหาเลี้ยงชีพ เธอและบราวน์ทำงานร่วมกันได้อย่างลงตัว จนไม่ต้องการความช่วยเหลือจากคนอื่นก็สามารถใช้ชีวิตอย่างมีอาหารมีน้ำได้\n「เราไม่ต้องการใครทั้งนั้น」เธอและหนูคู่หูได้สาบานไว้「เราต้องการกันและกันเท่านั้น」\nแต่ทุกครั้งที่คืนที่มีหิมะตก เธอก็มักจะมองไปที่หน้าต่างที่สว่างไสวด้วยแสงสีเหลือง มองไปที่คนที่อยู่ข้างในกอดกันอยู่ข้างๆ มื้ออาหารที่ขาดแคลนและให้พรแก่กัน\nเธอจริงๆ แล้วไม่ต้องการหลังคาที่ซ่อนเร้น ไม่ต้องการเตียงสูงหรูหราหรือหมอนนุ่มๆ เธอมีคู่หูที่น่าเชื่อถืออยู่แล้ว แต่เธอก็ยังสงสัยว่าการมีบ้านที่มั่นคงนานๆ จะรู้สึกอย่างไร\nคำถามนี้ได้รับคำตอบหลังจากที่เมสันรับเธอไปเลี้ยง。"
  },
  AwakerStory_11241_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11241_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11242_Content = {
    Text = "「รามอน่า」แสดงออกถึงความอดกลั้นอย่างมากต่อการปรากฏตัวเช่นนี้ ตามที่เธอบอกไว้ เธอจะปรากฏตัวผ่านร่างของรามอน่าเมื่อผู้พิทักษ์เรียกหาเท่านั้น \nเธอมักจะมาและไปอย่างรวดเร็ว นอกจากการต่อสู้แล้ว เธอเหมือนจะไม่ต้องการมีปฏิสัมพันธ์กับโลกของเราอีกต่อไป \nเป็นเพราะความกลัวต่อฝันร้ายที่หลอกหลอนเธอหรือ? หรือกลัวว่าตนเองจะหลงใหลในสิ่งที่เธอได้สูญเสียไปแล้ว... เราไม่มีทางรู้ได้。"
  },
  AwakerStory_11242_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11242_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11243_Content = {
    Text = "A.F.1@2ปี@1เดือน@1วันที่10:31 น. ตำรวจได้รับรายงานว่า พบคราบเลือดหลายแห่งในคฤหาสน์@1@1 เบลฟอร์ดนักสืบประจำสำนักงานเขตเดินทางไปยังที่เกิดเหตุทันที และพบสารเหลวสีเขียวอมฟ้าที่ไม่ทราบส่วนประกอบในคราบเลือดดังกล่าว\nเวลา 13:44 น. นักสืบเบลฟอร์ดยื่นรายงาน ซึ่งคณะกรรมการพิจารณาภายใต้ข้อตกลงมิสทีออนได้รับช่วงการดำเนินคดีทันที\nเวลา 14:25 น. ทีมตอบสนองลำดับที่เจ็ดของคณะกรรมการพิจารณาเดินทางถึงคฤหาสน์ ควบคุมตัวบุคคลที่เกี่ยวข้องและปิดกั้นสถานที่ ทีมงานได้สันนิษฐานว่าในคฤหาสน์แห่งนี้อาจมีเหยื่ออย่างน้อย 5 ราย และมีการกัดกร่อนเกิดขึ้นหลายบริเวณในสถานที่\nเวลา 18:00 น. ผู้ตรวจสอบจากมหาวิทยาลัยมิสชาร์กเดินทางมาถึงที่เกิดเหตุ ยืนยันการมีอยู่ของปรากฏการณ์กัดกร่อน และนำเอาสิ่งมีชีวิตที่เรียกคืนสติความทรงจำเข้าสู่คฤหาสน์เพื่อทำความสะอาดและสอบสวน\nเวลา 23:11 น. การทำความสะอาดในคฤหาสน์เสร็จสิ้น ผู้ตรวจสอบพบเอกสารด้านความลึกลับและอุปกรณ์พิธีการจำนวนมากในห้องลับใต้ดินและห้องหนังสือของคฤหาสน์ และยังพบสิ่งมีชีวิตไม่สมบูรณ์ที่เรียกคืนสติความทรงจำเรียกว่า 「สาวใช้การ์ลอน」 ซึ่งเป็นหัวหน้าสาวใช้ของ@3ดยุค ในขณะที่ถูกค้นพบ การ์ลอนกำลังใส่ชุดสาวใช้และสวมเครื่องประดับหลากสไตล์อย่างตั้งใจที่จะทำความสะอาดใต้ดิน สิ่งมีชีวิตนี้มีลักษณะภายนอกเหมือนมนุษย์ มีผิวสีเขียวอมฟ้า ปลายแขนและขาทั้งสี่โปร่งใสเป็นวุ้น คล้ายเป็นผลลัพธ์ของการเรียกแบบผิดพลาดหรือไม่สมบูรณ์ โดยของเหลวที่หลั่งออกมาจากร่างของสิ่งมีชีวิตนี้มีลักษณะและสีเหมือนกับคราบเลือดและชิ้นส่วนที่พบ\nผู้ตรวจสอบได้สอบถามข้อมูลจากสิ่งมีชีวิตนี้ และการ์ลอนยอมรับทุกข้อกล่าวหาโดยไม่มีข้อโต้แย้ง และกล่าวว่าทั้งหมดนี้เป็นเพื่อให้ได้รับความสนใจจากนายของตน เมื่อเธอทราบว่าดยุค@3จะถูกจับกุม เธอกล่าวบางเบา 「ถ้างั้นนายใหม่ของฉันอยู่ที่ไหนล่ะ?」 จากนั้นร่างของเธอสลายไปเป็นเจลและทิ้งแกนเงินไว้\nเวลา 01:37 น. หัวหน้าทีมตอบสนองลำดับที่เจ็ดของคณะกรรมการพิจารณาสอบปากคำบุคคลที่เกี่ยวข้อง และตามข้อตกลงได้กักตัว@1เจ้าของคฤหาสน์@3ดยุค\nเวลา 03:09 น. ผู้ตรวจสอบกลับสู่มหาวิทยาลัยมิสชาร์ก และบันทึกแกนเงิน K-033 ลงในคลัง\n——《บันทึกเหตุการณ์คฤหาสน์@1@1》"
  },
  AwakerStory_11243_Title = {
    Text = "เรื่องราว·แรก"
