  AwakerStory_11243_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11244_Content = {
    Text = "A. F. 3@2 ปี เมืองชายฝั่งของสาธารณรัฐอาร์เจนโตเกิดปรากฏการณ์หลอมละลาย ปรากฏการณ์หลอมละลายครั้งนี้ขยายตัวในรูปแบบเกลียวโดยมีท่าเรือเป็นศูนย์กลาง ส่งผลกระทบต่อพื้นที่รอบๆ หลายร้อยเมตร ทำให้มีผู้เสียชีวิต @1 คน\nจากการตรวจสอบ ปรากฏการณ์หลอมละลายเริ่มต้นที่เรือประมงในท่าเรือ เรือดังกล่าวออกทะเลในวันที่ A. F. 3@2 ปี @1 เดือน @1@1 วัน และจับสิ่งมีชีวิตคล้ายปลาค็อดที่มีลวดลายเกลียวสีเงิน\nสิ่งมีชีวิตดังกล่าวมีร่างกายที่นุ่ม เมื่อถูกวัตถุมีคมตัดจะเกิดการแตกตัวออกทั้งหมด และมีของเหลวที่ผสมกับเปลือกหอยและเศษอื่นๆ ไหลออกมา เมื่อเรือประมงกลับถึงท่าเรือ ปลาที่จับมาเริ่มมีการเพิ่มจำนวนของเปลือกหอย แต่ไม่ได้รับความสนใจ จนกระทั่งชาวประมงคนหนึ่งมองว่าตนเป็นเปลือกหอยและพยายามบิดเบือนร่างกายจนบาดเจ็บสาหัสต้องเข้ารับการรักษาในโรงพยาบาล เหตุการณ์จึงถูกแจ้งขึ้น\nหลังจากนั้น เจ้าหน้าที่มิซากะได้ค้นพบแหล่งที่มาของการหลอมละลายที่โรงงานกระป๋อง@4 และได้ทำการกำจัดออกไป โดยได้รับ O-36 เงินใจ\n——«รายงานการได้รับเงินใจระบบปลุกตื่น: O-36»"
  },
  AwakerStory_11244_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11244_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11245_Content = {
    Text = "เจนกินแนบตัวอยู่ที่ช่องประตูห้องปรึกษาจิตวิทยา ตั้งหูแอบฟัง\nเสียงของซิลเวียอบอุ่นและเป็นมิตร ในขณะที่เสียงของไอจิสเหมือนเสียงยุงพึมพำ ไม่ชัดเจนและขาดๆ หายๆ\n「ไอจิส เธอต้องเรียนรู้ที่จะปฏิเสธ」\n「แต่ว่า ฉัน... ทำให้คนอื่นลำบาก... อยาก... ตอบแทน...」\n「ไอจิสไม่ได้ทำให้ใครลำบากเลย ดูสิ ผู้พิทักษ์อนุญาตให้เธอเดินไปมาในโรงเรียนอย่างอิสระ ไม่จำกัดเธอเลย นั่นแหละคือการแสดงความไว้วางใจ」\n「สัญญากับฉันนะ อย่าเพิ่งตอบรับคำขอที่ไร้เหตุผลของคนอื่น โดยเฉพาะคาราบู ถ้าเธอไปช่วยเธอขังหรือทำความสะอาด จะทำให้ผู้พิทักษ์ลำบากนะ」\n「เจนกิน เธอเข้ามาได้ยังไง?」\n「เจน, เจนกิน! เป็น... เป็นฉันที่ตอบตกลงกับคาราบูเอง! เธอ... อย่าโกรธเกินไป!」"
  },
  AwakerStory_11245_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11245_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
