  AwakerStory_11245_UnlockDesc_1 = {
    Text = "ผ่านด่านเนื้อเรื่องหลักบทที่ 1 「เรื่องลับของเขตตะวันออก」"
  },
  AwakerStory_11246_Content = {
    Text = "วินเคอร์เคยมีชื่อที่เป็นของตัวเอง\nชื่อนั้นเคยเต็มไปด้วยความรักจากพ่อแม่\nเคยถูกเพื่อนเขียนซ้ำแล้วซ้ำเล่า สลักลงในความทรงจำ\nและถูกทำเครื่องหมายร่วมกับวันเกิดบนปฏิทิน\n\nวินเคอร์เคยมีใบหน้าที่เป็นของตัวเอง\nใบหน้าที่เติบโตขึ้นมาภายใต้สายตาของพ่อแม่\nที่เคยแสดงความสุขและความเศร้าเมื่ออยู่กับเพื่อน\nที่เคยถูกหยุดเวลาไว้ในภาพถ่าย\n\nวินเคอร์เคยมีบ้านที่เป็นของตัวเอง\nบ้านห่างไกลจากคาดาส ไม่เหมือนกันแม้แต่น้อย\nสุดท้ายมันก็สลายไปพร้อมกับการหายไปของพ่อแม่\nถูกกลืนกินโดย @2 สีดำ และหายไปอย่างสมบูรณ์\n\nวินเคอร์มีความกลัวที่ลึกซึ้ง\nมันมืดมน น่ากลัว กลืนกินทุกสิ่ง และไร้เหตุผล\nมันละลายและกัดกร่อนทุกอย่างจนหมดสิ้น\nเพียงแค่สัมผัส การมีอยู่ของมันก็จะกลายเป็นเถ้าถ่าน\n\nวินเคอร์เหลือเพียงชื่อที่เคยเป็นของตัวเอง\nร่างกายมนุษย์ไม่สามารถเปล่งเสียงหรือเลียนแบบได้\nเธอทำได้เพียงปิดตาลงในความเหนื่อยล้าสุดขีด\nหวังถึงความฝันที่คุ้นเคย ซึ่งได้ยินเสียงเรียกขานอีกครั้ง。"
  },
  AwakerStory_11246_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11246_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11247_Content = {
    Text = "เธอเกิดขึ้นก่อนที่ประวัติศาสตร์ของมนุษย์จะถูกบันทึกไว้ อารยธรรมเก่าที่ไม่สามารถตรวจสอบได้ในปัจจุบัน\nที่นั่น พลเมืองจากกลุ่มดาวได้สร้างอาณาจักรอันรุ่งเรืองและวิหารของเทพเจ้าที่ไม่เสื่อมสลาย เธอเติบโตในความเชื่อ ตั้งแต่เด็กเธอเคารพต่อพระเจ้าอย่างจริงจัง ตั้งใจที่จะเป็นอัครทูตของเทพเจ้า\nอย่างไรก็ตาม การเรียกของเทพเจ้าไม่ใช่เรื่องง่ายดาย เธอปรารถนาที่จะเห็นปาฏิหาริย์และความลึกลับ แต่ไม่เคยได้เห็นแม้แต่ครั้งเดียว\nจนกระทั่งธูลูขึ้นครองราชย์ เธอผู้ขยันขันแข็งก็ได้ขึ้นสู่ตำแหน่งมหากุศล—นั่นคือช่วงเวลาที่เธอไม่มีวันลืม ความรู้สึกที่สับสนและความปิติยินดีเต็มไปด้วยจิตวิญญาณของเธอ ทำให้จิตใจของเธอสั่นสะเทือน\nเธอได้เห็นปาฏิหาริย์ เธอได้เข้าใจความจริง: ราชาเยาว์นั่นคือสิ่งที่เธอปรารถนา ผู้ที่เป็นอมตะในร่างมนุษย์\nหลายปีต่อมา น้ำท่วมครั้งใหญ่ที่ทำลายอารยธรรมเกิดขึ้น เธอได้ฟังคำทำนายสุดท้ายเกี่ยวกับความเป็นอมตะจากธูลู แล้วกลับไปที่วิหารเพื่อสวดมนต์จนถึงนาทีสุดท้าย\nหลังจากนั้นผ่านไปหลายยุคสมัย มนุษย์ใหม่ได้กลับมาขยายพันธุ์บนแผ่นดินอีกครั้ง เรื่องราวในยุคก่อนประวัติศาสตร์ไม่มีใครรู้จักอีกต่อไป\nตั้งแต่นั้นมา การทดลองของมิลียาห์มจึงเพิ่งเริ่มต้นขึ้น。"
  },
