  AwakerStory_11252_Content = {
    Text = "ความทรงจำของเธอนับตั้งแต่วันที่เข้าไปในคุก ก็เต็มไปด้วยสีเลือด \n ความทรงจำที่เรียบง่ายและอบอุ่นในอดีตเหมือนกับความฝันที่หลอกลวง ได้เลือนลางและแตกหัก กลายเป็นเศษแก้วแหลมคมที่ถูกฝังในเนื้อและเลือดของเธอทีละชิ้น \n เธอจำไม่ได้ว่ามีอ้อมกอดที่อ่อนโยนและใบหน้าที่ห่วงใยนั้นอย่างไร สิ่งที่เหลืออยู่ในใจมีเพียงความเกลียดชังและคำถามที่เป็นนิรันดร์ \n ความเจ็บปวด ความอับอาย การหักหลัง... ความทุกข์ทั้งหมดนี้เกิดจากอะไร? \n เธอถามซ้ำแล้วซ้ำเล่า จนกระทั่งถึงเวลาที่เธอได้รับเสรีภาพ แต่ก็ไม่มีใครตอบ \n ดังนั้นให้เธอออกไปค้นหาคำตอบด้วยตัวเอง จากอกที่เต็มไปด้วยเสียงร้องครวญคราง ถามหัวใจที่สกปรกแต่ละดวงด้วยตัวเอง。"
  },
  AwakerStory_11252_Title = {
    Text = "ข้อมูลพื้นฐาน"
