  AwakerStory_11253_Content = {
    Text = "วิญญาณเล็ก ๆ ที่ควรจะหายไปในกระแสประวัติศาสตร์ ได้รับการฟื้นคืนด้วยความปรารถนาของแม่ และพลังงานวิญญาณจากการจัดตั้งวงเวทย์ของ@1@2@1 รวมกับสัตว์ยักษ์ที่นอนอยู่ใต้ทะเลน้ำแข็งของเอลวอส กลายเป็นมอนสเตอร์สาว「ลิลลี่」\nเนื่องจากการปลุกไม่สมบูรณ์ ลิลลี่ในช่วงเริ่มต้นการปลุกไม่มีความรู้สึก เธอเป็นเพียงหุ่นเชิดต่อสู้ที่เชื่อฟังคำสั่งเท่านั้น\nสมาชิกสมาคมนักประติมากรรม ฟรานซิส ออซวูด เคยใช้ลิลลี่เป็นร่างแบบในการทดลองที่ผิดกฎหมายยาวนานถึง@2ปี จากไดอารี่ของฟรานซิส สามารถทราบได้ว่าลิลลี่ในขณะนั้นมีสถานะไม่เสถียรอย่างมาก มักจะควบคุมตัวเองไม่ได้ก่อให้เกิดความเสียหายในวงจำกัด ทำให้ฟรานซิสต้องเปลี่ยนที่อยู่บ่อยครั้ง\nด้วยการบริโภคสารละลายวิญญาณและการปลูกเงินใจ ลิลลี่ได้ฟื้นคืนความรู้สึกและความทรงจำบางส่วนในวันที่ไม่มีการบันทึก หลังจากผ่านความยุ่งยากหลายประการ ฟรานซิสได้เข้ามาดูแลสถานพักฟื้นไรที่กำลังจะล้มละลาย และได้ปรับเปลี่ยนให้เป็นสถานที่ทดลอง\nในเหตุการณ์「สุนัขแห่งนรก」ที่เมืองเล็ก ๆ ของไร หมายเลข L-776 แม่ของเธอ ฟรานซิส ออซวูด ถูกขังอยู่ในมิติที่ผิดปกติที่เธอสร้างขึ้นเอง จนสูญเสียการติดต่อ."
  },
  AwakerStory_11253_Title = {
    Text = "เรื่องราว·5"
