  AwakerStory_11255_Content = {
    Text = "วานด้าเป็นผู้หญิงที่ฉลาด ร่ำรวย และสวยงาม ตามที่เธอพูด เธอมีชีวิตอยู่เพื่อหาความสุข เธอทำให้ผู้ชายกลายเป็นทาสของเธอ และเหยียบเท้าที่เย็นเหมือนแสงจันทร์ลงบนหลังของทาสนั้น ด้วยมงกุฎที่ประดับด้วยดอกไม้ วีนัสผู้เป็นสัญลักษณ์แห่งความชั่วร้ายและความฝัน ในเงามืดนี้ เธอเป็นเพียงตัวตนที่มีรูปร่างเพรียวยาวเปล่งประกาย。"
  },
  AwakerStory_11255_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11255_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11256_Content = {
    Text = "ในการพยายามตรวจสอบบันทึกของลิลลี่ ออสวูด เอริก้าส่งสัญญาณเตือนผิดพลาด 81 ครั้ง ในฐานะที่เคยถูกโลกลืม บันทึกการเกิดและบันทึกการรักษาของลิลลี่ได้กลายเป็นโคลนสีดำไปแล้ว\nแต่เรายังสามารถสังเกตเห็นรูปทรงของเงินใจของเธอผ่านเครื่องมือพิเศษ: บางและขดเป็นวง คล้ายเส้นผมหลายเส้นที่พันกัน——พูดให้ถูกต้องกว่านั้นคือ คล้ายกับเส้นผมแรกเกิดของเด็กทารก\nสิ่งที่ต้องระวังเป็นพิเศษคือ ลิลลี่มักจะแสดงความผูกพันพิเศษต่อผู้เชื่อมโยง มากกว่าการเรียกตัวเองว่า「เพื่อน」หรือ「เจ้านาย」 การเรียกตัวเองว่า「แม่」อาจช่วยให้เราสร้างความสัมพันธ์กับเธอได้เร็วขึ้น."
  },
  AwakerStory_11256_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11256_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11257_Content = {
    Text = "ราโมน่าเริ่มเข้ามาเป็นลูกค้าประจำที่สนามฝึกของมหาวิทยาลัยตั้งแต่อายุสิบปี เธอที่กล้าหาญรับการสอนจากนักดาบชุดดำในร่างมนุษย์ กลายเป็นบุคคลที่นักสืบหลายคนชื่นชม\nหลังจากเริ่มเรียนหลักสูตรเตรียมอุดมศึกษา เธอได้ใช้ความสามารถในการจดจำที่ยอดเยี่ยม คะแนนเต็มในเอกสารสอบ และทักษะดาบที่สง่างามและอันตราย ทำให้ราโมน่ามีสถานะสูงส่งในมิซากะ ความมีระเบียบและความยอดเยี่ยมกลายเป็นชื่อเสียงของเธอ\nแต่สิ่งที่ทำให้หลายคนไม่เข้าใจคือ แม้จะมีความสามารถขนาดนี้ ราโมน่ากลับไม่ได้รับสิทธิ์ในการปฏิบัติงานอย่างอิสระ เธอที่เข้าเรียนก่อนกำหนดยังต้องเรียนหลักสูตรเตรียมอุดมถึงห้าปี และได้เห็นนักสืบหลายคนเข้าสู่โลกแห่งอาคม\nเธอกำลังรออะไรอยู่? เธอได้รับมอบหมายภารกิจอะไร?\nคำถามนี้ได้รับคำตอบหลังจากนักรักษาความลับคนใหม่เข้าเรียน。"
  },
  AwakerStory_11257_Title = {
    Text = "เรื่องราว·2"
