  },
  AwakerStory_11258_Content = {
    Text = "ชุดยูนิฟอร์มต้องรีดด้วยไอน้ำ ผ้าห่มต้องล้างด้วยมือ เตาผิงในฤดูร้อนต้องสะอาดสะอ้าน ในฤดูหนาวต้องมีไฟติดตลอดเวลา พื้นไม้ต้องเงางามจนสะท้อนภาพได้ ชั้นวางหนังสือต้องปราศจากฝุ่นผง ชาดำต้องรักษาอุณหภูมิให้อยู่ในระดับที่เหมาะสมเสมอ เพื่อความสะดวกในการดื่มได้ทุกเมื่อ\nเพื่อเจ้านายใหม่ที่สูงส่ง พิเศษ และไม่เหมือนใคร ผู้ที่ให้ชีวิตใหม่แก่เธอ ผู้พิทักษ์ เธอสามารถทำทุกอย่างได้ เธอคือแม่บ้านที่ดีที่สุดในโลก แน่นอนว่าต้องสามารถทำงานได้อย่างสมบูรณ์แบบ และแกะสลักทุกรายละเอียด\nคำชมจากเจ้านายทำให้เธอมีความสุขอย่างมาก แต่ยังไม่พอ ยังไม่พอ ต้องทำอย่างไรถึงจะได้รับความสนใจจากเจ้านายมากขึ้น? ต้องทำอย่างไรถึงจะทำให้ตัวเองโดดเด่นมากขึ้น?\n「ต้องขาดต่างหู สร้อยคอ สร้อยข้อมือ แหวน และเครื่องประดับบนหัวแน่ๆ!」 เธอจึงใช้ไม้กวาดจิ้มลงที่พื้น พูดกับตัวเองว่า 「แค่มีเครื่องประดับที่เปล่งประกาย คาเรนก็จะน่ารักมากขึ้น ทุกคนก็จะชอบมองคาเรนมากขึ้นแน่นอน!」"
  },
  AwakerStory_11258_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11258_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11259_Content = {
    Text = "ต้นปี A.F.3@2 เมืองสีไคที่กำลังปรับปรุง พบสิ่งผิดปกติในสวนที่ถูกไฟไหม้: เถ้าถ่านเหมือนเถาวัลย์เลื้อยขึ้นบนผนังที่ถูกเผาของเรือนดอกไม้ โดยมีดอกกุหลาบเถ้าถ่านที่บานสะพรั่งซึ่งเปล่งประกายเหมือนโลหะ.\nตามเส้นทางของเถาวัลย์ นักสืบจากมหาวิทยาลัยมิซากะได้หยิบเงินใจนี้ขึ้นมา ในช่วงที่สัมผัสกับผงสีเงินนั้นปลายนิ้วของเธอถูกเผาไหม้จนเป็นสีดำสนิท แต่ไม่มีความรู้สึกเจ็บปวด ข้างแก้มกลับมีน้ำตาไหลออกมาอย่างไร้เหตุผล.\nการร้องไห้เกิดขึ้นโดยไม่มีเหตุผล และในพริบตาก็หายไปในเถ้าถ่าน.。"
  },
  AwakerStory_11259_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11259_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11260_Content = {
    Text = "เมื่อผู้ปีนเขามาถึงยอดเขาเอลวอส。\nเมื่อผู้แข่งขันยกถ้วยรางวัลอันดับหนึ่งของโลก。\nเมื่อผู้มีความเชื่อมั่นฟังการเปิดเผยในความฝัน。\nเมื่อชัยชนะมาง่ายเกินไป ความรู้สึกพอใจที่ตามมาก็จะกลายเป็นความเคยชินที่น่าเบื่อหน่าย。\nมองไปรอบๆ กลับไม่มีคู่ต่อสู้ ไม่มีความสนุก。\nในทางปฏิบัติ ไรเกอร์ปรารถนาการแข่งขันที่เต็มไปด้วยความตื่นเต้น ปรารถนาหัวใจที่กระโดดออกจากลำคอหลังจาก ALL-IN ปรารถนาช่วงเวลาที่อะดรีนาลีนพุ่งพล่าน。\n「ไม่จำเป็นต้องพูดสิ่งเหล่านั้น คนที่เข้าใจเธอมีเพียงฉันเท่านั้น เธอปรารถนาเพียงความล้มเหลวเท่านั้น。\nให้ฉันมอบความล้มเหลวที่หวานที่สุดแก่เธอเถอะ。」"
  },
  AwakerStory_11260_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11260_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11261_Content = {
    Text = "เฮลอตคือมีดที่แหลมคมและเย็นชา。\nผู้ปลุกตื่นที่เคยปฏิบัติภารกิจร่วมกับเธอพูดว่า เฮลอตเป็นอาวุธที่มีประโยชน์มาก เธอแข็งแกร่งพอที่จะทำภารกิจให้สำเร็จเสมอ เพียงแค่ได้รับคำสั่งสังหาร ไม่ว่าจะต้องเผชิญหน้ากับศัตรูที่แข็งแกร่งเพียงใด เธอก็จะสามารถฝ่าฟันเข้าหาและนำหัวของศัตรูกลับมาได้。\nแต่แค่นั้นแหละ。\nเธออาจจะปกป้องคนที่เดินทางไปด้วยกัน แต่ก็แค่การปฏิบัติตามคำสั่ง ไม่ใช่การใส่ใจต่อเพื่อนร่วมทีม เธอไม่เชื่อใจพวกเขา ดังนั้นพวกเขาก็ไม่สามารถฝากหลังให้เธอได้。\nพวกเขาไม่รู้ว่า สำหรับเธอ ดาบที่หันไปทางฝ่ายตนเองนั้นเป็นสิ่งต่ำทราม เป็นสิ่งที่น่ารังเกียจ และควรได้รับการลงโทษและถูกดูถูก。\nเธอรู้ดีถึงความชั่วร้ายของการทรยศ ดังนั้นเธอจึงไม่มีวันชักดาบใส่เพื่อนร่วมทาง。"
  },
  AwakerStory_11261_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11261_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11262_Content = {
    Text = "ผลกระทบจากการตื่นขึ้นที่ยังไม่สมบูรณ์ บวกกับความกระตุ้นทางจิตใจจากการเปลี่ยนแปลงผู้เชื่อม ทำให้นิสัยและจิตใจของลิลี่เกิดการถดถอยในระดับหนึ่ง ความเงียบในมหาวิทยาลัยของเธอเป็นที่ประจักษ์แก่สายตา\nนอกจากการเดินตามคนปกปิดความลับกับร่างที่ตื่นขึ้นอย่างโลตันแล้ว ลิลี่แทบไม่ปรากฏตัวคนเดียวในมหาวิทยาลัย เธอจะไม่เข้าห้องเรียน และไม่เข้าร่วมเล่นเกมกับเหล่าเด็กชายที่ตื่นขึ้น เมื่อไม่จำเป็นต้องออกศึก เธอเพียงแค่รอคำสั่งอยู่เงียบๆ ในหอพักของเธอ\nหน้าต่างห้องของลิลี่มองออกไปยังหลุมฝังศพกุญแจที่ด้านหลังมหาวิทยาลัย ช่วงอาทิตย์ตกดิน เธอจะยืนอยู่ข้างหน้าต่าง มองออกไปที่หลุมฝังศพกุญแจที่ถูกปกคลุมด้วยแสงสีเหลืองทองในยามโพล้เพล้\nแสงจากสุสานกุญแจซึ่งอยู่ในรูปร่างของกุญแจเงินทอดเงายาวในแสงอาทิตย์อัสดง และลิลี่ที่ยืนอยู่ตรงหน้าต่างนั้นก็เงียบสงัดเหมือนกับหลุมฝังศพเหล่านั้น。"
  },
  AwakerStory_11262_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11262_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11263_Content = {
    Text = "นี่คือเมืองแห่งดอกไม้และบทกวี ที่นี่ กวีกำลังรักซึ่งกันและกันเทียบเท่ากับช่อกุหลาบที่เพิ่งถูกตัดออกมา ยังสามารถแลกเปลี่ยนเป็นอาหารสำหรับครอบครัวสามคนได้หนึ่งสัปดาห์ การถือกำเนิดของผลงานชิ้นเอกก็หมายถึงกวีที่มีพรสวรรค์จะมีชื่อเสียงขึ้นมา \nผู้หญิงคนนั้นเคยเป็นคนสวนที่อยู่กับปุ๋ยและกิ่งไม้แห้งทุกวัน เธอเพลิดเพลินกับบทกวีที่มีเสน่ห์ที่นำมาให้เธอซึ่งไม่ต้องดูแลสวนอีกต่อไป แม้กระทั่งล็อกเรือนกระจกไม่ให้ใครเข้าไปในสวนดอกไม้ \nเมื่อคนอื่นถาม เธอก็ตอบเพียงว่าเรือนกระจกซ่อนอยู่ด้วย 「แรงบัลดาลใจ」 \nพวกเธอเกิดมาในฐานะลูกของข้าราชบริพารชั้นสูง หลังจากที่สหพันธ์คอนสแตนท์ก่อตั้งขึ้น ขุนนางเก่าถูกปราบปรามและพวกเธอก็สูญเสียที่อยู่ \nนั่นคือสาวใช้ที่เติบโตเคียงข้างคุณหนู แต่กลับแสดงให้เห็นถึงพรสวรรค์ในการเขียนตั้งแต่ยังเด็ก — แต่สาวใช้จะอ่านบทกวีได้อย่างไร? \nสภาพแวดล้อมรอบตัวเปลี่ยนแปลงอยู่ตลอดเวลา ความสามารถในการเขียนกวีไม่สามารถช่วยให้สาวน้อยมีชีวิตอยู่ได้ สิ่งต่าง ๆ ทำให้สาวน้อยรู้สึกไม่สบายใจและเศร้าหมองมากขึ้น \nจนกระทั่งคนสวนยื่นมือออกไป — มือที่ถูกพุ่มหนามบาด มอบสวนให้กับเธอ ในอาณาจักรเล็ก ๆ นี้ พวกเธอใช้ชีวิตอย่างมีความสุขที่สุดในช่วงเวลาหนึ่ง \nชีวิตที่สงบสุขเริ่มเปลี่ยนไปเมื่อคนสวนได้รับบทกวีมา \nพรสวรรค์ของเพื่อนรักช่างน่าหลงใหล เธออยากให้คนอื่นได้เห็นบทกวีที่มอบให้เพื่อน \nเพื่อนที่อายและเศร้าไม่ต้องการเซ็นชื่อ คนสวนจึงเซ็นชื่อของตนที่จุดลงนาม — 「ถ้าตีพิมพ์ เซ็นชื่อก็จะสะดวกสำหรับพวกเขาในการส่งเงินรางวัล」 \nการเปลี่ยนแปลงของคนสวนเริ่มต้นจากการได้รับค่าลิขสิทธิ์ครั้งแรก \nเธอไม่เข้าใจว่าทำไมเธอจึงกลายเป็นภาระแทนที่จะเป็นผู้ปกป้อง \nเธอไม่เข้าใจว่าทำไมเพื่อนถึงสามารถเก็บเกี่ยวความรักและคำชมทั้งหมดได้อย่างง่ายดาย ในขณะที่ความพยายามของเธอต้องพ่ายแพ้ต่อพรสวรรค์ \nถูกความปรารถนาและความอิจฉาครอบงำ เธอเริ่มใช้ความไว้วางใจของเพื่อนเพื่อหลอกลวงผลงานของเธอ การหลอกลวงไม่สามารถย้อนกลับได้ เมล็ดพันธุ์ถูกฝังในใจของคนสวนตั้งแต่แรก เมื่อชื่อเสียงของกวีที่มีพรสวรรค์เริ่มแพร่กระจายก็เริ่มงอกงาม ในการสัมภาษณ์บนถนนครั้งหนึ่งเกิดตูมตามขึ้น — แฟนคลับที่คลั่งไคล้ได้ถามคนสวนด้วยอารมณ์ที่ซ่อนอยู่ในบทกวี ทำให้คนสวนที่ไม่สามารถอ่านบทกวีได้รู้สึกเครียดและรีบหนีออกไป ในคืนที่กลับไปถึงสวนดอกไม้ เธอเผชิญกับสีหน้าที่ห่วงใยของเพื่อน ความตื่นตระหนกในดอกไม้เบ่งบานในขณะนี้ \nหลังจากเกิดไฟไหม้ครั้งใหญ่ที่ทำให้สีไคตกตะลึง กวีที่มีพรสวรรค์ประกาศหยุดการเขียน พร้อมกับความมั่งคั่งและชื่อเสียงที่เธอได้รับในช่วงเวลาสั้น ๆ หายไป."
  },
  AwakerStory_11263_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11263_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11264_Content = {
    Text = "ในช่วงสามปีที่ผ่านมา มีการเกิดอุบัติเรือภัยจำนวนมากในเขตทะเลมองเกิลไทรแองเกิล และยังมีกรณีการสูญหายอย่างลึกลับของเรือทั้งลำอีกหลายครั้ง\nมีคำให้การจากลูกเรือคนหนึ่ง เขาเล่าว่าในขณะที่เขาเข้าร่วมการช่วยเหลือเรือที่เกิดอุบัติ เขามองเห็น「ผู้หญิงที่มีศีรษะเปล่งแสง」บนดาดฟ้าของเรือที่เกิดอุบัติ\nนักสืบพื้นที่ที่ได้รับข้อมูลนี้ได้เดินทางไปยังเขตทะเลมองเกิลไทรแองเกิล แต่เรือที่พวกเขาใช้อยู่ได้ขาดการติดต่ออยู่ช่วงเวลาหนึ่ง เมื่อทีมเสริมมาถึงและพบเรือลำดังกล่าว เรือลำนั้นเสียการควบคุมและกำลังลอยไปตามกระแสน้ำเข้าสู่ศูนย์กลางของมองเกิลไทรแองเกิล ลูกเรือทั้งหมดมีอาการขาดน้ำอย่างรุนแรง อ่อนแออย่างสุดขีด อีกทั้งยังรายงานว่ามีภาพลวงตาที่เข้มข้นอย่างมาก\nหลังจากการตรวจสุขภาพลูกเรือ พบซิลเวอร์คอร์ในสิ่งของส่วนตัวของนักสืบไอเฟิร์ส แต่นักสืบเองปฏิเสธมาตลอดว่าเรือไม่เคยมีปฏิสัมพันธ์ใดๆ กับผู้ปลุกตื่น\nซิลเวอร์คอร์ดังกล่าวได้ถูกเก็บรักษาโดยระบบผู้ปลุกตื่น ด้วยหมายเลข 6291-S-S-01 โดยมีกำหนดนำมาใช้งานในปี A. F. 315 เพื่อเป็นส่วนหนึ่งของการฝึกอบรมการปลุกตื่นสำหรับนักสืบสำรวจเบื้องต้น."
  },
  AwakerStory_11264_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11264_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11265_Content = {
    Text = "หลังจากถูกปลุกตื่น เร finally ได้ทราบว่ามอร์ฟี่เคยใช้ชีวิตอย่างไรในคณะศาสนา \n เธอใช้ร่มกันแดดและใช้เวลาอย่างมากในการจัดแต่งตัวก่อนออกไปข้างนอก ชาช่วงบ่ายจะต้องมีในเวลา 16.00 น. พร้อมกับนมชาดำและสโคนกับแยมสตรอเบอรี่ รักษาความสะอาดและความสง่างาม นี่คือโชคชะตาของสุภาพสตรี ไม่ว่าเธอจะอยู่ที่ไหน เธอยังคงยึดมั่นในชีวิตของสุภาพสตรี \n (หมายเหตุจากผู้บันทึก: ฉันคิดว่า เธอใช้มือจับพุดดิ้งเนื้อแกะอย่างตรงไปตรงมานั้นไม่สามารถเรียกว่าเป็นสุภาพสตรีได้...) \n แม้ตอนนี้จะไม่มีคนใช้ที่คอยเรียกเธอ แต่เธอยังคงใช้ชีวิตในแบบที่เธอต้องการ ซึ่งเป็นเรื่องที่น่ายินดีจริงๆ \n ผลกระทบจากเหตุการณ์นั้นทำให้เธอไม่ค่อยติดต่อกับผู้ปลุกตื่นมิเรียมและโกไลแอท แม้กระทั่งจะตั้งใจมองข้าม ในการพบกับผู้ปลุกตื่นธูลู เธอก็แสดงออกถึงอารมณ์ที่ซับซ้อนมาก \n หากพูดถึงอดีต เธอจะมีอารมณ์ที่ไม่ดี อาจจะเป็นเพราะเธอยังต้องการเวลาอีกสักหน่อยเพื่อปรับอารมณ์。"
  },
  AwakerStory_11265_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11265_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11266_Content = {
    Text = "ไม่ต้องกลัวกับผ้าปิดตาสีดำของเขา ความมืดที่ข้ามกันจะไม่บดบังความเมตตาของเขา ร่างที่ตาบอดได้สูญสิ้นไปแล้ว แต่ความปรารถนาในการไถ่บาปจะอยู่ตลอดไป ต่อหน้าเขา ทุกสิ่งควรได้รับความรัก ทุกสิ่งจะได้รับความรัก \n คำของพ่อพระถูกจารึกไว้บนกระดานหิน ด้วยกระดูกและเลือดที่ได้รับพรนี้ เขาจะมอบ「พระพร」ให้กับพวกท่าน。"
  },
  AwakerStory_11266_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11266_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11267_Content = {
    Text = "เขามักจะมีสีหน้าเคร่งเครียด เดินไปเดินมาคนเดียวอยู่ที่ข้างทะเลสาบ เรื่อยๆ นักเรียนก็เริ่มเรียกข้างทะเลสาบว่า「ดินแดนของมนุษย์ปลาที่มืดมน」 ดังนั้นเขาจึงมาที่นี่อย่างเคร่งขรึมเหมือนเป็นเจ้านายทุกวัน เมื่อเขากระโดดลงไปที่ก้นทะเลสาบ ฟองอากาศที่ลอยขึ้นมาก็โอบกอดเขาอย่างอ่อนโยน ในน้ำ เสียงยุ่วยุจากฝั่งก็เหมือนจะได้ยินไม่ชัดเท่าไหร่。"
  },
  AwakerStory_11267_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11267_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11268_Content = {
    Text = "ผู้ศรัทธาที่แท้จริงที่สุดของเทพเจ้า ข้าราชบริพารที่ซื่อสัตย์ที่สุดของพระราชา ใช้แสงแห่งความเชื่อมั่นส่องสว่างเส้นทางการแสวงบุญ \nการล่มสลายและจมลงของอาณาจักรนิรันดร์ สำหรับฟารอสเหมือนกับหอคอยที่สูญเสียฐานราก เถาวัลย์ที่สูญเสียดิน การศรัทธาในอาณาจักรนิรันดร์เป็นแรงสนับสนุนให้เธอลอยอยู่ในโลก แต่ความทุกข์ที่ค้นหามานานและความโดดเดี่ยวที่ไม่มีที่สิ้นสุดในที่สุดก็ทำให้ผู้เดินทางที่น่าสงสารต้องพังทลาย \nฟารอสจมลึกลงไปในทะเลที่เธอรักและเกลียด ก่อให้เกิดคลื่นยักษ์ น้ำทะเลพลุ่งพล่านดุจดั่งงานพิธีบูชาที่แสนงดงามในความทรงจำ ทำให้เธอรู้สึกถึงการปลอบประโลมเล็กน้อย \nเมื่อถูกฮีโร่ตัดศีรษะ ความสนใจที่จ้องมองก็ต้องเป็นอาณาจักรนิรันดร์ที่เธอไม่สามารถปล่อยวางได้เช่นกัน。"
  },
  AwakerStory_11268_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11268_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11269_Content = {
    Text = "เธอดูเหมือนจะวนเวียนอยู่รอบๆ มอเตอร์ไซค์ชื่อ 「แฟนท่อม」 อยู่ตลอดเวลา: ขันสกรูตรงนี้บ้าง, ปรับท่อที่นั่นบ้าง...นี่คือโครงการที่ไม่มีจุดสิ้นสุด ถึงแม้ว่าหลายคนจะคิดว่าเธอได้ทำการซ่อมแซมได้ดีที่สุดแล้ว แต่เธอก็ยังคงมุ่งมั่นทำมันทุกวัน\nเหตุผลของเธอก็คือความรู้สึกที่ว่า 「มันยังขาดอะไรบางอย่าง」 ซึ่งไม่สามารถอธิบายได้มาแต่ไหนแต่ไร。"
  },
  AwakerStory_11269_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11269_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11270_Content = {
    Text = "「4:30 วิ่งจ๊อกกิ้ง 6 ไมล์ตามแม่น้ำอิซิส ระหว่างทางมีปากเสียงกับคุณยายที่เดินผ่านมา และเตะสุนัขพันธุ์ปูดเดิลออกไป \n……\n12:00 รับประทานอาหารกลางวัน แพนเค้กน้ำผึ้ง, ออเดิร์ฟมะกอก……เนื้อแกะย่าง 5 จาน? น่าเชื่อถือไม่ได้ \n13:00 ไปที่คลับต่อสู้ปลาเทราต์ สถิติ: ชนะ 10 แพ้ 0, สถิติเร็วที่สุด 3 วินาที——คู่ต่อสู้ยอมแพ้เองเพราะกลัวมากเกินไป \n19:00 ไปชมการแสดง《ผู้เลี้ยงแกะ》ที่โรงละครโคเวนต์กับผู้พิทักษ์ เนื่องจากแสดงความคิดเห็นทางการเมืองที่อันตรายเสียงดังจึงถูกไล่ออก \n22:00 ถูกพบว่าพเนจรอยู่ใกล้โรงพยาบาลเซนต์แมรี สมเหตุสมผลที่จะคาดเดาว่าเขาตั้งใจจะขโมยถุงเลือดของโรงพยาบาล \nการสังเกตข้างต้นสิ้นสุดลง การประเมินระดับอันตราย: SSS。」\n——คัดลอกจาก《บันทึกการสังเกตผู้ปลุกตื่นของฮันนา》"
  },
  AwakerStory_11270_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11270_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11271_Content = {
    Text = "ฟินเทอร์เห็นนักเรียนที่แอบร้องไห้อยู่ในห้องทดลอง\nเธอไม่ใช่นักเรียนที่ฟินเทอร์ชอบที่สุด แต่เป็นคนที่ชอบฟินเทอร์ที่สุด\nนักเรียนหญิงคนนี้ไม่เคยสนใจในการต่อต้านและความเย็นชาของฟินเทอร์ และไม่กลัวพลังที่ไม่สามารถควบคุมของฟินเทอร์\nเธอยอมใช้ค่าครองชีพเพื่อซื้อขนมทั้งหมดมาเพียงเพราะกังวลว่าฟินเทอร์จะมีพลังงานไม่พอ\nเธอยังยอมใส่ชุดป้องกันที่หนักหน่วง เพียงเพื่อจัดผมยาวที่ยุ่งเหยิงของฟินเทอร์\n...ในสายตาฟินเทอร์ การตอบแทนให้เธอคือสิ่งที่ควรทำ\nดังนั้น ฟินเทอร์จึงทำสิ่งที่เธอสามารถทำได้\n—ถ้าการร้องไห้เป็นเพราะกังวลว่าสอบไม่ผ่าน งั้นการข่มขู่นักเรียนคนอื่นให้ยอมสละคะแนนก็น่าจะเป็นทางออกที่ดีใช่ไหม?"
  },
  AwakerStory_11271_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11271_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11272_Content = {
    Text = "มิซากะปลุกและกักเก็บเหล่าผู้ตื่นขึ้นจำนวนมาก แต่ไม่มีใครที่พิเศษไปกว่าไทอีส \nเธอช่วยนักเรียนหญิงเลือกแต่งหน้าเพื่อออกเดต ช่วยคนสิ้นหวังกลับมามีกำลังใจ และช่วยนักสืบที่จิตใจพังทลายให้หายจากความหดหู่\nเหมือนคนรัก เหมือนพี่สาว และเหมือนแม่ เธอมักสร้างบ่อโคลนที่เรียกว่า 「ความรัก」 และทำให้ผู้คนตกลงไปอย่างเงียบๆ โดยที่พวกเขาไม่รู้ตัวจนทำให้พวกเขาพร้อมที่จะทุ่มเททุกสิ่งเพื่อเธอ——\nหลังจากการขัดขวางนักเรียนไม่ให้ดื่มของเหลวลึกลับที่ไทอีสมอบให้เป็นครั้งที่สาม ศูนย์จัดการผู้ตื่นขึ้นจึงได้ออกคำสั่งจำกัดต่อตัวเธอ \n「โดยปราศจากการดูแลของผู้ทรงอำนาจ ห้ามไม่ให้ไทอีสเข้าใกล้นักเรียนทุกคนโดยเด็ดขาด」"
  },
  AwakerStory_11272_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11272_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11273_Content = {
    Text = "ความหมายทั้งหมดสลายหายไปเหมือนทราย ฉากหลอกลวงของโลกค่อยๆ จางหายไปในสายตาของเธอ ทุกสิ่งกลับสู่ความมืดมิดที่เป็นต้นกำเนิดที่สุด \n ในการแสดงครั้งสุดท้ายบนเวทีมืดมิดนี้ นักเต้นรำทางวิทยาศาสตร์ยังคงเต้นรำอย่างเต็มที่ \n เธอไม่สนใจที่จะถูกย่อยสลายอย่างช้าๆ เพราะจุดจบของการแสดงนั้นถูกเขียนไว้ตั้งแต่ต้นแล้ว \n เช่นเดียวกับที่เคยเป็นมา เธอจะมอบพละกำลังของอัจฉริยะอย่างไม่มีเงื่อนไขให้กับโลก ในวิธีที่ใกล้เคียงกับความจริงที่สุด \n หากคุณถามเธอเพียงเล็กน้อย เธอจะยืนยันว่าตนยังคงมีความรักต่อมนุษย์และโลก เธอจะสิ้นสุดความทุกข์ทรมานทั้งหมดในโลกมนุษย์และนำผู้คนกลับสู่บ้านที่แท้จริงและดั้งเดิม。"
  },
  AwakerStory_11273_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11273_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11274_Content = {
    Text = "A. F. 3@1ปี @1เดือน.\nที่แนวปะการังปีศาจชายฝั่งตะวันออกของสาธารณรัฐอาร์เจนโต เหล่าชาวประมงในพื้นที่ได้รายงานว่าพบ「ศพที่มีรูปร่างแปลกประหลาด」——มีขนาดเล็กและตัวงอ ลูกตาปูดโปน ผิวหนังแข็งบางส่วน นิ้วมือมีพังผืด และที่แปลกที่สุดคือรอยแดงที่สมมาตรข้างคอทั้งสองข้าง หากไม่ใช่เพราะเขาสวมชุดนักเรียน อาจจะยากที่จะถูกมองว่าเป็น「ศพของมนุษย์」.\nเมื่อนักสืบมาถึง ศพที่แปลกประหลาดนั้นถูกชาวประมงที่ตกใจมองว่าเป็นสิ่งไม่ดีเผาทิ้งไปแล้ว เหลือเพียงกระเป๋าถือใบหนึ่งที่เคยเป็นที่นิยมในหมู่นักเรียน ในกระเป๋าไม่มีเสื้อผ้าเปลี่ยนใดๆ มีเพียงเอกสารที่มีลายมือเบลอๆ เข็มทิศ และภาพถ่ายของหญิงวัยกลางคนอยู่ในนั้น."
  },
  AwakerStory_11274_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11274_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11275_Content = {
    Text = "เด็กหญิงสวมใส่ชุดที่เรียบง่าย ผิวของเธอยังรู้สึกเจ็บแสบจากการขัดที่รุนแรงเมื่อครู่ เธอไม่เข้าใจว่าทำไมถึงถูกทหารพามาที่นี่ บ้านของขุนนางไม่ใช่สถานที่ที่ทาสสามารถเข้าออกได้ตามใจชอบ และเธอยังอายุน้อยเกินกว่าจะมาที่นี่เพื่อรับใช้\nคุณนายที่สวมใส่เสื้อคลุมสีขาวนั่งอยู่บนเก้าอี้ เด็กหญิงก้มหน้าลง เพราะความกลัวและความตื่นเต้นทำให้เธอสั่นเทา\n「ฉันไม่ผิดหวังจริงๆ…」คุณนายกล่าว，「ดูเหมือนมาก ดูเหมือนจริงๆ」\nดูเหมือน? หมายความว่าเธอเหมือนใครหรือ?\n「ดีมาก ดีมาก」คุณนายปรบมือด้วยความดีใจ，「เธอนี่แหละ ตั้งแต่วันนี้เป็นต้นไป ฉันจะเป็นแม่ของเธอ จำไว้ไหม?」\nแม่? แต่เธอก็มีแม่อยู่แล้ว แม่อยู่ที่บ้าน และตอนที่เธอถูกพาออกไป แม่ก็ร้องไห้เสียงดัง\nแล้วแม่ของเธอล่ะ?\nความสงสัยและความไม่เข้าใจวนเวียนอยู่ในหัวของเด็กหญิง เธออยากถามคำตอบ แต่ก็เข้าใจว่าความหมายของเจ้านายก็คือคำสั่งของทาส ทาสที่ขัดคำสั่งจะต้องได้รับการลงโทษอย่างรุนแรง\n「จำไว้ให้ดีนะ คุณนาย」\n「เป็นเด็กดีจริงๆ ฉันคิดดู… จะเรียกเธอว่าเฮลอตนะ ชอบชื่อนี้ไหม เฮลอต? ต้องชอบแน่ๆ มา ใส่ชุดนี้ให้แม่ดูหน่อย」"
  },
  AwakerStory_11275_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11275_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11276_Content = {
    Text = "โกไลแอทเป็นคนอวดดีและเย่อหยิ่ง แต่ความแข็งแกร่งของเขานั้นไม่มีใครสามารถปฏิเสธได้ จากบันทึกการต่อสู้ของคุณเอริกาไม่ยากที่จะเห็นว่า พละกำลังอันดุดันนั้นเพียงพอที่จะทำให้เขาฝ่าฟันอันตรายได้คนเดียว ฉันคิดว่า สาเหตุที่โกไลแอทไม่สนใจความสามารถของคู่หูนั้น เป็นเพราะในโลกของเขา ไม่มีใครที่แข็งแกร่งกว่าตนเอง\nอย่างไรก็ตามโกไลแอทเมื่อเผชิญหน้ากับมิเรียม มักจะแสดงอาการหวาดกลัวออกมาโดยไม่รู้ตัว เป็นเรื่องยากที่จะจินตนาการว่ามีสิ่งใดที่ทำให้ผู้นำที่แข็งแกร่งและกษัตริย์เก่าผู้นี้เกิดความเกรงกลัว\nนอกจากนี้ เขายังแสดงความสนใจที่ไม่ธรรมดาต่อคุณเมอร์ฟี่ บางครั้งเขาจะวนเวียนอยู่รอบ ๆ บริเวณเขาวงกตในโรงเรียน ดูเหมือนเขาจะรอคอยให้เมอร์ฟี่เสร็จสิ้นภารกิจกลับมา; บางครั้งเขาก็จะสังเกตเมอร์ฟี่อย่างเงียบ ๆ ว่าเธอได้รับบาดเจ็บในระหว่างภารกิจหรือไม่\nคุณพิสลีย์ก็สังเกตเห็นเรื่องนี้เช่นกัน เธอเคยพูดเล่นกับฉันว่า:「เฮ้ คุณไม่คิดว่าเขากำลังพยายามเป็นพ่อที่ธรรมดาอยู่หรือ?」\n——《บันทึกการสังเกตของนักวิจัยฝึกงาน》"
  },
  AwakerStory_11276_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11276_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11277_Content = {
    Text = "สำนักงานของเวินเค่อถูกเรียกว่าเป็นดาวเหนือของมหาวิทยาลัยมิซากะ ที่นั่นสว่างไสวตลอดเวลา มุมใดก็ตามที่อาจมีเงา ถูกทำให้สว่างโดยอุปกรณ์ให้แสงที่หลากหลาย ตั้งแต่โคมไฟไปจนถึงโคมไฟน้ำมัน จากหลอดไฟทังสเตนไปจนถึงเทียนไข。\nความกลัวความมืดทำให้เธอไม่ชอบการนอนหลับ ดังนั้นเธอจึงมักนั่งอยู่ใต้โคมไฟที่ใหญ่ที่สุด โดยเขียนสัญลักษณ์ที่ไม่มีใครเข้าใจลงบนกระดาษร่างที่กระจายอยู่ทั่วพื้น โดยไม่สนใจวันและคืน。"
  },
  AwakerStory_11277_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11277_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11278_Content = {
    Text = "เคคัสเกลียดมนุษย์ ตั้งแต่เขายังเป็นเด็ก เขาก็เกลียดพวกเขาแล้ว\nเขาเคยช่วยเด็กหญิงคนหนึ่งที่จมน้ำ แต่กลับถูกเด็กคนอื่นกล่าวหาว่าเป็นคนอันตราย; เขาหนีห่างจากพวกเขา แต่กลับถูกไล่ตามและถูกเรียกว่า 「มนุษย์กบเหม็น」 \n\nในวันเวลาที่มืดมนตลอดสิบปีนั้น สิ่งเดียวที่ทำให้เขาหวังได้คือจดหมายจากลุงออร์น ความรู้ที่กว้างขวางของเขามีเรื่องราวของภูตผีปีศาจมากมายที่ทำให้เคคัสตัวน้อยหลงใหล แต่ความสุขนั้นไม่ยืนยาว ไม่กี่ปีหลังจากนั้นลุงออร์นกลับหายตัวไป\nจนกระทั่งปีที่เขาอายุ 16 เคคัสกลับไปเยี่ยมบ้านของปู่ และบังเอิญพบต้นฉบับของออร์น เขาจึงได้รู้ความหมายอันสูงส่งที่ซ่อนอยู่ในลวดลายที่บิดเบี้ยวบนร่างกาย\nอา มนุษย์ เป็นสิ่งมีชีวิตที่ต่ำต้อยไร้ค่าในที่สุด\nตั้งแต่นั้นมา เขาจึงไม่รู้สึกหมดหวังอีกต่อไป แต่กลับตั้งใจรอ รอวันที่ชะตากรรมจะมาถึง。"
  },
  AwakerStory_11278_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11278_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11279_Content = {
    Text = "เรื่องที่เด็กหนุ่มเคยถูกเรียกว่า \"อัศวินแห่งความตาย\" นั้น ในโรงเรียนไม่มีใครจดจำมากนักแล้ว\nเพียงแค่ในเวลาตีหนึ่ง ทิวทัศน์ในวันนั้นจะกลายเป็นฝันร้าย แทรกซึมเข้าสู่ความฝันของเด็กหนุ่ม\nร่างหลอมละลายที่บุกเข้ามาในโรงเรียน หอระฆังที่พังทลาย ผู้พิทักษ์ที่ใกล้จะหมดลมหายใจ\n\"อย่าร้องไห้ โอกีล นี่ไม่ใช่ความผิดของเธอ...\"\nทหารเหล็กที่บุกเข้ามาในบ้านเรือน พระราชวังที่ทรุดโทรม เลือดดำที่ไหลออกมาจากนิ้วของเจ้าหญิง\n\"อย่าสละชีพเพราะฉัน โอกีล เธอทำมากพอแล้ว...\"\nก้อนกรวดแห่งความทรงจำที่พาเอาความเจ็บปวด มาชะล้างจิตวิญญาณของเด็กหนุ่ม。"
  },
  AwakerStory_11279_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11279_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11280_Content = {
    Text = "บางครั้งผู้ปลุกตื่นจะมีอาการไม่ปรับตัวกับร่างใหม่และชีวิตใหม่หลังจากตื่นขึ้นมา ขณะที่บางคนก็ยอมรับสถานการณ์ได้อย่างรวดเร็ว และเริ่มต้นชีวิตใหม่อย่างกระตือรือร้น\nธูลูไม่อยู่ในประเภทใดๆ ไม่เคยมีใครแสดงความไม่สนใจในโลกปัจจุบันอย่างโจ่งแจ้งเช่นเขามาก่อน\nคุณภาพของเขานั้นยอดเยี่ยมอย่างยิ่ง บางทีเขาอาจมีปรีชาญาณเกี่ยวกับสถานการณ์และวิกฤตในโลกปัจจุบัน แต่เขากลับเลือกที่จะใช้เวลาส่วนใหญ่ไปกับการนอนหลับ\nแม้ว่าไม่ได้เกิดจากความปรารถนาของเขา แต่เขาก็มีชื่อเสียงพอสมควรในโรงเรียนระหว่างมนุษย์และผู้ปลุกตื่น นักวิจัยต่างจับตามองการกระทำของเขา และเป็นครั้งคราวก็ส่งผลงานวิจัยออกมา; ภาควิชาโบราณคดีและภาควิชาดาราศาสตร์มักจะส่งคำเชิญให้เข้าร่วมการสัมมนาทางวิชาการในหลากหลายชื่อ ซึ่งส่วนใหญ่จะระบุชื่อเขาเป็นผู้เข้าร่วม\nธูลูมีอิทธิพลค่อนข้างมากในหมู่ผู้ปลุกตื่น: เมอร์ฟี่เมื่อเห็นเขาก็จะรู้สึกไม่สบายใจ โกลิอัทดูเหมือนจะอยากท้าทายเขาอย่างลับๆ ขณะที่มิลียาห์มถือว่าคำพูดของเขาเป็นคำสั่งศักดิ์สิทธิ์\nสำหรับเรื่องเหล่านี้ เขาไม่เคยแสดงท่าทีพิเศษใดๆ ไม่มีความคาดหวังหรือความต้องการ\nบางครั้งเขาจะตอบสนองต่อคำขอบางอย่างตามใจชอบ แต่บางครั้งก็ไม่ตอบสนอง."
  },
  AwakerStory_11280_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11280_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11281_Content = {
    Text = "จนกระทั่งกลายเป็นสิ่งที่เรียกว่าวิญญาณตื่นขึ้น โซเรลก็ยังคงไม่สามารถลืมเลือนไปได้เกี่ยวกับพวกขุนนางที่ประจบประแจงเธอไม่ได้ ลืมหน้าตาของพวกเขาอันเต็มเปี่ยมไปด้วยความชอบใจและปลอมแปลงไม่ได้เลย\nรอยยิ้มเหล่านั้นช่างทำให้เธอสะอิดสะเอียนเหลือเกิน ทั้งวิจิตร ซ่อนเร้น และแฝงไปด้วยความต้องการและการวางแผนเพื่อเธอ เธอกลับจำต้องถักทอเครื่องอำนวยความสบายเพื่อแสดงตัวเองอย่างอ่อนโยน\nเธอต้องสร้างเครือข่ายที่ละเอียดอ่อนที่สุด เข้าไปแทรกซึมทุกมุมมืด รวบรวมทุกผู้คนไว้ในเครือข่าย และครองครองทุกข้อมูล\nเธอยังจำเป็นต้องทำตัวเหมือนน้ำที่ค่อย ๆ ร้อนขึ้น เพื่อจมพวกเขาลงไปในนั้น และเมื่ออยากจะถอดหน้ากากออกมา ก็จะพบว่าตนตกอยู่ในเครือข่ายนี้กลับไม่มีทางหนี\nแต่เมื่อเริ่มตระหนักถึงสิ่งต่าง ๆ ที่เกิดขึ้น คนที่ไม่สามารถหนีได้นั้นกลับกลายเป็นเธอเอง\nเธอหลีกเลี่ยงไม่ได้ หย่อนยานไม่ได้ และปล่อยมือไม่ได้\nโซเรลไม่มีสิทธิ์ที่จะหันหลังกลับอีกต่อไป นอกจากการยืนอยู่เหนือผู้คนทั้งหมด เธอไม่มีเส้นทางอื่นที่จะเดินได้อีกแล้ว"
  },
  AwakerStory_11281_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11281_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11282_Content = {
    Text = "\n「ฉันต้องการสวมใส่ควอตซ์สีม่วงที่ดำเหมือนไวน์แดง。」\n「ฉันต้องการใส่กระโปรงยาวที่ทำจากขนของนกกระจอกเทศที่หรูหรา。」\n「ฉันต้องการเป็นแสงเดียวในงานเลี้ยง。」\nพนักงานเสิร์ฟกระพริบตาเป็นสีเหลืองอำพัน เธอยังมีความปรารถนาที่ดีอีกมากมาย แต่ไม่สามารถพูดออกมาได้อีกแล้ว ร่างกายที่แข็งทื่ออยู่ตรงหน้า คือเปลวไฟสีเขียวที่ไร้ขอบเขต ซึ่งเบ่งบานอย่างเงียบๆ ในคืนอันมืดมิด。"
  },
  AwakerStory_11282_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11282_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11283_Content = {
    Text = "เธอกำลังคำนวณความเร็วในการฟันดาบ คำนวณมุมในการหลบหลีกการโจมตี \n เธอกำลังคำนวณความเป็นไปได้ของแผนการหลบหนี คำนวณความน่าจะเป็นที่โลกจะก้าวไปสู่อนาคต \n จนกระทั่งสุดท้าย เธอก็ไม่เคยยอมแพ้ในการคำนวณ \n เช่นเดียวกับที่เธอไม่เคยยอมแพ้ในการเดินอยู่ในดินแดนที่ไม่มีใคร.。"
  },
  AwakerStory_11283_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11283_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11284_Content = {
    Text = "ศิลปินจากสีไคไม่ได้ใส่ใจมนุษย์ เธอเพียงแสวงหาความงามที่บริสุทธิ์ในความหมายที่แท้จริง โดยการบันทึกช่วงเวลาที่ผ่านไปอย่างรวดเร็วให้กลายเป็นนิรันดร์ \n แรงบัลดาลใจพุ่งออกมาอย่างไม่ขาดสาย มีดแกะสลักไม่เคยหยุดนิ่ง ทุกครั้งที่เสร็จสิ้นผลงาน หมอกสีปะการังก็กินช้าๆ ร่างกายไปทีละนิด ความเจ็บปวดและความสุขเกิดขึ้นพร้อมกัน และประติมากรก็ไม่ได้ใส่ใจตัวเอง。"
  },
  AwakerStory_11284_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11284_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11285_Content = {
    Text = "@3สร้างขึ้นในยุคสองของซามนิต ซึ่งตกแต่งด้วยสไตล์ที่ประณีตของที่สามปอมเปอีและเลมวาฮิ นี่คือที่อยู่อาศัยที่เป็นแบบฉบับของชนชั้นพ่อค้าที่ร่ำรวยในสมัยโรมัน มีลานกลางสองลาน ห้องอาหารสี่ห้อง และ@1@1\n...ทั้งหมดถูกเผาทิ้งในเหตุการณ์การกบฏทาสที่มีชื่อเสียงนั้น...ตามบันทึกจากช่วงเวลาเดียวกัน พบว่าที่ใต้ซากปรักหักพังมีการผนึกแมงมุมขนาดใหญ่สีขาวซีด ชาวบ้านเรียกมันว่า「เทพเจ้าแห่งเขาวงกต」และเชื่อมั่นว่าผู้ที่เหยียบเข้าสู่ดินแดนของแมงมุมจะหลงทางในทางเดินและทางเข้าที่ไม่มีที่สิ้นสุด และท้ายที่สุดจะกลายเป็นเจ้าภาพให้กับลูกหลานของมัน \nเรื่องเล่าที่น่าสนุกและน่าขนลุก แต่จะไม่ขัดขวางเรา@2@1\n——ตัดตอนจาก「@2บันทึกการขุดค้นซากปรักหักพัง」\n\n...สถานการณ์เลวร้ายมาก ท่านเซอร์กู๊ดแมน กลุ่มของโมเร็ตตี้หายไปหลายวันแล้ว เราทุกคนเข้าใจว่าเรื่องนี้ไม่มีความเกี่ยวข้องกับตำนาน「เทพเจ้าแห่งเขาวงกต」เลย แต่ก็น่ากังวลจริงๆ ขณะนี้เราตัดสินใจที่จะสิ้นสุดการสำรวจล่วงหน้าและกลับไปยังดูเรน \nนอกจากนี้ ทีมขุดค้นพบกลุ่มวัสดุที่มีลักษณะเป็นแกนเงินในซากปรักหักพัง ซึ่งอาจเกี่ยวข้องกับ@1ที่ท่านเคยกล่าวถึงก่อนหน้านี้...\n——ตัดตอนจากจดหมายถึงเซอร์กู๊ดแมน โดยคลาร์กสัน จอห์นสัน"
  },
  AwakerStory_11285_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11285_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11286_Content = {
    Text = "A. F. 2@2 ปี 11 เดือน เกิดแผ่นดินไหวครั้งใหญ่ในเขตเบเรน\nวันถัดมา ศาสตราจารย์สองท่านได้รับมอบหมายให้เดินทางไปยังพื้นที่ที่เกิดแผ่นดินไหว เพื่อค้นหาทีมนักสืบมิซากะที่ขาดการติดต่อหลังเกิดเหตุ\nทีมงานนี้เคยทำงานอยู่บริเวณชายฝั่งทะเลระหว่างแผ่นดิน โดยมีภารกิจหลักในการสำรวจและขุดค้นโบราณสถาน เพื่อหาความเชื่อมโยงที่เกี่ยวข้องกับ「ปรากฏการณ์หลอมละลาย」\nวันที่ 8 เดือนพฤศจิกายน ที่ที่มีข่าวลือว่าพบเห็นสมาชิกในทีมเป็นครั้งสุดท้าย ศาสตราจารย์@2พบซากพระราชวังที่ไม่ได้ถูกบันทึกในประวัติศาสตร์ และได้เก็บกุญแจเงินมาตรฐานมิซากะหมายเลข I–@2 แต่ไม่พบสมาชิกในทีม\nวันที่ 9 เดือนพฤศจิกายน มีการขุดพบเงินใจสองชิ้นที่บริเวณซาก และนำกลับไปยังลอนดีเนี่ยน โดยเนื่องจากมีคุณค่าทางประวัติศาสตร์จึงถูกเก็บรักษาไว้เพื่อรอวันปลุกตื่นอีกครั้ง."
  },
  AwakerStory_11286_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11286_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11287_Content = {
    Text = "วันดามาถึงมิซากะในวันแรกก็ถูกกล่าวหาอย่างรุนแรงในข้อหา「เหยียบย่ำผู้อื่นอย่างไร้ความปราณี」\nตามข้อมูลจากนักเรียนที่ไม่ประสงค์ออกนามคนหนึ่ง เขาแค่เดินผ่านห้องสมุดโดยบังเอิญ และได้สบตากับวันดาโดยไม่ตั้งใจ จากนั้นก็ถูกผลักลงไปที่พื้น @2 ถูกใส่ @3(นักเรียนคนนี้ปฏิเสธที่จะเปิดเผยรายละเอียดเพิ่มเติม) \nกระบวนการทำร้ายเกิดขึ้นตั้งแต่เริ่มจนเสร็จสิ้นไม่เกินห้านาที เหตุการณ์เลวร้ายมาก น่าหวาดกลัว \nคณะกรรมการวินัยมิซากะ(เรียกสั้นๆ ว่า MDC) จะให้ความสำคัญและเห็นอกเห็นใจต่อสถานการณ์ดังกล่าวอย่างสูง และได้ตั้งเป็นกลุ่มเฉพาะกิจ โดยจะดำเนินการปรับเปลี่ยนความคิดและพฤติกรรมของวันดาอย่างรอบด้าน เพื่อช่วยให้เขาปรับตัวเข้ากับชีวิตในมหาวิทยาลัยได้เร็วที่สุด."
  },
  AwakerStory_11287_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11287_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11288_Content = {
    Text = "「@1 มกราคม@1 วัน, สุสานมหาวิทยาลัยถูกทำลายอีกครั้ง จนถึงขณะนี้ นี่เป็นเหตุการณ์ขุดสุสานที่ร้ายแรงครั้งที่สามในเดือนนี้ \n สมาชิกสมาคมได้ทำการติดตามสอบสวนเป็นเวลาหลายสัปดาห์ และได้ระบุเบื้องต้นว่า ผู้ปลุกตื่นซังก้าเป็นผู้ต้องสงสัย \n เชื่อว่าผู้ที่เคยไปเยี่ยมชมห้องทำงานของประติมากรคนนี้จะต้องตกตะลึงกับรูปปั้นธีมมหาสมุทรที่มีรูปร่างหลากหลายและการดูหมิ่นที่แปลกประหลาด และจะสงสัยเกี่ยวกับแหล่งที่มาของวัสดุ: เราพบสร้อยลูกปัดเปลือกหอยที่น่าสงสารของนาแทชาในระหว่างการฝังศพ และหินแกรนิตอับบาร์ดีนที่มีวัสดุเดียวกับหลุมศพ แตกต่างจากพิคแมนที่หลงใหลในการอธิบายแนวคิดในการสร้างสรรค์ ซังก้ากลับยากที่จะเข้าใจ—แม้ว่าเธอจะยิ้ม แต่เธอก็เพิกเฉยต่อข้อสงสัยของเราโดยสิ้นเชิง \n ห้ามแตะต้องมีดแกะสลักของเธอ และห้ามอยู่กับเธอเพียงลำพังในห้องทำงาน—ศาสตราจารย์เดกสเตอร์เคยเตือนเราเช่นนี้ แต่เพื่อเปิดเผยความจริงเกี่ยวกับเหตุการณ์ขุดสุสาน วิธีการที่รุนแรงจึงเป็นสิ่งจำเป็น \n ตอนนี้คือ @1 มกราคม@1 เวลา 00:45 น. สมาชิกสมาคมนักชอบการวิเคราะห์ @2 ได้แอบเข้าไปในห้องทำงานของซังก้า ขอให้โชคดี @3」\n — คัดลอกจาก《สมาคมนักชอบการวิเคราะห์, บันทึกการสอบสวน S-618》"
  },
  AwakerStory_11288_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11288_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11289_Content = {
    Text = "โลทันมีป้ายติดอยู่มากมายมากเกินไป ไม่มีใครรู้ว่าควรจะมีท่าทีอย่างไรในการอยู่ร่วมกับนักดาบในชุดดำคนนี้\nถ้าเธออ่อนน้อมเกินไป เธอจะทำลายเข่าของคุณด้วยชื่อเสียงที่น่าเบื่อ; ถ้าเธอหยิ่งเกินไป เธอจะใช้ดาบยักษ์ตัดขาดความไม่เคารพของคุณ; ถ้าเธอแข็งกร้าวเกินไป เธอจะใช้การต่อสู้ทำให้จิตวิญญาณของคุณอ่อนลง\nแต่บางที นี่อาจเป็นความหยิ่งยโสของผู้ที่เกิดใหม่จากดาวเคราะห์: ในฐานะที่เคยเป็นการ์เดียน เธอควรมีสิทธิในการหยิ่งยโส。"
  },
  AwakerStory_11289_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11289_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11290_Content = {
    Text = "ทุกครั้งที่ค่ำคืนมาถึง นอติลาและแม่จะเข้าไปในคลังเก็บของด้วยกัน หยิบเครื่องมือหลากหลายชนิดขึ้นมา และใช้ชิ้นส่วนที่เก็บสะสมมาเพื่อประกอบมอเตอร์ไซค์ล้อเดียวชื่อว่า \"ฟันธง\" \n「ทำไมไม่ซื้อรถมอเตอร์ไซค์เลยล่ะ?」เธอถามแม่ที่ถือเครื่องมืออยู่ โดยเงยหน้าขึ้น \n「แบบนั้นเราก็ออกไปผจญภัยได้ทันทีเลยนะ」 \nแม่จับมือเธอ พร้อมสอนให้เธอเชื่อมโลหะได้อย่างรวดเร็วและมีคุณภาพ พร้อมกล่าวว่า \n「เครื่องจักรและมนุษย์ต่างก็มีอารมณ์และบุคลิกที่แตกต่างกัน ทุกคนที่เข้าใจเราอย่างแท้จริงจะสามารถใช้เวลากับเราได้นานขึ้น」 \n「เหมือนเพื่อนกันใช่ไหม?」 \n「ยกเว้นว่าเครื่องจักรที่เราสร้างขึ้น—ใช่แล้ว เหมือนเพื่อน」 \nล้อขนาดใหญ่ต้องแข็งแรง เครื่องยนต์ที่ติดตั้งต้องทนทาน เพราะเมื่อพวกเธอออกเดินทางแล้ว จะไม่หันหลังกลับง่ายๆ พวกเธอจะเดินทางไปทั่วโลกและร่วมกันทำภารกิจที่ยิ่งใหญ่ \nโรคภัยไข้เจ็บพรากแม่ไปจากเธอ ทิ้งไว้แต่เครื่องมือที่เต็มไปด้วย แต่กลับว่างเปล่าในอู่ซ่อมรถ นอติลากอดฟันธงที่ยังไม่เสร็จสมบูรณ์ ตั้งใจที่จะทำตามความฝันของเธอและแม่กับเพื่อนที่เย็นชาใบนี้ \nจนถึงการออกเรือครั้งสุดท้าย。"
  },
  AwakerStory_11290_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11290_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11291_Content = {
    Text = "[คำตอบ]\nในฤดูร้อนปีแอลลูเวียมที่ 3@2 มีข่าวลือเกี่ยวกับสัตว์ทะเลประหลาดแพร่กระจายอยู่บนเกาะอีเรียลาน มีชาวประมงอ้างว่าได้เห็นสัตว์กลุ่มหัวขา ซึ่งมีความสูงประมาณเท่าตึกห้าชั้นที่ใกล้ชายฝั่ง สัตว์นั้นมีทั้งตัวเป็นสีแดงเข้ม มีวงดำล้อมรอบกระจายอยู่บนหนวดของมัน\n\nเมื่อได้ยินข่าวลือเกี่ยวกับสัตว์ประหลาดนี้ ฉันกำลังทำการตรวจสอบปรากฏการณ์ที่น่าสงสัยในเขตแมนแลนร่วมกับรุ่นพี่ชื่อจอห์นสัน วันต่อมา รุ่นพี่ได้เตรียมเรือที่จะเดินทางไปยังเกาะอีเรียลาน และฉันเขียนรายงานฉบับนี้อยู่กลางมหาสมุทรอเมแลนต์\n\nวันที่สามของการเดินทาง พบซากปลาลอยอยู่บนพื้นผิวทะเลจนเต็มพื้น อาทิ ปลาซาบะ ปลาแฮลิบัต และปลาโลมา ฉันสาบานได้ว่าในกลุ่มซากนี้มีวาฬสเปิร์มตัวหนึ่งที่ตั้งท้องอยู่ด้วย แม้จะมีคำอธิบายจากลูกเรือเก่าว่าปรากฏการณ์นี้เกิดจากการขาดออกซิเจนในน้ำทะเลที่มาจากการเพิ่มขึ้นของประชากรใต้ทะเล แต่ฉันกลับรู้สึกว่าเราอาจพลาดบางสิ่งไป\n\nวันที่แปดของการเดินทาง อาการเมาเรือของฉันแย่ลง มีความรู้สึกคลื่นไส้อย่างแรงจนแทบไม่สามารถกินอาหารได้ แม้ว่าเราใกล้จะถึงเกาะอีเรียลานแล้ว แต่จอห์นสันยืนกรานอย่างมากว่าเราควรกลับไปทันที ฉันไม่เข้าใจเหตุผลของเขา แต่ฉันเลือกที่จะเชื่อใจรุ่นพี่คนนี้\n\n— เบลล์ โคลัมบัส \"รายงานการฝึกงานในฤดูร้อนปีแอลลูเวียมที่ 3@2\""
  },
  AwakerStory_11291_Title = {
