  },
  AwakerStory_11297_Content = {
    Text = "เธอไม่ได้เกิดมาพร้อมกับความกระหายเลือด ในอดีตเธอก็เคยได้รับสัมผัสของความอบอุ่นที่เจิดจ้าและชั่วครู่เหมือนดอกไม้ที่บานยามค่ำคืน การหักหลังและการถูกจองจำได้รดน้ำความแค้นที่ร้อนแรง เปลวไฟแห่งการแก้แค้นแผ่กระจายไปทั่วเมเซีย ด้วยหัวใจที่ถูกกัดกร่อนด้วยความเกลียดชังอย่างยาวนาน ตอนนี้เธอปิดกั้นตัวเองจากทุกคน..."
  },
  AwakerStory_11297_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11297_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11298_Content = {
    Text = "เนื่องจากร่างที่ปลุกตื่นซึ่งเป็นต้นกำเนิดของสมองในถังเคยมีประวัติในการหลุดพ้นจากตัวจำกัด S355 ปัจจุบันได้รับการดำเนินการย้ายโดยอาจารย์ชอร์ท และถูกจัดตั้งในตัวจำกัดการย่อยสลายพิเศษใหม่ \n ตัวจำกัดนี้ตั้งอยู่ในความลึกของสระดำ โดยมีการจัดสรรการตรวจสอบอย่างน้อยทุก 60 นาทีโดยกลุ่มตรวจสอบสระดำ ในขณะที่รับประกันว่าไม่มีเครื่องมือหรือวัตถุอื่นในรัศมี 30 เมตรรอบตัวจำกัด \n จากการตรวจสอบพบว่าร่างนี้ยังคงมีสติสัมปชัญญะตลอดเวลา แทบจะไม่มีการนอนหลับเกิดขึ้น ร่างนี้เคยพยายามบอกสมาชิกในกลุ่มเกี่ยวกับการทดลองปรับเปลี่ยนเงินใจที่ผิดกฎหมายที่เกิดขึ้นก่อนหน้านี้ สมาชิกในกลุ่มคนหนึ่งที่มีการสื่อสารสั้น ๆ กับร่างนี้จึงตกอยู่ในความบ้าคลั่ง \n ปัจจุบันกลุ่มตรวจสอบทั้งหมดประกอบด้วยสามคน ห้ามมีการสัมผัสหรือพูดคุยกับร่างนี้โดยเด็ดขาด และต้องสวมหมวกกันเสียงตลอดการตรวจสอบ \n ... \n ระดับการจำกัดความลับของร่างนี้ได้ถึงระดับสูงสุดในการควบคุมร่างที่ปลุกตื่น ผู้ที่มีความรู้เกี่ยวกับเรื่องนี้ห้ามเปิดเผยข้อมูลเกี่ยวกับร่างนี้ทั้งภายในและภายนอกมิซากะ หากไม่มีการอนุมัติจากอาจารย์และการดูแลโดยตรง ห้ามบุคคลใดเข้าไปเยี่ยมชม \n —— คัดจาก《รายงานการบันทึกกลุ่มตรวจสอบสระดำมิซากะ》"
  },
  AwakerStory_11298_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11298_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11299_Content = {
    Text = "พระองค์มีตัวตนอยู่จริง \n พระองค์คือสายตาที่พระเจ้าโปรยปรายออกมา เป็นกิ่งก้านที่พระเจ้าขยายออกไปในจักรวาล \n พระองค์เพลิดเพลินกับความยิ่งใหญ่ของประวัติศาสตร์ และปรารถนาความเจริญรุ่งเรืองของอารยธรรม \n พระองค์ต้องการก้าวข้ามความเหี่ยวเฉา ต้องการเหนือความตาย \n เธอต้องการบทกวีที่ต่ำต้อย ลมที่มีผงและเค็ม ต้องการใบไม้สีเงินและแสงจันทร์ที่มอซูล \n สตรีมีมนต์ขลัง แม่มด และแม่มด... สายตาของผู้คนเป็นเพียงสิ่งภายนอก \n หากแม้เพียงหยดเลือดเดียวสามารถหลบหนีจากการโจมตีสีดำได้ พระองค์ก็จะสามารถกอดความเป็นนิรันดร์อีกครั้ง。"
  },
  AwakerStory_11299_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11299_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11300_Content = {
    Text = "หนามแหลมของกุหลาบแทงทะลุหน้ากระดาษบทกวี ทิ้งรอยเลือดใสไว้ กลิ่นแอลกอฮอล์ลอยฟุ้งไปทั่ว เปลวไฟไร้สีลุกลามไปทั่วทุกแห่ง \n ในกองไฟนั้น ฮอร์ลาถือบทกวีสุดท้ายไว้ เขียนคำบรรยายเงียบ ๆ สำหรับเส้นทางสุดท้ายของกวีอัจฉริยะที่ซ่อนตัวอยู่ในเรือนดอกไม้。"
  },
  AwakerStory_11300_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11300_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11301_Content = {
    Text = "ช่วงวัยสาวของเธอนั้นใช้ชีวิตอยู่ในค่ายทหาร \n เช่นเดียวกับเด็กทุกคนที่เติบโตในค่ายทหาร เธอเชื่อมั่นในเกียรติยศของกองทัพอย่างไม่เปลี่ยนแปลง และมองว่ามันคือชีวิตของเธอ โลกของเธอนั้นเรียบง่าย: สิ่งที่ผู้บังคับบัญชารับรองคือสิ่งที่ถูกต้อง สิ่งที่ผู้บังคับบัญชาห้ามคือสิ่งที่ผิด \n「จงฟันไปที่ศัตรู เราจะมอบอิสรภาพที่แท้จริงให้กับแผ่นดินนี้; จงฟันไปที่กองทัพที่บุกเข้ามา อย่าเห็นใจพวกเขา การเสียสละในตอนนี้คือเพื่อความสงบสุขและความเจริญรุ่งเรืองในอนาคต」\n เธอฝึกฝนภายใต้คำขวัญนี้ และก้าวเข้าสู่สนามรบด้วยคำขวัญนี้ หลังจากการช่วยเหลืออย่างสุดชีวิตครั้งหนึ่ง เธอได้รับบาดเจ็บที่ขา และได้รับชื่อเสียงว่าเป็นวีรบุรุษสงคราม ตั้งแต่นั้นมาเธอจึงสวมเหรียญตราและถอยกลับมาเป็นผู้ฝึกสอนทหารใหม่ โดยไม่รู้เลยว่าขาที่บาดเจ็บนี้จะเปิดเผยโลกใบไหนให้กับเธอ \n อวัยวะที่ถูกตัดทอนถูกดูถูกเหยียดหยาม อัลวาจึงลาออกจากกองทัพ เมื่อเธอเดินออกสู่ท้องถนน เธอจึงได้ค้นพบว่าคำพูดอันแสนสว่างไสวของผู้บังคับบัญชาเป็นเพียงคำโกหกเท่านั้น — การปลดปล่อยนั้นเป็นเพียงฉากบังหน้าในการรุกราน ผู้คนจากต่างแดนต้องทนทุกข์ทรมาน \n นี่ไม่ใช่ประเทศในอุดมคติของเธอ นี่ไม่ใช่อนาคตที่สว่างไสวปราศจากเลือดและน้ำตา \n เพราะเหตุนี้เธอจึงยกดาบแห่งการชดใช้ขึ้นต่อหน้าผู้ร่วมงานเก่าของเธอ และสาบานว่าจะต่อสู้เพื่อความยุติธรรมที่แท้จริง。"
  },
  AwakerStory_11301_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11301_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11302_Content = {
    Text = "「ยินดีต้อนรับสู่ร้านแลกเปลี่ยนของดาฟโฟดิล เรามีบริการแลกเปลี่ยนสินค้าและซื้อหัวกะโหลก ราคาย่อมเยาและซื่อสัตย์ไม่มีโกง」\nในหมอกสีเทาที่ฟุ้งกระจาย ผู้หญิงคนหนึ่งได้สะบัดท่อไม้โบราณของเธอเบาๆ ใต้ชายหมวกที่สั่นไหว ริมฝีปากที่ปรากฏและหายไปนั้นวาดเป็นรอยยิ้มที่เต็มไปด้วยความคลุมเครือ。"
  },
  AwakerStory_11302_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11302_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11303_Content = {
    Text = "ทุกคนยอมรับความจริงอย่างรวดเร็วว่า ที่ไหนมีเจนกิน ที่นั่นมีบราวน์ และที่ไหนมีบราวน์ ที่นั่นมีเจนกิน และถ้าบราวน์ทำอะไรคนเดียว อย่าสงสัยเลยว่าจะต้องมีเงาของเจนกินอยู่เบื้องหลัง\n「อะไรคือการที่ฉันขโมย? ฉันมีหลักฐานว่าไม่อยู่ในที่เกิดเหตุ!」\nเด็กหญิงพูดพร้อมกับถือสิ่งของที่ถูกบราวน์「เอาไป」ไว้。"
  },
  AwakerStory_11303_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11303_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11304_Content = {
    Text = "ปี A.F.180 ภายใต้ผลกระทบจากภัยแล้งครั้งใหญ่ในซีกโลกเหนือ แม่น้ำคาราซูเกิดการตัดขาด \n ผู้อยู่อาศัยในพื้นที่ได้ขุดค้นพบโครงกระดูกมอนสเตอร์จากโคลนในลำน้ำ เนื่องจากแม่น้ำคาราซูมีความหมายว่า 「น้ำที่ผสมปนเป」 ในวัฒนธรรมท้องถิ่น โครงกระดูกนี้จึงถูกตั้งชื่อว่า 「กระดูกแห่งความโกลาหล」 \n ผ่านการตรวจสอบจากนักชีววิทยาทางทะเล พบว่าเป็นโครงกระดูกของวาฬปีกใหญ่ ยาวประมาณ 32 ฟุต และทั้งตัวถูกปกคลุมด้วยสารสีเงินชนิดหนึ่ง ปีถัดมา โครงกระดูกนี้ถูกประมูลในงานประมูลของอิซิสในราคา 130 ล้านเลโอฟัง \n สำนักงานการค้าปฏิเสธที่จะเปิดเผยตัวตนที่แท้จริงของผู้ซื้อ แต่ข่าวลือระบุว่า โครงกระดูกนี้ถูกส่งไปยังมหาวิทยาลัยเอกชนในชานเมืองเมืองลอนดีเนี่ยน。"
  },
  AwakerStory_11304_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11304_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11305_Content = {
    Text = "การหลงตัวเองที่ไม่สนใจใครนั้นก็แค่เกราะที่แสดงออกอย่างไม่จริงใจ ภายใต้ชุดเดรสที่ประณีตนั้นซ่อนอยู่หัวใจกบฏที่ไม่มีใครรู้\nอยู่ภายในกรงที่สวยงามซึ่งถูกสร้างขึ้นจากเรื่องเล่าศักดิ์สิทธิ์ มอร์ฟี่รู้ดีว่าความเสแสร้งของมนุษย์และพระเจ้านั้นเป็นอย่างไร: สายตาของผู้ศรัทธาที่มองมาที่เธอมีเพียงความกลัวและความสงสาร ความรักที่「ผู้เลี้ยงดู」มีให้เธอ ก็แค่การดูแลเครื่องบูชาเท่านั้น จุดจบของภารกิจจะไม่ใช่เกียรติยศ แต่คือความตายของตัวเธอเอง——เธอรู้ดีถึงจุดจบแล้ว จะไปหลงใหลในอาณาจักรที่คำสอนวาดภาพไว้ได้อย่างไร\nแผนการสร้างเทพ การฟื้นคืนของกษัตริย์เก่า ความหวังที่ไม่เป็นจริงมากมายถูกฝากไว้ที่เธอ——แต่ไม่มีใครเคยสนใจเลยว่าเธอเองต้องการที่จะรับชะตากรรมที่ต้องตายเพื่ออนาคตที่ไม่แน่นอนหรือไม่\nนกขมิ้นไม่อยากติดอยู่ในกรงตลอดไป ดังนั้นจึงกระพือปีกพุ่งไปที่รั้วที่เต็มไปด้วยพุ่มหนาม เธอตัดสินใจที่จะเสี่ยงชีวิตเพื่อหลุดพ้นจากการผูกมัดของชะตากรรม และต่อไปนี้จะต้องเป็นผู้ตัดสินใจทิศทางการบินของตนเอง\n「ฉันชื่อมอร์ฟี่... อย่าคิดว่าจะมาสั่งการฉัน! เรื่องไหนที่ควรทำ เรื่องไหนที่ไม่ควรทำ ฉันรู้ดีอยู่ในใจ」"
  },
  AwakerStory_11305_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11305_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11305_UnlockDesc_1 = {
    Text = "ผ่านด่านเนื้อเรื่องปกติบทที่ 5 「ตาพายุ」"
  },
  AwakerStory_11306_Content = {
    Text = "ในความเงียบเหงา เธอได้ต้อนรับการล่มสลายของสปิริตทะเล และได้รับการต่ออายุอย่างอัศจรรย์บนแผ่นดิน \n ไม่ว่าจะเกิดมาพร้อมกับความสุข หรือเลือกที่จะลืมเพื่อหลีกหนีจากความระทมทุกข์ ความบริสุทธิ์ที่ตรงไปตรงมานั้นกลับแผ่ซ่านเสน่ห์อันไร้ขีดจำกัด ทำให้ผู้คนไม่สามารถต้านทานได้ที่จะเข้าร่วมกับกองทัพของเธอ—นี่อาจเป็นกลยุทธ์เล็กๆ ของเธอในการขยาย 「กลุ่มเพื่อน」 ก็เป็นได้。"
  },
  AwakerStory_11306_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11306_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11307_Content = {
    Text = "ในฐานะที่เกิดจากความวุ่นวาย เธอคือพละกำลังแห่งความวุ่นวายที่บริสุทธิ์ เป็นจิตวิญญาณแห่งเสรีภาพที่ไม่สามารถถูกควบคุมได้ และยังเป็นระเบียบที่ยังไม่ได้ถูกกำหนด \n เธอต้องการความท้าทาย ต้องการการต่อสู้ และเมื่อแรงกระหายในการทำลายที่ไม่สามารถหยุดยั้งได้ถูกปลดปล่อย เธอจึงจะสามารถทำตามคำสั่งเดียวจากผู้สร้างได้ \n —— เพื่อเฝ้าดูดาวเคราะห์จนถึงวันสิ้นโลก เธอได้รอคอยการต่อสู้ที่เต็มไปด้วยความตื่นเต้นมานานเกินไปแล้ว。"
  },
  AwakerStory_11307_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11307_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11308_Content = {
    Text = "ฉันมีสิทธิ์ในการมีความปรารถนาไหม?\nถ้ามี ฉันสามารถเป็นส่วนหนึ่งของน้องสาวได้ไหม?\nทำให้เธอเป็นคนที่สมบูรณ์ ทำให้เราทั้งคู่สมบูรณ์.\nแบบนี้ฉันจึงสามารถแสดงออกถึง 「ความรัก」 ได้อย่างไม่มีข้อกังวล และเธอก็สามารถโอบกอด 「ความรัก」 ได้อย่างไร้กังวล.\nโอ้ ทิงค์ที่รัก... นี่คือสิ่งที่ฉันในฐานะเด็กที่เกิดมาก่อนควรทำให้เธอใช่ไหม。"
  },
  AwakerStory_11308_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11308_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11309_Content = {
    Text = "「คำวิจารณ์ที่ไม่ปรานี」·「คะแนนต่ำในเอกสาร」·「รายงานวิจัยที่ไม่ผ่าน」\nในเส้นทางการสอนหลายสิบปีของดอลล์ นักเรียนที่ได้รับใบรับรองจบการศึกษาจากเธอนับว่ามีน้อยมาก นักเรียนส่วนใหญ่ถูกทัศนคติที่เข้มงวดเกินไปของเธอกดดันให้ถอยออกไปและหันไปหาศาสตราจารย์คนอื่นๆ สุดท้ายชื่อเสียงที่ไม่ดีของศาสตราจารย์ดอลล์จึงเริ่มแพร่กระจายในหมู่นักเรียน\nแต่ก็มีนักเรียนบางคนเชื่อว่า เธอแค่ใช้มาตรฐานนี้ในการคัดเลือก「สาวก」เท่านั้น ผู้ที่มีความตั้งใจแน่วแน่ที่สุดเท่านั้นที่สมควรถือกุญแจที่เปิดประตูแห่งความจริงและติดตามเธอไปเปิดเผยผ้าคลุมความจริงของโลก\nด้วยความเชื่อนี้ แม้ว่าความเป็นไปได้ที่จะจบการศึกษาจากดอลล์จะน้อยมาก แต่จดหมายสมัครขอเรียนกับดอลล์ยังคงส่งเข้ามาอย่างต่อเนื่อง\nบางครั้ง รามอน่าที่ถูกเรียกมาให้ตรวจสอบจดหมายสมัครก็อดคิดไม่ได้ว่าถ้านักเรียนเชื่อเช่นนี้ก็ดีเหมือนกัน\nในมุมมองของรามอน่า เธอแค่ใช้มาตรฐานของผู้ปลุกตื่นในการเรียกร้องนักเรียนมนุษย์ เท่านั้นเอง."
  },
  AwakerStory_11309_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11309_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11310_Content = {
    Text = "ดาฟโฟดิลมีความเคลื่อนไหวที่น่าพิศวงในมหาวิทยาลัยมิซากะ เนื่องจากเธอมีความรู้ต้องห้ามในการเดินทางข้ามมิติอย่างอิสระ สามารถมาและไปได้ตามต้องการ ไม่ถูกจำกัดด้วยศูนย์กลางเงินใจใต้ดิน\nเธอมักจะขายอุปกรณ์หรือวัสดุลึกลับที่มาที่ไปน่าสงสัย บางครั้งก็ช่วยผู้ปลุกตื่นคนอื่นหนีจากการควบคุมของมหาวิทยาลัยมิซากะในระยะสั้น\nต่อมา ผ่านการเจรจา เธอได้เปิดสาขา 「ร้านค้าปลอบประโลม」 ของเธอในมุมหนึ่งของมหาวิทยาลัย ใกล้กับห้องพยาบาล\nแน่นอนว่าสินค้าทั้งหมดที่ขายจะต้องได้รับการลงทะเบียนและตรวจสอบจากมหาวิทยาลัยมิซากะ。"
  },
  AwakerStory_11310_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11310_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11311_Content = {
    Text = "ผู้บันทึก: เอริช ฟอน แวร์เนอร์\nวันที่: 7 พฤศจิกายน ปี 19@1\nพิกัด: 68°14′S, 67°10′W\n\nเนื่องจากซากปลาวาฬสเปิร์มจำนวนมากที่ลอยอยู่ผิดปกติบนเส้นทางเดินเรือ เราจึงถูกบังคับให้ขึ้นฝั่งบนเกาะน้ำแข็งที่ถูกสาปแช่งแห่งนี้ ใต้น้ำตกน้ำแข็งในอ่าวฟยอร์ดทางใต้ คณะสำรวจพบซากสัตว์ในกลุ่มเซฟาโลพอดที่มีความยาวประมาณห้าสิบฟุต ซากของมันมีสีน้ำเงินครามเข้ม และมีวงกลมซ้อนกันที่เรืองแสงสีน้ำเงินฟอสฟอรัสปกคลุมทั่วลำตัว โดยขอบของลวดลายวงกลมนั้นหลั่งเมือกบางๆ ออกมา หลังจากที่เราเก็บตัวอย่างและทำให้บริสุทธิ์แล้ว พบว่ามีผลึกสีน้ำเงินจำนวนมากที่น่าวิตกกังวลตกตะกอนออกมาจากเมือกนั้น\nถ้วยดูดบนหนวดของซากนี้มีเส้นผ่านศูนย์กลางเกินสองฟุต และบนผนังด้านในของถ้วยดูดมีลวดลายที่คล้ายกับอักษรที่ไม่รู้จักสลักอยู่ เส้นประสาทหลักอยู่ในสภาพเจลใสกึ่งโปร่งแสง และยังคงมีการเต้นเบาๆ แม้ในสภาพแวดล้อมที่อุณหภูมิติดลบสามสิบองศา (ดูรูปภาพแนบ D-7) ดร.แฮร์ริส นักชีววิทยาที่ร่วมเดินทางมาด้วย พยายามเก็บตัวอย่างเนื้อเยื่อเส้นประสาทหลัก แต่ในทันทีที่มีดผ่าตัดสัมผัสกับมัน ซากทั้งหมดก็แตกสลายเป็นผงในทันที ฝุ่นสีน้ำเงินครามที่มองเห็นได้ด้วยตาเปล่าลอยฟุ้งอยู่ทั่วห้องปฏิบัติการ\n\nระหว่างเดินทางกลับ ดร.แฮร์ริสเริ่มมีอาการเพ้อคลั่งอย่างต่อเนื่อง เขาวาดรูปทรงเรขาคณิตที่เป็นการผสมผสานระหว่างเกลียววนและทรงหลายหน้าบนผนังห้องซ้ำแล้วซ้ำเล่า และกรีดร้องว่า「พวกมันวางไข่อยู่ใต้แผ่นน้ำแข็งแอนตาร์กติกา」 ในเช้าวันรุ่งขึ้น ลูกเรือที่ออกตรวจพบว่าเขาจมน้ำเสียชีวิตในถังน้ำอับเฉา การชันสูตรพลิกศพพบว่าถุงลมในปอดของเขาเต็มไปด้วยจุลินทรีย์สีน้ำเงินคราม (มีแหล่งกำเนิดเดียวกับฝุ่นซากหมึกยักษ์) กัปตันสั่งให้เผาเสื้อผ้าทั้งหมดที่สัมผัสกับตัวอย่าง\nขอให้ไม่มีใครต้องสัมผัสกับฝันร้ายที่ซ่อนอยู่ใต้ชั้นน้ำแข็งนี้อีกเลย\n\n——《บันทึกการสำรวจแอนตาร์กติกา · ภาคผนวกที่ 37》"
  },
  AwakerStory_11311_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11311_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11312_Content = {
    Text = "เราจะลืมวีรบุรุษอูฮาชี่ได้อย่างไร? เขาเคยเป็นชายหนุ่มผู้โดดเด่นที่สุด นักรบคุกเข่าลงกลางผืนทรายสีทองยามอาทิตย์อัสดง เลือดอุ่นได้ชโลมทั่วร่างกายของเขา แร้งบินวนบนฟ้าเพื่อร้องเพลงอาลัยแก่เขา:\nไม่มีใครจะเคารพคุณด้วยน้ำตา ไม่มีใครจะฝังคุณด้วยเสียงร้องไห้ เพราะในขณะที่คุณยังมีชีวิต คุณก็ได้เป็นที่รู้จักไปทั่วโรมแล้ว"
  },
  AwakerStory_11312_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11312_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11313_Content = {
    Text = "A. F.@2ปี@1เดือน\nท่านลอร์ดคาเวนดิชที่รัก:\n\nขออภัยที่ฉันกล้าขอให้พนักงานบ้านฟเรย์นำกระดาษและปากกามาให้ฉัน ฉันพยายามใช้สติและความเรียบร้อยสุดท้ายเขียนจดหมายนี้ ด้วยความเจ็บป่วยอย่างหนัก ฉันไม่สามารถพบแม่ โบบี้ และท่านได้อีก ความคิดถึงนี้เพียงพอที่จะทำให้ฉันบ้า\nถูกขังอยู่ในห้องใต้ดินมาแล้ว... 353 วัน? ฉันไม่รู้ บางทีอาจจะ 326 วัน\nที่นี่หนาวมาก เต็มไปด้วยกลิ่นเน่าเปื่อย บาดแผลของฉันไหลออกมาเป็นเมือกสีดำ และถูกหนูแทะจนไม่เหลือเค้าเดิม แต่ไม่เป็นไร ความเจ็บปวดเป็นสิ่งที่ดี มันทำให้คนยังมีสติ\n「แวมไพร์ชั่วร้าย」,     「ทำให้ครอบครัวเสื่อมเสีย」...การแยกฉันออกจากคนอื่นเป็นการตัดสินใจที่ชาญฉลาดจนน่าแปลกใจ วิญญาณของฉันถูกปีศาจควบคุมไปแล้ว ในขณะที่เขียนจดหมายนี้ ฉันเพิ่งดูดเลือดจากชายเร่ร่อนที่เสียชีวิต ฟเรย์บอกว่าท่านเป็นผู้สั่งให้พามาจากถนน แม้ว่ารสชาติจะเปลี่ยนไปบ้าง แต่ฉันก็รู้สึกดีใจที่แท้จริง ท่านยังใส่ใจฉันอยู่\nนอกจากนี้...สามารถให้ผ้าห่มผืนหนึ่งได้ไหม? ตอนนี้ฉันไม่มีเสื้อผ้าอะไรที่จะปกปิดร่างกายเลย ฤดูหนาวในลอนดีเนี่ยนมันหนาวเกินไป\nจนถึงตอนนี้ ฉันยังคงคิดถึงช่วงเวลาที่เราใช้ร่วมกันในช่วงวันหยุดที่เวย์ติงแมนชั่นในวัยเด็ก\n\nน้องสาวที่จริงใจของท่าน\nลีห์\n——ดึงมาจาก「คดีแวมไพร์เคนซิงตัน·สรุปคดี: หลักฐาน C-601」"
  },
  AwakerStory_11313_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11313_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11314_Content = {
    Text = "A.F.31@1 ในช่วงกลางเดือนธันวาคม ตำรวจได้รับแจ้งความจากผู้จัดการโรงละครแห่งที่สองใน@2สวนดอกไม้ ผู้แจ้งระบุว่าภายในหนึ่งสัปดาห์เกิดเหตุไฟไหม้ขนาดเล็กถึงสี่ครั้งในโรงละคร และมีข่าวลือเกี่ยวกับ \"วิญญาณบัลเล่ต์\" แพร่กระจายในหมู่สมาชิกคณะบัลเล่ต์ที่ใช้โรงละครแห่งนี้อย่างหนาหู\nเพื่อให้การแสดงรอบปฐมทัศน์ของบัลเล่ต์เรื่อง \"บทเพลงหงส์\" ดำเนินไปอย่างราบรื่น ตำรวจจึงได้ร่วมมือกับสถานีดับเพลิงเขตตะวันตกในการสืบสวน\nก่อนวันการแสดง บมหาวิทยาลัยเมซาก์ได้เข้าควบคุมการสืบสวนในที่สุด นักสืบพบว่าเบื้องหลังจุดเกิดเพลิงไหม้หลายแห่งมีร่องรอยความรู้เหนือธรรมชาติ เหล่านักสืบ@3 พบว่ามี \"สิ่งปลุกสำเหนียกตัวหนึ่ง\" อยู่ในซากปรักหักพังใต้ดินของโรงละครแห่งที่สอง\nสิ่งปลุกสำเหนียกตัวนี้ไม่ได้ปราศจากสติสัมปชัญญะ เธอเรียกตัวเองว่า \"ลิซ\" หลังจากพูดคุย สิ่งปลุกสำเหนียกลิซได้สารภาพในที่สุดว่าเป็นผู้ก่ออัคคีภัย หลังจากการแสดงรอบปฐมทัศน์ของ \"บทเพลงหงส์\" สิ้นสุดลง นักสืบ@3 ได้พาสิ่งปลุกสำเหนียกลิซกลับไปยังมหาวิทยาลัยเมซาก์และดำเนินการจัดระเบียนอย่างเป็นทางการ\n\nตามบันทึกประวัติศาสตร์ ในปี A.F.29@1 เมื่อเกิดเหตุเพลิงไหม้ที่โรงละครแห่งที่สองใน@2สวนดอกไม้ โรงละครกำลังจัดการแสดงบัลเล่ต์ ในวันนั้น ผู้ที่เสียชีวิตในเปลวเพลิงนอกจากเหล่าผู้มีเกียรติในที่นั่งผู้ชมแล้วยังมีนักบัลเล่ต์สาวผู้มีชื่อว่า \"เอลิซาเบธ ซาลเลอร์\" ซึ่งเป็นนักเต้นคนสำคัญของเรื่อง。"
  },
  AwakerStory_11314_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11314_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11315_Content = {
    Text = "ทีละก้าว และอีกหนึ่งก้าว ฉันค่อย ๆ เดินเข้าไปในน้ำ พยาบาลหญิงที่สถานพักฟื้นไม่เคยอนุญาตให้ฉันเดินมาถึงที่ไกลขนาดนี้ ขอเพียงแค่การหลบหนีของคนป่วยคนหนึ่งซึ่งในเร็วๆ นี้ก็จะไม่สามารถจ่ายค่ารักษาพยาบาลได้ ไม่ทำให้เธอโดนตำหนิมากจนเกินไป\nแสงอาทิตย์ยามเย็นสะท้อนแสงบนทะเล กระแสน้ำพัดมาที่ฉันอย่างนุ่มนวลพร้อมกับยกกระโปรงของฉันขึ้น น้ำทะเลที่อบอุ่นเหมือนการกอดอันอบอุ่นของแม่\nร่างกายของฉันไม่เคยเบาสบายได้เท่านี้มาก่อน ในอกของฉันมีภูเขาไฟที่แห้งแล้งซึ่งตอนนี้เหลือเพียงลมทะเลที่พัดผ่าน\n「กลับบ้านเถอะ」\nฉันได้ยินเสียงทะเล ใช้เสียงของพ่อและแม่ของฉันเรียกฉัน พวกเขาไปยังอีกฟากของทะเลเพื่อหาเงินรักษาโรคให้ฉัน หากฉันไม่ได้เกิดมาพร้อมร่างกายที่โชคร้ายเช่นนี้ พวกเขาคงไม่ต้องทุกข์ยากขนาดนี้ใช่ไหม หากฉันสามารถหายไปกลางทะเลในคืนเดือนหงายโดยไม่ก่อให้เกิดเสียงใด ๆ... ฉันเคยคิดแบบนี้นับครั้งไม่ถ้วน แต่เมื่อคิดถึงใบหน้าที่เศร้าของพ่อแม่ ฉันก็ไม่สามารถทำได้\nแต่แล้ววันหนึ่ง บนคืนเดือนหงาย เรือที่พ่อแม่โดยสารก็หายไปไร้ร่องรอยกลางทะเล\n「กลับบ้านเถอะ」\nฉันใช้กำลังทั้งหมดที่มีเร่งฝีเท้าให้เร็วขึ้น ทะเลมักเปิดรับทุกดวงวิญญาณที่ทุกข์ทรมานอย่างสงบเสมอ และสำหรับฉัน สถานที่ที่พ่อแม่อยู่คือที่หลบภัยอันนิรันดร์\nเมื่อความมืดมิดจากทุกทิศทุกทางมาถึง ในชีวิตฉันนี่เป็นครั้งแรกที่ฉันสามารถหายใจได้อย่างเป็นอิสระ."
  },
  AwakerStory_11315_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11315_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11316_Content = {
    Text = "ปัญญาที่เกินมนุษย์ทำให้ร่างกายต้องแบกรับภาระหนัก เขาต้องหลับใหลมากกว่า15ชั่วโมงในแต่ละวัน และเมื่อเขาตื่นขึ้นมาก็มักรู้สึกง่วงอยู่เสมอ。\nในความฝัน เขาบางครั้งสามารถรู้สึกถึงความโกรธแค้นของเทพเจ้า; บางครั้งสามารถฝันถึงมิติที่สลับซับซ้อน; บางครั้งแม้แต่สามารถเดินเข้าไปในที่ลึกๆ และเผชิญหน้ากับพระเจ้า...\nเขาไม่เคยขอพรจากพระเจ้าเพื่อการเปิดเผยหรือคำทำนาย แต่ไม่ว่าจะหลบหนีอย่างไร คำทำนายก็ยังคงเกิดขึ้นอยู่ดี。\nเขาไม่เคยขอให้มีการเครื่องบูชา การถูกเคารพนับถือและถูกยำเกรงเป็นสิ่งที่ผู้อื่นทำโดยพลการ เขาไม่มีความสนใจในทุกสิ่ง。\nการฟื้นคืนชีพก็แค่รบกวนความฝันอันยาวนานของเขาเท่านั้น。\nไม่จำเป็นต้องเรียก ไม่จำเป็นต้องขอพร。"
  },
  AwakerStory_11316_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11316_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
