  AwakerStory_11325_UnlockDesc_1 = {
    Text = "ผ่านด่านเนื้อเรื่องปกติบทที่ 5 「ตาพายุ」"
  },
  AwakerStory_11326_Content = {
    Text = "ในปีที่ 282 ของอัลลูวิ เดือนมิถุนายน ตามคำขอการสอบสวนที่ส่งโดยคณะกรรมการตรวจสอบข้อตกลงมิสเดีย เราได้ส่งนักสืบไปยังพื้นที่นิวเลโอ \n หลังจากเหตุการณ์อุกกาบาตตกเมื่อหนึ่งปีก่อน อัตราการเสียชีวิตที่ผิดปกติในพื้นที่นี้ยังคงสูงอยู่ \n นอกจากนี้ นักสืบยังพบพืชที่มีการกลายพันธุ์หลายชนิดที่จุดตกของอุกกาบาต หลังจากการวัดด้วยเครื่องมือ พบว่าพืชเหล่านี้มีการแผ่รังสีในระดับสูงซึ่งน่าสงสัยว่าเกิดจากอุกกาบาต \n อย่างไรก็ตาม ในหลุมอุกกาบาตไม่มีแร่ธาตุต่างดาวใด ๆ ปากคำของชาวบ้าน ระบุว่า ในวันที่สามหลังจากอุกกาบาตตก กลุ่มนักวิทยาศาสตร์สวมชุดขาวได้ตัดและนำอุกกาบาตไป \n(หมายเหตุ: น่าสงสัยว่าเป็นองค์กรวิทยาศาสตร์เอกชน ตัวตนยังไม่ชัดเจน) \n หลังจากการประสานงานระหว่างคณะกรรมการตรวจสอบและรัฐบาลท้องถิ่น ชาวบ้านทั้งหมดได้ย้ายออกจากที่นี่ และพื้นที่นี้ได้รับการประกาศอย่างเป็นทางการว่าเป็นเขตห้ามอยู่อาศัย \n ตามการคำนวณของห้องปฏิบัติการฟิสิกส์มหาวิทยาลัยมิซากะ เขตนี้จะต้องมีการห้ามอยู่อาศัยอย่างน้อย 80 ปี."
  },
  AwakerStory_11326_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11326_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11327_Content = {
    Text = "ในเรื่องการเลือกคู่ต่อสู้ โลทันมีมาตรฐานของเธอเอง\nนักรบจากสถาบันส่วนใหญ่เรียนจนสมองเสีย คิดแต่เรื่องทฤษฎีที่ไม่เป็นรูปเป็นร่าง น่าเบื่อหน่าย\nผู้ที่โดดเด่นในกองทัพมักถูกข้อบังคับและศีลธรรมผูกมัด รู้สึกน่าเบื่อมาก\nมีเพียงอัจฉริยะที่มีพรสวรรค์โดยธรรมชาติและมีสัญชาตญาณการต่อสู้เท่านั้น ที่จะได้รับความสนใจจากเธอ\nสัตว์ยักษ์ที่มีอายุยืนยาวพอๆ กับดาวเคราะห์ ยับยั้งความต้องการต่อสู้ รอคอยอย่างเคารพให้คู่ต่อสู้ที่ได้รับการยอมรับเติบโตจนถึงจุดสูงสุด——เด็กหนุ่มที่มีพรสวรรค์อย่างมาก เขาบัญชาพลังจากทะเลลึก ความแข็งแกร่งของจิตวิญญาณสามารถเชื่อมต่อกับเทพเจ้าแห่งนอกโลกได้ หากมีเวลาเขาจะต้องเติบโตเป็นผู้ที่น่าปรารถนา\nแต่ อาจเป็นเพราะเวลาที่ยาวนานทำให้การตัดสินใจของเธอผิดพลาด ในครั้งนี้ วิญญาณแห่งความวุ่นวายมองผิดไป เรื่องราวมากมาย โลทันไม่ต้องการพูดถึงกับใครอีก\nเรารู้เพียงว่า ตั้งแต่นั้นมา เธอได้ดูถูกผู้ที่「ไม่ตั้งใจพัฒนา」และ「ไม่พยายามก้าวหน้า」"
  },
  AwakerStory_11327_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11327_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
