  AwakerStory_11328_Content = {
    Text = "หมายเลขเงินใจ：B-005\nเวลาขุดค้น：A.F.1@1ปี@3เดือน\nสถานที่ขุดค้น：ชนบทฟลานเดอร์ ในซากสุสานโรมันโบราณที่ไม่รู้จัก\nรายละเอียดการบันทึก：ผู้ถือเงินใจชื่อว่า ลูดวิก ปริน เนื่องจากเหตุการณ์อัญเชิญวิญญาณจึงถูกตัดสินโดยศาสนาท้องถิ่นให้ประหารด้วยไฟ ปรินอ้างว่าได้รับเงินใจนี้จากสนามรบในสงครามครูเซดครั้งที่เก้า หลังจากนั้นได้เดินทางไปยังบริเวณบราบันต์ ร่วมกับ「ผู้รับใช้จากนอกโลก」,「คู่หูที่มองไม่เห็น」 เพื่อจัดพิธีบูชายัญที่มีความรุนแรงสำหรับการอัญเชิญ「สิ่งที่ไม่สามารถบรรยายได้」\nผู้บันทึก：วอร์ด ฟิลลิปส์\n——《รายงานการได้รับเงินใจของผู้ปลุกตื่น：B-005》"
  },
  AwakerStory_11328_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11328_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11329_Content = {
    Text = "ในความเหงา คนหนึ่งต้องเหมือนกับทีม 24 มีความคิดที่ยุ่งเหยิง—พวกเธอกระซิบและหัวเราะคิกคักในความมืด ไม่หยุดดึงรั้งจิตใจของ 24 ด้วยความปรารถนาที่จะกลืนกินเธอเข้าไป ในกลิ่นเหม็นจากท่อระบายน้ำที่มุมถนน ขนฝ้ายที่ปลิวไปทั่วในเขตก่อสร้าง ขนมปังดำที่หมดอายุ... อดีตได้ผ่านพ้นไป ไม่มีใครจดจำหญิงงานธรรมดาในเขตตะวันออก เธอในที่สุดก็ปลดปล่อยร่างกายที่อ่อนล้า แต่กลับก้าวเข้าสู่บึงโคลนใหม่。"
  },
  AwakerStory_11329_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11329_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11330_Content = {
    Text = "ในสองพี่น้องนี้ มีคนหนึ่งที่ไม่ควรเกิดมา\nที่ดาวเคราะห์แห้งแล้งในกลุ่มดาวลีรา ซึ่งเฟนท์และทิงค์ได้ใช้ชีวิตครึ่งหนึ่งในคำพูดที่ไม่ดี\nแต่ใครกันแน่คือคนที่ไม่ถูกยอมรับ?\nพี่สาวเฟนท์แข็งแกร่งแต่ไม่สามารถควบคุมตัวเองได้ พลังชีวิตที่เธอแย่งชิงมักจะไหลผ่านไปเหมือนน้ำในแม่น้ำ เธอจึงต้องพึ่งพาการเลียหยดน้ำค้างที่เหลืออยู่เพื่อประทังชีวิต\nน้องสาวทิงค์สวยงามแต่ไม่สามารถพึ่งพาตนเองได้ ชีวิตที่ดื้อรั้นเหมือนผักตบชวามิอาจหยั่งรากได้ ต้องวนเวียนอยู่รอบๆ พี่สาว\nบางที พวกเธออาจคิดว่าตนเองคือคนที่ไม่ควรมีอยู่ เพียงแต่เฟนท์ตัดสินใจก่อน——ด้วยการคุกคามตัวเอง เธอจึงผลักน้องสาวเข้าสู่การเดินทางที่จะจากไป\n「ไปเถอะ ทิงค์ อย่าให้ฉันทำให้เธอหยุดอยู่ที่นี่」\n「เธอต้องร้องเพลงระหว่างดาวและกลายเป็นสีสันที่ได้รับการจับตามองที่สุด」"
  },
  AwakerStory_11330_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11330_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11331_Content = {
    Text = "ส่วนใหญ่จะนั่งเงียบๆ ในมุมหนึ่งของพื้นที่ เหมือนกับประภาคารที่แท้จริง ที่จะพูดขึ้นเพื่อดึงทุกคนกลับสู่เส้นทางที่ถูกต้องและให้คำแนะนำในเวลาที่หลงทาง\nไฟสว่างจะสามารถส่องออกมาให้เห็นถึงความบ้าคลั่งและความหวาดระแวงของเธอได้ก็ต่อเมื่ออยู่ร่วมกับผู้มาเยือนจากทะเลลึกคนอื่นๆ\nภายใต้รูปลักษณ์ที่เงียบสงบและมีสติ ฟาร์โรสกลับมีความรู้เกี่ยวกับการเดินเรือในมหาสมุทรอย่างน่าประหลาด แม้ว่าจะยังไม่สามารถล้างข้อกล่าวหาเรื่องการลักพาตัวและบูชายัญนักเดินเรือได้ และยังอยู่ภายใต้การควบคุมของผู้พิทักษ์ แต่ฟาร์โรสก็ยังช่วยให้ทางโรงเรียนปรับปรุงเอกสารที่เกี่ยวข้องกับการเดินเรือได้มากมาย\n——ตามข้อเสนอแนะจากนักเดินเรือของเรือที่ร่วมมือกับทางโรงเรียน ข้อเสนอแนะในการปรับปรุงของฟาร์โรสมีประสิทธิภาพ แต่บ่อยครั้งจะมีเจตนาหรือไม่ตั้งใจที่จะชี้นำเส้นทางไปยังพื้นที่สามเหลี่ยมมองเกิล\nทางโรงเรียนทราบเรื่องนี้แล้ว จึงห้ามฟาร์โรสเข้าถึงเอกสารที่เกี่ยวข้องกับมหาสมุทรทุกชนิด."
  },
  AwakerStory_11331_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11331_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11332_Content = {
    Text = "นักเล่นแร่แปรธาตุประจำพระองค์ของคาลิกูลา มาร์คัส แอนติส ได้สร้าง 「โกลเอ็ม」 โดยต้องใช้ชีวิตของมนุษย์จำนวนมากเป็นค่าใช้จ่าย \n เนื่องจากพิธีกรรมการสร้างไม่สมบูรณ์ จึงต้องดื่มเลือดมนุษย์จำนวนมากทุกวัน เพื่อฆ่าศัตรูทางการเมืองของคาลิกูลาและช่วยเขาในการสวมมงกุฎเป็นจักรพรรดิแห่งโรม \n ทรราชคาลิกูลาได้ขึ้นครองราชย์ไม่ถึงสี่ปีก็ถูกฆาตกรรม เขาถูกล็อกไว้ในอุโมงค์ใต้แท่นบูชาที่ถูกทำลายโดยกลุ่มคนโกรธแค้นและกลัว ต้องทนทุกข์กับความหิวโหยและกระหายน้ำเกือบพันปี \n ในช่วงเวลายาวนาน เขามีชีวิตอยู่โดยการดูดเลือดหนู ความกระหายที่สืบทอดมาจากสายเลือดทำให้เขาบ้า \n ไม่พอเลย ยังไม่พอ... \n ในยุค@2 พ่อมดจากเลบานอนได้พบเขา และสัญญาว่าจะช่วยให้เขาหลุดพ้น โดยมีเงื่อนไขว่าเขาต้องฆ่าชนเผ่าเลมวาซีในสนามรบ \n นี่เป็นเรื่องดีขนาดนี้เลยเหรอ? \n เขาทำภารกิจได้อย่างง่ายดาย แต่มีเรื่องเล็กน้อยเกิดขึ้น: เพราะความตื่นเต้นเกินไป เขาเผลอฆ่าคนทั้งหมดในสนามรบและดูดเลือดของพวกเขาจนหมด——รวมถึงพ่อมดและตัวเขาเองด้วย"
  },
  AwakerStory_11332_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11332_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11333_Content = {
    Text = "ปลุกตื่นวัสดุ G752a เงินใจ พบในกองโคลนเน่าเสียที่ซากเรือนจำประตูใหม่ลอนดีเนี่ยน.@2นักสืบในทางเดินของห้องขังที่มืดมิดบังเอิญเหยียบหัวกระโหลกที่แตกหักลื่นล้ม จึงค้นพบมันโดยบังเอิญ.\nผลลัพธ์การปลุกตื่นเบี่ยงเบนจากที่คาดไว้ ในเมือกหลอมละลายสีดำที่อุบัติขึ้นไม่ใช่นักโทษประหารที่โหดเหี้ยม หรือเพชฌฆาตที่แข็งแรง แต่เป็นสาวตัวเล็กที่มีรอยยิ้มเจ้าเล่ห์."
  },
  AwakerStory_11333_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11333_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11334_Content = {
    Text = "@2ชื่อที่ถูกเขียนซ้ำแล้วซ้ำเล่าในประวัติศาสตร์。\nนักบวช แม่ ราชินี พระราชินี แม่มด……ชื่อนี้ถูกให้ชื่อเรียกมากมายเกินไป จนทำให้นักประวัติศาสตร์ยังยืนยันไม่ได้ว่าตำแหน่งใดที่สามารถแทนที่ร่างผู้ปลุกตื่นที่เรารู้จักในปัจจุบัน。\nทาอิสเองก็ไม่ลังเลที่จะแบ่งปันอดีตของเธอกับเรา——ทั้งหมดนั้นคือเธอ แต่ก็ไม่ใช่ทั้งหมด。\n「เกิดมาในตระกูลสูงส่งคือเธอ。」\nทาอิสคือเด็กหญิงที่เปล่งประกายที่สุดในวิหาร ในฐานะลูกสาวของนักบวช เธอสง่างามดุจหงส์ และอ่อนโยนดุจแสงจันทร์。\n「กราบไหว้ที่ต้นไม้นั้นคือเธอ。」\nทาอิสคือใบไม้ที่สดใสที่สุดบน「ต้นไม้」 ความเชื่อมั่นทำให้เธอได้รับพรจาก「ต้นไม้」。\n「ถูกดูดเลือดออกจากร่างกายคือเธอ。」\nเมื่อภัยพิบัติมาถึงและอาคารล้มทลาย อารยธรรมโบราณและโง่เขลาเลือกเธอที่ดีที่สุด。\n「เลือดในเส้นเลือดคือสารจากต้นไม้คือเธอ。」\n「ต้นไม้」ที่ได้รับการเคารพจากประชาชนมีการเลือกของตนเอง กิ่งก้านฝังรากอยู่ในร่างกาย มอบอายุเกือบจะเป็นอมตะให้กับผู้ศรัทธา。\n「แต่ เธอไม่ใช่ผู้ที่ต้องการทำลายอารยธรรม。」\nสิ่งที่ทาอิสต้องการไม่เคยเป็นการทำลายโลก。\n「แต่คุณทาอิส คุณต้องการอะไรครับ?」\n「เอ๊ะ——ไม่ใช่พูดกันไว้แล้วเหรอ? เมื่อเราให้ผลผลิตระหว่างกัน คุณก็จะรู้คำตอบแล้ว。」"
  },
  AwakerStory_11334_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11334_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11335_Content = {
    Text = "เอลวาไม่เคยสงสัยในความยุติธรรมของตัวเอง แต่วันที่หม่นมัวและคืนที่ว้าวุ่นได้มอบความตระหนักรู้ที่ชัดเจนให้กับเธอ \n สิ่งที่ไม่เป็นจริงนั้นมีอยู่จริง \n จุดเริ่มต้นแรกเริ่มไม่เคยเปลี่ยนแปลง ความยุติธรรมที่เธอต่อสู้นั้น ไม่ใช่องค์กรที่กลายเป็นผู้รุกราน ไม่ใช่บุคคลที่ตะโกนสโลแกน แต่เป็นสิ่งที่ตั้งอยู่ในความเชื่อของเธออย่างเต็มที่ \n\n ชีวิตทั้งหมด ความบริสุทธิ์ทั้งหมด ความฝัน ความทะเยอทะยาน และความปรารถนาดีทั้งหมด ในหน้ากระสุนสามารถเปลี่ยนเป็นเถ้าถ่านได้อย่างง่ายดาย \n สิ่งที่สูญเสียไปในสงครามจะไม่มีวันกลับมา มันเหมือนกับปีศาจในนรกที่ค่อยๆ กินทุกสิ่งที่ดีงาม \n ดังนั้น ผู้ที่ก่อสงครามเพื่อความเห็นแก่ตัวของตนเอง ก็ต้องลิ้มรสความรู้สึกของการหายไปในอากาศ จะมีวีรบุรุษที่แท้จริง ผู้มีความหมายใหญ่หลวง ต่อสู้เพื่ออนาคตที่สดใสของทุกคนอย่างไม่เห็นแก่ตัว \n นี่แหละคือคุณค่าของความยุติธรรม \n ... \n\n หากผิดพลาด ก็ต้องแก้ไข \n ต้องทำให้การเสียสละคุ้มค่า ต้องทำให้ขาทั้งสองที่ถูกตัดและความเจ็บปวดที่หลงเหลือคุ้มค่า \n หากมีสิ่งที่โชคร้ายถูกทำลาย ก็ต้องใช้แขนขาเทียมใหม่มาทวงคืน \n สิ่งเล็กน้อยที่เปราะบางเหล่านั้น จะไม่มีวันสูญเสียแสงสว่างของมัน \n ทุกสิ่งเพื่อยูโทเปียที่แท้จริงที่ไม่มีเลือดและน้ำตา。"
  },
  AwakerStory_11335_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11335_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11336_Content = {
    Text = "ต้องระมัดระวัง คำพูดที่เยือกเย็นและมีสติปัญญาของเธอนั้นมีเสน่ห์ที่ทำให้หลงใหล อย่าสงสัยว่าภายใต้ศีรษะที่แปลกประหลาดนั้นมีใบหน้าที่แตกต่างหรือไม่ เพียงแค่ต้องเข้าใจว่าเธอมีความไม่พอใจอย่างยาวนานต่อร่างกายที่คล้ายมนุษย์นี้ \n แสงไฟของเธอเคยดึงดูดผีเสื้อกลางคืน และเคยทำให้ผู้ที่หลงทางต้องพบกับความตาย ขณะนี้ดูเหมือนว่ามันได้แสดงถึงความสับสนของผู้ที่หลงทางอยู่。"
  },
  AwakerStory_11336_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11336_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11337_Content = {
    Text = "น้ำท่วมที่ซัดสาดไปทั่วโลกได้พัดพาเอาอารยธรรมออกไป แต่ก็ชะล้างฝุ่นละอองของประวัติศาสตร์ออกไปด้วยเช่นกัน。\nหลังจากภัยพิบัติ ผู้คนได้มองเห็นประวัติศาสตร์ที่ถูกลืมเลือนบางส่วนจากซากโบราณสถานในเมืองมอซูล。\n「ต้นไม้」ตั้งตระหง่านอยู่ที่จุดตัดของสองแม่น้ำ ไหลน้ำสีแดงสดลงมาและธาราไปยังอารยธรรม。\n「ต้นไม้」ไม่เคยตาย มีชีวิตอยู่ตลอดไป。\nนักประวัติศาสตร์โบราณในที่สุดก็ยืนยันว่า 「ต้นไม้」 ไม่มีตัวตนจริง เป็นอุปมาเกี่ยวกับอารยธรรมโบราณ เป็นสัญลักษณ์ทางจิตวิญญาณ。\nในมุมที่ไม่มีใครเห็น เมล็ดพันธุ์ได้หยั่งรากในทุกที่ของโลก。"
  },
  AwakerStory_11337_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11337_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11338_Content = {
    Text = "「คุณเจ้าขา โปรดตีฉันเถอะ」\nในดวงตาที่ควรจะแห้งเหือดของเธอมีเปลวไฟแห่งความปรารถนาแผดเผา น้ำตาเทียนไขที่หลอมละลายไหลรินดั่งน้ำตา\nความหิวโหย ความเจ็บปวด การสาปแช่ง ความสกปรก ทุกสิ่งที่เธอต้องการให้ถูกดูหมิ่น และทุกสิ่งที่เธอมอบความสุขให้ ในที่สุดก็ปรากฏตัวขึ้นที่นี่ในขณะนี้。"
  },
  AwakerStory_11338_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11338_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11339_Content = {
    Text = "เธอคือ นักขับร้องระหว่างกลุ่มดาว เป็นฝุ่นดาวที่เปล่งประกาย。\nเธอคือ นกที่ถูกขังในกรงทอง เป็นเครื่องเล่นแผ่นเสียงที่ถูกทิ้งอย่างไม่ใส่ใจ。\nเมื่อดาวร้างกำลังถูกทำลายล้างในจักรวาล เธอถูกบังคับให้ได้รับความหวังในชีวิต กลายเป็นผู้เดินทางที่รักบ้านเกิดในอวกาศที่ไร้เจ้าของ ผู้ค้นหาที่ร้องเพลงตลอดไป。\n「พี่สาว... แม้ว่าฉันจะเป็นคนเดียวที่สามารถเดินได้อย่างอิสระในพวกเรา แต่ตลอดเวลานั้น ก็เป็นเธอที่สนับสนุนฉันนะ」"
  },
  AwakerStory_11339_Title = {
    Text = "ข้อมูลพื้นฐาน"
