  AwakerStory_11339_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11340_Content = {
    Text = "ร่างกายที่ถูกฉายออกมาจากความตั้งใจนี้หยุดอยู่ในรูปแบบของสาวน้อยที่จากไปก่อนวัยอันควร ชุดที่เน่าเปื่อย ผิวที่ซีดเผือด ดวงตาที่เต็มไปด้วยเงามืดจากอดีต สื่อสารอย่างไม่มีเสียงถึงบางสิ่งที่ถูกโรคภัยและความทุกข์ทรมานบ่วงรัดอยู่。"
  },
  AwakerStory_11340_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11340_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11341_Content = {
    Text = "ตั้งแต่เหตุการณ์@2 เคคัสได้จับมือปรองดองกับเรา และกลายเป็นสมาชิกนอกระบบของระบบผู้ปลุกตื่น เขาเข้าใจความรู้@1แค่เพียงเล็กน้อย แต่ยินดีที่จะนำเสนอและแบ่งปัน\nเขาเต็มไปด้วยความอ่อนน้อมต่อคนอย่างธูลู มิเรียม โกไลแอท และคนอื่น ๆ แต่กลับมองไปยังเผ่าพันธุ์อื่น โดยเฉพาะมนุษย์ ด้วยสายตาที่มืดมนและไม่เป็นมิตร นักวิจัยที่เคยอ่านแฟ้มข้อมูลเข้าใจความหวาดระแวงของเขา อย่างไรก็ตาม ผู้ปลุกตื่นที่มีอารมณ์ร้ายบางคนกลับไม่สามารถทนได้ บรรยากาศที่ตึงเครียดแบบนี้มักต้องให้ซิลเวียออกมาช่วยบรรเทาและแก้ไข เคคัสกับซิลเวียก็เริ่มสร้างความไว้วางใจกันมากขึ้น\nภายใต้การชี้แนะของซิลเวีย เคคัสได้ตื่นรู้ถึง「ความเข้าใจของเผ่าพันธุ์สูง」 และหลีกเลี่ยงการตอบโต้ต่อการยั่วยุของผู้อื่น\n「เด็กคนนั้นมักจะเต็มไปด้วยความอบอุ่นเมื่อระลึกถึงแม่มนุษย์ของเขา ทุกคนบอกว่าแม่คือเกณฑ์มาตรฐานในการรับรู้โลกของเด็ก โดยพื้นฐานแล้ว ความเป็นศัตรูของเขาต่อมนุษย์เกิดขึ้นจากการเลี้ยงดู ดังนั้น เขาแค่ขาดการชี้นำและความใส่ใจเท่านั้น」ซิลเวียได้เขียนไว้ในบันทึกการให้คำปรึกษาทางจิตใจ."
  },
  AwakerStory_11341_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11341_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11342_Content = {
    Text = "ผู้ดูแลข้อมูลของร่างที่ถูกปลุกได้ส่งแฟ้มข้อมูลของเธอไปยังฝ่ายบริหารนักเรียนหลายครั้ง แต่กลับถูกเธอส่งคืนมาอีกครั้ง ถูกฝังอยู่ใต้ภูเขาเอกสาร\n「วางไว้ที่นี่ก็พอ สุดท้ายจะต้องส่งมาอยู่ดี」\nน้ำเสียงของเธอยังคงสงบเช่นเคย แต่แววตากลับกระพริบไม่หยุด\n\nใต้ความสงบนี้ ซ่อนอารมณ์อันยิ่งใหญ่เช่นใดกันนะ?"
  },
  AwakerStory_11342_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11342_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11343_Content = {
    Text = "「หากคุณเป็นครั้งแรกที่ต้องทำภารกิจสำรวจล่ะก็ ไปหาอ็อกเกียร์มาร่วมทางด้วยสิ!」\nเมื่อเผชิญความกังวลใจของนักสำรวจหน้าใหม่ รุ่นพี่ที่มีประสบการณ์มักจะให้คำแนะนำเช่นนี้ อ็อกเกียร์เป็นที่นิยมในหมู่นักเรียนและอาจารย์อย่างเหนือความคาดหมาย\nแม้ว่าอุปนิสัยดั้งเดิมของเขาจะทำให้เกิดเหตุการณ์ไม่คาดฝันเล็กน้อยในบางครั้ง แต่ด้วยการสนับสนุนซึ่งกันและกัน อ็อกเกียร์ก็มักจะสร้างจังหวะที่เข้ากันได้อย่างลงตัวกับนักสำรวจคนอื่น ในช่วงไม่กี่ปีมานี้ การให้อ็อกเกียร์ร่วมภารกิจกับนักสำรวจหน้าใหม่ครั้งแรกก็ได้กลายเป็นแนวปฏิบัติที่ทุกคนในโรงเรียนเห็นพ้องต้องกัน เรื่องขำขัน เช่น 「อ็อกเกียร์จะเตรียมเสื้อคลุมให้กับนักสำรวจหญิง」 หรือ 「อ็อกเกียร์จะหน้าแดงเมื่อเห็นต้นขา」 ก็ถูกเล่าสืบต่อกันมาในหมู่นักเรียน\nฉายา 「อัศวินแห่งความตาย」 ค่อย ๆ ถูกลืมเลือน ถูกแทนที่ด้วยความไว้วางใจและความอบอุ่น เหลือเพียงหนามอันเล็กที่ยังทิ่มอยู่ในใจของหนุ่มน้อย。"
  },
  AwakerStory_11343_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11343_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11344_Content = {
    Text = "เมื่อเช้าของวันหนึ่งเมื่อสิบสองปีก่อน เขตตะวันออกลอนดีเนี่ยน มีทารกหญิงคนหนึ่งถูกห่อด้วยผ้าพันคออย่างมิดชิดที่หน้าประตูบ้านคนจน เรื่องนี้ในเขตตะวันออกที่ทุกคนต่างหวาดกลัวไม่ถือว่าแปลก แต่สิ่งที่ทำให้ซาร่าซึ่งยังเด็กรู้สึกโกรธคือ ในฤดูหนาวที่หนาวเย็นนั้น ผู้ทิ้งเด็กอย่างโหดร้ายได้ห่อปากและจมูกของทารกไว้ใต้ผ้าพันคอ และทารกก็ไม่ร้องไม่ไห้ ถ้าไม่ใช่เพราะดวงตาที่ใสสะอาดของเธอกระพริบไปมา ซาร่าคงคิดว่าเธอตายไปแล้ว\nในขณะที่ซาร่าคิดว่าเธอจะได้เป็น \"พี่สาว\" ของเด็กดีอีกคนหนึ่ง ผู้อำนวยการในขณะนั้นได้นำเด็กคนนี้ไปขายให้ช่างตัดเสื้อในตลาดเขตตะวันออกในราคาเลโอฟัง\n“เราเลี้ยงเด็กคนนั้นไม่ไหว ให้เธอเป็นลูกสาวของช่างตัดเสื้อ แม้ว่าเธอจะต้องเจอความลำบากบ้าง แต่เธออย่างน้อยก็จะได้เรียนรู้ทักษะ”\nเด็กที่เพิ่งเกิดมาแค่สองเดือนจะพูดถึง \"ทักษะ\" ได้อย่างไร?\nซาร่ารู้สึกถึงท้องที่ว่างเปล่า ไม่ได้โต้แย้งการตัดสินใจของผู้อำนวยการ。"
  },
  AwakerStory_11344_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11344_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11345_Content = {
    Text = "A. F. 2@1ปี งานแสดงศิลปะสีไค \n「ฉันจะพาเธอกลับบ้าน!」ผู้โจมตีตะโกนเสียงดัง ขณะที่เขาใช้ค้อนตีผลงานสุดท้ายของประติมากรออกัสต์ที่ชื่อว่า「หญิงปะการังไร้ชื่อ」 เขาถูกฝูงชนที่มุงดูหยุดไว้โดยเร็ว ผู้คนตกใจพบว่า ผู้สูงอายุที่ดูสับสนคนนี้คือออกัสต์ที่หายตัวไปนาน \nทันใดนั้น ความคาดเดาและการพูดคุยเกี่ยวกับ「หญิงปะการังไร้ชื่อ」ก็หลั่งไหลเข้ามา \nผู้คนพูดกันว่า แบบจำลองของมันคือสาวศิษย์ที่ชื่อซาน ซึ่งเป็นศิษย์ที่ดีที่สุดของออกัสต์ ผลงานที่ดีที่สุดของเขาล้วนมาจากมือของซาน เขาคือผู้ขโมยที่น่าละอาย \nผู้คนพูดกันว่า ซานมีภูมิหลังที่ดี พ่อของเธอเป็นนักเขียนชื่อดัง และมีน้องชายเป็นนักการทูต เธอได้ตัดขาดความสัมพันธ์กับครอบครัวเพื่อตั้งใจเรียนรู้การแกะสลัก โดยเดินทางไปปารีสเพียงลำพัง และใช้ชีวิตอย่างยากจนจนกระทั่งตาย \nผู้คนพูดกันว่า ซานป่วยเป็นโรคประหลาด ร่างกายของเธอเต็มไปด้วยของเหลวสีดำ ทุกครั้งที่เธอแกะสลัก ร่างกายของเธอจะกลายเป็นปะการัง 「หญิงปะการังไร้ชื่อ」จริงๆ แล้วคือรูปลักษณ์ของเธอที่กลายเป็นปะการัง ไม่ใช่ผลงานประติมากรรม \nผู้คนยังพูดกันต่อไป... \nอาจารย์และศิษย์ มิตรสหาย และโรคจิต เมื่อผู้คนแยกย้ายกันไป ห้องแสดงงานก็เหลือเพียงหญิงปะการังที่ถูกสร้างขึ้นจากคำพูด เธออาบแสงจันทร์ กระพริบตา รอคอย รอคอย——ช่วงเวลาที่จะกลับบ้าน."
  },
  AwakerStory_11345_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11345_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11346_Content = {
    Text = "ในขณะที่โรคระบาดที่น่ากลัวเข้ามา วานด้าสั่งให้ปิดประตูใหญ่ของปราสาทด้วยการเชื่อมเหล็ก ทำให้ชีวิตของเธอแยกตัวออกจากโลกภายนอกอย่างสิ้นเชิงและใช้ชีวิตอย่างสนุกสนาน \n ที่นี่มีตัวตลกที่พูดจาเล่นตลกและกวีที่ประพันธ์บทกวีในทันที มีนักดนตรีที่แสดงเพลงและมีอาหารอร่อยและเหล้า \n ความสุขและความสงบทั้งหมดอยู่ภายในปราสาท ขณะที่ภายนอกคือโลกแห่งความมืดที่ @2 \n เมื่อกำแพงภายนอกกลายเป็นพื้นที่ตายอย่างสิ้นเชิง วานด้าจัดงานเลี้ยงหน้ากากที่หรูหราอย่างผิดปกติสำหรับผู้ติดตามหลายร้อยคนของเธอ \n นี่คือการเฉลิมฉลองที่ยาวนานสามวันสามคืนที่หรูหราและไร้ระเบียบ เมื่อเสียงระฆังในคืนวันที่สามดังขึ้น แขกบางคนก็กลายเป็นบ้า บางคนกลายเป็นของเหลวสีดำ วานด้ามีใบหน้าที่แตกเหมือนเซรามิก และมี @2 สีดำไหลออกมาจากรอยแตกของหน้ากาก \n ผู้ติดตามที่ตกใจสั่นเทาอยู่ข้างๆ วานด้า แต่เธอกลับสงบ \n เธอฟาดแส้สั่งให้ @2 ที่บ้าจริงๆ ให้คนที่เหลือดื่มเหล้าและเล่นดนตรีต่อไป ไม่ให้หยุด \n งานเลี้ยงที่แปลกประหลาดจบลงในเช้าวันที่สี่ ภายในห้องโถงหรูหรามี @2 สีดำและเลือดสดเต็มไปหมด \n ไม่มีใครรู้ว่าที่นี่เคยเกิดอะไรขึ้น."
  },
  AwakerStory_11346_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11346_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11347_Content = {
    Text = "ตามบันทึกเหตุการณ์ภัยพิบัติหินⅢ ผู้พิทักษ์ได้นำเงินใจอันนี้กลับมาจากบ้านคนจนลอนดีเนี่ยน นอกจากนี้ยังมีตุ๊กตาหมีผ้าขนาดเล็กที่เต็มไปด้วยปะชุนติดมาด้วย \n เงินใจนี้มีน้ำหนักประมาณ 2.1 กรัม รูปร่างเรียวและเงางาม เหมือนหยดน้ำ เมื่อเจ้าหน้าที่ทดลองที่สัมผัสกับเงินใจนี้จะตกอยู่ในสภาวะชะงักงัน รักษาท่าทางสัมผัสเงินใจไว้ จนกว่าจะมีคนปลุกตื่นขึ้นมา เพื่อป้องกันการสัมผัสโดยบังเอิญ นักวิจัยดอลล์จึงเก็บเงินใจนี้ไว้ในลูกแก้วกระจกปิดสนิท และเปลี่ยนตาของตุ๊กตาหมีผ้า \n「มันดูเหมือนกับว่ามันกำลังร้องไห้ทุกวัน.」"
  },
  AwakerStory_11347_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11347_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11347_UnlockDesc_1 = {
    Text = "ผ่านด่านเนื้อเรื่องหลักบทที่ 1 「เรื่องลับของเขตตะวันออก」"
  },
  AwakerStory_11348_Content = {
    Text = "กลิ่นสนิมแพร่กระจายในอากาศ \n นั่นคือ... กลิ่นของ「อาหาร」 \n สาวน้อยค่อยๆ เปิดตา หลังจากถูกฉีดยาสงบประสาทในปริมาณมากเป็นเวลานาน สมองของเธอเต็มไปด้วยความวุ่นวาย ข้างหน้า มีสุนัขบีเกิลที่ถูกกัดขาดลำคอนอนอยู่ ดูเหมือนชื่อว่า... บัมบี้? โบบี้? \n สาวน้อยเพิ่งจะตกอยู่ในความทรงจำ ท้องของเธอก็ส่งสัญญาณเจ็บปวดอย่างรุนแรง—เธอถูก「อาหาร」โจมตี ในขณะนี้ ชายเร่ร่อนที่ถูกมัดอยู่กำลังสั่นมืออย่างควบคุมไม่ได้ เหมือนกับกำลังตะโกนเสียงดัง \n 「แวมไพร์! มอนสเตอร์... มอนสเตอร์!!」\n อย่างไรก็ตาม สาวน้อยกลับไม่สนใจ เพียงแต่ตั้งใจลูบเลือดที่ท้องของเธอ \n เลือดสดอุ่นๆ จำนวนมาก ไหลออกจากบาดแผลอย่างสนุกสนาน เหมือนผ้าไหมลื่นไหล แพร่กระจายไปทั่วพื้น \n ที่แท้ เธอยังรู้สึกเจ็บ ยังมีเลือดไหลออกมา \n สาวน้อยน้ำตาไหลเงียบๆ เธอยื่นมือที่เปื้อนเลือดอ่อนแอไป ลูบไล้ใบหน้าของ「เหยื่อ」 \n 「ต่อไป ขอให้คุณช่วยทำแรงกว่านี้อีกได้ไหม?」"
  },
  AwakerStory_11348_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11348_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11349_Content = {
    Text = "ถูกเลือกจากเด็กนับพันเมื่อถูกผลักขึ้นบนบัลลังก์ ธูลูยังไม่สูงเท่าบัลลังก์หินลาพิสลาซูลี\nแต่ไม่มีใครกล้าตำหนิความไม่ใส่ใจและการหลับใหลที่ยาวนานของเขา——ทุกคนรู้ดีว่านี่คือหลักฐานว่าพระราชากำลังฟังคำสั่งจากเทพเจ้า\nการตัดสินใจของกษัตริย์หนุ่มผู้ชาญฉลาดจะต้องแก้ปัญหาได้; คำทำนายที่กล่าวออกมาจะต้องเป็นจริง\nธูลูก็ยอมรับชีวิตแบบนี้: เข้าสู่นิมิตของ「เทพเจ้า」พบกับการมีอยู่ที่ไม่สามารถเข้าใจได้ ปกครองประเทศด้วยคำทำนาย และกลับไปหลับใหลอีกครั้ง...\nการดำเนินชีวิตของอารยธรรมนี้ถูกกำหนดโดยเจตจำนงของเทพเจ้า ไหลไปตามกระแสและทำตามวิถีที่ถูกกำหนด เพียงแค่ทำหน้าที่เป็น「ผู้สื่อสาร」ที่ไม่เหมือนใครก็เพียงพอ\nอย่างไรก็ตาม ธูลูมีคำทำนายเพียงหนึ่งเดียวที่ไม่สามารถพูดออกไปได้: ประเทศจะถูกทำลายด้วยน้ำท่วม อารยธรรมจะต้องถูกฝังอยู่ใต้ทะเล\nเพราะรู้ทุกอย่างจึงเข้าใจว่าการทำลายล้างไม่สามารถเปลี่ยนแปลงได้——แต่ขออย่างน้อยในช่วงเวลาสุดท้าย อย่าให้พวกเขาใช้ชีวิตอยู่ในความกลัวและความไม่แน่นอน\nนี่คือการตัดสินใจของเขาในฐานะพระราชา ไม่ใช่ในฐานะ「ผู้ดำเนินการของเทพเจ้า」"
  },
  AwakerStory_11349_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11349_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11350_Content = {
    Text = "หลังจากถูกปลุกตื่น เมอร์ฟี่ก็มักจะฝันถึงการหลบหนีอยู่เสมอ และในตอนท้ายของความฝันนั้น เธอถือมีดของ「แม่」แทงทะลุหน้าอกของตัวเองใต้แสงจันทร์อันสดใส จากนั้นความฝันก็สิ้นสุดลงอย่างกะทันหัน และในชั่วขณะที่ลืมตาขึ้น ก็พบกับรูปสลักงาช้างที่ตั้งอยู่ข้างเตียงพอดี\n\nการกระทำของเมอร์ฟี่ในมิซาเกนนั้นเหมือนกับเวอร์ชันที่อายุน้อยกว่าของ「ผู้เลี้ยงดู」เธอ เธอสวมชุดขาวดำตลอดทั้งวัน ไม่ค่อยพูดคุยหัวเราะกับใคร มีเพียงเมื่อบทสนทนาเผลอหันมาที่เรื่องความชอบในขนมหวาน หน้ากากพระมารดาผู้บริสุทธิ์ถึงจะเผยให้เห็นรอยร้าว\n(หมายเหตุของเจ้าหน้าที่: หวังว่าครั้งหน้าเมื่อเธออยากลองชิมเค้กชิ้นเล็กๆ จะสามารถพูดออกมาตรงๆ ได้เลย แทนที่จะรอให้เวลาน้ำชายามบ่ายของทุกคนสิ้นสุดลงแล้วค่อยทิ้งโน้ตสั่งให้ส่งไปที่ห้องของเธอ)\n\nเธอคุ้นชินกับการรักษาระยะห่างจากผู้ตื่นทุกคนที่มาจากดาวสมุทร ต่างจากตัวเองในอีกโลกหนึ่ง เธอไม่ได้หลีกเลี่ยงการสัมผัสกับผู้ที่เกี่ยวข้องโดยตั้งใจ เพียงแต่สีหน้าเย็นชาที่แข็งทื่ออยู่บนใบหน้าและคำเสียดสีที่แฝงความเป็นปฏิปักษ์ ได้ขับไล่พวกที่ไม่อยากชนกำแพงออกไปโดยไม่รู้ตัว"
  },
  AwakerStory_11350_Title = {
    Text = "เรื่องราว·2"
