  AwakerStory_11351_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11352_Content = {
    Text = "ที่นี่คือดินแดนแห่งสัญญา ที่นี่คืออุดมคติของศิลปะ ที่นี่คือสถานที่อันยิ่งใหญ่ที่สุด—การเต้นรำควรเป็นบ้านของนักเต้นรำ ควรรักษาความบริสุทธิ์อันเป็นนิรันดร์ \nตราบใดที่ฉันเผาไหม้ สิ่งที่ไม่อาจทนได้จะไม่สามารถแปดเปื้อนวิหารของเรา... นี่คือพันธกิจของฉัน ความหวังของฉัน... โปรดอนุญาตให้ฉันเผาไหม้อย่างร้อนแรง ฉันจะเผาทุกสิ่งที่แปดเปื้อนเพื่อทุกคน。"
  },
  AwakerStory_11352_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11352_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11353_Content = {
    Text = "ชู่ว... ไม่ต้องตื่นตระหนก นั่นเป็นเพียงเสียงของหนูที่เน่าเปื่อยในห้องใต้ดินที่ชื้น จากก้นบึ้งของความมืดมิดที่สุด ความปรารถนาสีชาดได้เกิดขึ้น วิญญาณที่ถูกจองจำปรารถนาสดเลือด เหมือนกับผู้ตาบอดที่ขอแสงสว่าง และผู้ที่เสพติดในกามารมณ์ วิธีที่จะทำให้เธอพอใจนั้นง่ายมาก: ด่าทอเธออย่างเต็มที่และดูหมิ่นเธอเถอะ。"
  },
  AwakerStory_11353_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11353_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11354_Content = {
    Text = "ก่อนหน้านี้ เราทราบว่ารากฐานของอารยธรรมมนุษย์ที่เก่าแก่ที่สุดเกิดขึ้นที่ดินแดนสองแม่น้ำ ซึ่งมีหลักฐานทางโบราณคดีที่มั่นคงยืนยันเรื่องนี้ \nแต่มนุษย์มักจะไม่เคยพึงพอใจกับสิ่งที่รู้ เมื่อเผชิญหน้ากับมหาสมุทรแห่งความมืดที่กว้างใหญ่ ผู้คนไม่หยุดที่จะแล่นเรือเข้าสู่น่านน้ำที่ไม่รู้จัก \nบางทีนี่อาจไม่ใช่ครั้งแรกที่เราได้รับการเตือนหรือคำใบ้ นักปรัชญาลึกลับเคยเสนอสมมุติฐานไว้ว่า จักรวาลคือวงจรอันน่าพรั่นพรึง และโลกของเราในยุคปัจจุบันรวมถึงมนุษยชาติด้วยนั้น เป็นเพียงห่วงโซ่สั้น ๆ หนึ่งในวงจรนั้น \nมีสิ่งของมากมายที่ถูกทำลายหายสาบสูญในวงจรเหล่านี้ โดยไม่เหลือหลักฐานใด ๆ ให้กล่าวถึง—นั่นนับว่าเป็นโชคดี เพราะบางพลังงานโบราณมีความสุดโต่งและเก่าแก่เพียงพอที่แม้แต่ซากที่หลงเหลืออยู่ก็อาจส่งผลกระทบต่อยุคสมัยของเราอย่างประเมินค่าไม่ได้ \n—เช่นเดียวกับครั้งนี้ที่ลูกเรือของ 「สงบระวังภัย」 ได้ค้นพบโดยไม่ตั้งใจใต้ทะเลลึกในมหาสมุทรแห่งเอเชียตะวันออกเฉียงใต้ ซึ่งได้ขยายขอบเขตความเข้าใจของมนุษย์เกี่ยวกับอารยธรรมยุคก่อนประวัติศาสตร์ไปไกลถึงหมื่นปี \nเราจึงได้ทราบถึงอารยธรรมที่มีประเทศ เจ้าปกครอง และความเชื่อเฉพาะตัว ซึ่งสูญสลายไปในอุทกภัยครั้งใหญ่ระดับโลก และพักผ่อนอยู่ใต้ท้องทะเลมายาวนาน \nหากไม่ได้รับความร่วมมือจากคณะกรรมการตรวจสอบตามสนธิสัญญามิสไตอาในการช่วยงานจำกัดพื้นที่ไว้ ประวัติศาสตร์มนุษยชาติอาจถูกเขียนขึ้นใหม่—ซึ่งโลกในปัจจุบันยังไม่พร้อมที่จะเผชิญกับการเปลี่ยนแปลงครั้งใหญ่เช่นนี้ได้。"
  },
