    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11355_Content = {
    Text = "คาเซียยืดมือเข้าไปในหมวก มันว่างเปล่าไม่มีอะไรเลย。\nคาเซียยืดมือเข้าไปในประตู มันว่างเปล่าไม่มีอะไรเลย。\nคาเซียยืดมือเข้าไปในหน้าอก มันว่างเปล่าไม่มีอะไรเลย。\nความสุข ความโกรธ ความเศร้า ความกลัว ความเกลียดชัง ความอบอุ่นของมนุษย์ เสียงอึกทึกก่อนเริ่ม การเชียร์ในช่วงพลิกผัน เสียงนกหวีดในช่วงที่น่าตื่นเต้น เสียงปรบมือในตอนปิดฉาก และความเหงาในตอนที่แยกย้ายกันไป ทั้งหมดนี้ได้หลุดลอยไปจากหน้าอกที่ว่างเปล่านี้ ไม่มีร่องรอยของการมีอยู่เลยแม้แต่น้อย。\nคาเซียยืนอยู่หน้ากระจกเลียนแบบสีหน้าของผู้ชม ริ้วรอยที่มุมตา แนวกล้ามเนื้อ และรูปโค้งของริมฝีปาก เห็นได้ชัดว่าเหมือนกับคนเหล่านั้น แต่กลับไม่สามารถรู้สึกถึงความหมายที่แท้จริงได้เลย。\nถ้าเพียงแค่รับรู้ได้ก็คงดี ถ้าเพียงแค่หลุดพ้นจากการเลียนแบบได้ก็คงดี ถ้าเพียงแค่เป็นหนึ่งในพวกเขาก็คงดี... หรือ ถ้ามีใครสักคนที่สามารถอยู่ต่อได้ก็คงดี...\nถ้าเป็นเช่นนั้น ก็ต้องสามารถเติมเต็มความ 「ว่าง」 ในช่องอกนี้ได้แน่ๆ。"
  },
  AwakerStory_11355_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11355_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11356_Content = {
    Text = "ข้อมูลการเดินทาง: การล่าประวัติศาสตร์ที่น่าสนใจ——ทัวร์หรู 7 วันที่ปราสาทแคมบริอัน\nวันที่เดินทาง: ปี A.F.3@2 วันที่ 18 มิถุนายน - 25 มิถุนายน\nไกด์: โธมัส·@2@1\nคำอธิบายการเดินทาง:\nมาเถอะ มาร่วมกันเปิดเผยม่านลึกลับของปราสาทที่น่ากลัวที่สุดในสามร้อยปี——ปราสาทแคมบริอัน!\nพวกเราเบื่อหน่ายกับตำนานที่น่าหลงใหลของหญิงผู้นำที่มีเสน่ห์และผู้ติดตามของเธออีกสิบห้าคนที่เห็นในหนังสือเก่าและภาพยนตร์เงียบ พวกมันซ้ำซากและไม่มีนวัตกรรม!\nตามคำกล่าวของผู้เชี่ยวชาญที่ไม่ประสงค์ออกนามจากมิซากะ บริเวณนี้เพิ่งมีการค้นพบใหม่!@2@1เต็มไปด้วยหนาม...\nโทรด่วนที่@2@1@1 การเดินทางครั้งนี้จะทำให้คุณไม่มีวันลืมและเหงื่อเย็นไหล!\n——ที่มา: จาก《เหตุการณ์การหายตัวไปของกลุ่มนักท่องเที่ยววูสเตอร์·บทสรุปคดี: หลักฐาน S-145》"
  },
  AwakerStory_11356_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11356_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11357_Content = {
    Text = "ในฐานะที่เป็นผู้ที่เดินอยู่ในแนวหน้าของการวิจัยการหลอมกร่อน ดอร์รู้ดีว่าก้าวที่ทำลายกำลังตามมาอย่างต่อเนื่อง และยิ่งไปกว่านั้น ในเรื่องการหลอมกร่อนเธอไม่เคยรู้สึกแปลกใหม่เลย \nในการค้นหาความจริงที่ก้าวไปข้างหน้าแล้วล้มเหลวอยู่ตลอดเวลา ดอร์เริ่มตระหนักว่าร่างกายของมนุษย์ในปัจจุบันอาจมีความบอดตามธรรมชาติ ไม่ว่าผู้ที่มีชีวิตจะพยายามอย่างไร ก็ไม่สามารถมองเห็นทิวทัศน์ของโลกฝั่งตรงข้ามได้ \nดังนั้นเมื่อของเหลวสีดำที่เหนียวข้นกำลังทำลายร่างกาย มันจะนำจิตวิญญาณไปสู่ความจริงที่อยู่ฝั่งตรงข้ามด้วยหรือไม่? \nเธอนั่งเงียบๆ กับคำสอนบนกระดานหินโบราณ ปล่อยให้การหลอมกร่อนกัดกร่อนสมองของเธอ ไม่ว่าเส้นทางที่ปลายทางจะเป็นเช่นไร เธอก็ไม่สามารถหันหลังกลับได้แล้ว \nโชคดีและโชคร้าย เธอใช้การมีอยู่ของตนเองเป็นเดิมพัน ในที่สุดก็ได้โอกาสเข้าไปในโลกภายใน และในชั่วพริบตา ความจริง สุญญตา และการทำลายล้างก็กลืนเธอไปพร้อมกัน \nในชั่วพริบตา เธอได้เป็นพยานถึงทุกสิ่งในจักรวาล ธาตุของการหลอมกร่อน ความจริงของโลก เธอปรารถนาสิ่งที่มีค่าในชีวิตอยู่ที่นี่มีครบทุกอย่าง \nความเชื่อทางวิทยาศาสตร์และการยึดมั่นในเหตุผลทั้งหมดกลายเป็นภาพลวงเพียงชั่วขณะ แนวป้องกันจิตวิญญาณที่เคยมั่นคงเหมือนเหล็กกลับพังทลายลงอย่างกะทันหัน \nอัจฉริยะที่ชื่อว่าดอร์ได้หายไปแล้ว ตอนนี้ที่ยืนอยู่ที่นี่เพียงแค่ซากศพที่ถูกสุญญตาเข้าครอบครองเท่านั้น。"
  },
  AwakerStory_11357_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11357_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11358_Content = {
    Text = "「A. F. 3@2ปี กลุ่มนิเวศวิทยาทางทะเลที่มหาวิทยาลัยมิชิแกนได้พบแนวปะการังที่มีรูปร่างแปลกประหลาดในพื้นที่ทะเลทางตอนใต้...」\n「ตัวอย่างนี้มีลักษณะพิเศษ ไม่เหมือนกับองค์ประกอบใดๆ ที่รู้จักบนโลก ในน้ำมีเนื้อสัมผัสที่ค่อนข้างนุ่ม แต่เมื่อขึ้นบกจะแห้งและแข็งตัวอย่างรวดเร็ว จากการศึกษาร่วมกันของภาควิชาชีววิทยาและภาควิชาดาราศาสตร์ คาดว่าอาจเป็นสารต่างดาวที่ไม่รู้จัก...」\n\n「A. F. 3@1ปี รหัสปลุกตื่นซังก้า.\nผู้ปลุกตื่นนี้ตั้งแต่ตื่นขึ้นมาก็ยังคงมีพฤติกรรมการแกะสลัก สไตล์ศิลปะที่มีชื่อเสียงจากเส้นโค้งและเส้นสายที่แปลกประหลาดนั้นยากที่จะจัดอยู่ในประเภทใดๆ นอกจากจะสร้างผลกระทบทางจิตใจต่อผู้ชมแล้ว ยังแทบไม่มีประโยชน์ต่อการศึกษาการหลอมกร่อนเลย」"
  },
  AwakerStory_11358_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11358_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11359_Content = {
    Text = "เขารอดชีวิตจากความตายเพียงลำพัง การเปลี่ยนแปลง; เขาได้เก็บซ่อนคมมีดยักษ์และสวมหน้ากากของอัครทูตไว้\nเมื่อปาฏิหาริย์มาถึง เขาก็เกิดความเคารพอย่างสัญชาตญาณ แต่เขาไม่เคยหวาดกลัวต่อเทพเจ้าใด ๆ และไม่เคยเข้าใจความเชื่อที่แท้จริง\nยักษ์ไม่ควรอยู่ต่ำกว่ามนุษย์ นักรบจะไม่ก้มหัวให้ใคร\nนับตั้งแต่โบราณกาลสงครามของเขายังไม่สิ้นสุด ความปรารถนาในการพิชิตและพละกำลังแห่งการมอบให้ได้ถูกฝังลึกในสายเลือดของเขา อาจมีวันหนึ่งเขาจะตาย หรืออาจมีวันหนึ่งเขาจะปกครองทุกหนแห่ง。"
  },
  AwakerStory_11359_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11359_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11360_Content = {
    Text = "คุณเองก็ต้องเคยฝันแบบนี้ใช่ไหม? อยู่ๆ ก็ได้รับมรดกมหาศาล อยู่ๆ ก็ได้รับพลังอันยิ่งใหญ่...มากพอที่จะเหยียบย่ำผู้ที่เคยดูถูกและทำร้ายเราไว้ทั้งหมด\nแล้วเมื่อฝันสิ้นสุดลง ในช่วงเวลาที่ต้องเผชิญความจริงที่ไม่มีวันสิ้นสุด ก็ยิ่งดำดิ่งสู่ความสิ้นหวัง\nแต่ว่านะ...ความฝันของฉันมันเป็นเรื่องจริง และโชคชะตาของฉันนั้นมาถึงแล้ว\n\nรู้หรือเปล่า พวกคุณน่ะคือผู้อ่อนแอจริงๆ\n\nทั้งความเปราะบางของร่างกายและจิตวิญญาณที่เฉื่อยชานั้นไม่สามารถรองรับสายเลือดอันสูงศักดิ์ได้หรือ? ไม่ ไม่มีทางที่เรื่องแบบนั้นจะเกิดขึ้น เพราะนามสกุลออนนี่แหละ คือเกียรติยศและสัญลักษณ์ของพวกเรา@2 ได้รับสายเลือดและนามสกุลมาแล้ว ฉันจึงไม่เป็นตัวประหลาดที่ฉันให้คนดูหมิ่นอีกต่อไป แต่กลายเป็น@1ผู้ที่มีสายเลือดสูงส่ง\n\nดังนั้น...โปรดเถอะ...อย่ามองฉันด้วยสายตาที่ทำให้หายใจไม่ออกแบบนั้นอีกเลย..."
  },
  AwakerStory_11360_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11360_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11361_Content = {
    Text = "ฮันนา: คุณแอลวา คุณเข้าร่วมมหาวิทยาลัยมิสซากมาสักพักแล้ว คุณเป็นที่นิยมมากในหมู่นักศึกษา มีสาว ๆ หลายคนส่งจดหมายรักมาให้ฉันส่งให้คุณ สนใจให้ฉันอ่านให้ฟังไหมคะ?\nแอลวา: นี่มัน...เอิ่ม ฉันหมายถึง ขอบคุณทุกคนมากค่ะ? แต่ฉันไม่ได้มานี่เพื่อ เอ่อ...เล่าวันของฉันเหรอ?\nฮันนา: ไม่คิดเลยว่าครูฝึกจะมีมุมน่ารักแบบนี้ ดูท่าว่าหลังบทสัมภาษณ์นี้ตีพิมพ์ ฉันคงต้องไปหลบข้างนอกไม่งั้นคงถูกสาว ๆ อิจฉาล้อมแน่เลย! เอาล่ะ กลับมาเข้าเรื่อง คุณช่วยแบ่งปันหนึ่งวันของครูฝึกผู้มีเสน่ห์น่าหลงใหลให้ผู้อ่านของเราฟังหน่อยได้ไหมคะ?\nแอลวา: เกรงว่าฉันจะทำให้ทุกคนผิดหวัง เพราะวันของฉันธรรมดามากเลยค่ะ ฉันตื่นประมาณตี 4 ทุกเช้าเพื่อออกกำลังกาย ให้ขานี้ชินกับการเคลื่อนไหว\nตอน 6 โมง ฉันไปที่โรงอาหาร ถึงแม้ร่างกายของผู้ปลุกตื่นจะไม่จำเป็นต้องกินอาหาร แต่ฉัน...ถือว่านี่เป็นนิสัยอย่างหนึ่งค่ะ\n8 โมงถึงเที่ยง ฉันจะมีหน้าที่ฝึกสอนเทคนิคต่อสู้ให้กับนักสืบ บางครั้งจะมีการฝึกพิเศษสำหรับผู้พิทักษ์ด้วย ส่วนเวลาอบรมในตอนบ่ายจะปรับเปลี่ยนตามแผนการเรียน บางครั้งก็เริ่มตอนบ่ายโมง หรือบางครั้งตอนบ่ายสาม\nทุกสัปดาห์ ฉันจะหาเวลาไปหาโนดิลา เพื่อให้เธอช่วยปรับแต่งขาเทียมของฉัน แม้ว่าเธอจะขี้ลืมเป็นบางที แต่ฝีมือเธอยอดเยี่ยมมาก หลังจากที่เธอตรวจสอบ ฉันจะรู้สึกเจ็บปวดลดลงอย่างมาก\nฮันนา: แล้วคุณทำอะไรเพื่อความบันเทิงบ้างล่ะคะ?\nแอลวา: ความบันเทิง...คำนี้ยังถือเป็นสิ่งใหม่สำหรับฉันค่ะ แต่เมื่อเร็ว ๆ นี้ ฉันได้ไปเล่นน้ำทะเลกับโอเรตตากับคนอื่น ๆ การได้อยู่กับเด็ก ๆ ที่มีจิตใจใสซื่อเหล่านี้ ทำให้ฉันรู้สึกผ่อนคลายมาก นอกจากนี้ การว่ายน้ำยังช่วยเสริมความแข็งแรงให้ร่างกายอีกด้วย เมื่อก่อนตอนที่ฉันยังเป็นทหารใหม่ ครูฝึกของฉัน——\nฮันนา: โอเค วันนี้เรามาจบคอลัมน์กันก่อนนะคะ! ถ้าอยากทราบเกี่ยวกับเรื่องราวในอดีตของคุณแอลวา อย่าลืมติดตามตอนต่อไปใน «ชีวิตประจำวันของมิสซาก»! \n——คัดลอกจากคอลัมน์บทสัมภาษณ์พิเศษใน «หนังสือพิมพ์มิสซาก» เรื่อง «ชีวิตประจำวันของมิสซาก»"
  },
  AwakerStory_11361_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11361_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11362_Content = {
    Text = "ก่อนที่ความจริงทั้งหมดจะปรากฏ ไม่มีใครเคยสงสัยเลยว่าโดรจะเป็นตัวการหลักเบื้องหลังเหตุการณ์อันน่าสะพรึงกลัวเหล่านั้น\nท้ายที่สุด เธอคือเสาหลักเเห่งความหวังในยุคสงครามมิซากะและแนวหน้าผู้หลอมรวม เป็นที่พึ่งพิงแข็งแกร่งดั่งหินผาในใจของทุกคน\nเมื่อดวงดาวนับไม่ถ้วนของมนุษยชาติบนฟากฟ้าถูกหลอมละลายจนสลายไป หลอดไฟแห่งมนุษย์อันมั่นคงนี้ก็ในที่สุดมอดดับภายใต้ความเถื่อนโหดร้าย กลายเป็นแรงขับดันในเงามืดที่มาจากรากฐานเดียวกันกับความมืด\nพายุทอร์นาโด น้ำท่วม ดินไหว... การฆาตกรรมที่ไม่ได้มีประสิทธิภาพชัดเจนไม่สมกับแผนการของอัจฉริยะ เธอใช้ปัญญาอันยอดเยี่ยมที่ยังคงไม่มีลดลงในการปรับเปลี่ยนเทคโนโลยีซิลเวอร์ชิปที่เธอเคยภาคภูมิใจให้กลายเป็นอาวุธทำลายล้างและมอบของขวัญแห่งการทำลายล้างสู่อันตรายที่มองไม่เห็นในแถบมิซากะทีละชิ้น\nท้ายที่สุดเมื่อเธอถูกจับกุม ร่างกายของหุ่นยนต์ก็ไม่สามารถถูกควบคุมอย่างแม่นยำโดยสมองที่ถูกกัดกร่อน ใบหน้าที่เคยสงบนิ่งเหมือนกระจกกลับเต็มไปด้วยความบิดเบี้ยวแปลกประหลาด ราวกับเพียงมองสบตามันจะทำให้ตกลงสู่ห้วงเหวแห่งความบ้าคลั่ง\nทุกคนต่างพร้อมใจกันละเลยคำพูดรำพึงคลุมเครือของเธอ แม้ว่าอาจเปิดเผยความจริงของโลกก็ตาม\nเพราะประสบการณ์ของเธอนั้นได้ยืนยันอีกครั้งว่ามนุษย์ยังคงเป็นสิ่งมีชีวิตที่ต้องการความหมายในการดำรงอยู่ต่อไป."
  },
  AwakerStory_11362_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11362_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11363_Content = {
    Text = "ดาฟโฟดิลได้ขายตัวเองให้กับห้องทดลองเงินใจของมหาวิทยาลัยมิซากะในราคาที่สูงลิ่ว。\nก่อนหน้านั้น หัวหน้าห้องทดลองดอลล์ได้แสดงความไม่พอใจอย่างมากต่อการสื่อสารในทิศทางเดียวที่สามารถเริ่มต้นได้เฉพาะโดยดาฟโฟดิล。\nแต่มีเพียงดาฟโฟดิลและผู้บริหารระดับสูงของมหาวิทยาลัยมิซากะที่ล่วงลับไปแล้วเท่านั้นที่รู้ว่าการสื่อสารในทิศทางเดียวเช่นนี้เกิดขึ้นจากการทำธุรกรรมที่อันตรายเพียงใด。"
  },
  AwakerStory_11363_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11363_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11364_Content = {
    Text = "หยิ่งยะโส เอาแต่ใจตัวเอง และเห็นแก่ตัว... หลายคนที่เคยติดต่อกับเธอ มักจะให้ความคิดเห็นเกี่ยวกับบุคลิกภาพของเธอแบบนี้ เธอเหมือนถูกดูแลอย่างดีในสภาพแวดล้อมชีวิตที่ผ่านมา อาจจะเป็นเพราะการดูแลอย่างใกล้ชิดเหล่านี้ที่ทำให้เธอมีนิสัยเอาแต่ใจตัวเอง \n 「เฮ้! คุณกำลังมองอะไรอยู่? ไม่ได้บอกไปแล้วหรือไง ว่าถ้าเรียกคุณสามครั้งต้องตอบคุณผู้หญิง!」 \n —— แม้แต่ตอนอ่านเอกสารก็ต้องระมัดระวังอย่างมาก。"
  },
  AwakerStory_11364_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11364_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11365_Content = {
    Text = "ที่มุมถนนในเมืองท่าเรือมีร้านแลกเปลี่ยนเล็กๆ แห่งหนึ่ง เจ้าของร้านเป็น 「คนมีความสามารถ」 ที่เชี่ยวชาญในการจัดการกับเหตุการณ์ลึกลับ \nไม่นานหลังจากน้ำท่วม ดาฟเดลที่ยังไม่เรียกว่าดาฟเดลได้มาถึงบริเวณเซนต์เปโดร และที่เมืองท่าเรือนี้เริ่มมีผู้เคราะห์ร้ายที่ 「หัวหายไปอย่างลึกลับ」 \nเจ้าของร้านได้ทำการสืบสวนและพบกับมันในตอนนั้น และหลังจากพยายามอย่างเต็มที่ในการควบคุมมัน เจ้าของร้านได้ทำการแลกเปลี่ยนกับมัน เจ้าของร้านสัญญาว่าจะสามารถนำหัวของตนกลับไปได้เมื่อชีวิตสิ้นสุด แต่ก่อนหน้านั้น ต้องทำหน้าที่เป็นผู้ช่วยของเจ้าของร้าน ไม่สามารถล่าหัวได้ตามอำเภอใจ \nดังนั้นมันจึงเริ่มต้นการเดินทางร่วมกับเจ้าของร้านและใช้ชีวิตร่วมกัน \nมันเคยสัมผัสความทรงจำในชีวิตของเจ้าของจากหัวมากมาย และได้อ่านความสุขและความโกรธแค้น แต่ความสุขที่ไร้สาระนี้เป็นเพียงการใช้เวลายาวนานเกินไปในการปกปิดความเหงาที่ล่องลอย \nในระหว่างการอยู่ร่วมกับเจ้าของร้าน มันได้สร้างมิตรภาพที่แท้จริงกับคนเป็นครั้งแรก: มันค้นพบว่าตนเองไม่ต้องการการปลอบใจที่ผิดเพี้ยนจากหัวที่ไม่มีที่สิ้นสุด แต่การมีปฏิสัมพันธ์ที่แท้จริงกับผู้คนเท่านั้นที่จะช่วยแก้ไขความเหงาและความว่างเปล่าที่ยาวนาน \nอย่างไรก็ตาม ความสุขช่วงสั้นนี้มีอายุไม่ถึงสิบปี เจ้าของร้านที่ไม่เคยหยุดการสืบสวนได้เสียชีวิตอย่างไม่คาดคิด \nดังนั้นมันจึงตัดหัวของเธอ สืบทอดรูปลักษณ์และร้านค้า รวมถึงชื่อของเธอ และกลายเป็น 「ดาฟเดล」 \nตั้งแต่นั้นมา ดาฟเดลได้เริ่มต้นการเดินทางพร้อมกับร้านแลกเปลี่ยนเล็กๆ เธอยังคงเรียกเก็บหัวเป็นการแลกเปลี่ยนจากผู้ที่ต้องการความช่วยเหลือ และสะสมหัวเป็นของสะสม \nแต่เธอไม่เคยล่าหัวอย่างไม่ระมัดระวังอีกต่อไป \nไม่เคยอีกเลย。"
  },
  AwakerStory_11365_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11365_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11366_Content = {
    Text = "กลับรัง กลับบ้าน กลับสู่อ้อมกอดของครอบครัว ไม่สำคัญว่าใช้คำไหนในการอธิบายความปรารถนาของเธอ แม้ว่าในรูปแบบของผู้ปลุกตื่นเธอก็ยังไม่สามารถลืมประเทศที่เธอฝันถึงได้ \n การหายใจของภูเขาไฟใต้ทะเลไม่ได้ดังก้องข้างหูอีกต่อไป ภาพลวงในทะเลลึกก็กลายเป็นภาพที่เลือนลาง แต่ความหลงใหลในการกลับสู่ประเทศนิรันดร์กลับกลายเป็นความร้อนแรงมากขึ้นเรื่อยๆ \n ระวังความอ่อนโยนของเธอในขณะนี้ เพื่อกลับไปยังบัลลังก์ของพระราชา เธอพร้อมที่จะเสียสละทุกอย่าง。"
  },
  AwakerStory_11366_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11366_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11367_Content = {
    Text = "ดอลล์เป็นบุคคลที่ขาดไม่ได้ในมหาวิทยาลัยมิซากะและในวงการวิชาการทั้งหมด\nในหมู่ผู้ปลุกตื่นที่ถูกจัดการโดยโรงเรียน ดอลล์ไม่ใช่ผู้ที่มีดัชนีนอร์สที่เสถียรที่สุด หรือไม่ใช่ผู้ที่มีความสามารถในการต่อสู้ที่แข็งแกร่งที่สุด แต่เธอเป็นผู้ที่มีความสงบและมีเหตุผลที่สุด\nสำหรับผู้ปลุกตื่นบางคนที่เคยเป็นมนุษย์ ช่วงเริ่มต้นของการ「กลับมามีชีวิต」มักจะมาพร้อมกับความสับสน ความตื่นตระหนก และอารมณ์ร้อนแรง อย่างไรก็ตาม ดอลล์ดูเหมือนจะไม่ได้รับผลกระทบจาก「ช่วงเจ็บปวด」ดังกล่าว\nในวันที่สองหลังถูกปลุกตื่น เธอก็กลับไปที่ห้องปฏิบัติการอีกครั้ง และภายในหนึ่งปีได้รวบรวมคู่มือเทคโนโลยีที่รวมความรู้จากต่างมิติและภูมิปัญญาของมนุษย์\nในปัจจุบัน ดอลล์ใช้เวลาครึ่งหนึ่งในการปฏิรูป「เทคโนโลยีเงินใจ」และอีกครึ่งหนึ่งในการ「จัดการกับความยุ่งเหยิงของนักเรียนที่โง่เขลา」\n——โดยบังเอิญ เนื่องจากอิทธิพลของการมีอยู่ในมิติสูง ดอลล์ได้ใช้ภาษาที่ไม่รู้จักบางอย่างในการเขียน「คู่มือเทคโนโลยี」นั้น การแปลกำลังดำเนินการอย่างเป็นระเบียบในเวลาว่างของดอลล์."
  },
  AwakerStory_11367_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11367_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11368_Content = {
    Text = "「ธิดาของเทพเจ้า และในขณะเดียวกันก็เป็นผู้ให้กำเนิดเทพเจ้า」\nนี่คือวิธีที่เธอยืนยันอำนาจของตน มีเพียงการรักษาเกียรติยศที่เป็นที่จับตามองของทุกคนเท่านั้น เธอจึงจะสามารถรักษาสมดุลที่สั่นคลอนนี้ไว้ได้ จะเป็นความหน้าซื่อใจคดก็ตามเถิด จะเป็นความลวงโลกก็ช่างเถิด ใครเล่าที่ไม่ได้ใช้ชีวิตอยู่ใน「ปัจจุบัน」?\nเมอร์ฟี่อุ้มผ้าอ้อมที่ห่อหุ้มทารกศักดิ์สิทธิ์อันน่าเกลียด ทำหน้าที่แทนพระประสงค์ของเทพเจ้า เปล่งคำโกหกออกมาทีละคำ\n「พระองค์ได้เสด็จมาแล้ว」\n「อาณาจักรแห่งเทพเจ้าจะต้องลอยขึ้นสู่ผิวน้ำ」\n「โปรดรอคอยอย่างสงบในชั่วขณะที่ดาวดวงต่อไปโคจรมาสู่ตำแหน่ง」\nแทนที่จะปล่อยให้คนหน้าซื่อใจคดสร้างภาพลวงตาขึ้นมา ไม่ดีกว่าหรือที่จะตกแต่งกรงขังนี้ด้วยมือของตัวเองให้เป็นแบบที่พอใจ ตราบใดที่「แม่」「เพื่อน」「คนรับใช้」ที่เธอปรารถนายังคงอยู่เคียงข้าง ไม่ว่าจะเป็นการก้มหัวที่แตกต่างกันระหว่างคำพูดและใจ หรือการแสร้งทำเป็นลึกลับทั้งที่คิดต่างออกไป เธอก็ยินดีรับและพอใจกับมัน\n「ฉันชื่อเมอร์ฟี่ เป็นเจ้าหญิงผู้ให้กำเนิดเทพเจ้า เรื่องของลีมูเรีย เรื่องความปรารถนาของดาวสมุทร... เธอไม่จำเป็นต้องสืบเสาะ ฉันมีแผนของตัวเองอยู่แล้ว」"
  },
  AwakerStory_11368_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11368_UnlockDesc = {
