  AwakerStory_11368_UnlockDesc_1 = {
    Text = "ปลดล็อกผ่านด่านบทที่ 4 ของดวงดาว「สวรรค์」"
  },
  AwakerStory_11369_Content = {
    Text = "A.F.3@2 วันที่ 2 เมษายน ปีนี้ โบราณสถานในเขตอัชเคลอนถูกทำลายลง \n ในฐานะที่เป็นคนเดียวที่เคยเรียนมหาวิทยาลัย ผู้มาเยือนอย่างฉันได้รับเชิญจากผู้ว่าการเขตให้เข้าร่วมในการประเมินทางสถาปัตยกรรมของโบราณสถาน ฮ่าฮ่า อย่าให้พวกเขารู้ว่ามหาวิทยาลัยของฉันจริงๆ แล้วไม่ใช่แบบนั้น \n ในวันที่ 3 บ่ายวันนั้น ฉันได้เข้าไปในศูนย์กลางของวัด ชนเผ่าโบราณฟลาชีได้ใช้วัดนี้เป็นสถานที่บูชา ที่นี่เคยมีความเชื่อทางศาสนาที่สูญหายไปบางอย่าง \n แต่สิ่งที่ปรากฏต่อหน้าฉันคือรูปปั้นที่ทุกคนไม่สามารถจำผิดได้ ฉันรู้ดีว่ารอยยับบนรูปปั้นนั้นควรจะเป็นลวดลายของผ้าลินินทแยง \n รูปปั้นมีมือหัก ศีรษะแยกจากลำตัว ขาทั้งสองข้างถูกทำลายอยู่บนธรณีประตู ร่างกายเต็มไปด้วยเมือกเหมือนถูกทากไต่ผ่านมา ฉันสังเกตเห็นรอยขีดที่แปลกประหลาด และรอยเท้าขนาดใหญ่ที่มีนิ้วเท้าติดกัน \n ความเชื่อทางศาสนาอาจยังคงแพร่หลายในพื้นที่นี้ แต่ยังไม่มีความจำเป็นต้องทำการสอบสวนอย่างเป็นทางการ ฉันจะขยายเวลาการพักอยู่ในเขตอัชเคลอน \n ——ฟิน@1·@2เซน《การท่องเที่ยวในซากเมืองฟิลิสตินห้าแห่ง》"
  },
  AwakerStory_11369_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11369_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11370_Content = {
    Text = "การอยู่ห่างจากห้องสมุดใต้ดิน สุสาน และลีห์ เป็นความเห็นร่วมกันของนักเรียน \n สาวที่ซีดเซียวและอ่อนแอชอบทำให้คนอื่นโกรธ แล้วค่อยๆเพลิดเพลินไปกับความโกรธของพวกเขา ราวกับนางงูในสวนอีเดน เธอมักจะโยนเหยื่อลับออกมาในเวลาที่เหมาะสม: มาทำร้ายฉันสิ... มาสิ... \n ส่วนใหญ่แล้ว เธอมักจะได้รับสายตาเหยียดหยัน ความสงสัย และคำด่า แต่มีครั้งหนึ่ง เธอในที่สุดก็ได้สิ่งที่ต้องการ——อูฟฮาชไม่ลังเลที่จะจัดการเธอ แม้กระทั่งเอาฟันของเธอไปหนึ่งซี่ เขาเป็นคนที่ไม่มีความอยากรู้อยากเห็นเกี่ยวกับคนอื่น ทุกอย่างในสายตาของเขาดูเหมือนจะเป็นเรื่องธรรมดา \n มองดูเงาของนักรบที่เดินจากไปอย่างสง่างาม ลีห์ยิ้มอย่างพอใจ แสงเช้าที่นุ่มนวลสาดส่องลงมาที่เธอ อีกหนึ่งวันที่สดใส \n เธอยังมีฟันอีกมากมาย เอาไปให้หมดเลย... ใครก็ได้ เอาไปให้หมดเลย..."
  },
  AwakerStory_11370_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11370_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11371_Content = {
    Text = "「...ในอดีตทางตอนใต้ของสหพันธรัฐคอนสแตน บริเวณเบนโดส เคยมีตำนานเกี่ยวกับ 'บิชอปผู้ประทานพร' กล่าวไว้ว่า ก่อนยุคมหาอุทกภัย 'บิชอปผู้ประทานพร' ผู้ที่มีความศรัทธาแรงกล้าและใจดีมาจากโบสถ์กลาง ได้ก่อตั้งสถานเลี้ยงเด็กกำพร้าแห่งเดียวในท้องถิ่นขึ้น และในช่วงที่โรคระบาดร้ายแรงได้เข้ามาแพร่กระจาย เขายังเปิดรับผู้ป่วยและผู้ลี้ภัยจำนวนมากที่ไม่มีที่ไป\nโรคระบาดรุนแรง คนทุกข์ทรมานไปทั่ว ผู้แทนได้อธิษฐานทูลขอพรจากพระบิดาอยู่ทุกวันทุกคืน ในที่สุดเขาได้รับพระพรเป็นแผ่นหินแห่งชีวิต และใช้เลือดและเนื้อของตัวเองเป็นบูชา เพื่อสร้างปาฏิหาริย์ในโลกมนุษย์ เขาช่วยฟื้นคืนชีพคนตายและรักษาผู้ป่วยหนัก แต่ผู้แทนผู้เมตตาคนนี้โดนปีศาจใส่ร้ายและถูกพิพากษาตายด้วยการเผา\nบังเอิญ ในช่วงเวลาเดียวกันกับที่ตำนาน 'บิชอปผู้ประทานพร' ปรากฏอยู่ ในบริเวณตอนกลางของ@2เดิม คือ@1 (ซึ่งปัจจุบันเป็นพื้นที่ตอนใต้ใกล้กับเบนโดสของสหพันธรัฐคอนสแตน) เคยมี 'พวกนอกรีตเลือด' รายพิเศษหนึ่ง จากบันทึกใน 'บันทึกการพิพากษาพวกนอกรีตจากศาลพิพากษาทวีป' ระบุว่าผู้เป็นนอกรีตคนนี้ถือแผ่นหินที่สลักเครื่องหมายปีศาจ และใช้เลือดและเนื้อเป็นบูชาในการประกอบพิธีกรรมชั่วร้ายในคืนที่พระจันทร์ถูกบดบังเพื่อหล่อเลี้ยงตนเอง คนนี้ถูกศาลพิพากษาจับตัวได้ในปี 107 ก่อนยุคมหาอุทกภัย นอกรีตสำนึกผิด สารภาพบาปต่อพระบิดาพระองค์เดียวอย่างศรัทธา และจบชีวิตด้วยการเผา\nในยุคเดียวกัน พื้นที่เดียวกัน และการใช้แผ่นหินกับพิธีกรรมแบบเดียวกัน——สิ่งที่ปฏิเสธไม่ได้คือ 'บิชอปผู้ประทานพร' และ 'พวกนอกรีตเลือด' มีหลายสิ่งที่คล้ายคลึงกันมาก และเมื่อพิจารณาถึงความโน้มน้าวเพียงฝ่ายเดียวของศาลพิพากษา มีความเป็นไปได้สูงที่บุคคลซึ่งถูกมองว่าเป็นพวกนอกรีตอาจถูกกลบเกลื่อนด้วยการใส่ร้าย โดยเหตุนี้ผู้เขียนจึงอดสงสัยไม่ได้ว่า ตำนานที่เล่าถึง 'บิชอปผู้ประทานพร' อาจจะมีอยู่จริง หรืออาจเป็นตัวตนเดียวกันกับ 'พวกนอกรีตเลือด' ที่ถูกบันทึกไว้ในศาลพิพากษานั่นเอง...」\n——คัดลอกจาก 'พระเจ้าของเรา: ศาสนาและความเชื่อในท้องถิ่นทางตอนใต้ของสหพันธรัฐคอนสแตน'\n"
  },
  AwakerStory_11371_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11371_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11372_Content = {
    Text = "สาวน้อยที่เฝ้ารอสิ่งที่เรียกว่า 「แม่」 และเชื่อฟังคำสั่งของ 「เจ้านาย」 \n โลกลืมชื่อของเธอไปแล้ว ดังนั้นเงาขาวอ่อนที่บานสะพรั่งเหมือนดอกลิลลี่ในลูกตาสีน้ำมันดำขนาดใหญ่ จึงถูกผู้ที่มาหลังตั้งชื่ออย่างรีบเร่งว่า 「Lily」"
  },
  AwakerStory_11372_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_11372_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_11373_Content = {
    Text = "ลิซเป็นผู้ปลุกตื่นที่น่าไว้วางใจ แม้ท่าทางของเธอจะไม่สามารถเรียกได้ว่า 「กระตือรือร้น」 แต่เธอก็แสดงความร่วมมืออย่างมากต่อกิจการทุกอย่างของโรงเรียน。\nสิ่งที่น่าจับตามองเพียงอย่างเดียวคือ แม้ลิซจะใช้เวลาอยู่ในห้องเต้นรำตลอดทั้งวันทั้งคืน แต่ไม่มีใครเคยเห็นท่าเต้นที่แท้จริงของเธอ。\nในฐานะนักเต้นบัลเล่ต์ที่ยอดเยี่ยม ชื่อของลิซเคยปรากฏในหนังสือพิมพ์บางฉบับที่เกี่ยวข้อง น่าเสียดายที่เนื่องจากผลกระทบของปรากฏการณ์หลอมละลาย แผนกข่าวสารของระบบปลุกตื่นจึงสามารถยืนยันได้เพียงว่าลิซเคยขึ้นเวทีที่โรงละครที่สองในปี A.F.29@1。\nนักข่าวประจำโรงเรียน ฮันนา พีสลี เคยเสนอให้จัดการประชุมผู้ที่ชื่นชอบการเต้นรำภายในโรงเรียน เพื่อใช้ความรักในเต้นรำ 「เคาะหัวใจของผู้ปลุกตื่นลิซ」。\nขณะนี้ ข้อเสนอนี้ยังไม่ได้รับการอนุมัติจากสำนักงานผู้ปลุกตื่น。"
  },
  AwakerStory_11373_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11373_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11374_Content = {
    Text = "โซเรลรู้ว่าเธอสวย ในใจของเธอ เธอเรียกความสวยนี้ว่าเป็นการโปรดปรานจากสวรรค์ \n เพียงแค่ขอพรด้วยน้ำตาที่เต็มตา ผู้คนก็จะเมตตาเธอ; เพียงแค่แสร้งทำเป็นน่าสงสาร เพื่อนเล่นที่มีความรู้สึกจะเข้าข้างเธอโดยไม่มีเงื่อนไข \n แต่ความสวยกลับไม่มีค่าอะไรต่อหน้าพลังที่แท้จริง \n เมื่อต้องเผชิญหน้ากับพ่อแม่ที่ต้องการมอบเธอให้กับชนชั้นสูงเพื่อแลกกับอนาคต โซเรลรู้สึกถึงรสชาติของความล้มเหล zumครั้งแรก \n มีใครช่วยเธอได้บ้าง? มีใครพาเธอหนีจากชะตากรรมที่โง่เขลาและล้าหลังนี้ได้ไหม? \n มีสิ่งใด มีสถานที่ใด... ที่สามารถทำให้ความสวยนี้กลายเป็นอาวุธที่แท้จริงได้ไหม? \n ขณะที่โซเรลปิดหน้าร้องไห้อยู่ ผู้ส่งสารที่ทำให้เกิดการเปลี่ยนแปลงในชะตากรรมได้ปรากฏตัวต่อหน้าเธอ。"
  },
  AwakerStory_11374_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_11374_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_11375_Content = {
    Text = "——นี่จะไม่ใช่ความผิดของเขาได้อย่างไร? สิ่งที่เขาทำนั้นยังห่างไกลจากคำว่าพอเพียง \nด้วยความรู้สึกผิดอย่างรุนแรงเช่นนี้ โอกีลจึงทำภารกิจบ่อยกว่าผู้ปลุกตื่นคนอื่นถึงสองเท่า โดยใช้ 「คุณธรรม」 ที่ทุกคนชื่นชมฝังกลบ 「ความตาย」 \nการทำงานที่มากเกินไปและคำขอบคุณจากนักสืบหนุ่มดูเหมือนจะสามารถล้างบาปที่ฝังอยู่ในจิตวิญญาณได้จริงๆ \nโรคเรื้อรังถูกผลักดันเข้าสู่เงามืดในใจ พวกเขามีกลิ่นเน่าที่น่าสะอิดสะเอียน และค่อยๆ ดึงอัศวินเข้าสู่บึงมืดดำ \n「ขอโทษครับ? สวัสดีครับ?」 \nมีคนหนึ่งที่นำแสงแดดหรือสายลมอ่อนๆ มาหาโอกีล \n「อาจารย์บอกว่า โอกีลจะเข้าร่วมกับฉันและราโมน่า ในการทำภารกิจการสืบสวนครั้งแรกของฉันใช่ไหมครับ?」 \nเขาไม่สามารถปกป้องเจ้าหญิงเป็นครั้งที่สองได้ แต่สวรรค์ให้โอกาสเขาในการปกป้อง 「ผู้พิทักษ์」 อีกครั้ง \n「ชื่อของฉันคือ โอกีล ยินดีที่ได้ทำสัญญากับคุณ ฉันจะใช้จิตวิญญาณปกป้องชีวิตของคุณ วันนี้ขอปฏิญาณ จะไม่มีวันลืม」"
  },
  AwakerStory_11375_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11375_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_11376_Content = {
    Text = "「เบื่อกับสวนสาธารณะธรรมดาแล้วหรือ? เบื่อกับการแสดงสัตว์ที่น่าเบื่อแล้วหรือ? งั้นมาที่งานคาร์นิวัลเวทมนตร์ของคาเซียเถอะ! เด็ก ๆ ที่ชอบสัตว์ ที่นี่มีสิงโตที่ร้องเพลงเสียงสูง นกฟลามิงโกที่เต้นบัลเล่ต์ ช้างที่แสดงกล และผู้ฝึกสอนล่อม้าผู้เดียวในโลก! คู่รักที่หวังจะเสริมสร้างความสัมพันธ์ สามารถลองม้าหมุนที่ไม่เหมือนใครของเรา เพื่อรับประสบการณ์โรแมนติกที่หาได้ยาก! นักรบที่รู้สึกว่าชีวิตขาดความตื่นเต้น สามารถท้าทายเขาวงกตกระจกที่ออกแบบโดยเจ้าของงานคาร์นิวัล ถ้าสามารถพาคนที่เข้าไป 41 คนแล้วไม่ออกมาออกมาได้ ยังจะได้รับรางวัลมากมายอีกด้วย!\nนอกจากเครื่องเล่นที่มีอยู่ในโลกนี้แล้ว มหาวิทยาลัยมิซากะยังจะได้เห็นโลกแห่งความน่ามหัศจรรย์จากมาสเตอร์เวทมนตร์คาเซีย ที่จะนำเสนอการตัดร่างกาย การแสดงกลผาดโผน การหลบหนีสุดขีด และมายากลอีกมากมาย! ผู้ชมผู้โชคดียังสามารถมีโอกาสขึ้นไปมีส่วนร่วมในโชว์ ได้สัมผัสเทคนิคการตัดที่ประณีตของอาจารย์คาเซีย รับรองว่าจะทำให้คุณเปลี่ยนมุมมอง ให้ชีวิตประจำวันของคุณน่าเบื่อยิ่งขึ้น! ที่น่าทึ่งก็คือ ทุกอย่างนี้ฟรี! ความสุขของคุณคือรางวัลที่ดีที่สุดของอาจารย์คาเซีย!\nทุกคนที่มหาวิทยาลัยมิซากะ สุดสัปดาห์นี้พบกันที่พื้นที่ว่างหลังโรงอาหาร อาจารย์คาเซียจะรอคุณอยู่!\n\nหมายเหตุ: เมื่อเข้าไปในงานคาร์นิวัลแล้วต้องสัมผัสประสบการณ์ทั้งหมด ไม่สามารถออกกลางคันได้ ผู้ที่มีความสามารถในการรับไม่สูงและมีจิตใจหรือหัวใจที่เปราะบางควรระมัดระวัง.\nหากหลังจากงานคาร์นิวัลมีอาการเบื่ออาหาร ร่างกายพิการ ตาเสีย และท้องแตก งานคาร์นิวัลนี้จะไม่รับผิดชอบใดๆ。」\n——《การเปิดงานคาร์นิวัลเวทมนตร์ของมาสเตอร์คาเซียอย่างยิ่งใหญ่!》"
  },
  AwakerStory_11376_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_11376_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_11377_Content = {
    Text = "「ซาลอน」ไม่รู้ตั้งแต่เมื่อไหร่ได้เงียบ ๆ เกิดขึ้นในสังคมชั้นสูงของลอนดีเนี่ยน\nในซาลอนที่ลึกลับนี้ มีผู้คนที่ได้รับโอกาสได้รับภาพวาดจากอาจารย์ มีคนที่ได้ทานอาหารค่ำกับนายกรัฐมนตรี และยังมีผู้ที่ได้รับสัญญาจากราชินี\nผู้จัดงาน สถานที่จัดงาน และเวลาจัดงานล้วนเป็นปริศนา ผู้คนเพียงรู้ว่า ทุกคนสามารถได้รับสิ่งที่ต้องการที่สุดในซาลอน\nแต่ไม่มีใครรู้ว่า แขกประเภทใดที่จะได้รับความสนใจจากเจ้าภาพและได้รับคำเชิญ\nแม้แต่ลอร์ดเดกสเตอร์ที่มีความสามารถในการเข้ากับคนได้ดี ก็ยังถูกปฏิเสธจากเจ้าภาพของซาลอน\n「ขอโทษครับ เจ้าภาพตอนนี้ชอบเชิญเฉพาะศิลปินชื่อดัง」\n「ขุนนาง? กรุณารอคำเชิญในอนาคต」"
  },
  AwakerStory_11377_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_11377_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_11378_Content = {
    Text = "คุณผู้หญิงที่สูงส่งจับมือเธอและบอกกับเธอว่า จะมอบความรักทั้งหมดในโลกนี้ให้กับเธอ \n เธอเชื่อในความอ่อนโยนของคุณผู้หญิงและการเอาใจใส่ของคุณชาย เชื่อในทุกๆ รอยยิ้ม ทุกๆ การกอด แต่ไม่รู้เลยว่าในสายตาของพวกเขา เธอเป็นเพียงสัตว์เลี้ยง เมื่อใดก็ตามที่มีภัยคุกคามต่อพวกเขา ก็สามารถทิ้งเธอได้ทันที \n พวกเขาโยนเธอลงกรงด้วยมือตนเอง ทำลายความไว้วางใจของเธอให้แตกสลาย—แต่ไม่ว่าจะเป็นการถูกเฆี่ยนตีจากคนคุมเรือนจำหรือการถูกทรมานจากญาติพี่น้อง ความทรยศจากคนที่ใกล้ชิดกลับเจ็บปวดมากกว่า \n เกลียดนัก เกลียดพวกเขาที่ใช้คำโกหกแลกกับความจริงใจของเธอ เกลียดพวกเขาที่ใช้ชีวิตของเธอสร้างความทุกข์ทรมานในละครที่น่าสมเพชนี้ ถ้านี่คือผลลัพธ์จากการเชื่อใจผู้อื่น เธอจะเป็นที่พึ่งพาตนเองตลอดไป \n ความไว้วางใจของเธอจะมอบให้เพียงแค่ตัวเธอเอง。"
  },
  AwakerStory_11378_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_11378_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_123300_Content = {
    Text = "วันหนึ่ง เธอจะกลับไปยังโลกของเธอ\n\nแต่ก่อนหน้านั้น เธออยากเห็นจุดจบของโลกนี้—\n\nคนที่ถูกเรียกว่า「ผู้พิทักษ์」จะถูกโลกที่บ้าคลั่งและน่าสะพรึงกลัวนี้กลืนกิน หรือจะเปล่งประกายออกมา นำมาซึ่งการช่วยเหลือและแสงสว่างที่แท้จริงให้กับโลกที่กำลังจะล่มสลายนี้?\n\nนี่คือปริศนา เป็นความท้าทาย เป็นการเดิมพัน.\n\nและเธอ ต้องการรู้คำตอบ."
  },
  AwakerStory_123300_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_123300_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_123301_Content = {
    Text = "A.F.3@2 ปี@1 เดือน วันที่ 17 หลังจากได้รับแจ้งจากคณะกรรมการตรวจสอบว่ามีพิธีบูชายัญมนุษย์ของลัทธิรุ่งอรุณแห่งดวงดาวกำลังจัดขึ้นในพื้นที่@4 ข้าพเจ้าจึงออกเดินทางไปยังพื้นที่ดังกล่าวเพื่อทำการสืบสวนทันที\nเมื่อข้าพเจ้าไปถึง ก็เป็นเวลาเย็นแล้ว พื้นที่ดังกล่าวถูกปกคลุมด้วยหมอกหนาจากสาเหตุที่ไม่ทราบแน่ชัด แทบจะมองไม่เห็นอะไรเลย\nข้าพเจ้าไม่ได้พกอุปกรณ์สลายหมอกมาด้วย แต่เมื่อพิจารณาถึงความร้ายแรงของเรื่องนี้ ข้าพเจ้าก็ยังคงบุกเข้าไปในหมอก หากเวลาสามารถย้อนกลับได้ ข้าพเจ้าจะไม่ทำสิ่งบ้าบอเช่นนี้อีกเด็ดขาด เพราะ... เพราะในหมอกมี@2ที่น่าสะพรึงกลัว...\nเมื่อสิ่งบิดเบี้ยวที่ไม่อาจบรรยายรูปร่างได้เหล่านั้นพุ่งเข้าหาข้าพเจ้าด้วยความเร็วเหนือมนุษย์ ข้าพเจ้าไม่สามารถตอบสนองได้เลยแม้แต่น้อย ร่างกายของข้าพเจ้าแข็งทื่อ ขยับไม่ได้\nแต่สุดท้ายข้าพเจ้าก็ไม่ได้ตาย เด็กสาวคนนั้น เด็กสาวลึกลับที่มาจากในหมอกช่วยข้าพเจ้าไว้\nเธอตะโกนอะไรบางอย่างที่อาจจะเป็น「ทอร์นาโด」? ข้าพเจ้าฟังไม่ชัด ข้าพเจ้าเห็นเพียงขวานลูกหนึ่งพุ่งมาจากในหมอก ผ่าหัวของสิ่งน่าสะพรึงนั้นออก จากนั้นเด็กสาวก็ดึงขวานออกมาแล้วแบกไว้บนไหล่\n「ในหมอกอันตรายมากนะ ถ้าไม่อยากตายก็ออกไปจากที่นี่ซะ」\nตอนที่เธอพูดประโยคนี้ สีหน้าของเธอเป็นรอยยิ้ม เป็นรอยยิ้มหวานใสแบบสาวน้อยวัยรุ่น แต่ไม่รู้เพราะอะไร ข้าพเจ้ากลับรู้สึกว่ารอยยิ้มนี้น่าขนลุกยิ่งกว่าสัตว์ประหลาดในหมอกเสียอีก\nมนุษย์คนหนึ่ง หรือจะเรียกว่าสิ่งที่มีรูปร่างเป็นมนุษย์ เดินท่องไปในหมอกหนาที่เต็มไปด้วยสัตว์ประหลาด แต่กลับไม่เป็นอันตรายแม้แต่น้อย และยังคงรักษารอยยิ้ม「หวานใส」แบบนี้ได้...\nด้วยความหวาดกลัว ข้าพเจ้าจึงลุกขึ้นมาได้ในที่สุด กรีดร้องถอยห่างจากเธอ\nในไม่ช้า หมอกหนาก็ปกคลุมสายตาของข้าพเจ้า ข้าพเจ้าตกอยู่ในสภาพที่มองไม่เห็นอะไรอีกครั้ง แต่เสียงหัวเราะของเธอ เสียงหัวเราะไร้เดียงสาแบบสาวน้อยวัยรุ่นของเธอ ยังคงก้องอยู่ในหมอกตลอดเวลา\n——《เอกสาร: การสืบสวนลัทธิรุ่งอรุณแห่งดวงดาวในพื้นที่@4》"
  },
  AwakerStory_123301_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_123301_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_123302_Content = {
    Text = "ในมุมมองของนักเรียนส่วนใหญ่ โมช่าเป็นคนที่เหมาะสมที่สุดที่จะเป็นเพื่อน เธอมักจะยิ้มแย้มแจ่มใสและเข้าร่วมสนทนาอย่างมีความสุข และไม่ค่อยปฏิเสธคำขอของคนอื่น ทำให้มีคนเชิญเธอไปเดินช็อปปิ้ง คุยเล่น หรือทานข้าวเสมอ \n แต่มีเพียงไม่กี่คนที่รู้ว่าเธอเป็นอย่างไรในความเป็นจริง ในหมู่คนเหล่านี้ เธอไม่จำเป็นต้องแสร้งทำเป็นเป็นมิตร ไม่ต้องปกปิดความดูถูกต่อกฎระเบียบและระเบียบวินัย \n 「เพื่อนอะไร? แค่ทำให้เวลาผ่านไปเท่านั้น ถ้าไม่ทำแบบนี้ ก็จะถูกมองว่าเป็นนักเรียนปัญหา ถูกอาจารย์เฮลเลตเรียกไปสอบถาม—มันน่ารำคาญจริงๆ」"
  },
  AwakerStory_123302_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_123302_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_123303_Content = {
    Text = "ชีวิตของเธอดูเหมือนจะเต็มไปด้วยเรื่องไม่คาดฝันเสมอ: เริ่มจากเผชิญกับหมอกปริศนาที่แผ่ขยาย แล้วก็ถูกเรียกไปยังต่างโลกอย่างไม่ทราบสาเหตุ\nเมื่อพิธีอัญเชิญเสร็จสิ้น และก้าวเท้าลงบนผืนดินของต่างโลกเป็นครั้งแรก ม่อเซี่ยก็เห็นหมอกหนาที่คุ้นเคย และในหมอกหนานั้น คือเสียงกรีดร้องของผู้คน\nนั่นคือเหยื่อบูชายัญที่กำลังหนีจากการไล่จับของพวกลัทธินอกรีต\nเหยื่อบูชายัญ? พวกลัทธินอกรีต? ช่างเป็นคำศัพท์ใหม่ที่... น่าตื่นเต้นเสียจริง\nนี่หมายความว่าโลกใหม่นี้ดำเนินไปตามกฎแห่งป่า ที่ผู้แข็งแกร่งกินผู้อ่อนแอ และบังเอิญเหลือเกิน เธอไม่เคยเป็นผู้อ่อนแอ\nเธอล่าพวกลัทธินอกรีตในหมอกอย่างสงบเยือกเย็น มีความสุขจนถึงขั้นฮัมเพลง\n「ทีละคน ทีละคน แล้วก็อีกคน... ในหมอกหนาที่ไม่มีใครรู้ ฉันระบายออกอย่างเต็มที่♪」\n「เคาะกะโหลกของเธอ เจาะลึกเข้าไปในสมอง มาฆ่าเวลากันด้วยการไล่ล่าเถอะ♪」\nในเสียงฮัมเพลงอย่างไม่ใส่ใจนี้ ม่อเซี่ยรู้สึกถึงความหิวกระหายจากความว่างเปล่าในจิตใจ——\nโลกบ้าคลั่งนี้ไม่อาจเติมเต็มความว่างเปล่าในใจของเธอได้ แต่มันสามารถบรรเทาความหิวโหยในจิตวิญญาณของเธอ ที่โหยหาการทำลายล้างและความคลั่งไคล้ได้"
  },
  AwakerStory_123303_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_123303_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_123304_Content = {
    Text = "พูดให้ถูกต้อง เธอไม่ได้เป็นส่วนหนึ่งของโลกที่ใกล้จะพังทลายนี้ แต่เธอก็ชื่นชมที่นี่.\nชื่นชมความงดงามของโลกที่กำลังลุกไหม้ ชื่นชมความเจ็บปวดและการพังทลายของมนุษย์ในความสิ้นหวัง.\nศรัทธาได้ตายไปแล้ว สังคมหยุดนิ่ง ศีลธรรมพังทลาย และธรรมชาติก็ไม่จำเป็นต้องปลอมตัวเป็น 「คนปกติ」 ที่น่าเบื่ออีกต่อไป——\nเธอ finalmente สามารถปลดปล่อยสัตว์ร้ายในใจอย่างถูกต้องตามกฎหมาย เผยให้เห็นตัวตนที่แท้จริงของเธอ และเป็นตัวตนที่แท้จริงของเธอ."
  },
  AwakerStory_123304_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_123304_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_126929_Content = {
    Text = "ไม่มีใครรู้จริงๆ ว่าสวี่ปรากฏตัวในวิทยาเขตตั้งแต่เมื่อไหร่ เหมือนกับที่เธอเดินเข้าออกราชสำนัก กระโจมของกษัตริย์ และสมาคมต่างๆ ในตะวันออกไกลอย่างเป็นธรรมชาติ\nทุกคนล้วนมีความรู้สึกคุ้นเคยกับเธอโดยธรรมชาติ ราวกับเป็นเพื่อนเก่าแก่หลายปี หรือแม้แต่คนรักที่อยู่ในใจ แม้ว่าพวกเขาจะไม่เคยผ่านอะไรร่วมกันมาก่อนเลย\nมีเพียงผู้ตื่นจำนวนน้อยมากเท่านั้นที่แสดงความระแวดระวังอย่างผิดปกติต่อสวี่ หรือพูดอีกอย่างคือ มีเพียงผู้ตื่นที่มีพลังแข็งแกร่งจำนวนน้อยมากเท่านั้น ที่สามารถรับรู้ถึงความสามารถอันผิดปกติของสวี่ ที่แผ่ซ่านเหมือนหมอก ซึมเข้าไปในความทรงจำของอีกฝ่าย\nฝ่ายบริหารของมิซาเกะเคยหารืออย่างจริงจังว่าจำเป็นต้องจำกัดเรื่องนี้หรือไม่ หรือแม้แต่พัฒนาอุปกรณ์ต่อต้านเฉพาะสำหรับเรื่องนี้ สวี่ได้คลายความกังวลนี้ผ่านการเจรจาบางอย่างและคำสัญญาหนึ่งข้อ\n「เจตนาของข้า... มิได้อยู่ที่เด็กน้อยเหล่านี้หรอก」"
  },
  AwakerStory_126929_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_126929_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_126930_Content = {
    Text = "A. F.@16@เรือบรรทุกสินค้าที่ไม่มีร่องรอยการเดินเรือปรากฏในวงการสำรวจใด ๆ และไม่ได้รับการอนุมัติจากเอกสารใด ๆ ได้เงียบ ๆ เทียบท่าที่ท่าเรือขนส่งลอนดีเนี่ยน.\nเรือบรรทุกสินค้านี้ได้รับการยืนยันว่ามาจากท่าเรือของอาณาจักรฟานหลงโบราณ@2 ในภูมิภาคตะวันออกไกล.\nคืนที่เรือบรรทุกสินค้านี้เข้าท่า พนักงานที่ทำงานที่ท่าเรือและผู้อยู่อาศัยใกล้เคียง ต่างบอกว่าเห็นผู้หญิงชาวตะวันออกผมดำ ตาดำ ผิวสีงาช้างในความฝัน.เมื่ออธิบายลักษณะของผู้หญิงคนนี้ ผู้เห็นเหตุการณ์ใช้คำว่า 「น่าหลงใหล」 และ 「คุ้นเคย」 โดยไม่ได้นัดหมาย และหลายคนที่เป็นชายก็มีอาการแข็งทื่อในระหว่างการเล่าเรื่อง.\nนักสืบมิซากะได้ทำการค้นหาเรือบรรทุกสินค้าอย่างรวดเร็ว แต่แปลกมากที่นอกจากเสียงหัวเราะที่แทรกอยู่ทั่วไปและการตอบสนองทางจิตวิญญาณที่ชัดเจนแล้ว ไม่พบร่องรอยของเงินใจใด ๆ.\nลอร์ดเดกสเตอร์ได้เข้าไปในห้องเก็บสินค้าของเรือบรรทุกสินค้าในวันถัดไป และพบเงินใจที่มีไอน้ำบาง ๆ ไหลอยู่ในแจกันเซรามิกที่ 「ถูกค้นหาหลายครั้ง」.\nจนถึงปี A. F. 314 เงินใจนี้ได้รับการยืนยันว่าไม่สามารถปลุกตื่นได้ด้วยวิธีใด ๆ.\nจนกระทั่งผู้พิทักษ์@3 คนปัจจุบันได้เข้ามาที่มิซากะ เงินใจนี้ได้ทำพิธีปลุกตื่นเอง และตื่นขึ้นมาเป็นผู้ปลุกตื่นที่เรียกตนเองว่า 「ซู」 และขอเชื่อมโยงกับ@3.\n——คัดลอกจาก「มหาวิทยาลัยมิซากะเงินใจบันทึกการจำ」"
  },
  AwakerStory_126930_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_126930_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_126931_Content = {
    Text = "คุณเคยรู้สึกไหมว่าโลกเงียบเกินไป จนอยากจะทำลายอะไรสักอย่างเพื่อให้ได้ยินเสียง?\nความรักและความปรารถนาเป็นขวดเงินที่เธอโยนออกไป สัตว์ที่ถูกขวดเงินนี้ทำให้ตื่นตระหนก... ถูกฆ่าด้วยความรัก ถูกฆ่าด้วยความรัก จนกว่าจิตใจจะอ่อนกำลัง เหลือเพียงแต่ร่างกาย.\nจากนั้น ร่างกายที่ถูกบีบคั้นเหล่านี้ จะมอบอำนาจที่สูงขึ้นมากมายให้กับเธอ ทำให้ทุกสิ่งที่มองเห็นเต็มไปด้วยความโกลาหลที่มีกลิ่นคาวและน่ารับประทาน.\nความโกลาหลที่ไม่หยุดยั้ง.."
  },
  AwakerStory_126931_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_126931_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_126932_Content = {
    Text = "...สิ่งที่มิใช่เทพเจ้าที่ควรบูชาแต่กลับบูชา เรียกว่าการบูชาอลัชชี ล่อลวงราษฎรสิ้นเปลืองทรัพย์ ห้ามเท่าไรก็ไม่หยุด\nชาวบ้านตามชายฝั่งทะเล ล้วนมีธรรมเนียมเก่าแก่ในการบูชาเทพเจ้าจิปาถะ ชอบสร้างศาลเจ้าและวัดป่า ใช้จ่ายมากมาย ทิ้งการทำนาทอผ้า แต่คนในหมู่บ้านกลับไม่รู้สึกว่าเป็นปัญหา ผู้ปกครองทำลายศาลเจ้าหลายครั้ง แต่พอทหารถอนกำลังไป ไม่นานก็กลับมาอีก\nยิ่งไปกว่านั้น มีชาวต่างถิ่นที่มาตั้งรกรากในหมู่บ้าน นำสัญลักษณ์ของลัทธิต่างถิ่นมาแขวนกลับหัว เอาตัวอักษร@3ที่มีรูปร่างคล้ายกัน เรียกว่า「อิ่ง」(บ่อ) แล้วนำมาใช้เป็นของตน\nเทพเจ้าหลักและเทพเจ้ารองที่บูชาในศาลเจ้า ล้วนเป็นบุคคลที่สามารถสืบประวัติได้ ส่วนใหญ่เป็นสตรีที่ตายอย่างอยุติธรรม ในตอนแรกผู้ศรัทธาก็ส่วนใหญ่เป็นหญิงชาวนา นักแสดง และหญิงโสเภณีเร่ร่อน\nภรรยาพาสามีเข้า แม่พาลูกเข้า โสเภณีพาลูกค้าเข้า เมื่อเติบใหญ่ขึ้น ก็ตั้งพรรคตั้งพวกหาผลประโยชน์ส่วนตัว มีปรากฏการณ์แปลกที่หลายหมู่บ้านร่วมกันสนับสนุนคนเดียว บ้างก็เข้ารับราชการ บ้างก็เลี้ยงกองกำลังส่วนตัว แย่งชิงกันไปมา\n@4@4@3@2\nตัวอักษรด้านล่างนี้ล้วนอ่านไม่ออกแล้ว นอกจากนี้ยังมีข้อความภาษา@3หลายบรรทัดที่เขียนอย่างเรียบร้อย เมื่อแปลโดยภาควิชาภาษาศาสตร์แล้ว คำแปลมีดังนี้:\n「ตาแก่หน้าด้านไร้ยางอาย เขียนลำเอียง น่าเบื่อจริงๆ ข้าเบื่อๆ เลี้ยงจิ้งหรีดมาชนกันเล่น ก็ยังจะมาจ้อ」\n「ธุระอะไรของแก」\n——คัดจาก《บันทึกคัดลอกจากเย่หูไจ้จ๋าจื้อ》"
  },
  AwakerStory_126932_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_126932_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_126933_Content = {
    Text = "สง่างาม มีเสน่ห์ และมีเสน่ห์ที่ดึงดูดใจของ 「เทพเจ้า」 ตะวันออก ตามตำนาน เมื่อเธอเลื่อนพัดออก คุณจะเห็นใบหน้าของคนที่คุณรักมากที่สุดใต้พัด \n แต่ตำนานก็เป็นเพียงตำนาน ขอให้เธออย่าได้มองมาที่คุณ เมื่อเธอแทรกซึมเข้าไปในความทรงจำของคุณเหมือนหมอกยามค่ำคืน นอกจากความคลั่งไคล้ที่บ้าคลั่งแล้ว... ในหัวของคุณก็จะไม่มีอะไรเหลืออีกแล้ว."
  },
  AwakerStory_126933_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_126933_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_129596_Content = {
    Text = "สถานการณ์ของผู้ตื่นมอสค่อนข้างพิเศษ ในสภาวะที่ไม่ถูกจำกัด การเปิดใช้ความสามารถไม่ได้ขึ้นอยู่กับเจตจำนงของตัวผู้ตื่นเอง รอบตัวเธอจะเกิดสนามพลังงานพิเศษคล้ายกระแสน้ำวน M เป็นระยะๆ อย่างไม่แน่นอน บดทำลายวัตถุที่อยู่ภายในสนามพลังงาน\nเมื่อมอสสัมผัสกับบุคคลหรือวัตถุที่มีน้ำอยู่ภายใน (รวมถึงของเหลวในร่างกายเช่นเลือด) จะเร่งการเกิดสนามพลังงานในตำแหน่งนั้น เนื่องจากปรากฏการณ์นี้อยู่นอกเหนือการควบคุมของมอสเอง ประกอบกับช่วงแรกของการตื่นเธออยู่ในสภาวะคลุ้มคลั่งเป็นเวลานาน จึงมีระดับอันตรายสูงมาก\nด้วยเหตุนี้ ภาควิชาผู้ตื่นจึงร่วมมือข้ามคณะกับภาควิชาฟิสิกส์ เคมี และอื่นๆ หลายภาค หลังจากทดลองหลายครั้งจึงสามารถพัฒนาโลหะสังเคราะห์「เหล็กมอส」ที่ทนทานต่อพลังทำลายล้างของเธอได้สำเร็จ และนำมาทำเป็นที่ครอบปากและอุปกรณ์จำกัดให้มอสสวมใส่\nจิตใจของผู้ตื่นมอสเริ่มมีเสถียรภาพหลังจาก「การทดลองสัมผัสผู้ตื่น O–1841」ครั้งที่สิบเอ็ดที่ดำเนินการโดยนักวิจัยคอลด์เวลล์ ในการทดลองนั้น มอสได้ถ่ายโอนอิทธิพลของกระแสน้ำวน M–เมิร์สก์สมาสู่ตัวเอง จึงลดอันตรายต่อสิ่งรอบข้างได้อย่างมาก\nแต่ยังต้องระวังว่า มอสไม่สามารถรักษาสภาวะนี้ได้นานด้วยตัวเองเพียงลำพัง มีเพียงการอาศัยอุปกรณ์จำกัด「เหล็กมอส」เท่านั้น มอสจึงสามารถรักษาอิทธิพลของกระแสน้ำวน M ไว้ภายในตัวเองได้อย่างมีเสถียรภาพในระยะยาว พร้อมทั้งนำพลังของเธอมาใช้ในการต่อสู้\nหลังจากฟื้นสติ มอสแสดงให้เห็นถึงนิสัยร่าเริงของเธอ และแสดงความใกล้ชิดกับผู้ตื่นโนติลาอย่างไม่ทราบสาเหตุ สิ่งนี้ดูเหมือนจะเกี่ยวข้องกับประสบการณ์ของต้นกำเนิดจิตวิญญาณของทั้งสอง\n——คัดจาก《รายงานผู้ตื่นมอส》"
  },
  AwakerStory_129596_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_129596_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_129597_Content = {
    Text = "แม้ว่าเธอจะรู้วิธีจัดระเบียบประโยคได้อย่างถูกต้อง แต่เธอก็ไม่สามารถบอกคุณได้ว่าเธอเกิดที่ไหน ในความเป็นจริง ไม่ว่าจะเป็นบ้านไหน ตอนนี้เธอสามารถนึกถึงได้เพียงชายหาดขาวสะอาด ป่าทึบ และมหาสมุทรที่ไร้ขอบเขตเท่านั้น \n แต่ถ้าคุณถามเธอว่าบ้านอยู่ที่ไหน เธอจะบอกคุณด้วยคำพูดที่แข็งกระด้างและภาษากายที่ร้อนแรงว่า: บ้านอยู่บนทะเล ล่องลอยไปตามกระแสน้ำ \n คนที่ไม่มีใครอยู่เคียงข้างนานไม่สามารถตัดสินว่าอะไรคือความเหงา แต่ในเรือลำนี้เธอได้ลิ้มรสถึงความรักในครอบครัว และได้รับมิตรภาพ: เธอแบ่งปันปลาย่างอร่อยและเปลือกหอยสวยงามกับเพื่อนที่ชื่อว่า นอติลุส แบ่งปันความฝันเกี่ยวกับแผ่นดิน การเดินทาง และการผจญภัย และสุดท้ายแบ่งปันความตายที่กลับสู่คลื่นทะเลสีดำและวังวน."
  },
  AwakerStory_129597_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_129597_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_129598_Content = {
    Text = "กระแสน้ำวนแอตแลนติกเหนือ M–เมิร์สก์ส ปรากฏขึ้นครั้งแรกใน A. F. 1■■ ในช่วงหลายร้อยปีถัดมา ขนาดของมันค่อยๆ ขยายใหญ่ขึ้น จนถึง A. F. 29■ M–เมิร์สก์สได้พัฒนาเป็นกระแสน้ำวนขนาดใหญ่ที่มีเส้นผ่านศูนย์กลางประมาณ 260–300 ฟุต(80–90 เมตร) กระแสน้ำกว้างประมาณ 5 ไมล์(8 กิโลเมตร)\nนอกเหนือจากแรงดูดอันทรงพลังจากกระแสน้ำและผลกระทบของมัน(ปลาและเรือประมงในน่านน้ำใกล้เคียงล้วนได้รับความเสียหาย) ใต้ M–เมิร์สก์สยังมีภัยคุกคามที่ใหญ่กว่า——รอยแยกกัดกร่อน หลังจากสมาชิกของสถาบันสังเกตการณ์และวิจัยเป็นเวลานาน จึงยืนยันได้ว่าการก่อตัวของ M–เมิร์สก์สมีความเกี่ยวข้องโดยตรงกับรอยแยกกัดกร่อนด้านล่าง และได้ดำเนินการกำจัดอย่างเป็นทางการใน A. F. 313\nภายในรอยแยก สถาบันได้ค้นพบซากสิ่งมีชีวิตและเรือจำนวนมาก และได้รับแกนเงินหมายเลข O–1841\n——คัดจาก«บันทึกเหตุการณ์ M–เมิร์สก์ส»"
  },
