  AwakerStory_129599_Content = {
    Text = "ไม่เข้าใจภาษา? ไม่ใช่ปัญหา การสื่อสารสามารถทำได้เหมือนกับการใช้ท่าทางและการวาดภาพ ไม่สามารถควบคุมพลังได้? ที่โรงเรียนนี้เหมือนกับเรื่องธรรมดา การทดลองไม่กี่วันก็สามารถแก้ไขได้.\nด้วยรอยยิ้มที่สดใสและบุคลิกที่เกือบจะดุร้าย มอสก็ได้รับความนิยมจากผู้ปลุกตื่นคนอื่นๆ อย่างรวดเร็ว แม้ว่าเธอจะมักสร้างความเสียหายอย่างใหญ่หลวงเพราะลืมพลังของตัวเอง(ขอให้พระเจ้าอวยพรน้ำพุที่ถูกสร้างใหม่ถึง 3 ครั้ง) แต่จะทำอย่างไรได้? เธอไม่ได้ตั้งใจ.\nประมาณนั้น."
  },
  AwakerStory_129599_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_129599_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_129600_Content = {
    Text = "ก่อนที่ทุกสิ่งจะถูกกระแสน้ำเชี่ยวกลืนกิน ท่ามกลางท้องทะเลอันไร้ขอบเขตและสายลมทะเลที่เค็มจางๆ บนเรือลำนั้น ครอบครัวที่ไม่ใช่สายเลือดเดียวกันและเพื่อนๆ ทำให้เธอเข้าใจความหมายของความโดดเดี่ยว และไม่ปรารถนาที่จะตกลงไปในนั้นอีก\nแต่เพื่อเพื่อนที่ดีที่สุดของเธอ ครอบครัวเล็กๆ ของเธอ เธอยินดีที่จะกลับคืนสู่ความเงียบงันอันมืดมิดนั้นอีกครั้ง\nหลังจากทุกสิ่งถูกปกคลุมด้วยความมืด เธอได้รับชีวิตใหม่ในอีกรูปแบบหนึ่ง แม้ว่าชีวิตแบบนี้จะมีความไม่สะดวกมากมาย——เธอมักลืมไปว่าพลังของเธอจะนำความเสียหายอย่างใหญ่หลวงมาสู่สิ่งรอบข้าง——แต่ความเป็นไปได้ที่จะได้เพื่อนเพิ่มขึ้นก็ยังคงทำให้เธอมีความสุขอย่างเหลือล้น\nแน่นอน ถ้าเพื่อนที่ดีที่สุดของเธอสามารถนึกออกถึงเรื่องราวที่พวกเธอเคยมีร่วมกัน ก็จะยิ่งดีกว่านี้\n「ดีกว่าดีกว่า ดีกว่ามากมากมาก!」"
  },
  AwakerStory_129600_Title = {
    Text = "เรื่องราว·สี่"
