  AwakerStory_129600_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_134315_Content = {
    Text = "ผู้ถักทอที่ถูกกักขังด้วยใยของตนเอง นักเขียนบทและผู้ชมนิรันดร์แห่งโรงละครโชคชะตา\nเส้นด้ายหล่นลงจากปลายนิ้ว พันกันเป็นม่าน บทละคร และกรงขัง——ทุกเส้นล้วนถูกอาราคเน่ปั่นด้วยมือของเธอเอง แล้วก็พันรัดเธอทีละชั้นๆ\nที่นั่งผู้ชมว่างเปล่าตลอดกาล มีเพียงเธอเองที่นั่งอยู่ใต้เวทีจ้องมองการแสดงที่สนุกสนานกับตัวเองบนเวที วนเวียนซ้ำแล้วซ้ำเล่า ไม่มีวันจบ\nการดำรงอยู่ของเธอ คือวิญญาณแห่งโรงละคร และเป็นรูปธรรมของโชคชะตา"
  },
  AwakerStory_134315_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_134315_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_134316_Content = {
    Text = "ในตอนแรก อาราคเน่ไม่รู้เลยว่าตนเองสามารถมองเห็นโชคชะตาได้ \nโลกในสายตาของเธอก็เหมือนกับคนอื่นๆ ——พร่ามัว อึกทึก และเต็มไปด้วยความบังเอิญ\nเมื่ออายุสองขวบ เธอเอ่ยประโยคแรกในชีวิต \nไม่ใช่「แม่」 ไม่ใช่「พ่อ」 แต่เป็นการยืนอยู่ใต้ระเบียง พูดเบาๆ กับพ่อบ้านผู้ชราที่ดูแลตระกูลมาหลายชั่วอายุคนว่า「ราตรีสวัสดิ์」 \nคืนนั้น พ่อบ้านเสียชีวิตกะทันหันจากโรคหัวใจ เธอกำนาฬิกาพกที่เขาทิ้งไว้ ร้องไห้จนหลับไปหน้าห้องพักคนรับใช้ ตอนนั้นเธอยังไม่เข้าใจความตายและโชคชะตา แต่ได้ลิ้มรสความขมขื่นที่โชคชะตาเผยออกมาก่อนเวลาแล้ว\nห้าขวบ ท่ามกลางเสียงโห่ร้องอย่างครึกครื้นของแขกในงานเลี้ยง เธอเลียนแบบแม่ เขย่งเท้าเต้นวอลทซ์อย่างเก้ๆ กังๆ \nรองเท้าเต้นรำสีแดงบนเท้าสดใสราวกับเลือด และราวกับลางบอกเหตุบางอย่าง เธอหมุนตัวแล้วล้มลง ไม่มีใครสังเกตเห็นภาพที่วาบผ่านดวงตาของเธอ ราวกับว่าถูกกำหนดให้ล้มลงตั้งแต่แรก\nวันเกิดอายุเจ็ดขวบ พ่อมอบกงล้อปั่นด้ายชื่อ「โมอิไร」ให้เธอ ——นั่นคือชื่อของเทพีแห่งโชคชะตาทั้งสาม \nเธอวิ่งเล่นในป่า เสียงหัวเราะใสกังวาน แต่เมื่อสะดุดล้ม ก็ได้ยินเสียง「กรึก」——กงล้อหัก \nเธอนั่งยองๆ ในกองใบไม้ร่วง นิ้วลูบไล้รอยแตก แล้วจู่ๆ ก็พบว่าราวกับมีเส้นด้ายนับไม่ถ้วนพุ่งออกมาจากรอยแตก พันรอบปลายนิ้วของเธอ ทอดยาวไปสู่ที่ไกลแสนไกลที่มองไม่เห็น\nหลังจากนั้น เธอก้าวเข้าโรงอุปรากรเป็นครั้งแรก รู้จักเพื่อนรักเป็นครั้งแรก ฝังร่างสุนัขที่รักด้วยมือตนเองเป็นครั้งแรก... \nทุกๆ「ครั้งแรก」ล้วนมาพร้อมกับฉากจบอันเงียบงันที่ปรากฏต่อหน้าเธอ เธอเริ่มเข้าใจว่า สิ่งที่เรียกว่าจุดเริ่มต้น ล้วนถูกกำหนดบทสรุปของโชคชะตาไว้แล้วตั้งแต่แรก\nตั้งแต่นั้นมา สายตาไม่อาจหยุดอยู่ที่เปลือกนอกได้อีกต่อไป ใบหน้าผู้คนกลายเป็นผ้าโปร่ง เธอมองทะลุได้ในพริบตาเดียวถึงสายธารแห่งชะตากรรมที่ไหลเชี่ยวอยู่เบื้องล่าง: ใครจะป่วยตายปลายฤดูร้อน ใครจะผูกคอตายคืนก่อนวันแต่งงาน ลูกของใครจะฝังร่างเขาด้วยมือตนเองในอีกสิบปี...ความประหลาดใจดับสูญ ความคาดหวังเหี่ยวเฉา สิ่งที่เรียกว่า「อนาคต」ไม่ใช่อะไรอื่น นอกจากข่าวมรณกรรมที่เธอเปิดอ่านล่วงหน้า\nเธอเคยพยายามเตือนคนรอบข้างถึงหายนะที่กำลังจะมาถึง แต่ทุกครั้งที่คำพูดหลุดออกจากปาก กลับกลายเป็นการเร่งให้คำทำนายเป็นจริง \nเมื่อเผชิญกับแววตาหวาดกลัวถอยหนีของพวกเขา ขณะนั้นเธอจึงเข้าใจในที่สุด: \n「การมองเห็น ไม่ได้หมายความว่าจะเปลี่ยนแปลงได้」\nข่ายแห่งโชคชะตาถูกทอขึ้นมานานแล้ว「การหยั่งรู้」ของเธอเป็นเพียงแสงริบหรี่ที่ลอดผ่านช่องตาข่าย——ส่องให้เห็นบทสรุป แต่ไร้พลังที่จะพลิกเปลี่ยนเส้นด้ายแห่งชะตา\nแล้วเธอก็หยิบกงล้อปั่นด้ายชื่อ「โมอิไร」ขึ้นมา \nกงล้อที่หักไปนั้นถูกซ่อมแซมแล้ว แต่รอยแตกยังคงอยู่ เธอทอผ้าวันแล้ววันเล่า พรสวรรค์เกี่ยวกับโชคชะตาหลอมรวมเป็นหนึ่งเดียวกับกงล้อนี้อย่างน่าอัศจรรย์ \nตั้งแต่นั้นมา โชคชะตาของทุกคนล้วนไหลผ่านปลายนิ้วของเธอ พันสานกัน ทอเป็นข่ายมหึมาที่ทอดข้ามกาลเวลา โดยไม่รู้ตัว เธอเองก็ถูกข่ายนิรันดร์นี้กักขังอยู่ภายใน เธอเป็นประจักษ์พยานแห่งเสียงหัวเราะและน้ำตานับไม่ถ้วน จุดหมุนไม่สิ้นสุด ความเป็นไปได้ไม่รู้จบ พัดพาหายนะที่ถูกลิขิตไว้ให้เกิดขึ้นซ้ำแล้วซ้ำเล่า...\nแต่อาราคเน่จะไม่หยุด ไม่ใช่เพื่อการทอผ้า แต่เพื่อการธำรงรักษา——หากเธอหยุด ข่ายแห่งโชคชะตาทั้งผืนอาจพังทลาย พร้อมกับชีวิตนับล้านที่จะกลับคืนสู่ความว่างเปล่า แต่เธอก็มองเห็นเช่นกันว่า เมื่อข่ายแห่งโชคชะตาถูกทอจนสำเร็จ การตื่นขึ้นของพระองค์จะนำมาซึ่งหายนะที่หลีกเลี่ยงไม่ได้...\nเธอในฐานะผู้ทอ และผู้ถูกพันธนาการ กลายเป็นทั้งผู้ชม และนักโทษ เป็นทั้งนักเขียนบท และตัวละครในบทละคร\nการมองเห็นโชคชะตาของผู้อื่นได้ชัดเจน เป็นเรื่องดีหรือเรื่องร้ายกันแน่? \nอาราคเน่เลิกถามคำถามนี้ไปนานแล้ว"
  },
  AwakerStory_134316_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_134316_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_134317_Content = {
    Text = "ม่านยังไม่ได้ถูกยกขึ้นจนสุด แสงไฟก็หลั่งไหลลงมาดั่งคลื่นทะเล\nผู้ชมของมิซาเกะกลั้นหายใจรอคอยตัวเอกแห่งโชคชะตาขึ้นเวที\nเวทีเล็กมาก เล็กจนแทบจะไม่มีที่ให้อีดิปุสก้าวเท้า แต่เมื่อเด็กหนุ่มในชุดนักเรียนยกมือขึ้น เสียงของเขาทะลุผ่านเวทีที่เรียบง่าย บทพูดแรกที่เขาเอ่ยออกมากลับดั่งคำพยากรณ์จากเทพเจ้า:「ข้าคือผู้โชคร้ายคนนั้น ที่ถูกกำหนดให้ฆ่าพ่อและแต่งงานกับแม่」\n...\n「ข้าทำผิดกฎของเทพข้อไหนกัน... ข้าผู้โชคร้ายนี้ทำไมต้องพึ่งพาเทพเจ้า? ทำไมต้องขอพรจากเทพ ในเมื่อการกระทำอันเคร่งศรัทธาของข้ากลับได้รับชื่อว่าไม่เคารพเทพ?」สาวน้อยนามว่าแอนติโกเน่ตั้งคำถามถึงความไม่ยุติธรรมของกฎแห่งเทพ\n...\nแฮมเล็ตเดินวนคิดอยู่ในปราสาทแห่งเดนมาร์ก「จะอยู่หรือจะตาย นั่นคือปัญหาที่ควรพิจารณา จะทนรับศรพิษอันโหดร้ายของโชคชะตาอย่างเงียบงัน หรือจะลุกขึ้นต่อสู้กับทุกข์ทรมานอันไร้ที่สิ้นสุดในโลกมนุษย์ กวาดล้างมันด้วยการต่อสู้ การกระทำทั้งสองอย่างนี้ อย่างไหนสูงส่งกว่ากัน?」\n...\nบนที่นั่งพิพากษา จอห์น พร็อกเตอร์ค่อยๆ เงยหน้าขึ้น ประกาศคำตอบของเขา:「เพราะข้าเทียบไม่ได้แม้แต่กับฝุ่นดินต่อหน้าผู้ที่ก้าวขึ้นตะแลงแกงอย่างไม่หวั่นเกรงความตาย ข้าจะมีชีวิตอยู่อย่างเสื่อมเสียเกียรติได้อย่างไร?」\n...\nถ้อยคำเหล่านั้นที่เกี่ยวกับโชคชะตา ถูกแสดงเป็นละครในวันนี้\nอาราคเน่ยืนอยู่ข้างม่านด้านข้าง นิ้วจิกเข้าฝ่ามืออย่างไม่รู้ตัว\nน้ำตาที่หลั่งเพราะเห็นอกเห็นใจตัวละคร เสียงปรบมือที่กึกก้องดั่งฟ้าร้องเมื่อม่านปิด...\nใบหน้าต่างๆ ของผู้ชมใต้เวทีปรากฏชัดในสายตา เธอรู้สึกขึ้นมาทันทีว่า หัวใจที่เต้นอย่างไร้จุดหมายมาเนิ่นนาน ในที่สุดก็ค้นพบจังหวะของมันแล้ว\nในขณะนี้ เสียงของเธอ การดำรงอยู่ของเธอ ได้แทรกตัวเข้าสู่กระแสอันยิ่งใหญ่ของโชคชะตาอย่างเงียบๆ——ไม่ใช่แค่ดวงตาที่เฝ้ามองโชคชะตาอีกต่อไป แต่เป็นบทละครใหม่ที่กำลังถูกเขียนขึ้น โชคชะตาของผู้ชม โชคชะตาของนักแสดง และโชคชะตาของนักเขียนบท ถูกเชื่อมโยงเข้าด้วยกันผ่านละครที่กำลังแสดงอยู่...\nชัยชนะแห่งหัวใจ ที่แท้แล้วเงียบสงบเพียงนี้ แต่ก็กึกก้องเพียงนี้"
  },
  AwakerStory_134317_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_134317_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_134318_Content = {
    Text = "ในฐานะผู้ทอข่ายแห่งโชคชะตา ผู้ธำรงเส้นด้ายแห่งชีวิตและความตายของผู้คนนับล้าน ผู้ที่อดีตและอนาคตไหลผ่านฝ่ามือ อาราคเน่มีงานอดิเรกที่เกือบจะดูตื้นเขิน\nเธอหลงรักการละคร ไม่ใช่เพราะหลงใหลในความผันผวนของเนื้อเรื่องหรือความงดงามของบทพูด——สิ่งเหล่านั้นเธอรู้จนขึ้นใจแล้ว ในฐานะผู้สร้างบทละคร ทุกจุดหักเหของเนื้อเรื่อง ทุกบทพูดของนักแสดง เธอรู้ดีทุกประการ \nแต่เธอก็ยังก้าวเข้าโรงละครครั้งแล้วครั้งเล่า\nสิ่งที่เธอปรารถนาอย่างแท้จริง คือ「ความรู้สึกของการอยู่ ณ ที่นั้น」ในขณะที่ก้าวเข้าสู่โรงละคร\nเมื่อม่านเปิดขึ้น ที่นั่งผู้ชมจมลงสู่ความมืด แต่เวทีกลับกลายเป็นโลกเดียวที่เป็นจริง ขณะนั้น เวลาไม่ใช่แม่น้ำที่ไหลไปทางเดียวอีกต่อไป แต่เป็นการแสดงในพื้นที่จำกัด——อดีต ปัจจุบัน อนาคต ซ้อนทับกัน ณ ที่นี้ ทุกอย่างไม่ใช่บทละครบนกระดาษอีกต่อไป แต่เป็นการสั่นสะเทือนของชีวิตที่กำลังเกิดขึ้น「ในขณะนี้」\nและเธอ ในที่สุดก็ไม่ใช่ผู้ยืนอยู่นอกโชคชะตา ผู้ที่ทำได้เพียงจ้องมองเส้นด้ายแต่ไม่อาจสัมผัสได้อีกต่อไป \nในโรงละคร เธอสามารถเก็บซ่อนความทรงจำไว้ชั่วคราว ก้าวขึ้นเวที ปล่อยให้ตัวเองเป็นเด็กสาวที่สั่นเทาเอ่ยคำสั่งเสีย หรือในฐานะผู้ชมที่ปล่อยให้นักแสดงแสดงอย่างอิสระ ปลดเปลื้องภาระของผู้หยั่งรู้ กลั้นหายใจ หลั่งน้ำตา สั่นสะเทือนไปกับทุกรอยยิ้มและทุกสีหน้าของนักแสดง ไม่ใช่ในฐานะผู้ทำนาย แต่ในฐานะมนุษย์ที่มีชีวิต ในท่าทีของผู้ไม่รู้ หายใจไปพร้อมกับตัวละคร สลายหัวใจไปกับบทพูดเพียงประโยคเดียว แม้จะรู้ดีว่าบทสรุปไม่อาจเปลี่ยนแปลง แม้โศกนาฏกรรมถูกลิขิตให้มาถึง ภาพลวงตานี้ก็ยังทำให้เธอหลุดพ้นจากชะตากรรมของผู้ชมนิรันดร์ได้ชั่วขณะ\nไม่ถูกกันออกจากโชคชะตา แต่ได้รับอนุญาตให้ก้าวเข้าไปในนั้น——แม้เพียงชั่วขณะ แม้เป็นเพียงภาพลวง\nความหมกมุ่นเล็กๆ นี้ คือพระคุณอันหรูหราที่สุดที่โชคชะตามอบให้อาราคเน่"
  },
  AwakerStory_134318_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_134318_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_134319_Content = {
    Text = "ข้าพเจ้าเดินทางไปยัง \"โรงละครโชคชะตา\" ในย่านเมืองเก่าเมื่อปลายฤดูใบไม้ร่วงปี 3@2 เพื่อเข้ารับการสัมภาษณ์ตำแหน่งนักร้องเมซโซ-โซปราโน\nเมื่อไปถึงเป็นเวลาสี่โมงสิบเจ็ดนาที ท้องฟ้าครึ้มมัว ไม่มีฝน ประตูหน้าโรงละครไม่ได้ล็อก ที่นั่งผู้ชมว่างเปล่า ไม่มีวี่แววของผู้สัมภาษณ์เลยแม้แต่น้อย\nแต่กลางเวทีกลับมีการแสดงหุ่นกระบอกอยู่——ไม่มีคนชักเชือก ไม่มีเสียงดนตรี มีเพียงหุ่นเชิดรูปร่างมนุษย์สีซีดจางหลายตัวเคลื่อนไหวอย่างไร้เสียง การเคลื่อนไหวของพวกมันแม่นยำอย่างยิ่ง ข้อต่อส่งเสียงกรอบแกรบเบาๆ เมื่อหมุน น่าขนลุกขนพองยิ่งนัก และสายเชือกเหล่านั้น... สายเชือกที่ห้อยลงมาจากเพดานโค้ง กลับสั่นไหวราวกับมีชีวิต บ้างตึง บ้างหย่อน ประหนึ่งกำลังเต้นรับจังหวะบางอย่างที่มองไม่เห็น\nขณะที่ข้าพเจ้าพยายามหันหลังจากไป เสียงผู้หญิงก็ดังขึ้นจากห้องวีไอพีหมายเลขห้า \n\"ยินดีต้อนรับ คริสตีน\"\nเสียงนั้นไม่ได้อ่อนเยาว์และไม่ได้แก่ชรา เหมือนเสียงสะท้อนที่ซึมผ่านม่านผ้าไหมที่ถูกปิดผนึกมานับร้อยปี พิสดารและน่าสะพรึงกลัว\nข้าพเจ้าหนาวสั่นไปทั้งตัว ยังไม่ทันได้แนะนำตัว เธอรู้ชื่อข้าพเจ้าได้อย่างไร? แล้วหุ่นเชิดเหล่านี้...\nข้าพเจ้าวิ่งสุดชีวิตไปยังทางออก แต่ในขณะที่มือกำลังจะแตะลูกบิดประตู แมงมุมนับไม่ถ้วนก็พรั่งพรูออกมาจากความมืด——ดวงตาเปล่งแสงวาบ พวกมันพ่นใยแมงมุมสีเงินขาว พยายามปิดกั้นเส้นทางหนีของข้าพเจ้า ที่น่าสยดสยองยิ่งกว่าคือ ฝูงแมงมุมเหล่านั้นกลับพูดภาษามนุษย์ได้ พร่ำพูดซ้ำแล้วซ้ำเล่าว่า \"ร้องเพลงสิ นางฟ้าของข้า จงร้องเพลงให้ข้าฟัง...\"\nข้าพเจ้าฉีกดึง วิ่ง กรีดร้องสุดแรง และในที่สุดก็หนีออกมาได้จริงๆ \n...\nนับแต่นั้นมา ข้าพเจ้าหวาดกลัวสายตาจากห้องวีไอพีหมายเลขห้า จึงร้องขอให้โรงอุปรากรปิดผนึกห้องนี้\nแต่ทว่า... ทุกครั้งที่ข้าพเจ้ายืนร้องเพลงใต้แสงสปอตไลท์ ก็รู้สึกเสมอว่ามีสายเชือกเบาๆ ดึงคิ้วของข้าพเจ้าจากเบื้องบน\nหรือว่าข้าพเจ้าก็กลายเป็นหุ่นเชิดที่ถูกบงการด้วยสายเชือกไปแล้ว? ข้าพเจ้าไม่กล้าคิดต่อ\n\n——คัดจาก \"บันทึกความทรงจำของนักร้องคริสตีน\""
  },
  AwakerStory_134319_Title = {
