  AwakerStory_146395_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_146396_Content = {
    Text = "ความทรงจำแรกสุดของเธอมีแต่ความโกรธ\nไม่มีใบหน้า ไม่มีขอบเขตของรูปร่าง มีเพียงสัญชาตญาณความรุนแรงที่เดือดพล่านพลุ่งพล่านไม่สิ้นสุด เธอคือเคออสที่รวมตัวกันจากห้วงลึกของทะเลดาว คือภัยพิบัติที่ก่อตัวขึ้นในช่วงเวลาหลายพันล้านปี เธอฉีกขาด เผาไหม้ กลืนกิน ไม่ใช่เพื่อจุดประสงค์ใด แต่เพราะนั่นคือสิ่งเดียวที่เธอรู้จัก\nจนกระทั่งท่านนั้น「เทพเจ้า」ในผ้าขาวมาถึง ราวกับดาวฤกษ์ถูกผ่าออกเป็นสองซีกจากแกนกลาง เธอรู้สึกว่าพละกำลังของตนถอยร่นดั่งน้ำขึ้นน้ำลง เนื้อและเลือดและกระดูกถูกถอนรากออกจากจิตวิญญาณ เปลวไฟแห่งความโกรธถูกลอกออกจากวิญญาณอย่างโหดเหี้ยม\n\nเทพเจ้าไม่สามารถระงับความโกรธของเธอได้ จึงเลือกที่จะแยกจิตและกายของเธอออกจากกัน\nอสูรโกลาหลไม่มีอีกต่อไป ร่างกายของเธอกลายเป็นเลวีอาธาน พาพละกำลังทั้งหมดของเธอจมลงสู่ความว่างเปล่า ส่วนเธอ ซากที่เหลือเพียงจิตใจ ตื่นขึ้นในสำนึกที่ว่างเปล่า\nเปลวไฟแห่งความโกรธไม่ได้ดับลง แต่เปลี่ยนแปลงเป็นสิ่งที่ยั่งยืนกว่าและน่าเกรงขามกว่า: ความปรารถนา ความปรารถนาอันไม่สิ้นสุดต่อพละกำลัง ผลักดันให้เธอลุกขึ้นยืนอีกครั้ง\nเธอเริ่มเดินทาง เริ่มต่อสู้ เธอท่องเที่ยวไปในทะเลดาวที่รกร้าง ท้าทายผู้แข็งแกร่งทุกคนที่ขวางหน้า ชัยชนะแต่ละครั้งราวกับการเติมทรายลงในเปลือกที่ว่างเปล่า เธอค่อยๆ ขัดเกลารูปร่างจากทราย ขัดเกลาเจตจำนง ขัดเกลาโครงร่างที่เป็นของ「โลธัน: เทพวาฬเวหา」\n\nแล้ว เธอก็ได้ยินเสียงร้องของวาฬนั้น\nวาฬแห่งท้องฟ้าดาวที่แปลงร่างกายเป็นทั้งโลก สิ่งมีชีวิตมหึมาที่ผูกมัดและเป็นทาสสรรพชีวิตนับพัน สิ่งที่เธอเห็นในองค์ท่านไม่ใช่ความปรารถนาและความกลัว แต่คือความคุ้นเคย ความทรงจำของเธอเริ่มฟื้นคืน เธอรู้ว่านั่นคือพละกำลังของเธอ เธอรู้ว่าตั้งแต่ต้นจนจบ องค์ท่านเป็นของเธอ\nดังนั้น เธอจึงมาต่อหน้าองค์ท่าน\nดังนั้น เธอจึงชักดาบใส่องค์ท่าน\n\nอำนาจของวาฬยักษ์ไหลบ่าเข้าสู่ร่างกายของเธอดั่งน้ำท่วมที่เขื่อนแตก เกือบจะฉีกเธอออกเป็นชิ้นๆ แต่ตลอดเวลาเธอยังคงยืนหยัด ในทะเลดาว มีซากกระดูกของวาฬยักษ์เพิ่มขึ้นมาหนึ่งตัว\nดาวเคราะห์ที่ถูกเป็นทาสได้รับอิสรภาพคืน วิญญาณที่ตายไปด้วยความปรารถนามองขึ้น เรียกขานเธอว่าผู้กอบกู้โลก การ์เดียน ส่งมงกุฎมาวางไว้ต่อหน้าเธอ\nโลธัน: เทพวาฬเวหาไม่ตอบสนองต่อเสียงชื่นชมเหล่านั้น เธอแค่ยืนอยู่บนซากกระดูกของวาฬยักษ์ รับรู้ถึงพละกำลังทารกแรกเกิดที่เดือดพล่านอยู่ภายใน ฟังเสียงเพรียกที่ไม่เคยหายไปจากห้วงลึกของวิญญาณกลายเป็นชัดเจนอย่างที่ไม่เคยเป็นมาก่อน\nนั่นคือเสียงของวาฬแห่งท้องฟ้าดาว นั่นคือเนื้อและเลือดของเธอเองที่อัญเชิญเธอ\n\nมือของเธอสัมผัสกะโหลกของเลวีอาธาน จิตและกายที่แยกตัวออกจากกันมานับกัลป์ก็หลอมรวมกันอีกครั้ง เกราะกระดูกปกคลุมร่างกายของเธอ พละกำลังเติมเต็มร่างกายของเธอ\nอสูรโกลาหลเกิดใหม่ แต่เธอไม่ใช่ภัยพิบัติที่รู้จักแต่ความโกรธเกรี้ยวอีกต่อไป การท่องเที่ยวอันยาวนาน การต่อสู้นับไม่ถ้วน บรรดาคู่ต่อสู้ที่เธอเคยเอาชนะและที่เคยเอาชนะเธอ ได้หลอมเคออสอันบริสุทธิ์นั้นให้กลายเป็นคมดาบที่มีเจตจำนง\nเธอหลับตา เพลิดเพลินกับพละกำลังที่สมบูรณ์ซึ่งเดือดพล่านอยู่ภายใน แต่เธอก็รู้ดีว่านี่ไม่ใช่จุดสิ้นสุด\n\nอำนาจของวาฬแห่งท้องฟ้าดาว พละกำลังของเลวีอาธาน ดาวฤกษ์ที่ถูกกลืนกินเหล่านั้น... ทั้งหมดล้วนเป็นขั้นบันไดที่อยู่เบื้องหลัง เธอยกดาบกระดูกขึ้น หันหลังเดินสู่ทะเลดาวที่ยังไม่รู้จักแห่งต่อไป\nเธอปรารถนา การต่อสู้ครั้งต่อไปที่จะทำให้เธอเดือดพล่าน"
  },
  AwakerStory_146396_Title = {
    Text = "เรื่องราว·3"
