  AwakerStory_146396_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_146397_Content = {
    Text = "โลธัน: เทพวาฬเวหาไม่เคยมองย้อนกลับไปยังซากศพที่อยู่เบื้องหลัง\nคู่ต่อสู้ที่ถูกเอาชนะ ดินแดนรกร้างที่ถูกเหยียบย่ำ ดาวฤกษ์ที่ถูกกลืนกิน... เธอก้าวข้ามพวกมันทีละอย่าง มองหาจุดหมายต่อไป\n\nมีคนถามเธอว่าหลังจากไปถึงจุดสิ้นสุดของพละกำลังแล้วจะทำอะไร\nเธอไม่ตอบ เพราะคำถามนี้ไม่มีความหมายใดๆ เหมือนกับการถามว่าเปลวไฟจะไปที่ไหนหลังจากเผาไหม้หมด เปลวไฟไม่มี「หลังจาก」 การเผาไหม้เองคือทั้งหมดของการมีอยู่ของมัน\n\nเธอเดินทาง เธอต่อสู้ เธอยกดาบขึ้นครั้งแล้วครั้งเล่า ไม่เคยเพื่อพิสูจน์ ปกป้อง แก้แค้น อำนาจ หรือสิ่งน่าเบื่อหน่ายอื่นใด\nแค่เพราะ ในชั่วขณะที่ดาบปะทะกัน ในเสี้ยววินาทีที่พละกำลังปะทะกัน เธอสามารถรู้สึกได้อย่างชัดเจนที่สุดว่าตนเองยังมีชีวิตอยู่\n\nทางแห่งการแสวงหาพละกำลังไม่มีสิ้นสุด และเธอก็ยินดีที่เป็นเช่นนั้น"
  },
  AwakerStory_146397_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_146397_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_146398_Content = {
    Text = "หลังจากมาถึงมิซากะ โลธัน: เทพวาฬเวหาอยู่อย่างเงียบงันเป็นเวลาสองวัน ในยามเย็นของวันที่สาม เธอปรากฏตัวที่สนามฝึกสาธารณะพร้อมกับดาบกระดูกของเธอ\n\nร่างตื่นแห่งมิซากะมีเหตุผลที่จะภาคภูมิใจ และผู้ที่ปรากฏตัวในสนามฝึกยิ่งเป็นเช่นนั้น แต่ต่อผู้มาเยือนที่ไม่ได้รับเชิญผู้ไร้มารยาทคนนี้ พวกเขายังคงระวังภัยอย่างสูง หลังจากการพบปะสั้นๆ บนเกาะภูเขาไฟ ตำนานเกี่ยวกับโลธัน: เทพวาฬเวหาได้แพร่กระจายในหมู่ร่างตื่น พวกเขารู้ว่าตนเองกำลังจะเผชิญกับคู่ต่อสู้เช่นใด\nแต่ความเป็นจริงพิสูจน์ว่าการระวังภัยของพวกเขายังไม่เพียงพอ\n\nเมื่อร่างตื่นคนแรกที่ก้าวออกมาท้าทายถูกฟาดด้วยดาบเพียงครั้งเดียวจนกระเด็นออกนอกขอบเขตสนามฝึกและล้มทลายกำแพงหินยี่สิบเมตรออกไป สนามฝึกทั้งหมดก็ตกอยู่ในความตื่นเต้นที่ไม่เคยมีมาก่อน คนที่สอง คนที่สาม... ในยามเย็นธรรมดาของปี@3 นั้น มีร่างตื่นทั้งหมดเก้าคนที่ท้าทายโลธัน: เทพวาฬเวหาทยอยกัน\n\nตามคำบอกเล่าของฮันนา นักข่าวหนังสือพิมพ์โรงเรียนที่อยู่ในเหตุการณ์ โลธัน: เทพวาฬเวหาไม่ได้พูดสักคำเดียวตลอดกระบวนการ ราวกับประภาคารที่เงียบงันและไม่สามารถทำลายได้ ยืนหยัดอยู่ท่ามกลางการโจมตีอย่างดุเดือดดั่งคลื่นทะเลของบรรดาร่างตื่น ดาบกระดูกทั้งสองเล่มส่องแสงดั่งแสงไฟในยามพระอาทิตย์ตก เส้นโค้งที่สง่างามสิ้นสุดการโจมตีของคู่ต่อสู้แต่ละคนอย่างแม่นยำ\n\nในวันนั้น เกราะของโลธัน: เทพวาฬเวหาเสียหายเกินกว่า 80% บ่าและท้องมีบาดเจ็บรุนแรงมากสองแห่ง บนดาบกระดูกมีรอยแตกขนาดใหญ่ เกือบจะหัก แต่ด้วยราคาที่ต้องจ่ายทั้งหมดนี้ เธอกลายเป็นคนเดียวที่ยังยืนอยู่บนสนามฝึกในท้ายที่สุด\n\nเธอมองรอยดาบที่ขีดลึกบนกำแพง หลุมลึกที่แรงกระแทกมหาศาลทิ้งไว้บนพื้น และบรรดาร่างตื่นที่จ้องมองเธอด้วยสีหน้าซับซ้อน แล้วก็ยิ้มเป็นครั้งแรกนับตั้งแต่มาถึงโลกนี้\n\n「ยินดีที่ได้พบพวกคุณ พวกคุณสามารถเรียกฉันว่าโลธัน: เทพวาฬเวหา」"
  },
