  AwakerStory_147418_Content = {
    Text = "ฟาร์มที่ตั้งอยู่ในภูเขาทางตะวันตกของเมืองจินโปเตอร ตอนนี้กลายเป็นทะเลทราย ไม่มีผู้คนอาศัยอยู่แล้ว。\nวันที่ 15 มิถุนายน ปี @2 มีอุกกาบาตตกลงมาที่นี่。ไม่กี่สัปดาห์ต่อมา ระบบนิเวศในพื้นที่ที่อุกกาบาตตกลงมเริ่มมีการเปลี่ยนแปลง พืชเติบโตอย่างบ้าคลั่งและออกผลแปลกๆ สัตว์เกิดการกลายพันธุ์ ครอบครัวหนึ่งของผู้อยู่อาศัยทั้งหมดเสียสติและเสียชีวิตอย่างลึกลับ。\nนักสืบมิซากะได้เริ่มการค้นหาอย่างเข้มข้นในพื้นที่ และในที่สุดพบเงินใจที่ปล่อยสีแปลกประหลาดออกมาที่ก้นบ่อน้ำ。ตามความทรงจำของนักสืบที่เกี่ยวข้องในขณะนั้น สีของเงินใจนั้นเป็น「สีที่บริสุทธิ์ ไหลไปทั่ว และไม่เหมือนกับสีใดในสเปกตรัมที่รู้จัก」\n\n——อ้างอิงจาก《บันทึกการเก็บรักษาเงินใจของมหาวิทยาลัยมิซากะ》"
  },
  AwakerStory_147418_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_147418_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
