  AwakerStory_148398_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_148399_Content = {
    Text = "ทุกคนรู้กันดีว่าโรงเรียนมีฉายาว่าอะไร?\nหอคอยงาช้าง! \nฟังดูเข้ากันได้ดีมากกับชื่อนางฟ้า เพราะท้ายที่สุดแล้ว จะหาสวรรค์อันสมบูรณ์แบบที่ไหนได้อีก ที่มีทั้งเงิน มีเวลาว่าง และมีผู้ศรัทธาที่มีใจเปิดกว้างเต็มไปด้วยความไว้วางใจอันล้ำค่า? \nลัทธิของคาราบูพัฒนาขึ้นด้วยความรวดเร็วอย่างน่าทึ่ง สร้างสาวกจำนวนมากในระยะเวลาอันสั้น กำลังหลักเกือบทั้งหมดเป็นผู้ปลุกตื่นวัยเยาว์ พวกเขาเชื่อในนาง「แม่ทูนหัวนางฟ้า」นี้อย่างเลื่อมใส ยินดีส่งมอบขนมและของหวานตามเวลาและจำนวนที่กำหนด. น่าแปลกใจหรือไม่ก็คาดได้ คาราบูก็จะประทาน「พร」ลงมาเป็นครั้งคราว ส่วนใหญ่เกิดขึ้นในวันหยุดประเพณีของราชอาณาจักรเลโอ เช่น หิมะที่ตกลงมาอย่างเป็นไปไม่ได้ในเทศกาลเงินเย็นปี 3@1 และฝนลูกกวาดในคืนปีใหม่ที่ยังคงเป็นที่เล่าขานจนถึงทุกวันนี้. \nสำนักงานการศึกษาดูเหมือนไม่เคยถกเถียงกันเลยว่าจะหยุดยั้ง「การเผยแผ่ศาสนาในโรงเรียน」ที่ไม่ควรมีอยู่นี้หรือไม่.\n「ปล่อยให้พวกเขาเล่นเถิด เราทุกคนรู้ว่าเด็กๆ เหล่านี้เคยผ่านอะไรมา มีบางสิ่งที่ทำได้เฉพาะคนที่เป็นเด็กเหมือนกันเท่านั้น.」\n「แน่นอน อย่าให้เกินเลยไปก็พอ.」\nบุคลากรในโรงเรียนที่ไม่สะดวกเปิดเผยชื่อรายหนึ่งยิ้มแย้มและกล่าวถ้อยคำดังกล่าว ตามข่าวที่ไม่น่าเชื่อถือระบุว่า เหตุการณ์ก่อนที่จะร่วมดื่มชาแดงกับเธอนั้น เป็นครั้งเดียวในชีวิตของคาราบูที่พยายามแตะต้องกฎของโรงเรียนอย่างแท้จริง."
  },
  AwakerStory_148399_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_148399_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_148400_Content = {
    Text = "เธอเปรียบดั่งเด็กที่เข้าใจทุกสิ่ง รู้ถึงความคิดลึกซึ้งที่สุดในใจเจ้า ทำให้เจ้าอดไม่ได้ที่จะไว้วางใจและเปิดเผยตัวเอง แล้วในจังหวะที่เหมาะเจาะที่สุด เธอก็มอบ「พร」ที่เจ้าปรารถนาให้แก่เจ้า. แต่จงจำไว้ อย่าได้เกิดความสงสารในร่างกายอ่อนหวานและดวงตาน่าสงสารของเธอ มิเช่นนั้นเจ้าอาจกลายเป็นหนึ่งในวิญญาณโลภที่ถูกร่างกายขาวบริสุทธิ์นั้นกลืนกินไปแล้ว."
  },
  AwakerStory_148400_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_148400_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_148401_Content = {
    Text = "เจ้าเคยโกหกไหม? เมื่อคำโกหกแรกออกมาจากปาก มักมาพร้อมกับลิ้นที่สะดุด หัวใจที่เกือบจะกระโดดออกจากลำคอ และเหงื่อที่ฝ่ามือ แม้แต่แสงอาทิตย์อุ่นๆ ก็กลายเป็นแสงจ้าที่ทำให้วิงเวียน. แต่เมื่อโกหกซ้ำหนึ่งหมื่นครั้ง ความกลัวก็จะหายไป. คำพูดที่เปล่งออกมาจะลื่นไหล ความคิดยิ่งแจ่มใสขึ้น รอยยิ้มก็กลายเป็นธรรมชาติ. รับบทนางฟ้า รับบทแม่ทูนหัว รับบทญาติของผู้มีอำนาจ เธอเชี่ยวชาญในตัวตนนับพันนับหมื่นที่ตัวเองสร้างขึ้นมานานแล้ว คุ้นเคยกับการซ่อนตัวเองไว้เบื้องหลังคำโกหก จนกระทั่งตัวเองก็กลายเป็นส่วนหนึ่งของคำโกหก. แต่กระต่ายป่าตัวน้อยในตอนแรกนั้น ยังคงซ่อนตัวอยู่ในไร่นาเล็กๆ ที่ถูกแสงอาทิตย์ยามเย็นส่องสาดในความทรงจำ. ในคืนที่น้ำแข็งละลาย ค่อยๆ แอบโผล่หัวออกมา."
  },
  AwakerStory_148401_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_148401_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_148994_Content = {
    Text = "แม้รูปร่างยังคงเดิม แต่ผู้คนก็มองออกในทันทีถึงความแตกต่างระหว่างเขากับอัศวินตัวน้อยที่พวกเขารู้จัก.\nดวงตาที่เคยใสสะอาดไม่ได้สว่างไสวอีกต่อไป เสื้อผ้าสีขาวก็เปื้อนมัวหมอง ยิ่งไม่ต้องพูดถึงการที่เขามักจงใจรักษาระยะห่างจากทุกคน.\nแต่ไม่ต้องกลัว ใต้โคลนดำน่าสะพรึงนั้น ยังคงเป็นหัวใจที่เจ้าคุ้นเคย หัวใจที่เต้นเพื่อความซื่อสัตย์และความยุติธรรม.\nแม้จะเคยลืมเลือนไปครั้งหนึ่ง แต่ในที่สุดเขาก็หยิบคำสาบานของอัศวินเหล่านั้นกลับคืนมา.\nเขาจะยังคงต่อสู้ต่อไป —— ต่อสู้กับเสียงอีกเสียงหนึ่งในตัวเขา ต่อสู้กับทุกสิ่งที่ทำร้ายสิ่งที่เขาหวงแหน."
  },
  AwakerStory_148994_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_148994_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_149051_Content = {
    Text = "มิซากะเคยเกิดเหตุการณ์ลึกลับที่สั่นสะเทือนทั้งโรงเรียน ต่อไปนี้คือบันทึกการสัมภาษณ์ที่นักข่าวโรงเรียนฮันนาจัดทำไว้:\n「ในยามดึกสงัด มีเสียงกรอบแกรบในห้องสมุด...ฉันไม่กล้าไปดู. จนกระทั่งเช้าวันรุ่งขึ้น ฉันพบว่าหนังสือข้างในถูกจัดเรียง\nเป็นระเบียบเรียบร้อย ดีกว่าที่ฉันจัดเองด้วยซ้ำ!」 ——บรรณารักษ์ห้องสมุดโรงเรียน\n「ไม่รู้สึกหรือว่าช่วงนี้โรงเรียนสะอาดขึ้นมาก? มีผีที่ทำความสะอาดขยะตอนกลางคืนหรือเปล่า?」\n——ครูสอนวิชาปฏิบัติท่านหนึ่ง\n「ตอนออกปฏิบัติภารกิจ รู้สึกตลอดว่ามีคนตามหลัง...บางครั้งได้ยินเสียงการต่อสู้อย่างดุเดือด พอหันกลับไปดู เหลือแต่ซากสัตว์ประหลาดที่ถูกทำลายกระจัดกระจายอยู่.」——นักสืบมือใหม่ท่านหนึ่ง\nนักเรียนกล้าหาญหลายคนจึงรวมตัวกันตั้งทีมสืบสวนโดยสมัครใจ แลกการนอนหลับหนึ่งคืนกับคำตอบ.\nผู้ก่อเหตุทั้งหมดยอมรับ「ความผิด」ของตัวเอง และขอโทษอย่างจริงใจสำหรับการก่อให้เกิดความตื่นตระหนก. แต่เมื่อเผชิญกับคำขอบคุณที่ตามมา เขากลับดูเขินอายเล็กน้อย. ในคำพูดของเขาเอง 「แค่อยู่ไม่สุขเท่านั้นเอง.」\nในเรื่องนี้ ครูจิตวิทยาโรงเรียนซิลเวียได้ให้การวินิจฉัยของเธอว่า: 「ในฐานะเด็กดีที่มีจิตใจดีงาม เขามีความรู้สึกผิดต่อเรื่องในอดีตอย่างแรงกล้าเกินไป นานวันเข้าก็กลายเป็นความรู้สึกว่าตัวเองไม่คู่ควรที่ฝังรากลึก —— ความปรารถนาดีที่ตรงไปตรงมาเกินไปจากผู้อื่น กลับทำให้เขารู้สึกแย่ลงกว่าเดิมด้วยซ้ำ.」\nเหตุการณ์นี้จบลงอย่างเบาๆ แต่ตำนาน「ผีล่องหน」ก็แพร่กระจายออกไปนับแต่นั้น. ครูและนักเรียนต่างรู้กันดีโดยไม่พูดถึงตัวตนของเขา เพียงแต่ค่อยๆ ทุกคนก็รู้ว่า「ผี」คนนี้แค่ต้องการช่วยเหลือทุกคนเท่านั้น.\nดูเหมือนทุกคนต่างเข้าใจว่า สำหรับเด็กหนุ่มที่ไม่ต้องการให้ใครมองเห็นคนนี้ คำขอบคุณที่ดีที่สุด คือการปล่อยให้ความลับนี้ยังคงเป็นของเขาคนเดียวต่อไป."
  },
  AwakerStory_149051_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_149051_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_149052_Content = {
    Text = "ผู้อ่านที่รัก นี่คือคำนำท้ายเล่ม และยังเป็นหนังสือสารภาพบาปของข้าพเจ้าด้วย.\nเพื่อให้นิยายอัศวินคลาสสิกโบราณเล่มนี้สำเร็จ ข้าพเจ้าได้ใช้เงินจำนวนมากประมูลหมวกเกราะลึกลับใบนั้นมา ซึ่งว่ากันว่าไม่ได้เป็นของอาณาจักรใดที่มีประวัติศาสตร์บันทึกไว้. ดังที่เห็น ด้วยบุญของมัน แรงบันดาลใจของข้าพเจ้าไม่ขาดสาย ราวกับได้เห็นสนามรบโบราณอันกว้างใหญ่จริงๆ มีอัศวินสวมเกราะกำลังประจัญบาน. ข้าพเจ้าอาศัยภาพหลอนอันมหัศจรรย์เหล่านี้สร้างสรรค์ผลงานที่สมบูรณ์แบบที่สุดในใจข้าพเจ้า.\nแต่ข้าพเจ้าไม่เคยคิดเลยว่า ในขณะที่ของเก่าชิ้นนี้มอบแรงบันดาลใจให้ข้าพเจ้า มันกลับซ่อนปีศาจอันน่าสะพรึงกลัวไว้ด้วย.\nผู้อ่านทั้งหลาย ลองจินตนาการดูสิ มีเสียงหนึ่ง วุ่นวาย ต่อเนื่อง ไม่หยุดทั้งกลางวันกลางคืน. แล้วจินตนาการว่าแขนขาของเจ้าเริ่มไม่อยู่ในการควบคุม สติสัมปชัญญะก็ขาดหายบ่อยครั้ง —— ไม่ ไม่ใช่การขาดหาย มันเหมือนกับว่าจิตใจหลุดออกจากร่างกาย เจ้ารู้ชัดว่าตัวเองกำลังทำอะไร แต่ทำได้แค่มองดู...... แต่นั่นมันเป็นร่างกายของข้าพเจ้าชัดๆ.\nเมื่อคืนที่ผ่านมา ในขณะที่ข้าพเจ้าเพิ่งเสร็จสิ้นนิยายเล่มนี้ ข้าพเจ้าได้ยินเสียงของมันอีกครั้ง.\nจากนั้น ช่างแย่เลย ข้าพเจ้าไม่อยากนึกถึงภาพเหล่านั้นเลย ——\nข้าพเจ้าได้กระทำบาปที่ไม่อาจแก้ไขได้ หนังสือพิมพ์จะบอกเจ้าก่อนหนังสือเล่มนี้......\nมัน, กลับมาอีกแล้ว, กำลังเริ่ม ——\n(ลายมือเอียงเบี้ยว)\nไม่ไม่ไม่ไม่ไม่ไม่ไม่ไม่ ข้าพเจ้าไม่สามารถ ——\n......\n\n(ลายมือกลับมาชัดเจน)\nน่าประหลาดใจ มันหยุดแล้ว ราวกับมีบางสิ่งกดทับมันไว้ ข้าพเจ้าไม่รู้ว่านั่นคืออะไร แต่ข้าพเจ้าต้องขอบคุณการต่อสู้ของมัน.\nบางทีอาจเป็นพระเจ้ากำลังมอบโอกาสสุดท้ายให้ข้าพเจ้า ไม่ให้ข้าพเจ้าตกต่ำเป็นปีศาจอย่างสมบูรณ์.\n\nปืนของข้าพเจ้าบรรจุกระสุนเต็มแล้ว.\nขอพระเจ้าอภัยโทษให้ข้าพเจ้า.\n\n\n——คัดจากคำนำท้ายเล่มของ «อัศวินไร้เงา» ผลงานชิ้นสุดท้ายของนักเขียนคลาร์ก ซีรอส"
  },
  AwakerStory_149052_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_149052_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_149064_Content = {
    Text = "โคลนดำมืดสัญลักษณ์แห่งบาปยังคงเดือดพล่านอยู่ภายในร่างกายของเขา พยายามครอบครองร่างนี้อีกครั้ง เขาต้องยึดเส้นด้ายที่เปราะบางนั้นไว้ให้แน่น มิเช่นนั้นเขาจะพ่ายแพ้.\nและสิ่งที่เขาค้นพบใหม่เพื่อตัวเอง——สิ่งที่คู่ควรแก่การปกป้อง ได้กลายเป็นสมอเพียงหนึ่งเดียวที่ยึดเหนี่ยวสติปัญญาของเขาไว้.\nเขาไม่อาจหวนคืนสู่บ้านเกิดอีกต่อไป แต่มิซากะได้กลายเป็นปราสาทแห่งใหม่ของเขา.\nเขาไม่อาจปกป้องเจ้าหญิงได้อีกต่อไป แต่โชคชะตายังคงสร้างการพบเจอใหม่.\nในสถานที่ที่ไม่มีผู้ใดเป็นสักขีพยาน หนุ่มน้อยคุกเข่าข้างเดียว มือข้างหนึ่งวางบนหน้าอกที่เย็นชา ประกาศต่อเจ้านายที่ไม่ได้อยู่ ณ ที่นั้น.\n「ข้าจะปฏิบัติตามคำสั่งของท่านอย่างเคร่งครัด คุ้มครองท่านและโลกของท่านตลอดไป แม้จะต้องเผาผลาญชีวิต แม้จะต้องใช้จิตวิญญาณจนหมดสิ้น.」\n「......นี่คือ คำสาบานที่ข้าแบกรับขึ้นมาอีกครั้ง.」"
  },
  AwakerStory_149064_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_149064_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_149065_Content = {
    Text = "เขาก็เคยออกเดินทางในการผจญภัยของตัวเอง เหมือนดังที่เขียนไว้ในนิทานก่อนนอน.\nแต่เขาไม่ใช่อัศวินที่ขับขานความยุติธรรม และในโลกนี้ก็ไม่มีเจ้าหญิงที่รอการช่วยเหลืออีกต่อไป.\nสิ่งที่เขาสังหาร ไม่ใช่มังกรชั่วร้ายน่าสะพรึง แต่เป็นชาวบ้านผู้บริสุทธิ์ไร้อาวุธมากมายที่กรีดร้องและหลบหนี.\n「อัศวินหนุ่มสังหารนักเวทมนตร์ชั่วร้าย ทำลายกองทัพศัตรูที่ดื้อรั้น เผาป้อมปราการของสัตว์ประหลาด......\nเขากล้าหาญ เขาเข้มแข็ง ไม่เคยพ่ายแพ้. บนเส้นทางที่ไม่รู้จุดสิ้นสุดนี้ มีเพียงรอยเลือดยาวเหยียดทิ้งไว้เบื้องหลัง.」\nหากในโลกนี้มีนักร้องเร่ร่อนที่แยกแยะความฝันกับความจริงไม่ออก เขาคงจะแต่งแต้มประสบการณ์นี้ให้ดูงดงามเช่นนี้.\nแต่ตัวเอกของเรื่องนั้นตื่นตัวอยู่เสมอ ดวงตาคู่นั้นไม่เคยสะท้อนสิ่งที่เป็นเท็จ.\nเขารู้ดีว่าปลายหอกของเขาทะลุทะลวงอกของผู้เฒ่า โคลนดำกลืนกินทหารที่ยอมแพ้ไปแล้ว กระท่อมเล็กๆ ที่สวยงามของครอบครัวใดครอบครัวหนึ่งก็กลายเป็นเถ้าถ่านหลังจากที่เขาผ่านไป...... เพียงเพราะสิ่งเหล่านี้ล้วนเกี่ยวข้องกับผู้ที่ชิงสิ่งที่เขาปกป้องไป.\nเขารู้ดีว่าเขาไม่เคยอยู่ในนิทาน ความฝันอันโรแมนติกเหล่านั้นตายไปพร้อมกับบ้านเกิดเมืองนอนแล้ว บางทีเขาอาจเติบโตขึ้นในชั่วขณะนั้น หรืออาจยังคงเป็นเด็กที่ยังไม่บรรลุนิติภาวะ.\nจนกระทั่งในที่สุดเขาตื่นรู้ เมื่อเขาอุทิศชีวิตเพื่อคนแปลกหน้าที่ไม่รู้จัก เขาก็มองเห็นภาพลวงตาที่ไม่ควรมีอยู่ในน้ำตาของตัวเอง.\n「โอเกียร์ ฉันผิดหวังในตัวเจ้ามาก เจ้าเป็นอัศวินที่มีแต่ยศศักดิ์ว่างเปล่า ไม่เหมาะสมที่สุด.」\nใบหน้าของ「เจ้าหญิง」ดูเหมือนถูกคลุมด้วยผ้าคลุม แต่เสียงของเธอกลับชัดเจนผิดปกติ คมกว่าดาบและดาบทุกเล่มในโลก แทงทะลุหัวใจของเขา.\nภาพหลอนอันโหดร้ายนี้ยังคงเป็นฝันร้ายที่ทรมานเขาจนถึงทุกวันนี้ และไม่ได้จางหายไปพร้อมกับความตาย.\nเขาจะมีชีวิตอยู่ในความเสียใจที่ทำลายคำสาบานตลอดกาล."
  },
  AwakerStory_149065_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_149065_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_60980_Content = {
    Text = "เมื่อพบกันครั้งแรก ฮาเมลน์มักทำให้คุณนึกถึงเครื่องปั้นดินเผาจากตะวันออกชนิดหนึ่ง ขาวสะอาด หรูหรา โค้งงาม มีประกายอ่อนโยนเหมือนคลื่นน้ำ แต่เมื่อสัมผัสกลับเย็นชา \nใต้รูปลักษณ์ที่สง่างาม ประณีต และไม่บกพร่องนั้น คือจิตวิญญาณที่บริสุทธิ์ที่สุด หรือพูดอีกอย่างคือความว่างเปล่าที่สุด ชีวิตของเขาตลอดทั้งชีวิตมีเพียงความคิดเดียว ราวกับเป็นเครื่องจักรที่ได้รับคำสั่งเพียงหนึ่งเดียว สูญเสียปฏิกิริยาอื่น ๆ \nทุกสิ่งทุกอย่างสำหรับเขาก็เป็นเพียงการเรียงลำดับเหมือนโน้ตเพลง \nมีเพียงการแสดง การแสดง และการแสดงที่ไม่หยุดหย่อน。"
  },
  AwakerStory_60980_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_60980_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_60981_Content = {
    Text = "แฮมลินมักไม่ปรากฏตัวต่อหน้านักเรียนเสมอ แม้ว่าเขาจะเต็มใจเข้าร่วมคอนเสิร์ตที่จัดโดยมิซากะ หรือสอนบทเรียนดนตรีให้นักเรียนฝีมือด้อย แต่ส่วนใหญ่แล้วเขามักจะอยู่คนเดียวในห้องเรียนเก็บเสียง หรือในป่าที่แยกออกไปเล่นเดี่ยว หรืออาจเรียกว่าฝึกฝน\nนอกจากสถานการณ์ที่เป็นทางการแล้ว เขามักเรียกการแสดงทั้งหมดของเขาว่าการฝึกซ้อม ราวกับว่าการฝึกเหล่านั้นไม่มีจุดจบ และเสียงดนตรีที่สมบูรณ์แบบจะไม่มีวันมาถึง\n「ช่างเป็นปรมาจารย์ที่ขยันและอ่อนน้อมถ่อมตนเสมือนนักเรียนตลอดกาลจริงๆ」ผู้คนที่หลงใหลในดนตรีอันนั้นเคยกล่าวชมเชย\nแต่ แฮมลินนั้นไม่เคยรู้จักคำว่าอ่อนน้อมถ่อมตน เขามักจะเกียจคร้านเกินไปที่จะคิดคำกล่าวที่เหมาะสมและเป็นมิตร ตรงกันข้ามคือคำพูดของเขามักตรงไปตรงมาและเข้มงวดเกินไป\nในเรื่องดนตรี เขามักเป็นโรคย้ำคิดย้ำทำขั้นรุนแรง จนบทเรียนดนตรีที่ควรจะเป็นบทเรียนที่ผ่อนคลายกลับกลายเป็นชั้นเรียนที่กดดันที่สุดในใจของนักเรียน และแฮมลินเองก็ได้รับสมญานาม「ครูปีศาจ」\nหากคุณต้องการดึงดูดความสนใจจากนักดนตรีเย็นชาคนนี้ เพียงแค่เล่นโน้ตผิดไปครึ่งเสียงเท่านั้น ใบหน้าของเขาก็จะขมวดคิ้วทันทีและหันมามองคุณ\nที่จริงแล้วเขาไม่มีปัญหาใดๆ กับคนที่เขา「เคยทรมาน」เพียงแค่เขาได้นำความกระตือรือร้นและมาตรฐานอันเข้มงวดนั้นบังคับใช้กับคนอื่น แม้ว่ามันจะอ่อนโยนกว่าที่เขามีต่อตัวเองมาก\nเขาเปรียบเสมือนม้าที่มีแครอทแขวนอยู่เหนือหัว ตั้งเส้นมาตรฐานที่ไม่มีวันเข้าถึงให้ตัวเอง\nนอกเหนือจากที่เขาเคยหยุดเพื่อชื่นชมนักเต้นที่สง่างามแล้ว เขาแทบจะไม่เคยริเริ่มสื่อสารกับผู้ปลุกตื่นคนอื่นๆ แต่เมื่อเจอการขอความช่วยเหลือหรือการเริ่มต้นการสนทนาโดยผู้อื่น เขามักจะแสดงความอดทนที่เกินความคาดหมาย\nบางทีสิ่งกีดกันเขาอาจไม่ใช่ความเย็นชา แต่เป็นคลังความรู้ที่แคบเกินไปมากกว่า."
  },
  AwakerStory_60981_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_60981_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_60982_Content = {
    Text = "A. F. 31@1ปี@1เดือน@2วัน มหาเศรษฐีชื่อดังผู้หลงใหลในการสะสมเพลงถูกพนักงานบ้านพบว่าเสียชีวิตอย่างกะทันหันในห้องทำงานที่บ้านกลางดึก โดยไม่มีบาดแผลหรืออาการถูกพิษใดๆ และมุมปากของเขายังมีรอยยิ้มที่น่าขนลุกซึ่งถือว่าพอใจ\nจากการตรวจสอบของตำรวจยืนยันว่าที่เกิดเหตุเป็นห้องปิดตาย ผ่านการตรวจสอบจากนักสืบและแพทย์นิติเวชจำนวนมาก สุดท้ายได้ข้อสรุปว่าเสียชีวิตโดยอุบัติเหตุ\nแต่ทำไมมหาเศรษฐีผู้มีอายุอยู่ในช่วงกลางคนและสุขภาพแข็งแรงถึงรักการขี่ม้า จึงเสียชีวิตอย่างกระทันหันในคืนที่เงียบสงบธรรมดาเช่นนี้ ไม่มีหมอคนไหนสามารถให้เหตุผลที่สมเหตุสมผลได้ เมื่อญาติของเขาไม่พอใจและข่มขู่ ตำรวจจึงติดต่อคณะกรรมการตรวจสอบเพื่อเข้ามาดูแลการสอบสวน\nคณะกรรมการตรวจสอบที่เดิมทีต้องการเพียงแค่ยุติเรื่อง กลับบังเอิญพบร่องรอยของพลังจิตวิญญาณจากโน้ตเพลงที่กระจายอยู่บนโต๊ะทำงานของมหาเศรษฐี โน้ตเพลงที่ประหลาดนี้ถูกส่งไปยังมิซากะ จากการศึกษา พบว่าโน้ตเพลงที่ขาดหายไปนี้มาจากบทสวดส่งวิญญาณที่มีชื่อเสียง«Requiem Mass in A Minor»ซึ่งหายไปในช่วงหลัง แต่หน้าโน้ตเพลงสุดท้ายกลับยังไม่สมบูรณ์ และพบว่าในที่เกิดเหตุมีโน้ตเพลงฉบับร่างใหม่ที่มีลายมือเขียนอย่างบ้าคลั่งมากมาย ดูเหมือนว่ามหาเศรษฐีกำลังพยายามเติมเต็มหน้าสุดท้าย\nในการศึกษา พบว่าการหมกมุ่นอยู่กับโน้ตเพลงจะนำไปสู่ความบ้าคลั่งในระดับต่างๆ โน้ตเพลงนี้จึงถูกปิดผนึกและเก็บรักษาไว้อย่างรวดเร็ว จากการคาดเดาของนักวิจัยมิซากะ อาจจะเป็นพฤติกรรมการเติมเต็มนี้ที่ทำให้มหาเศรษฐีประสบกับความบ้าคลั่งและความตาย และได้ทำพิธีปลุกในรูปแบบที่ไม่ปกติ\nหลังจากนั้นเป็นเวลานาน ทางโรงเรียนก็ไม่พบเบาะแสใดๆ เกี่ยวกับการปรากฏตัวหรือการทำร้ายของผู้ปลุกตื่นที่ไม่รู้จักนี้ จึงทำให้เรื่องนี้ค่อยๆ ถูกนักสืบของมิซากะลืมเลือน\nนักวิจัยในวงการดนตรีเท่านั้นที่ยังคงคิดถึงโน้ตเพลงครึ่งฉบับที่ถูกปิดผนึกนั้นอย่างไม่ลดละ และตั้งตารอการปรากฏตัวของผู้แต่งบทสวดส่งวิญญาณในตำนาน."
  },
  AwakerStory_60982_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_60982_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_60983_Content = {
    Text = "พรสวรรค์ดูเหมือนจะเป็นเพียงความโปรดปรานที่หายากเกินไปของชะตากรรม จนเขาไม่เคยเห็นในคนรอบข้างในช่วงวัยรุ่นที่ยาวนานนั้น มันกลายเป็นภาพลางๆ ที่ใช้เป็นสัญลักษณ์ในการกระตุ้นให้เขาเดินต่อไปข้างหน้าโดยการตีตนเองเป็นพ่อ\nดังนั้นเขาจึงเชื่อมั่นว่าความขยันขันแข็งที่ยืนหยัดตลอดเวลาคือบันไดสู่ความสมบูรณ์แบบ จนกระทั่งเขายืนอยู่บนยอดเวทีโลก ความจริงนี้ยังคงไม่เปลี่ยนแปลงสำหรับเขา\nจนกระทั่งเขาได้พบกับคนที่เดินเข้ามาเคียงข้างอย่างกะทันหัน\nนั่นคืออัจฉริยะที่เจิดจรัสมาก คนที่กล่าวกันว่าของขวัญพรสวรรค์นั้นได้ถูกยึดครองโดยคนคนเดียว\nจากความอิจฉาและความริษยาในใจ เขาเกิดความสับสนและรู้สึกไร้ความช่วยเหลือขึ้นมา\nแล้วถ้าฉันไม่มีสิ่งนั้น จะสามารถไปถึงจุดหมายที่สมบูรณ์แบบได้หรือไม่?\nบันไดที่เดินผ่านมาเหมือนจะกลายเป็นเถ้าถ่านในทันที ขณะที่ประตูที่อยู่เหนือศีรษะยังคงอยู่ไกลออกไป\nเขามักจะเดินวนเวียนอยู่ข้างนอกฝูงชนที่ล้อมรอบคนคนนั้น ราวกับว่าเขาแสร้งทำเป็นสูงส่งอยู่ตามลำพัง\nแต่ทุกครั้งที่เขามองไปในทิศทางนั้น ใจของเขาก็ยังคงซ้อมพูดทักทายอยู่\nแมลงวันธรรมดาๆ ยังคงวนเวียนอยู่รอบๆ คนคนนั้น สร้างเสียงกระซิบที่เต็มไปด้วยความอาฆาต\nเขาเป็นคนที่ไม่เก่งกาจเกินไป จนถึงกับเงียบขรึมมานาน ไม่มีทางแก้ตัว\nถ้างั้นใช้ดนตรีเถอะ ดนตรีคือภาษาที่สมบูรณ์แบบที่สุด และคนคนนั้นจะต้องเข้าใจ\nจนกระทั่งชะตากรรมได้เก็บรวบรวมทุกสิ่งที่มอบให้พร้อมดอกเบี้ยในทันที\nอัจฉริยะจากไปเร็วเกินไป คนธรรมดาอยู่ยืด\nคนเหล่านั้นที่เคยยุยงให้แตกแยกในอดีต เขายังไม่เคยสั่นคลอนแม้แต่น้อย\nในขณะนี้มองดูโน้ตเพลงที่ยังไม่ได้มอบให้บนโต๊ะอย่างไม่พอใจ เขากลับน้ำตาไหลเพราะความเกลียดชังตัวเอง\nเขาเข้าใจทันทีว่าก่อนจะไปถึงสวรรค์ที่สมบูรณ์แบบ ต้องใช้ทุกวิถีทางในโลกมนุษย์\nโชคดีที่เมื่อเปรียบเทียบกับคนธรรมดา เขามีสติปัญญาที่เพียงพอ\nท้ายที่สุดในสายตาของเขา ทุกอย่างก็เป็นเพียงการจัดเรียงและคำนวณเหมือนโน้ตเพลง."
  },
  AwakerStory_60983_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_60983_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
