  AwakerStory_60984_Content = {
    Text = "ชีวิตของเขาชินกับความซ้ำซากน่าเบื่อ ความโดดเดี่ยวกลายเป็นสภาวะปกติในชีวิตของเขาแล้ว\nความไม่ยอมแพ้ ความสับสน และความแค้นได้ถูกย่อยสลายในเวลาที่ยาวนาน ตอนนี้เขาได้รวมเป็นหนึ่งกับดนตรี นั่นคือการก้าวข้ามขีดจำกัดของความรักที่เรียกว่า ไม่สามารถขัดขืนได้ ไม่มีทางหลบหนี\nสิ่งที่เขามีทั้งหมด ก็เหลือเพียงแค่ดนตรี\nเดินต่อไปข้างหน้า อย่าหันกลับมามองบันไดเก้าร้อยเก้าสิบขั้น\nท้ายที่สุดเขาได้สัมผัสถึงเสียงเพลงที่สูงสุดนั้น และขลุ่ยที่ถูกกำหนดไว้แล้ว\nโปรดยอมรับดนตรีที่หลั่งไหลนี้ ให้มันชุ่มชื่นจิตวิญญาณและความฝันของคุณ\nเหมือนกับที่เขาได้ทำให้จิตวิญญาณของเขาเป็นเครื่องดนตรี เพื่อที่จะได้สะท้อนเสียงร่วมกับคุณ。"
  },
  AwakerStory_60984_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_60984_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_66033_Content = {
    Text = "ทาวีปรากฏตัวในมิซากะเพียงสามครั้งเท่านั้น \n ครั้งแรก เธอได้จุดประกายไฟแห่ง 「ปัญญา」 เธอได้เปิดช่องทางสู่ความฝัน และสอนปัญญาที่หายากให้กับผู้ก่อตั้งมิซากะที่ค้นหาความรู้ในความมืดมิด เธอได้มอบ 「คลังความรู้」 แรกเริ่มของมิซากะ และความรู้พร้อมเบาะแสเกี่ยวกับการย่อยสลาย \n ครั้งที่สอง เธอได้นำคำทำนายเกี่ยวกับ 「ตัวแปร」 มาสู่โลก น้ำในสระดำเดือดพล่าน ต้อนรับการมาถึงของผู้ที่ 「เปลี่ยนแปลง」 โลก \n ครั้งที่สาม เธอได้ส่งสัญญาณเกี่ยวกับ 「ปลายทาง」 เสียงร้องของเธอและเสียงสะอื้นของเธอดังก้องไปทั่วโลกา แต่ไม่สามารถหยุดยั้งเคออสและการล่มสลายที่หลีกเลี่ยงไม่ได้。"
  },
  AwakerStory_66033_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_66033_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_66034_Content = {
    Text = "คาดาสไม่ได้เป็นความฝันเดียวที่เธอพยายามปกป้อง\nเธอได้เห็นการเกิดและการล่มสลายของดาวหลายดวงและกาแล็กซีหลายแห่ง ประวัติศาสตร์ในอดีตและอนาคตได้สะสมเป็นความรู้ รวมอยู่ในประตูสูงสุดที่อยู่เบื้องหลังเธอ เธอมองลงไปยังภาพเหล่านั้นด้วยสายตาที่เต็มไปด้วยความเห็นอกเห็นใจ ซึ่งกลายเป็นการมองผ่านในความฝัน และสูญหายไปในความมืดของห้วงลึกอันไม่มีที่สิ้นสุด\nเธอเคยเหยียบยืนอยู่บนดินแดนแห่งหนึ่ง แต่ในขณะที่เธอหันกลับไปในชั่วพริบตา ทุกสิ่งที่เธอเคารพรักก็พังทลายลงภายใต้ลมหายใจของ「ความประสงค์สูงสุด」\nหลังจากการซ้ำแล้วซ้ำอีก เธอในที่สุดก็รู้สึกถึงความจริงที่โหดร้าย ว่าการมีอยู่ของเธอเองคือการเริ่มต้นของฝันร้าย การมีอยู่ที่ใหญ่โตเกินไปของเธอเพียงพอที่จะดึงดูดสายตาของ「ความประสงค์สูงสุด」 การแทรกแซงของเธอจะนำมาซึ่งชะตากรรมที่เลวร้ายยิ่งขึ้นสำหรับโลกที่เธอใส่ใจ\nดังนั้นเธอจึงถอยหลัง เธอจมอยู่ในความเงียบสงบ\nจนกระทั่งเธอได้เห็นความเป็นไปได้ของตัวแปรจาก「พระองค์」ในเศษสติของอวกาศที่ไม่มีที่สิ้นสุด……"
  },
  AwakerStory_66034_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_66034_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_66035_Content = {
    Text = "ในห้วงความฝันลึกลับครั้งแรกที่ฉันได้พบกับเงาร่างของเธอ \n ในพื้นที่ที่ถูกปกคลุมด้วยหมอกหนา อันไม่มีที่สิ้นสุดและไม่มีวันจบสิ้น เธอเฝ้ารักษาประตูใหญ่ที่เชื่อมต่อกับจักรวาลอันกว้างใหญ่และยิ่งใหญ่ที่ไม่เสื่อมคลาย หลังรอยแตกลึกของประตูนั้น แสงลึกลับประหลาดกระพริบเต้นรำ ราวกับว่ามันกำลังส่งสัญญาณข้อมูลบางอย่างที่ยังไม่ถูกตีความ ในช่วงที่จับสัญญาณได้ ฉันรู้สึกเหมือนสูญเสียร่างกายของตัวเอง ฉันลอยอยู่ในระหว่างดวงดาวอย่างมึนงง ถูกปกคลุมด้วยความมืดอันน่าอัศจรรย์ ฉันรู้สึกตื่นตระหนกและตกใจ ความฝันสั่นสะเทือน ประตูที่หนักหน่วงค่อยๆ เปิดออกอย่างไม่สามารถต้านทานได้ ลูกกลมมากมายราวกับดวงดาวนับพันส่องแสงอยู่หลังประตู ฉากอันลึกซึ้งและน่ามองไม่สามารถเข้าใจได้ทำให้ฉันรู้สึกมึนงง... และผู้เฝ้าประตู — ทาวี เพียงแค่จ้องมองฉันอย่างนิรันดร์และเงียบงัน \n — วอร์ด ฟิลลิปส์《บันทึกกุญแจเงิน》"
  },
  AwakerStory_66035_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_66035_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_66036_Content = {
    Text = "ในฐานะผู้ดำเนินการของมวลสารแห่งปัญญา ผู้รักษาประตู ทาวีไม่เคยขาดความปรารถนาในการค้นหาตนเอง。\nเธอปรารถนาที่จะเดินบนโลกเช่นเดียวกับผู้ที่เธอเฝ้ารักษา เป็นพยานต่อการเปลี่ยนแปลงของอารยธรรมและความเปลี่ยนแปลงของประวัติศาสตร์ และรวบรวมสิ่งที่มองเห็นเข้าไปในคลังที่เรียกว่า「ความรู้ทุกอย่าง」 แต่การมีอยู่ของเธอไม่อนุญาตให้เธอออกจากหน้าที่ ดังนั้นในใจลึกๆ ของเธอ อาจจะมีเพียงความอิจฉาในตัวสาวน้อยที่แบกรับความตั้งใจหนึ่งในตัวเธอ..."
  },
  AwakerStory_66036_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_66036_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_66037_Content = {
    Text = "ทาวีไม่ได้อยู่ในโลกปัจจุบัน。\nการมีอยู่ของเธอจะนำมาซึ่งการจ้องมองของ「ความประสงค์สูงสุด」 ดังนั้นเธอจึงไม่สามารถมีอยู่ได้ ไม่สามารถมีอยู่。ปัญญาและความเงียบ คือทั้งหมดที่เธอสามารถมอบให้กับผู้ที่ค้นหาความรู้เหล่านี้อย่างไม่รู้จักเหน็ดเหนื่อย。\nในความรอคอยที่วันแล้ววันเล่า เธอได้มอบปัญญา ความกล้า และพรอันเงียบงันของเธอให้กับชะตากรรมของมนุษย์。"
  },
  AwakerStory_66037_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_66037_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_76412_Content = {
    Text = "ฉันไม่เชื่อว่ารอเบิร์ตจะฆ่าตัวตายด้วยปืน ใช่ ฉันไม่เชื่อ\n\nเขาเคยได้รับเหรียญกล้าหาญ เคยไขคดีฆาตกรรมที่ยากลำบากหลายคดี เป็นเจ้าหน้าที่ผู้มีจิตใจแน่วแน่ และสิ่งสำคัญที่สุดคือเขากำลังจะเข้าพิธีแต่งงานเร็วๆ นี้ หญิงสาวและเขารักกันและกัน ดังนั้นต้องมีคำสมคบคิด! มีคนฆ่าเขาและสร้างสถานการณ์ให้ดูเหมือนฆ่าตัวตาย!\n\nไม่ว่าใครจะเป็นฆาตกร ฉันจะตามหาตัวเขาและทำให้เขาจ่ายค่าเสียหาย นี้คือสิ่งที่ฉันต้องทำในฐานะน้องชายและเจ้าหน้าที่ \n\n……\n\nไม่มีร่องรอยในที่เกิดเหตุเลย ดังนั้นฉันต้องกลับไปที่บ้านเกิด ซึ่งเป็นที่ที่รอเบิร์ตไปที่นั่นก่อนที่จะเกิดเหตุนั้นครั้งสุดท้าย หลังจากการสืบสวนหลายทาง ฉันรู้ว่าเขาเข้าไปในภูเขาลึก\n\nเกี่ยวกับเหตุผลที่เขาเข้าไป ฉันเดาว่าเนื่องมาจากประเพณีท้องถิ่น: ลูกคนแรกในแต่ละครอบครัวจะถูกพ่อแม่พาเข้าไปในภูเขาเมื่อถึงวันสำคัญในชีวิต\n\nเพราะพ่อแม่ของเราได้ย้ายออกจากที่นั่นตั้งแต่เรายังเด็ก รอเบิร์ตจึงไม่ได้ปฏิบัติตามประเพณีนั้น ฉันคิดว่าความรับผิดชอบของการกำลังจะสร้างครอบครัวได้ปลุกให้เขาปฏิบัติตามประเพณีนี้\n\nไม่ว่าอย่างไรก็ตาม ฉันต้องไปที่ภูเขาลึกนั้น เมื่อเขียนข้อความเหล่านี้เสร็จ ฉันจะออกเดินทางทันที\n\n……\n\nในภูเขามีสิ่งปลูกสร้างที่ใหญ่โต ฉันไม่รู้ว่ามันสร้างมาตั้งแต่เมื่อไร และฉันไม่สามารถบอกได้ ฉันรู้แค่เพียงว่าที่นี่มีพิธีกรรมป่าเถื่อนดำเนินอยู่ตลอดเวลา ซากศพที่กระจัดกระจายและดักแด้แมลงเหล่านั้น... อ๊วก ฉันไม่สามารถเขียนต่อได้อีกแล้ว\n\n……\n\nดักแด้เหล่านี้...ไม่ ไม่ นั่นไม่ใช่ปู่ย่าของฉัน ไม่ใช่บรรพบุรุษของฉัน ฉันไม่ได้มีสายเลือดของสัตว์ประหลาด! อ๊าา——\n\n……\n\n...พวกสัตว์ประหลาดที่กำลังกระทำพิธีกรรมพบตัวฉันแล้ว พวกมันต้องการเปลี่ยนฉันให้กลายเป็นสัตว์ประหลาดด้วย!\n\n……\n\nหากใครพบสมุดบันทึกนี้ ฆ่าฉันเสียทันที...@2\n\n……\n\nสรรเสริญผู้ยิ่งใหญ่ @2 ซู๊ด@2...สรรเสริญความไร้สติแสนบอดบื้อ @4...ซู๊ดซู๊ดซู๊ด...@1ซู๊ด...\n\n—ตัดตอนมาจากสมุดบันทึกของเจ้าหน้าที่เกี่ยวข้องผู้เสียชีวิต@3 มีการตัดบทความบางส่วน"
  },
  AwakerStory_76412_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_76412_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_76413_Content = {
    Text = "「ขอบคุณค่ะ คลีเมนไทน์ ฉันรู้สึกดีขึ้นมาก คุณคือคนที่เข้าใจฉันที่สุดในโลกนี้」\n\nเมื่อออกจากห้องปรึกษาจิตใจของคลีเมนไทน์ ผู้พิทักษ์มักจะได้ยินเสียงแบบนี้เสมอ ไม่ว่าวิธีการของผู้ป่วยและผู้ปลุกตื่นจะเป็นอย่างไรเมื่อพวกเขาเข้ามา แต่เมื่อออกไปแล้วพวกเขาจะเดินอย่างกระฉับกระเฉงและยิ้มแย้ม\n\nแม้แต่ครั้งหนึ่งที่เดินผ่านมา ผู้พิทักษ์เห็นคลีเมนไทน์กำลังให้คำปรึกษาจิตใจกับแมวจรจัดที่หลงเข้ามาในห้อง\n\nผลลัพธ์ก็เห็นได้ชัดเจน ทุกคนที่เคยเข้ารับการปรึกษาจิตใจต่างก็พูดถึงคลีเมนไทน์อย่างไม่หยุดปาก ซึ่งทำให้ความมีอิทธิพลของคลีเมนไทน์แพร่กระจายอย่างรวดเร็ว ในขณะเดียวกันก็สร้างปัญหา\n\n「สวัสดีตอนเที่ยงค่ะ ผู้พิทักษ์」\n\nคลีเมนไทน์ยิ้มให้คุณเมื่อเธอปรากฏตัวบนเส้นทางที่คุณต้องผ่าน และคุณไม่ได้รู้สึกแปลกใจเลย เพราะเครื่องสื่อสารของเธอที่ดังขึ้นตลอดเวลานั้นได้บอกทุกอย่างแล้ว ผู้ป่วยที่ไว้วางใจเธออย่างมากได้กลายเป็นหูตาของเธออย่างเงียบ ๆ ช่วยเธอในการบรรลุเป้าหมายทีละอย่าง\n\n「ฉันคิดว่า ถึงแม้ว่าคุณอยากจะเป็นนายกเทศมนตรีของเมืองนี้ ผู้ป่วยที่เคยปรึกษาก็จะช่วยคุณอย่างไม่มีเงื่อนไข」\n\nเมื่อเผชิญหน้ากับการล้อเลียนของผู้พิทักษ์ คลีเมนไทน์ยิ้มอย่างไม่ใส่ใจ\n\n「ฉันไม่สนใจเรื่องพวกนี้」\n\nใช่แล้ว คลีเมนไทน์ไม่สนใจเรื่องนี้ และโชคดีที่เธอไม่สนใจ\n\nมิฉะนั้น ความลับที่มืดมิดที่ถูกเปิดเผยในระหว่างการปรึกษาจิตใจก็เพียงพอที่จะทำให้เมืองนี้วุ่นวาย\n\n「ตอนนี้ ฉันแค่อยากจะสำรวจความลับในใจลึก ๆ ของคุณ ผู้พิทักษ์」\n"
  },
  AwakerStory_76413_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_76413_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_76414_Content = {
    Text = "ในตอนแรก แค่ความเจ็บปวดเล็กน้อยก็สามารถทำให้เธอพึงพอใจได้\n\nต่อมา ความโหยหาความหวาน ทำให้เธอใส่ความมุ่งร้ายลงไปในจิตวิทยาที่เธอชักนำมากขึ้นเรื่อยๆ\n\nความมุ่งร้ายนั้นเปรียบได้กับแม่น้ำที่สะสมและไหลทะลักออกมา ท่วมเกาะแห่งจิตใจทีละเกาะ\n\nอย่างไรก็ตาม มันยังไม่เพียงพอ ห่างไกลจากคำว่าพอใจ\n\nแค่ความฝันนิรันดร์นั้นตื่นขึ้นมาเท่านั้น ทั้งโลกถึงจะกลายเป็นทะเลแห่งความเจ็บปวด นำมาซึ่งความสุขที่เหนือชั้น\n\nด้วยเหตุนี้ เธอจึงตื่นเต้น เธอสวดภาวนา และเธอรอคอย\n\nเมื่อทุกสิ่งกลายเป็นความวุ่นวาย เธอจะก้มศีรษะลงต่ำ ดื่มด่ำกับความเศร้าที่สุดของโลกแห่งนี้ด้วยความยินดี\n\nแม้ว่าทะเลแห่งความเจ็บปวดนี้จะทำให้เธอจมน้ำตายก็ตาม\n"
  },
  AwakerStory_76414_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_76414_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_76415_Content = {
    Text = "ทุกคนมีหน้ากากบุคลิกที่แตกต่างกัน และเธอเลือกหน้ากากที่สามารถทำให้จิตใจคนชาระงับได้มากที่สุด—\n\nเธอยิ้มอย่างอ่อนโยน พูดด้วยรอยยิ้ม ทุกอารมณ์และทุกคำพูดของเธอล้วนรู้สึกสบาย ทำให้ผู้ป่วยที่มาขอรับคำปรึกษาทางจิตใจรู้สึกจากใจว่าตนได้พบกับเพื่อนรู้ใจและผู้ชี้นำในชีวิตนี้แล้ว.\nเพียงเท่านี้ก็เพียงพอ.\n\nผีเสื้อที่ถูกกำหนดให้ล่มสลายไม่จำเป็นต้องรู้ผลลัพธ์ เพียงแค่ต้องเดินตามการชี้นำของเธอไป.$n#\n\nในความรอดที่ดูเหมือนอบอุ่นนั้น เปลวไฟเผาไหม้ร่างกาย ไม่สามารถหวนกลับได้อีกต่อไป.\n"
  },
  AwakerStory_76415_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_76415_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_76416_Content = {
    Text = "ในความเป็นจริง คลีเมนไทน์ที่แท้จริงได้ตายไปตั้งแต่ช่วงเวลาที่ถูกวิญญาณอันยิ่งใหญ่ที่สูญสลายเข้าครอบงำ.\n\nจากแท่นบูชาที่เต็มไปด้วยซากเลือดและเนื้อที่แตกสลาย ได้เกิดขึ้นมาจากเปลือกไข่ เป็นผู้ที่มีสาระสำคัญอันยิ่งใหญ่ ซึ่งมีคุณค่ามากกว่าชีวิตมนุษย์.\n\nชีวิตใหม่ ความทรงจำเก่า ร่างกายที่เกิดจากดาวเคราะห์นี้ วิญญาณที่เกิดขึ้นจากความลึกของจักรวาล.\n\nการมีอยู่ที่เต็มไปด้วยความขัดแย้งเช่นนี้ทำให้คลีเมนไทน์รู้สึกสับสน แต่ไม่นาน ความหิวจากวิญญาณทำให้เธอไม่สามารถคิดได้.\n\nอาหารของมนุษย์นั้นช่างน่าเบื่อหน่าย มีเพียงความทรงจำที่เจ็บปวดเท่านั้นที่พอจะรับประทานได้ และยิ่งความทรงจำนั้นเต็มไปด้วยความทรมานและความสิ้นหวัง มันก็ยิ่งหวานและอร่อย.\n\nในขณะนั้น เธอ finally เข้าใจวิธีการมีชีวิตอยู่ของเธอ.\n\n「เล่ามาหาฉันเถอะ ไม่ว่าจะเป็นความเจ็บปวดหรือความสิ้นหวัง แสดงให้ฉันเห็นทั้งหมด」.\n\nเธอนั่งอยู่หลังโต๊ะทำงาน มองไปที่ผู้ป่วยที่มาปรึกษาด้วยความมุ่งร้าย แต่สีหน้าของเธอกลับเต็มไปด้วยความอ่อนโยน จนทำให้ใครก็ตามสามารถวางใจได้.\n\nนั่นคือการปลอมตัวและหน้ากากของแมลงขณะล่าเหยื่อ.\n"
  },
  AwakerStory_76416_Title = {
    Text = "เรื่องราว·3"
