  AwakerStory_81335_Content = {
    Text = "หากเกิดในครอบครัวธรรมดา คาสโตรอาจเติบโตเป็นเด็กหนุ่มที่พูดไม่เก่ง แต่มีความอบอุ่นและมั่นคงเหมือนต้นไม้ แต่ตอนนี้ เขาคือผู้ที่ยังคงร่างกายและจิตวิญญาณที่สมบูรณ์ในบรรดาคู่แฝด เขานิ่งเงียบเหมือนหิน รอคอยที่จะฝังประกายไฟที่เคยมีร่วมกันในวัยเยาว์ไว้ในใจ ไม่เคยยอมแพ้ ไม่เคยเปลี่ยนแปลง。\nปีกที่เติบโตเต็มที่และสามารถพัดพาพายุได้ถูกเก็บรวบรวมและจำศีล นกตัวหนึ่งรอคอยเงียบๆ เพื่อให้ประตูกรงเปิดออก และอีกครั้งจะได้โบยบินในท้องฟ้า。"
  },
  AwakerStory_81335_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_81335_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_81336_Content = {
    Text = "ขณะที่ฉันกำลังปฏิบัติภารกิจอยู่บนที่ราบสูงที่ห่างไกลจากลอนดีเนี่ยนมากมาย ซึ่งเป็นที่ที่ไม่ค่อยมีคนรู้จักเพราะความแห้งแล้ง ฉันบังเอิญพบเรื่องราวที่น่าตกใจในหมู่บ้านที่มีผู้อยู่อาศัยเหลืออยู่เพียงไม่กี่คน \nในคืนที่มอนสเตอร์ปรากฏตัว ท้องฟ้าดูเหมือนจะถูกบดบังด้วยเงาแปลกประหลาดบางอย่าง หมอกลอยอยู่บนพื้นดิน ขณะที่ในท้องฟ้าลึกๆ มีสีเขียวมรกตที่หม่นหมอง ปรากฏว่ามันไม่ใช่ปรากฏการณ์ทางธรรมชาติธรรมดา แต่เป็นเงาของชีวิตที่มีชีวิตและหายใจอยู่ \nในภูเขาที่รกร้างซึ่งมีต้นไม้สูงตระหง่านอยู่ลึกลงไป เสียงคำรามและเสียงตะโกนที่ไม่เป็นของสิ่งมีชีวิตใดๆ ดังขึ้น มันสามารถกระตุ้นความกลัวที่ลึกที่สุดในสัญชาตญาณของผู้คน \nเงาขนาดใหญ่พุ่งผ่านไปอย่างรวดเร็ว ทั้งภูเขาสั่นสะเทือนตามเงาที่บดบังท้องฟ้า และกิ่งก้านใบไม้ของต้นไม้ทั้งหมดก็สั่นสะเทือนตามไปด้วย เสียงกระซิบที่เป็นระเบียบ \n「ฉันเห็นมันแล้ว! หนวดที่ยาวและหนาแน่น ดวงตาที่เปล่งประกายสีเขียว นั่นแหละคือแหล่งกำเนิดของเงาที่น่ากลัวในท้องฟ้า มันพบฉัน และจ้องมองฉันอย่างแน่นหนา! ฉันคิดว่าชีวิตของฉันจะสิ้นสุดลงในขณะนั้น แต่บางทีอาจเพราะมันเพิ่งกินอาหารไป มันจึงเมตตาหันหลังกลับก่อนที่ฉันจะหมดสติจากการขาดอากาศ」 \nนี่คือสัมภาษณ์เดียวที่มีต่อผู้เห็นเหตุการณ์อย่างเป็นทางการ ชาวบ้านที่ยังตกอยู่ในฝันร้ายไม่ยอมจำรายละเอียดเพิ่มเติม แต่จากสัญญาณที่มีอยู่ มอนสเตอร์สีเขียวเข้มขนาดใหญ่นี้ นอกจากจะทำลายป่าไม้บางส่วนราวกับพายุที่พัดผ่าน ทิ้งซากสัตว์ร้ายที่มีเลือดหลงเหลืออยู่ไม่กี่ตัว มันก็ไม่ได้แสดงความก้าวร้าวมากไปกว่านั้น ดูเหมือนว่ามันจะเป็นเพียงสัตว์ร้ายที่กำลังหาอาหารอย่างปกติ \nบางทีการเข้ามาใกล้หมู่บ้านของมันอาจเป็นเพียงความอยากรู้อยากเห็น \n\nแต่เมื่อเผชิญกับความน่ากลัวที่ไม่รู้จัก เราจำเป็นต้องตั้งสมมติฐานที่เลวร้ายที่สุด ฉันจะดำเนินการสำรวจในที่ราบสูง @3 เป็นเวลา 15 วัน หากมีสัญญาณอันตรายที่น่าสังเกตเพิ่มเติม ฉันจะรายงานเพิ่มเติมในบันทึกภารกิจ \n\n——《บันทึกการสำรวจนอกเขตมิซากะ ปี @2》"
  },
  AwakerStory_81336_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_81336_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_81337_Content = {
    Text = "การแสวงหาเสรีภาพ การหลบหนีจากศาสนจักรมีราคาที่ต้องจ่ายอะไรบ้าง? ฝาแฝดคาดการณ์ถึงการลงโทษที่น่าสะพรึงกลัว บางครั้งอาจคาดการณ์ถึงการสูญเสียชีวิตของพวกเขาเอง แต่สิ่งที่พวกเขาไม่คาดคิดเลยคือ การทรมานที่เจ็บปวดที่สุดไม่ใช่การทรมานทางร่างกาย แต่เป็นการลอกล้างจิตวิญญาณออกไป \n\nคาสเตอร์จ้องมองโพลลักซ์ด้วยดวงตาที่เต็มไปด้วยความเศร้าโศก เมื่อปีกที่โพลลักซ์ถือว่าสง่างามและเป็นสิ่งล้ำค่ากำลังถูกดึงออกไปต่อหน้าต่อตา เขาขบกัดริมฝีปากของเขาจนเลือดซิบด้วยความเจ็บปวดและเดือดดาล รอคอยอย่างบ้าคลั่งและรู้สึกผิด หวังว่าความเจ็บปวดเดียวกันจะมาถึงตัวเขาแทนโพลลักซ์ \n\nแต่อูเรียตต์เพียงแค่โบกมือ คาสเตอร์ซึ่งบาดเจ็บอย่างหนักถูกลากลงไปเหมือนถุงผ้าขาด และถูกโยนลงในบ่อน้ำที่เต็มไปด้วยของเหลวหมักเก่า ที่รู้จักกันในนาม 「การบำบัดบาป」 \n\nน้ำยาเหนียวดำเหมือนน้ำมันลงตัวในทุกแผลของคาสเตอร์ ซึมเข้าไปทุกส่วน และคลุมไปบนขนปีกทั้งหมด ทำให้เขาหายใจยากขึ้นเรื่อยๆ \n\nในขณะที่แผลกำลังฟื้นตัวและเสียหายใหม่อย่างต่อเนื่อง จินตนาการของคาสเตอร์เต็มไปด้วยภาพปีกที่ถูกดึงออกไป เขานั่งอยู่ในกรงแคบด้วยความร้อนรนและขบเขี้ยวเคี้ยวฟัน อยากรับความทรมานแทนเขาเอง เขาอยากให้วันนั้นเขาเองเป็นคนที่สูญเสียปีกไป และในภายหลังเขาได้ให้คำมั่นว่าเขาจะใช้ปีกนี้เพื่อพาโพลลักซ์บินสู่อิสรภาพอีกครั้ง \n\nคาสเตอร์ทนอยู่ในน้ำนี้ทุกวันเหมือนในนรก เวลาผ่านไปอย่างลึกลับและยาวนาน เหมือนผ่านไปยี่สิบปี จนถึงวันที่เขาแทบจะตาย เมื่อเขาคลานออกมาจากห้วงนรกมืดแด็นอย่างสิ้นหวัง สิ่งที่เขาพบกับสายตาของเขาคือสายตาเยือกเย็นและไม่ใส่ใจ \n\n「เก็บสายตาน่าเกลียดของคุณให้มากกว่านี้ และคำแนะนำหนึ่งคำ คาสเตอร์ คุณกับฉันเพียงรับใช้บุตรศักดิ์สิทธิ์ผู้ทรงถือคบเพียงเท่านั้น เวลาที่เบื้องหลังไม่มีอะไรให้ทำ ไม่ควรสนิทสนมมากไป มันเพียงแค่สร้างความเบื่อน่าเกลียด」 \n\nคาสเตอร์ไม่รู้ว่าเหตุใดโพลลักซ์จึงลืมเขาไปหมด แต่ในที่สุดเขาเข้าใจถึงความหมายของสายตาลึกซึ้งที่อูเรียตต์แสดงให้เขาเห็นเมื่อออกจากบ่อแห่งบาป เพียงเพราะเธอได้จูงปลอกที่คุมเขาไว้อย่างแน่นอนและรู้สึกมั่นคง 。"
  },
