  AwakerStory_81337_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_81338_Content = {
    Text = "ฝาแฝดเกิดมาพร้อมกับความว่างเปล่านอกจากกันและกัน และคาสโทร์ยังคงลิ้มรสรสชาติของการสูญเสียไม่รู้จบ\nถูกทำร้าย ถูกลืมเลือน ถูกทรยศ หัวใจที่เงียบสงบนี้ไม่ได้ทำด้วยหิน แต่เขายังคงลุกขึ้นทีละก้าว\n「ไม่เป็นไร ฉันจะยืนหยัดแทนส่วนของนายด้วย」 คาสโทร์จ้องมองน้องชายที่มีสภาพแตกสลาย เชื่อมั่นอย่างไร้ทิศทาง\nหัวใจของเขากำมือแน่นกับเปลวไฟอ่อนแอ และผ่านพ้นลมพายุอันเย็นยะเยือกที่เหมือนใบมีด\nสักวันหนึ่ง เขาจะปีนขึ้นไปถึงยอดเขาแห่งความอิสระ เขาจะแผ่ปีกสัมผัสม่านฟ้าต่ำที่โน้มลงมา\nเขาเชื่อว่า ณ จุดสิ้นสุดเส้นทางมีหนาม จะต้องมีแสงสว่างแห่งสัญญาที่น้องชายเคยบอกไว้ในวัยเด็ก。"
  },
  AwakerStory_81338_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_81338_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_81615_Content = {
    Text = "เธอคือธงที่โบกสะบัดสูงในขณะที่เรือกำลังแล่น เพื่อชี้นำทิศทาง และยังเป็นเพลงคร่ำครวญที่ยืนหยัดปฏิบัติหน้าที่จนถึงวินาทีสุดท้ายเมื่อเรือจมลง。\n\nความรับผิดชอบ ความมุ่งมั่น ชีวิตของเธอทั้งหมดผูกติดกับเรือ มิฉะนั้นไม่มีอื่น。\n\nเพราะการชี้นำทิศทางคือความหมายของการมีอยู่ของเธอ。\n"
  },
  AwakerStory_81615_Title = {
    Text = "ข้อมูลพื้นฐาน"
  },
  AwakerStory_81615_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_81616_Content = {
    Text = "ก่อนที่เธอจะเรียนรู้การพูด คลอเปอร์ซานต์ที่เติบโตขึ้นบนเรือสำราญก็สามารถเลียนเสียงคลื่นซัดเข้ามาในเรือได้แล้ว \n\n บางครั้งเสียงนั้นคือ 「ฮือฮา」 บางครั้งเสียงนั้นคือ 「โครมคราม」 เหมือนกับเสียงกล่อมให้หลับที่ธรรมชาติขับร้องให้เธอฟัง ทำให้เธอรู้สึกสบายใจ รู้สึกอบอุ่น และรู้สึกถึงความปรารถนา \n\n เธอมักจะเข้าใจ 「อารมณ์」 ของทะเลได้เร็วกว่าคนอื่นเสมอ และมักจะอ่าน 「ภาษา」 ของเมฆได้เร็วกว่าคนอื่นเสมอ ทุกคนบอกว่าเธอเป็น 「ผู้ชี้นำ」 ที่เกิดมาเพื่อสิ่งนี้ \n\n จริง ๆ แล้วเมื่อได้ยินคำนี้ครั้งแรก คลอเปอร์ซานต์ในวัยเด็กยังไม่สามารถเข้าใจได้ เธอแค่รู้สึกอยากช่วยเหลือกัปตันและนักเดินเรือที่รับเธอมาให้กลับบ้านอย่างปลอดภัย ไม่ใช่ให้เสียชีวิตจากพายุหรือภัยพิบัติอื่น ๆ บนเรือ \n\n ผู้ชี้นำที่เข้าใจความปรารถนาของเธอจึงกล่าวว่า 「เป็นผู้ชี้นำเถอะ คลอเปอร์ซานต์ เป็นผู้ชี้นำ ทำหน้าที่ของคุณ แล้วความปรารถนาของคุณจะเป็นจริง」 \n\n คลอเปอร์ซานต์ที่ยังงงงวยพยักหน้า จากนั้นผู้ชี้นำก็กลายเป็นครูของเธอ เขาสอนเธอเกี่ยวกับการสังเกตดาวบนท้องฟ้า วิธีการปรับระดับเซกซานต์ และบอกเธอถึงเพลงที่ผู้ชี้นำสืบทอดกันมา เพลงที่ไม่สู้ดีนัก \n\n 「ฉันไม่อยากถูกน้ำเค็มกอดไว้ มันหนาวเกินไป และไม่อยากกลายเป็นไฟฟอสฟอรัส」 คลอเปอร์ซานต์ในวัยเด็กแสดงความคิดเห็น \n\n ครูของเธอไม่ได้สอนอะไรเธอเลย แค่ลูบหัวเธอและยิ้มให้ \n\n เพราะเวลาจะสอนให้เธอเข้าใจความหมายของหน้าที่ 「ผู้ชี้นำ」 \n\n เธอคือแสงสว่างเดียวในมหาสมุทรอันลึกซึ้ง เป็นความหวังเดียวที่มีอยู่ \n"
  },
  AwakerStory_81616_Title = {
    Text = "เรื่องราว·3"
  },
  AwakerStory_81616_UnlockDesc = {
    Text = "อัตราการประสานไปถึงระดับ 7"
  },
  AwakerStory_81617_Content = {
    Text = "ไม่มีใครรู้ว่าเรือผีลำนั้นอยู่ที่ไหน และไม่มีใครสามารถยืนยันได้ว่า \"มัน\" มีอยู่จริงหรือไม่ ข้อมูลเดียวที่ฉันมีอยู่ในมือคือรูปปั้นหัวงาช้างที่ดูเหมือนจะมีพลังเวทมนตร์บางอย่าง.\n\nตั้งแต่ฉันได้มันมา ฉันฝันถึงมันทุกวัน ใช่แล้ว นั่นคือเรือผีที่ไม่รู้ว่าอยู่ที่ไหน \"มัน\" มีลำเรือที่เปล่งแสงเรืองรองเหมือนมีชีวิต ดูเหมือนจะเป็นประตูสู่มิติที่มนุษย์ไม่อาจรู้จัก เมื่อตื่นขึ้นมา ฉันยังคงจำเสียงกระซิบที่ดูหมิ่นและป่วยไข้เหล่านั้นได้.\n\nฉันหวังว่าตัวเองจะบ้าไปแล้ว หรือทำลืมเสียงแปลกประหลาดเหล่านี้ที่มนุษย์ไม่สามารถเปล่งออกมาได้ แต่ไม่ใช่.\n\nความฝันที่น่าสะอิดสะเอียนนั้น แสงสว่างที่น่าสะพรึงกลัวนั้นทำให้ฉันทรมาน ดังนั้นฉันจึงต้องออกตามหา \"มัน\" โดยมีรูปปั้นหัวงาช้างเป็นแนวทาง โชคดีที่อาจารย์จากมิสคาโตนิกจะไปกับฉัน เพื่อสำรวจเรือผีและไฟเซนต์เอลโม—พวกเขาเรียกแสงเรืองรองนั้นแบบนี้.\n\nขอให้โชคดี ขอให้พระเจ้าคุ้มครองเรา.\n\n——ตัดตอนจาก \"เอกสารการสอบสวนปรากฏการณ์เหนือธรรมชาติของมิสคาโตนิก\""
  },
  AwakerStory_81617_Title = {
    Text = "เรื่องราว·แรก"
  },
  AwakerStory_81617_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_81618_Content = {
    Text = "ชีวิตประจำวันของเคอร์เปอร์ซานต์นั้นค่อนข้างเป็นกิจวัตร คุณเพียงแค่ต้องไปยังสถานที่เฉพาะในเวลาที่กำหนด ก็จะสามารถพบเธอได้\n\nโดยปกติแล้ว เคอร์เปอร์ซานต์จะตื่นนอนเวลา 6:00 น. เพื่ออาบน้ำเย็นและออกกำลังกาย เวลา 7:00 น. เป็นเวลารับประทานอาหารเช้า โดยนอกจากข้าวโอ๊ตต้มและปลาดองแล้ว ยังต้องเสริมด้วยคาเฟอีนจำนวนมากด้วย\n\nเวลา 9:00-12:00 น. จะเป็นเวลาที่เคอร์เปอร์ซานต์ทำการศึกษาต่อยอด โดยเธอจะใช้เวลาในช่วงนี้แก้ไขแผนที่เดินเรือหรือปรับเครื่องมือต่างๆ เมื่อเสียงระฆังเลิกเรียนดังขึ้น เคอร์เปอร์ซานต์จะออกไปโบกธงทำหน้าที่เป็นเจ้าหน้าที่คุมจราจร ซึ่งช่วยให้ถนนของสถาบันไม่แออัดในช่วงเวลาอาหารกลางวัน\n\nเวลาอาหารกลางวันของเคอร์เปอร์ซานต์จะขึ้นอยู่กับ 「สภาพการจราจร」 แต่จะไม่เกิน 12:30 น. หลังจากพักผ่อนช่วงสั้นๆ เวลา 14:00 น. เธอจะปรากฏตัวที่ชายหาดอย่างตรงเวลา เพื่อตรวจสอบทิศทางลมและสภาพอากาศ ในเวลานี้ควรสังเกตพฤติกรรมของเคอร์เปอร์ซานต์ ฟาโลส และซีเลสท์อย่างระมัดระวัง เพื่อหลีกเลี่ยงการที่พวกเธอจะ 「ยึด」 แบบจำลองเรือของพิพิธภัณฑ์ หรือหลอกล่อผู้คนให้ออกเรือ\n\nเวลา 19:00 น. เป็นเวลาอาหารเย็น เพื่อทำให้วงจรการนอนหลับที่ถูกทำลายอย่างสิ้นเชิงจากการเดินเรือระยะยาวนั้นชาไป เคอร์เปอร์ซานต์จึงต้องดื่มแอลกอฮอล์และยาช่วยนอนหลับจำนวนมาก มีเพียงวิธีนี้เท่านั้นที่จะทำให้เธอหลับได้สำเร็จในเวลา 22:00 น. มิฉะนั้น เคอร์เปอร์ซานต์จะบังคับให้ตัวเองตื่นอยู่ เพื่อรับมือกับ 「เหตุการณ์ไม่คาดคิด」 ที่อาจเกิดขึ้นระหว่างการเดินเรือ\n\nเหตุการณ์ที่อาจเกิดขึ้นได้รวมถึงแต่ไม่จำกัดเพียง ปรากฏการณ์ไฟเซนต์เอลโมที่ควบคุมไม่อยู่ ทำให้พื้นที่ทั้งหมดสว่างดั่งกลางวัน หรือระบบไฟฟ้าในพื้นที่เกิดข้อผิดพลาดและควบคุมไม่ได้ การทำงานของเครื่องจักรผิดปกติและเกิดเพลิงไหม้ เป็นต้น\n\n<Red:โปรดทราบ ห้ามให้เอริกาและเคอร์เปอร์ซานต์ติดต่อกันในช่วงเวลานี้อย่างเด็ดขาด!>\n\nแจ้งเตือนบทวิจารณ์ชิ้นสุดท้าย:\n\nหลังจากการมาของเคอร์เปอร์ซานต์ วินเคิลได้พยายามหลายครั้งที่จะดึงและวิจัยเกี่ยวกับ@2บนหน้าอกของเคอร์เปอร์ซานต์ในฐานะแหล่งกำเนิดแสง ได้มีการแจ้งเตือนด้วยคำพูดไปแล้ว หากใครพบเห็นสิ่งผิดปกติ โปรดแจ้งให้ผู้ปกปิดความลับทราบทันที\n\n——ผู้ปกปิดความลับ%player%"
  },
  AwakerStory_81618_Title = {
    Text = "เรื่องราว·2"
  },
  AwakerStory_81618_UnlockDesc = {
    Text = "อัตราการประสานถึงระดับ 5"
  },
  AwakerStory_81619_Content = {
    Text = "จนถึงช่วงสุดท้าย คอปเปอร์ซานท์พยายามทำหน้าที่ของตน แต่เรือที่เธอนำร่องกลับจมลงไป\n\nทุกครั้งที่คืนเงียบสงัด เธอจะฝันถึงผู้โดยสารที่ล่วงลับไป: น้ำทะเลไหลเข้ามาในตัวเรือ สัตว์ทะเลหนวดสัมผัสอาละวาด บางคนจมน้ำตาย บางคนกระโดดลงทะเล บางคนค kneel ลงไปอธิษฐานขอแนวทางสุดท้าย แต่ความหวังกลับล่มสลาย\n\nความจริงที่โหดร้ายนี้กำลังตำหนิเธอ ทำร้ายเธอ—เธอได้ดูหมิ่นอาชีพของตน\n\nเพื่อสิ่งนี้ เธอต้องถูกลงทัณฑ์ ฟ้าผ่าที่พันธนาการเธอตลอดชีวิตก็คือการลงทัณฑ์ แต่ยังไม่เพียงพอ เธอต้องชดใช้สำหรับการละเลยของเธอ\n\nโชคดีที่การมีอยู่ที่ยิ่งใหญ่ได้มอบคำตอบ: ตราบใดที่ประเทศเทพฟื้นคืน ทุกสิ่งในโลกจะกลับกลายเป็นดินแดนแห่งความสุข\n\n「ดังนั้น เพื่อที่จะทำให้เสียงคำรามอันไม่มีที่สิ้นสุดของมหาสมุทรสงบลง เพื่อผู้บริสุทธิ์ที่ถูกฝังอยู่ในทะเล เพื่อชี้นำทิศทางของสรรพชีวิต ฉันขอการฟื้นคืนของแดนศักดิ์สิทธิ์」\n\nนี่คือการนำร่องครั้งสุดท้ายของเธอ\n"
  },
  AwakerStory_81619_Title = {
    Text = "เรื่องราว·สี่"
  },
  AwakerStory_81619_UnlockDesc = {
    Text = "อัตราการประสานระดับ 9"
  },
  AwakerStory_95006_Content = {
    Text = "■หมายเลขแฟ้ม: DIOL-A3-27\n■รหัสร่างกายที่ตื่นขึ้น: ■■■■\n\nตามพฤติกรรม นิสัยการทำงาน และทัศนคติต่อภารกิจต่างๆ ของร่างกายที่ตื่นขึ้นนี้(ซึ่งจะเรียกว่า เคธี่กูลา) เจ้าหน้าที่สอบสวนได้ทำการคาดเดาที่เกี่ยวข้อง และได้ขยายผลการสอบสวนในภายหลัง โดยตอนนี้จะทำการซิงค์เนื้อหาดังต่อไปนี้: \nเคธี่กูลาเป็นเด็กกำพร้าในเขต @2 ซึ่งพ่อแม่ของเธอได้ทอดทิ้งเธอตั้งแต่วัยเด็ก \nเคธี่กูลาได้อาศัยอยู่ในพื้นที่นี้โดยอาศัยวิธีการที่ไม่รู้จัก และได้ช่วยเหลือเด็กๆ ที่มีชะตากรรมที่น่าสงสารหลายคน ต้องระวังว่าในกระบวนการนี้มีการใช้วิธีการที่เต็มไปด้วยความรุนแรงและเลือดเย็น ในบันทึกที่ชัดเจน เจ้าของการสอบสวนเคยฆ่าครอบครัวของเด็กที่เธอรับเลี้ยงอย่างโหดเหี้ยม \nในระยะเวลายาวนานต่อมา แหล่งรายได้หลักของเคธี่กูลาคือการรับจ้างงานที่มองไม่เห็น เช่น การฆ่าล้างแค้นของแก๊ง การต่อสู้ระหว่างแก๊ง การปล้นของที่ผิดกฎหมาย และการกระทำที่ผิดกฎหมายอื่นๆ \nจากคำบอกเล่าของคนในท้องถิ่นและข้อมูลบางอย่างในพื้นที่นี้ ทำให้สามารถคาดเดาได้ว่า ณ จุดหนึ่ง เคธี่กูลาและเด็กที่เธอรับเลี้ยงได้รวมกลุ่มกันเป็นแก๊งที่สำคัญ ซึ่งได้รวมกลุ่มองค์กรอาชญากรรมส่วนใหญ่ในพื้นที่นี้ \nในขณะนี้ยังไม่สามารถทราบได้ว่าเคธี่กูลากลายเป็นร่างกายที่ตื่นขึ้นได้อย่างไร แต่เวลาในการทำลายฐานที่มั่นของโบสถ์แห่งตะเกียงในพื้นที่นั้นตรงกับเวลาที่คาดการณ์ว่าเธอกลายเป็นร่างกายที่ตื่นขึ้น จากความเกลียดชังที่เธอมีต่อโบสถ์แห่งตะเกียง สามารถคาดเดาได้ว่าเธอกลายเป็นร่างกายที่ตื่นขึ้นนั้นเกี่ยวข้องกับโบสถ์แห่งตะเกียง \nจากสถิติที่ไม่สมบูรณ์ จนถึงขณะนี้มีฐานที่มั่นของโบสถ์แห่งตะเกียงถูกทำลายไปแล้ว 43 แห่ง รวมถึงฐานใหญ่ 7 แห่ง,      แท่นบูชาลงเทพ 12 แห่ง และสถานทดลอง 17 แห่ง \n\nจากรายงานการสอบสวนข้างต้นและพฤติกรรมประจำวันของร่างกายที่ตื่นขึ้นนี้ คณะกรรมการได้ทำการประเมินอันตรายของเคธี่กูลาใหม่ตามข้อเสนอของประธานเกียรติยศ K·เทรลัค โดยได้บันทึกผลการประเมินดังนี้: \nจากการตัดสินใจของคณะกรรมการทั้งหมด ร่างกายที่ตื่นขึ้นนี้ไม่มีภัยคุกคามโดยตรงหรือโดยอ้อมต่อมิซากะ และในกรณีที่ไม่มีการเปลี่ยนแปลงข้อตกลงความร่วมมือที่มีอยู่ จำเป็นที่จะไม่ต้องแทรกแซงการมีอยู่และพฤติกรรมของเธอ \nดังนั้น จึงมีการตัดสินใจให้นำเคธี่กูลาออกจาก DIOL และทำการแช่แข็งการสอบสวนทั้งหมดที่เกี่ยวข้องกับเธอ โดยให้บันทึกทั้งหมดถูกปิดผนึกอย่างสมบูรณ์ และห้ามไม่ให้บุคคลที่มีระดับต่ำกว่า Ω เข้าถึง \n\nผู้บันทึก K·เทรลัค\n(เขียนในตัวอักษรเล็กที่ด้านล่างของแฟ้ม) \nยินดีด้วย! ในที่สุดก็ทำให้พวกเด็กที่ตกใจกลัวยกเลิกโครงการที่น่ารำคาญนี้ได้ ไม่เสียเวลาในการผลักดันเรื่องเหล่านี้ \nนี่คือบันทึกสุดท้ายเกี่ยวกับคุณเคธี่กูลา หากไม่มีเหตุการณ์อะไรเกิดขึ้นในอนาคต จะไม่มีแฟ้มใหม่เพิ่มเติมในหมายเลขนี้ ดังนั้นไม่ว่าใครก็ตาม ตอนนี้สามารถปิดแฟ้มที่น่ารำคาญนี้ และออกไปหายใจอากาศบริสุทธิ์ และตั้งใจในสิ่งที่น่าสนใจกว่านี้ได้แล้ว!\n——คาราโพลิส·เทรลัค เพื่อนของคุณที่กลายเป็นคนว่างงาน."
  },
