  AwakerStory_95007_UnlockDesc = {
    Text = "ระดับอัตราการประสาน 3"
  },
  AwakerStory_95008_Content = {
    Text = "(เขียนด้วยตัวอักษรเล็กที่ต้นเอกสาร)\nบ้าเอ๊ย คุณไปเจอเอกสารนี้ได้ยังไงกัน ทั้งๆ ที่ผมห้ามไม่ให้ใครเข้าถึงมัน... เอาเถอะ ในเมื่อคุณสามารถเห็นเอกสารนี้ได้ นั่นหมายความว่าอำนาจของคุณเหนือกว่าผม นั่นแปลว่าคุณต้องเป็นหนึ่งในพวกเขา ซึ่งผมก็ไม่มีสิทธิ์ขัดขวางไม่ให้คุณรู้เรื่องเหล่านี้\n\nแต่ขอให้คุณจดจำไว้เสมอว่า เอกสารนี้ไม่ควรจะมีอยู่ที่ไหนเลย และเนื้อหาต่อไปนี้ก็ไม่ใช่ผลการสอบสวนอย่างเป็นทางการ แต่เป็นผลิตผลที่เกิดจากการคาดเดาทุติยภูมิบนฐานข้อเท็จจริงส่วนตัว\n\nผมต้องขอเตือนคุณอย่างจริงจังว่า ในขณะที่มีการจดบันทึกเอกสารนี้ มีการใช้วิธีการสอบสวนที่ไม่สามารถอธิบายได้โดยละเอียด ความคาดเดาส่วนตัวที่อาจมีอคติ และการรับสินบนจากผู้ถูกสอบสวน หากคุณไม่ใส่ใจกับพฤติกรรมเหล่านี้ของผม ขอให้คุณอ่านต่อไป ผมให้เกียรติในตัวผมรับประกันว่า เนื้อหาต่อไปนี้มีความจริงที่ชัดเจน\n\n■ หมายเลขเอกสาร: ■■■■-A■■-SSS \n■ รหัสตัวตนที่ปลุกตื่น: เจ้าแห่งเปลวไฟ\n「จริงๆ แล้ว ฉันไม่ชอบการต่อสู้」\nผมค่อนข้างแปลกใจที่ได้รับคำตอบเช่นนี้ เพราะในรายงานทั้งหมด นักสืบจะอธิบายเกี่ยวกับการต่อสู้ของเธอ พร้อมกับใช้คำว่า 「บ้าคลั่ง」 「มีความสุข」 「สนุกสนาน」 \nผมเคยคิดว่าเธอคงเห็นการต่อสู้ว่าเป็น 「ไม่เริ่มก่อน แต่ก็ไม่ปฏิเสธ」 ไม่เคยคิดเลยว่าเธอจะรู้สึกรังเกียจเรื่องแบบนี้โดยตนเอง \nเมื่อการพูดคุยดำเนินไปลึกลงเรื่อยๆ ผมจึงเริ่มเข้าใจอะไรบางอย่าง เมื่อผมถามว่าสามารถบันทึกเนื้อหานี้ได้หรือไม่ เคธี่กูลาก็อนุญาตให้ผมทำโดยไม่ลังเล \n\n「คุณต้องรู้ว่า สำหรับคนส่วนใหญ่ในโลก การมีชีวิตอยู่ก็เป็นความฟุ่มเฟือยอย่างหนึ่ง」\nผมเห็นด้วยกับคำพูดนี้ แม้ว่าผมและผู้คนที่ผมพบเจอส่วนใหญ่จะมีชีวิตที่เหนือชั้น ผมยังสามารถไปชมการแสดงที่โรงละครใหญ่ในเลนดิเยนนี่ได้ทุกเมื่อ แต่ผมก็รู้สึกได้ถึงโลกแท้จริง และรู้ถึงเบื้องหลังชีวิตที่ดีของผมว่ามีผู้คนมากมายที่ต้องแบกรับภาระหนักแทน\n\n「ดังนั้น ในหลายครั้ง ความปรารถนาในการต่อสู้ที่รุนแรง คือค่าใช้จ่ายที่คุณต้องจ่ายเพื่อการมีชีวิตรอด」\n「เราไม่มีทางเลือกในวิธีการใช้ชีวิต เมื่อคุณเดินเข้าสู่ความโคลนแล้ว การจะถอนตัวแทบเป็นไปไม่ได้เลย」\nผมตั้งใจจะโต้แย้งความคิดนี้ แต่เมื่อผมพิจารณาถึงกรณีหลายๆ อย่างที่ผ่านมาด้วยความระมัดระวังแล้ว ผมพบว่าพวกเขาไม่ธรรมดา และคนที่ไม่มีชื่อเสียงก็ส่วนใหญ่จะจบลงในบันทึกความทรงจำเท่านั้น \n「บางทีอาจมีคนที่ไร้เดียงสาบอกว่า ถ้าเป็นแบบนี้ ในตอนแรกก็ไม่ควรทำไม่ใช่หรอ? ความคิดแบบนี้ดีนะ ฉันเคยสลักคำนี้บนหลุมศพแห่งหนึ่ง เพื่อรำลึกถึงผู้ที่ยึดมั่นในหลักการนี้」\n「เพื่อปกป้องทุกคนในโลกที่โหดร้ายนี้ ฉันต้องแสดงออกถึงความแข็งแรง บ้าคลั่ง พอที่จะทำให้เจตนาร้ายที่มีอยู่ทุกหนแห่งหวาดกลัว」\n「แน่นอน อารมณ์ที่ฉันแสดงออกระหว่างการต่อสู้ไม่ใช่การแสร้งทำ ฉันเพลิดเพลินในความรู้สึกที่การต่อสู้มอบให้ฉันจริงๆ」\n「มันอาจจะเข้าใจยากหน่อย แต่มันก็เหมือนที่คุณอาจจะชอบเนื้อหาของงานของคุณ แต่ไม่ได้ชอบตัวงานนั้นเอง」\nหลังจากที่ได้ยินคำอธิบายนี้ ผมเข้าใจความหมายในคำพูดของเธอทันที จริงๆ แล้ว ผมชอบดูความลับของคนอื่นเพื่อเติมเต็มความอยากรู้อยากเห็นที่ไร้จรรยาบรรณของผมในที่งาน แต่ไม่ได้หมายความว่าผมชอบต้องตื่นเช้าตอนแปดโมงตรงเพื่อไปที่ไหนสักแห่งทั้งวันตามคำสั่ง\n\n「เมื่อฉันถูกทอดทิ้งตอนแรกๆ ฉันก็เหมือนผู้หญิงอื่นๆ มากมาย สับสน ลังเล ไม่มีที่พึ่งพิง」\n「ฉันหวังจะได้รับความช่วยเหลือจากคนอื่น แต่สิ่งที่โลกมอบให้ฉันนั้นมีเพียงแค่การทรยศและความเจ็บปวดนับไม่ถ้วน」\n「ค่อยๆ ฉันเริ่มสร้างเกราะป้องกันความร้ายกาจจากโลกด้วยความโหดร้ายและความบ้าคลั่ง ปรับตัวต่อทุกอย่างเหมือนดื่มยาพิษฆ่าตัวตาย」\n「จนสุดท้าย เกราะเหล่านั้นก็ละลายในเปลวไฟที่ไม่มีวันดับ และรวมเข้ากับเลือดเนื้อของฉันเป็นหนึ่งเดียว」\nเหมือนจะยืนยันคำพูดของเธอเมื่อครู่ เคธี่กูลาเผยรอยยิ้มที่โหดร้าย ชั่วร้าย และบ้าคลั่งในคราวเดียว ทำให้ผมตกใจจนของเหลวสีเหลืองอ่อนในแก้วหกลงบนตัวผม \nโอ้ หรือบางทีนี่อาจเป็นเรื่องดี เพราะถ้าผมพลั้งเผลอกล้ามเนื้อและมีของเหลวออกมา จะได้แก้ตัวได้ง่ายๆ ว่าเป็นเครื่องดื่มที่หกใส่ตัวไปก่อนหน้านี้ \nก่อนจากลา เคธี่กูลาก็ยังไม่ตอบคำถามของผมโดยตรง แต่ผมคิดว่า สิ่งที่ผมตัดสินใจก่อนหน้านั้นถูกต้องแล้ว เธอไม่ควรอยู่ใน DIOL \n—— ผู้บันทึก คาลาปอริส ทราลัค\n\n「ความปรารถนาเริ่มแรกของฉัน ก็แค่อยากมีบ้านหลังหนึ่ง」\n「บ้านที่ไม่มีการทรยศ ไม่มีความเจ็บปวด และเต็มไปด้วยเสียงหัวเราะ」\n「แต่น่าเสียดาย จนถึงวันนั้น ฉันถึงได้รู้ว่า」\n「มันเป็นเพียงความเพ้อฝันที่ฟุ่มเฟือยที่สุดในโลกอันโหดร้ายนี้」\n—— เคธี่กูลา"
  },
  AwakerStory_95008_Title = {
    Text = "เรื่องราว·สี่"
