  AwakerStory_95009_UnlockDesc = {
    Text = "ร่างกายที่ตื่นขึ้นถึงระดับ 1"
  },
  AwakerStory_95010_Content = {
    Text = "■รหัสแฟ้ม: DIOL-A3-9\n■รหัสผู้ปลุกตื่น: ■■■■\n\nจากการสังเกตอย่างต่อเนื่อง พบว่าผู้ปลุกตื่นนี้ไม่มีความสนใจผิดปกติต่อมิซากะ แทบจะกล่าวได้ว่าไม่มีความสนใจเลย เธอจะมาในมหาวิทยาลัยเฉพาะเมื่อได้รับมอบหมายงาน จากนั้นก็จะรีบจากไปอย่างรวดเร็ว \nแม้ว่ารายงานการสอบสวนที่ส่งกลับมาแสดงให้เห็นว่าผู้ปลุกตื่นนี้มีบันทึกการอยู่ในมหาวิทยาลัยเป็นเวลานานหลายครั้ง \n\nแต่จากการสอบสวนต่อมา สาเหตุหลักที่เธออยู่คือการช่วยนักเรียนแก้ปัญหาบางอย่าง จากการประเมินไม่พบอันตรายด้านความปลอดภัยจึงไม่จำเป็นต้องเข้าแทรกแซง \n\nสิ่งที่ต้องระวังคือ ผู้ปลุกตื่นนี้ดูเหมือนจะมีความสนใจต่อผู้พิทักษ์มากกว่าคนอื่นๆ โดยเคยนำวัตถุที่ถูกจัดเป็นสิ่งต้องห้าม @3 มามอบให้ผู้พิทักษ์หลายครั้ง และเชิญผู้พิทักษ์เข้าร่วมงานเลี้ยงที่ไม่มีผู้เข้าร่วมคนอื่นรู้จัก พิจารณาถึงความสำคัญของผู้พิทักษ์ต่อมิซากะ หากผู้ปลุกตื่นนี้มีเจตนาที่จะกระทำการอันตรายต่อผู้พิทักษ์ จะต้องจัดเตรียมเจ้าหน้าที่ติดอาวุธระดับ γ อย่างน้อย 4 คน เพื่อให้แน่ใจว่าผู้พิทักษ์สามารถถอนตัวได้อย่างปลอดภัย \n\nผู้บันทึก K·เทรลัค\n\n(เขียนไว้ที่ด้านหลังของแฟ้ม)\nเฮ้ พี่ชาย อาจจะเป็นพี่สาวก็ได้ ไม่สำคัญหรอก \nคนโชคร้ายคนก่อนหน้านี้ได้ลาออกไปแล้ว ตอนนี้เป็นหน้าที่ของฉันที่ต้องรับผิดชอบโครงการน่ารังเกียจนี้ \nถ้าคุณเห็นสิ่งนี้ แสดงว่าคุณไม่ใช่คนที่แค่รอวันตาย แต่เป็นคนที่มีความสามารถในการสังเกต คุณน่าจะปรบมือให้ตัวเอง \nฟังนะ แม้ว่าเราจะบอกว่าเรากำลัง 「เฝ้าสังเกตในเงามืด」 แต่ฉันรู้สึกว่าเธอรู้ว่าเรามีอยู่แล้ว เพียงแค่ไม่ยอมสนใจเท่านั้น \nฉันไม่เข้าใจว่าทำไมเราต้องเฝ้าสังเกตคนแบบนี้ แม้ว่าในการสัมผัสครั้งแรกกับเธอจะมีความเข้าใจผิดบ้าง แต่ก็เป็นผลจากผู้ติดตามลัทธิชั่วร้าย ไม่เกี่ยวข้องกับตัวเธอเลย \nนอกจากนี้ ความสัมพันธ์ระหว่างเธอกับนักเรียน โดยเฉพาะอย่างยิ่งกับผู้พิทักษ์นั้น เปรียบเสมือนคุณยายซื้อขนมให้หลาน! จะมีใครคิดว่าคุณยายจะนำหลานไปบูชายัญให้กับลัทธิชั่วร้ายไหม... ไม่ รอแป๊บ อาจจะมีที่ไหนสักแห่งที่เป็นแบบนั้น แต่ไม่สำคัญ! \nสิ่งสำคัญคือ ถ้าเธอมีแผนการจริงๆ ฉันรับรองว่า เรื่องต่างๆ ได้เกิดขึ้นโดยไม่รู้ตัวแล้ว ไม่ใช่รอให้คณะกรรมการค่อยๆ ค้นพบกลยุทธ์ที่****** \nอ่า รู้สึกดีมากที่ได้ด่ามัน สรุปคือ ฉันได้วางแผนจะลบเธอออกจากรายชื่อนี้ ก่อนที่คณะกรรมการจะทำอะไรที่ไม่สามารถให้อภัยต่อเธอ \nทันทีที่พวกนั้นจริงจังทำให้เธอโมโห ฉันรับรองว่ามันจะไม่ใช่เรื่องง่ายๆ อย่างอาคาร 2 ชั้นแน่นอน หวังว่าตอนนั้นฉันจะตายไปแล้ว ไม่อย่างนั้นฉันคงจะตายอย่างทรมาน \nถ้าคุณคือคนที่จะเฝ้าสังเกตเธอ จำไว้ว่าห้ามทำอะไรที่รุนแรง ถ้าคุณไม่ชอบเธอ ก็ให้คิดว่าเธอเป็นแค่คนทำงานสกปรกให้กับโรงเรียนก็พอ เว้นแต่เธอจะแสดงอาการไม่มั่นคงอย่างชัดเจน ห้ามมีความขัดแย้งแบบตรงไปตรงมาเด็ดขาด! \nแน่นอน ถ้าคุณต้องการของขวัญเล็กน้อย... เธอคงไม่สนใจว่าคุณเคยเฝ้าสังเกตเธอ ขอให้คุณกล้าไปขอเถอะ พูดตามตรง ขนมในกระเป๋าของเธออร่อยมาก \n——คาราโพลิส·เทรลัค เพื่อนที่ด่าคณะกรรมการด้วยกัน."
  },
